:root {
    --lux-bg: #f6f7fb;
    --lux-surface: rgba(255, 255, 255, 0.82);
    --lux-rail-surface: rgba(255, 255, 255, 0.76);
    --lux-header-surface: rgba(255, 255, 255, 0.64);
    --lux-border: rgba(226, 232, 240, 0.9);
    --lux-text: #111827;
    --lux-muted: #64748b;
    --lux-shadow: 0 20px 50px rgba(15, 23, 42, 0.08);
    --lux-shadow-sm: 0 8px 22px rgba(15, 23, 42, 0.06);
    --lux-radius-lg: 22px;
    --lux-radius-md: 15px;
    --lux-rail-width: 55px;
    --lux-menu-width: 232px;
    --lux-module-rail-width: 44px;
    --lux-menu-context-width: calc(var(--lux-menu-width) - var(--lux-module-rail-width));
    --lux-rail-padding-y: 12px;
    --lux-rail-padding-x: 12px;
    --lux-sidebar-padding: 12px 6px 20px;
    --app-sidebar-width: calc(var(--lux-rail-width) + var(--lux-menu-width));
    --app-sidebar-rail: var(--lux-rail-width);
    --app-font-sans: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    --lux-brand-font: "Manrope", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    /* Luxury readable type scale (minimum ~9px; prefer --lux-text-sm+ for body copy) */
    --lux-text-2xs: 0.5625rem;
    --lux-text-xs: 0.625rem;
    --lux-text-sm: 0.6875rem;
    --lux-text-md: 0.75rem;
    --lux-text-body: 0.8125rem;
    --lux-text-lg: 0.875rem;
    /* Stacking order — overlays must sit above --lux-z-page-header */
    --lux-z-sidebar: 1029;
    --lux-z-offcanvas: 1035;
    --lux-z-page-header: 1040;
    --lux-z-page-header-menu: 1060;
    --lux-z-overlay: 10040;
    --lux-z-overlay-panel: 10041;
    --lux-z-shell-panel: 10050;
}

[data-lux-font="inter"] {
    --app-font-sans: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

[data-lux-font="source-sans"] {
    --app-font-sans: "Source Sans 3", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

[data-lux-font="ibm-plex"] {
    --app-font-sans: "IBM Plex Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

[data-lux-font="plus-jakarta"] {
    --app-font-sans: "Plus Jakarta Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

[data-lux-font="dm-sans"] {
    --app-font-sans: "DM Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

[data-lux-font="roboto"] {
    --app-font-sans: "Roboto", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

[data-lux-font="open-sans"] {
    --app-font-sans: "Open Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

[data-lux-font="lato"] {
    --app-font-sans: "Lato", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

[data-lux-font="manrope"] {
    --app-font-sans: "Manrope", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

[data-lux-font="montserrat"] {
    --app-font-sans: "Montserrat", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

[data-lux-typography="soft-luxury"] {
    --lux-brand-font: "Manrope", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

[data-lux-typography="strict-enterprise"] {
    --lux-brand-font: "Plus Jakarta Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

[data-lux-typography="custom"] {
    --lux-brand-font: "Plus Jakarta Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

body.lux-shell,
body.lux-shell #root,
body.lux-shell #main_content {
    font-family: var(--app-font-sans) !important;
}

body.lux-shell *:not(.brand-name):not(.brand-registered):not(.brand-pro):not(.logo-text):not(.lux-user-panel__brand-name):not(i):not(code):not(pre):not(kbd):not(samp) {
    font-family: inherit !important;
}

.brand-name,
.brand-registered,
.brand-pro,
.logo-text,
.lux-user-panel__brand-name,
#header_top.lux-rail .brand-name,
#left-sidebar .brand-name,
.user_div .brand-name {
    font-family: var(--lux-brand-font) !important;
}

body.lux-shell {
    background:
        radial-gradient(circle at top left, rgba(var(--lux-primary-rgb), 0.12), transparent 34%),
        radial-gradient(circle at 92% 18%, rgba(var(--lux-accent-rgb), 0.14), transparent 30%),
        var(--lux-bg) !important;
}

body.lux-shell-dark {
    --lux-bg: #0f172a;
    --lux-surface: rgba(30, 41, 59, 0.88);
    --lux-rail-surface: rgba(15, 23, 42, 0.92);
    --lux-header-surface: rgba(15, 23, 42, 0.82);
    --lux-border: rgba(51, 65, 85, 0.9);
    --lux-text: #f8fafc;
    --lux-muted: #94a3b8;
}

/* ========== Page-level alert strip (MainLayout global errors) ========== */
body.lux-shell #main_content > .lux-page-alert {
    position: absolute;
    top: 0;
    z-index: 10000;
    left: var(--app-sidebar-width);
    width: calc(100% - var(--app-sidebar-width));
    margin-top: 0.625rem;
    padding: 0.75rem 1rem;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    border-radius: 14px;
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    animation: lux-page-alert-in 0.32s ease-out;
}

@keyframes lux-page-alert-in {
    from {
        opacity: 0;
        transform: translateY(-6px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.lux-page-alert--danger {
    border: 1px solid rgba(244, 63, 94, 0.24);
    background: linear-gradient(135deg, rgba(254, 242, 242, 0.98), rgba(255, 247, 247, 0.9));
    box-shadow:
        0 12px 32px -20px rgba(190, 18, 60, 0.5),
        inset 0 1px 0 rgba(255, 255, 255, 0.75);
}

.lux-page-alert__icon {
    display: inline-grid;
    place-items: center;
    width: 2.125rem;
    height: 2.125rem;
    border-radius: 10px;
    flex-shrink: 0;
    background: rgba(244, 63, 94, 0.12);
    color: #be123c;
    font-size: 1rem;
}

.lux-page-alert__message {
    flex: 1;
    min-width: 0;
    margin: 0;
    font-size: 0.8125rem;
    font-weight: 600;
    line-height: 1.45;
    color: #9f1239;
}

.lux-page-alert__dismiss {
    display: inline-grid;
    place-items: center;
    width: 1.75rem;
    height: 1.75rem;
    padding: 0;
    border: none;
    border-radius: 999px;
    background: rgba(244, 63, 94, 0.1);
    color: #be123c;
    cursor: pointer;
    flex-shrink: 0;
    transition: background 0.15s ease, color 0.15s ease, transform 0.15s ease;
}

.lux-page-alert__dismiss:hover {
    background: rgba(244, 63, 94, 0.18);
    color: #9f1239;
    transform: scale(1.04);
}

.lux-page-alert__dismiss:focus-visible {
    outline: 2px solid rgba(244, 63, 94, 0.45);
    outline-offset: 2px;
}

body.lux-shell-dark #main_content > .lux-page-alert--danger {
    border-color: rgba(251, 113, 133, 0.28);
    background: linear-gradient(135deg, rgba(76, 5, 25, 0.94), rgba(51, 8, 22, 0.9));
    box-shadow:
        0 14px 36px -22px rgba(0, 0, 0, 0.65),
        inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

body.lux-shell-dark .lux-page-alert--danger .lux-page-alert__icon {
    background: rgba(251, 113, 133, 0.16);
    color: #fda4af;
}

body.lux-shell-dark .lux-page-alert--danger .lux-page-alert__message {
    color: #fecdd3;
}

body.lux-shell-dark .lux-page-alert--danger .lux-page-alert__dismiss {
    background: rgba(251, 113, 133, 0.14);
    color: #fda4af;
}

body.lux-shell-dark .lux-page-alert--danger .lux-page-alert__dismiss:hover {
    background: rgba(251, 113, 133, 0.24);
    color: #ffe4e6;
}

@media screen and (max-width: 1200px) {
    body.lux-shell #main_content > .lux-page-alert {
        left: var(--app-sidebar-rail);
        width: calc(100% - var(--app-sidebar-rail));
    }
}

@media screen and (max-width: 767px) {
    body.lux-shell #main_content > .lux-page-alert {
        left: 0;
        width: 100%;
        border-radius: 0 0 14px 14px;
        margin-top: 0;
    }
}

/* ========== Connection error page (backend unreachable) ========== */
body.lux-connection-error-open,
body.lux-connection-error-open #root,
body.lux-connection-error-open #main_content.lux-connection-error-shell {
    overflow: hidden;
    height: 100vh;
    min-height: 100vh;
}

body.lux-connection-error-open {
    background: #0c1222 !important;
}

#main_content.lux-connection-error-shell {
    position: fixed;
    inset: 0;
    z-index: 20000;
    width: 100%;
    min-height: 100vh;
    margin: 0;
    padding: 0;
    background: #0c1222;
}

.lux-connection-error-screen {
    position: relative;
    display: flex;
    flex-direction: column;
    min-height: 100vh;
    width: 100%;
    overflow: hidden;
    color: #f8fafc;
}

.lux-connection-error__backdrop {
    position: fixed;
    inset: 0;
    z-index: 0;
    pointer-events: none;
    overflow: hidden;
    background-color: #0c1222;
    background-image: url("/assets/images/login-background.jpeg");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
}

.lux-connection-error__scrim {
    position: absolute;
    inset: 0;
    background:
        linear-gradient(
            112deg,
            rgba(8, 12, 28, 0.94) 0%,
            rgba(10, 22, 48, 0.88) 38%,
            rgba(13, 71, 90, 0.55) 52%,
            rgba(15, 23, 42, 0.72) 68%,
            rgba(8, 12, 28, 0.82) 100%
        ),
        radial-gradient(ellipse 80% 60% at 20% 80%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22), transparent 55%),
        radial-gradient(ellipse 60% 50% at 85% 20%, rgba(20, 184, 166, 0.12), transparent 50%);
}

.lux-connection-error__brand {
    position: relative;
    z-index: 2;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: clamp(1.25rem, 3vw, 2rem) 1.5rem 0;
}

.lux-connection-error__brand .auth-screen__brand-name,
.lux-connection-error__brand .brand-name {
    color: #f8fafc;
}

.lux-connection-error {
    position: relative;
    z-index: 1;
    flex: 1;
    display: grid;
    place-items: center;
    align-content: center;
    min-height: 0;
    padding: clamp(1rem, 3vw, 2rem) clamp(1rem, 3vw, 2rem) clamp(2rem, 4vw, 3rem);
}

.lux-connection-error__grid {
    position: absolute;
    inset: -20%;
    background-image:
        linear-gradient(rgba(var(--lux-primary-rgb), 0.05) 1px, transparent 1px),
        linear-gradient(90deg, rgba(var(--lux-primary-rgb), 0.05) 1px, transparent 1px);
    background-size: 42px 42px;
    mask-image: radial-gradient(ellipse 70% 60% at 50% 40%, #000 20%, transparent 78%);
    opacity: 0.55;
}

.lux-connection-error__orb {
    position: absolute;
    border-radius: 999px;
    filter: blur(48px);
    opacity: 0.55;
    animation: lux-connection-orb-float 9s ease-in-out infinite;
}

.lux-connection-error__orb--1 {
    width: 18rem;
    height: 18rem;
    top: 8%;
    left: 12%;
    background: rgba(var(--lux-primary-rgb), 0.22);
}

.lux-connection-error__orb--2 {
    width: 14rem;
    height: 14rem;
    right: 10%;
    top: 18%;
    background: rgba(var(--lux-accent-rgb), 0.18);
    animation-delay: -2.5s;
}

.lux-connection-error__orb--3 {
    width: 22rem;
    height: 22rem;
    left: 38%;
    bottom: -4%;
    background: rgba(244, 63, 94, 0.14);
    animation-delay: -5s;
}

@keyframes lux-connection-orb-float {
    0%,
    100% {
        transform: translate3d(0, 0, 0) scale(1);
    }

    50% {
        transform: translate3d(0, -14px, 0) scale(1.04);
    }
}

.lux-connection-error__card {
    position: relative;
    z-index: 1;
    width: min(100%, 42rem);
    padding: clamp(1.5rem, 3vw, 2.25rem);
    border-radius: 22px;
    border: 1px solid rgba(var(--lux-primary-rgb), 0.16);
    background:
        linear-gradient(145deg, rgba(255, 255, 255, 0.94), rgba(248, 250, 252, 0.82));
    box-shadow:
        0 28px 64px -36px rgba(15, 23, 42, 0.45),
        inset 0 1px 0 rgba(255, 255, 255, 0.9);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
    text-align: center;
    animation: lux-connection-card-in 0.45s ease-out;
}

@keyframes lux-connection-card-in {
    from {
        opacity: 0;
        transform: translateY(12px) scale(0.98);
    }

    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

.lux-connection-error__icon-wrap {
    position: relative;
    width: 5.5rem;
    height: 5.5rem;
    margin: 0 auto 1.25rem;
}

.lux-connection-error__pulse {
    position: absolute;
    inset: 0;
    border-radius: 999px;
    border: 1px solid rgba(244, 63, 94, 0.28);
    animation: lux-connection-pulse 2.4s ease-out infinite;
}

.lux-connection-error__pulse--inner {
    inset: 0.55rem;
    animation-delay: 0.45s;
}

@keyframes lux-connection-pulse {
    0% {
        transform: scale(0.82);
        opacity: 0.75;
    }

    70%,
    100% {
        transform: scale(1.18);
        opacity: 0;
    }
}

.lux-connection-error__icon {
    position: absolute;
    inset: 0.85rem;
    display: grid;
    place-items: center;
    border-radius: 18px;
    background: linear-gradient(145deg, rgba(254, 242, 242, 0.98), rgba(255, 247, 247, 0.88));
    border: 1px solid rgba(244, 63, 94, 0.22);
    color: #be123c;
    font-size: 1.65rem;
    box-shadow: 0 10px 24px -16px rgba(190, 18, 60, 0.55);
}

.lux-connection-error__eyebrow {
    margin: 0 0 0.45rem;
    font-size: 0.72rem;
    font-weight: 800;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: #be123c;
}

.lux-connection-error__title {
    margin: 0 0 0.75rem;
    font-size: clamp(1.45rem, 2.8vw, 2rem);
    line-height: 1.15;
    font-weight: 800;
    color: #0f172a;
}

.lux-connection-error__lead {
    margin: 0 auto 1.35rem;
    max-width: 34rem;
    font-size: 0.9rem;
    line-height: 1.6;
    color: #64748b;
}

.lux-connection-error__checks {
    list-style: none;
    margin: 0 0 1.5rem;
    padding: 0;
    display: grid;
    gap: 0.65rem;
    text-align: left;
}

.lux-connection-error__check {
    display: flex;
    align-items: flex-start;
    gap: 0.75rem;
    padding: 0.75rem 0.85rem;
    border-radius: 14px;
    border: 1px solid rgba(148, 163, 184, 0.2);
    background: rgba(255, 255, 255, 0.72);
}

.lux-connection-error__check-icon {
    display: inline-grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    border-radius: 10px;
    background: rgba(var(--lux-primary-rgb), 0.1);
    color: rgb(var(--lux-primary-rgb));
    flex-shrink: 0;
}

.lux-connection-error__check-copy {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
    min-width: 0;
}

.lux-connection-error__check-copy strong {
    font-size: 0.8125rem;
    color: #1e293b;
}

.lux-connection-error__check-copy span {
    font-size: 0.75rem;
    line-height: 1.45;
    color: #64748b;
}

.lux-connection-error__actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 0.65rem;
    margin-bottom: 1rem;
}

.lux-connection-error__btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.45rem;
    min-height: 2.65rem;
    padding: 0.55rem 1.15rem;
    border-radius: 999px;
    border: 1px solid transparent;
    font-size: 0.8125rem;
    font-weight: 800;
    cursor: pointer;
    transition: transform 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
}

.lux-connection-error__btn--primary {
    border-color: rgba(var(--lux-primary-rgb), 0.32);
    background: linear-gradient(135deg, rgba(var(--lux-primary-rgb), 0.95), rgba(var(--lux-accent-rgb), 0.88));
    color: #fff;
    box-shadow: 0 14px 28px -18px rgba(var(--lux-primary-rgb), 0.75);
}

.lux-connection-error__btn--primary:hover {
    transform: translateY(-1px);
    box-shadow: 0 18px 34px -18px rgba(var(--lux-primary-rgb), 0.85);
}

.lux-connection-error__btn:focus-visible {
    outline: 2px solid rgba(var(--lux-primary-rgb), 0.45);
    outline-offset: 2px;
}

.lux-connection-error__footnote {
    margin: 0;
    font-size: 0.75rem;
    color: #94a3b8;
    line-height: 1.5;
}

body.lux-shell-dark .lux-connection-error__card {
    border-color: rgba(148, 163, 184, 0.18);
    background: linear-gradient(145deg, rgba(30, 41, 59, 0.94), rgba(15, 23, 42, 0.88));
    box-shadow:
        0 28px 64px -36px rgba(0, 0, 0, 0.65),
        inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

body.lux-shell-dark .lux-connection-error__title {
    color: #f8fafc;
}

body.lux-shell-dark .lux-connection-error__lead,
body.lux-shell-dark .lux-connection-error__check-copy span,
body.lux-shell-dark .lux-connection-error__footnote {
    color: #94a3b8;
}

body.lux-shell-dark .lux-connection-error__check {
    background: rgba(15, 23, 42, 0.55);
    border-color: rgba(71, 85, 105, 0.45);
}

body.lux-shell-dark .lux-connection-error__check-copy strong {
    color: #e2e8f0;
}

