    body.offcanvas-active #left-sidebar.lux-sidebar {
        left: calc(-1 * var(--lux-menu-width)) !important;
    }

    body.offcanvas-active .page {
        left: var(--lux-rail-width) !important;
        width: calc(100% - var(--lux-rail-width)) !important;
    }
