/* ========== Shared summary toggles (collapse/expand) ========== */
.lux-bid-summary__toggle,
.lux-emp-summary__toggle,
.lux-acct-summary__toggle {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    min-height: 1.875rem;
    padding: 0 0.65rem;
    border: 1px solid #e2e8f0;
    font-size: 0.75rem;
    font-weight: 800;
    text-transform: uppercase;
    color: #475569;
    cursor: pointer;
}

a.lux-bid-summary__toggle,
a.lux-emp-summary__toggle,
a.lux-acct-summary__toggle {
    text-decoration: none;
}

.lux-bid-summary__toggle.lux-summary-toggle--icon,
.lux-emp-summary__toggle.lux-summary-toggle--icon,
.lux-acct-summary__toggle.lux-summary-toggle--icon {
    min-width: 1.875rem;
    padding: 0 0.5rem;
    text-transform: none;
}

.lux-summary-toggle__chevron {
    display: inline-block;
    line-height: 1;
    transition: transform 0.28s ease;
}

.lux-bid-summary__toggle[aria-expanded="true"] .lux-summary-toggle__chevron,
.lux-emp-summary__toggle[aria-expanded="true"] .lux-summary-toggle__chevron,
.lux-acct-summary__toggle[aria-expanded="true"] .lux-summary-toggle__chevron {
    transform: rotate(180deg);
    animation: none;
}

.lux-bid-summary__toggle[aria-expanded="false"] .lux-summary-toggle__chevron,
.lux-emp-summary__toggle[aria-expanded="false"] .lux-summary-toggle__chevron,
.lux-acct-summary__toggle[aria-expanded="false"] .lux-summary-toggle__chevron {
    animation: lux-summary-chevron-hint 1.85s ease-in-out infinite;
}

.lux-bid-summary__toggle:not(.lux-summary-toggle--icon)[aria-expanded="false"] > i.fe-chevron-down,
.lux-emp-summary__toggle:not(.lux-summary-toggle--icon)[aria-expanded="false"] > i.fe-chevron-down,
.lux-acct-summary__toggle:not(.lux-summary-toggle--icon)[aria-expanded="false"] > i.fe-chevron-down {
    display: inline-block;
    animation: lux-summary-chevron-hint 1.85s ease-in-out infinite;
}

.lux-bid-summary__toggle:not(.lux-summary-toggle--icon)[aria-expanded="true"] > i.fe-chevron-up,
.lux-emp-summary__toggle:not(.lux-summary-toggle--icon)[aria-expanded="true"] > i.fe-chevron-up,
.lux-acct-summary__toggle:not(.lux-summary-toggle--icon)[aria-expanded="true"] > i.fe-chevron-up {
    display: inline-block;
    animation: lux-summary-chevron-hint-up 1.85s ease-in-out infinite;
}

@keyframes lux-summary-chevron-hint {
    0%, 70%, 100% {
        transform: translateY(0);
    }
    35% {
        transform: translateY(3px);
    }
}

@keyframes lux-summary-chevron-hint-up {
    0%, 70%, 100% {
        transform: translateY(0);
