/* ========== luxury-assist-dock.css ========== */

/* ========== Assist dock — draggable FAB + icon stack ========== */

.lux-assist-dock {
    position: fixed;
    right: 0;
    z-index: 1040;
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 0.55rem;
    pointer-events: auto;
    touch-action: none;
}

.lux-assist-dock.is-dragging {
