.lux-assist-dock__backdrop {
    position: fixed;
    inset: 0;
    z-index: 1039;
    border: none;
    padding: 0;
    margin: 0;
    background: transparent;
    cursor: default;
    pointer-events: auto;
}

.lux-assist-dock__icons {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 0.55rem;
    padding-right: 6px;
