        max-height 0.28s ease,
        opacity 0.22s ease,
        transform 0.22s ease;
}

.lux-assist-dock__icons.is-visible {
    max-height: 320px;
    opacity: 1;
    transform: translateY(0);
}

@keyframes luxAssistIconsIn {
