    color: #334155;
}

.lux-activity-detail-popover__mosaic-head span {
    display: block;
    margin-top: 0.04rem;
    font-size: 0.6875rem;
    font-weight: 600;
    color: #64748b;
}

.lux-activity-detail-popover__tiles {
    flex: 1;
    min-height: 0;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.4rem;
    padding: 0.5rem 0.7rem 0.65rem;
    align-content: start;
    overflow-y: auto;
    overscroll-behavior: contain;
}

.lux-activity-detail-popover__tile-group-label {
    grid-column: 1 / -1;
    padding: 0.18rem 0.08rem 0.05rem;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-activity-detail-popover__tile-group-label:not(:first-child) {
    margin-top: 0.12rem;
    padding-top: 0.28rem;
    border-top: 1px dashed rgba(226, 232, 240, 0.95);
}

.lux-activity-detail-popover__tile {
    display: flex;
    align-items: flex-start;
    gap: 0.3rem;
    padding: 0.35rem 0.38rem;
    border: 0px solid rgba(241, 245, 249, 0.98);
    border-radius: 12px;
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.88));
}

.lux-activity-detail-popover__tile-icon {
    display: inline-grid;
    place-items: center;
    width: 1.2rem;
    height: 1.2rem;
    border-radius: 7px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary-dark, #3730a3);
    flex-shrink: 0;
    font-size: 0.6875rem;
}

.lux-activity-detail-popover__tile-copy {
    min-width: 0;
}

.lux-activity-detail-popover__tile-copy > span {
    display: block;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-activity-detail-popover__tile-copy strong {
    display: block;
    margin-top: 0.06rem;
    font-size: 0.625rem;
    font-weight: 700;
    color: #0f172a;
    line-height: 1.35;
    overflow: visible;
    text-overflow: unset;
    white-space: normal;
    word-break: break-word;
}

.lux-activity-detail-popover__tile.is-key-date {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18);
    background: linear-gradient(180deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.05), rgba(255, 255, 255, 0.98));
}

.lux-activity-detail-popover__tile.is-key-date strong {
    font-size: 0.6875rem;
    font-weight: 800;
    color: #1e1b4b;
}

.lux-activity-detail-popover__tile.is-key-person strong {
    font-weight: 800;
    color: #334155;
}

.lux-activity-detail-popover__tile-copy em {
    display: block;
    margin-top: 0.05rem;
    font-style: normal;
    font-size: 0.6875rem;
    font-weight: 700;
    color: #64748b;
}

.lux-activity-detail-popover__tile-input {
    width: 100%;
    margin-top: 0.06rem;
    min-height: 1.35rem;
    padding: 0.12rem 0.32rem;
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.25);
    border-radius: 7px;
    font-size: 0.625rem;
    font-weight: 700;
}

.lux-activity-detail-popover__foot {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.45rem;
    padding: 0.55rem 0.9rem;
    border-top: 1px solid rgba(226, 232, 240, 0.9);
    background: rgba(248, 250, 252, 0.96);
    flex-shrink: 0;
}

.lux-activity-detail-popover__foot-left,
.lux-activity-detail-popover__foot-right {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
}

.lux-activity-detail-popover__btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.28rem;
    min-height: 1.85rem;
    padding: 0 0.75rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 9911px;
    background: rgba(255, 255, 255, 0.95);
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    color: #64748b;
    cursor: pointer;
}

.lux-activity-detail-popover__btn.is-ghost {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
    color: var(--lux-primary-dark, #3730a3);
}

.lux-activity-detail-popover__btn.is-primary {
    border: none;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
    color: #fff;
    box-shadow: 0 6px 18px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.25);
}

.lux-activity-detail-popover__btn.is-checklist.is-open {
    border-color: rgba(245, 158, 11, 0.35);
    background: rgba(245, 158, 11, 0.1);
    color: #b45309;
}

.lux-activity-detail-popover__btn.is-checklist.is-progress {
    border-color: rgba(99, 102, 241, 0.35);
    background: rgba(99, 102, 241, 0.1);
    color: #4338ca;
}

.lux-activity-detail-popover__btn.is-checklist.is-done {
    border-color: rgba(16, 185, 129, 0.35);
    background: rgba(16, 185, 129, 0.1);
    color: #047857;
}

@media (max-width: 900px) {
    .lux-activity-detail-popover {
        width: min(96vw, 52rem);
        height: min(92vh, 46rem);
        max-height: min(92vh, 46rem);
    }

    .lux-activity-detail-popover__strip,
    .lux-activity-detail-popover__insights-row,
    .lux-activity-detail-popover__grid,
    .lux-activity-detail-popover__layout,
    .lux-activity-detail-popover__meters {
        grid-template-columns: 1fr;
    }

    .lux-activity-detail-popover__tiles {
        grid-template-columns: 1fr;
    }

    .lux-activity-detail-popover__canvas {
        overflow: auto;
    }
}

/* ========== luxury-search.css ========== */

/* ========== Global Search — luxury full-width workspace page ========== */

.lux-search-page {
    --lux-search-radius: 22px;
    --lux-search-radius-sm: 14px;
    width: 100%;
    max-width: none;
    padding: 0 16px 28px;
    box-sizing: border-box;
}

/* —— Hero —— */
.lux-search-hero {
    position: relative;
    margin: 8px 0 16px;
    padding: 24px 28px;
    border-radius: var(--lux-search-radius);
    border: 0px solid rgba(226, 232, 240, 0.95);
    background: linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.92));
    box-shadow: 0 24px 60px rgba(15, 23, 42, 0.07);
    overflow: hidden;
}

.lux-search-hero--compact {
    padding: 20px 24px;
}

.lux-search-hero__glow {
    position: absolute;
    top: -45%;
    right: -5%;
    width: 360px;
    height: 360px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18), transparent 70%);
    pointer-events: none;
}

.lux-search-hero__glow--left {
    top: auto;
    right: auto;
    bottom: -55%;
    left: -6%;
    width: 280px;
    height: 280px;
    background: radial-gradient(circle, rgba(20, 184, 166, 0.12), transparent 70%);
}

.lux-search-hero__inner {
    position: relative;
    z-index: 1;
}

.lux-search-hero__inner--split {
    display: grid;
    grid-template-columns: minmax(220px, 340px) minmax(0, 1fr);
    gap: 1.5rem;
    align-items: center;
}

.lux-search-hero__copy {
    min-width: 0;
}

.lux-search-hero__kicker {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    margin: 0 0 0.4rem;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-search-hero__kicker i {
    color: var(--lux-primary, #5b5ff4);
}

.lux-search-hero__title {
    margin: 0 0 0.3rem;
    font-size: clamp(1.35rem, 2.2vw, 1.75rem);
    font-weight: 800;
    letter-spacing: -0.04em;
    line-height: 1.15;
    color: #0f172a;
}

.lux-search-hero__subtitle {
    margin: 0;
    font-size: 0.875rem;
    line-height: 1.45;
    color: #64748b;
}

/* —— Search bar —— */
.lux-search-bar {
    display: flex;
    align-items: stretch;
    gap: 0.625rem;
    padding: 0.4rem;
    border-radius: 9911px;
    background: #fff;
    border: 0px solid rgba(148, 163, 184, 0.35);
    box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.8) inset,
        0 12px 32px rgba(15, 23, 42, 0.08);
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
    width: 100%;
}

.lux-search-bar:focus-within {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.45);
    box-shadow:
        0 0 0 3px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12),
        0 12px 32px rgba(15, 23, 42, 0.08);
}

.lux-search-bar__icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    flex-shrink: 0;
    color: #94a3b8;
    font-size: 1.125rem;
}

.lux-search-bar__input {
    flex: 1;
    min-width: 0;
    border: none;
    background: transparent;
    font-size: 1rem;
    font-weight: 500;
    color: #0f172a;
    padding: 0.65rem 0;
    outline: none;
}

.lux-search-bar__input::placeholder {
    color: #94a3b8;
    font-weight: 400;
}

.lux-search-bar__clear {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    margin: auto 0;
    padding: 0;
    border: none;
    border-radius: 9911px;
    background: #f1f5f9;
    color: #64748b;
    cursor: pointer;
    flex-shrink: 0;
    transition: background 0.15s ease, color 0.15s ease;
}

.lux-search-bar__clear:hover {
    background: #e2e8f0;
    color: #0f172a;
}

.lux-search-bar__submit {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    min-width: 108px;
    padding: 0 1.25rem;
    border: none;
    border-radius: 9911px;
    font-size: 0.875rem;
    font-weight: 700;
    color: #fff;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-accent, #14b8a6));
    box-shadow: 0 8px 20px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.32);
    cursor: pointer;
    flex-shrink: 0;
    transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.lux-search-bar__submit:hover:not(:disabled) {
    transform: translateY(-1px);
    box-shadow: 0 12px 24px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.38);
}

.lux-search-bar__submit:disabled {
    opacity: 0.55;
    cursor: not-allowed;
}

.lux-search-bar__submit.is-loading {
    pointer-events: none;
}

/* —— Layout: sidebar + results panel —— */
.lux-search-layout {
    display: grid;
    grid-template-columns: 260px minmax(0, 1fr);
    gap: 16px;
    align-items: start;
    min-height: calc(100vh - 220px);
}

.lux-search-sidebar {
    display: flex;
    flex-direction: column;
    gap: 12px;
    position: sticky;
    top: 72px;
}

.lux-search-sidebar__card {
    padding: 1rem;
    border-radius: var(--lux-search-radius-sm);
    border: 0px solid rgba(226, 232, 240, 0.95);
    background: #fff;
    box-shadow: 0 8px 24px rgba(15, 23, 42, 0.04);
}

.lux-search-sidebar__title {
    margin: 0 0 0.75rem;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: #64748b;
}

/* —— Filters —— */
.lux-search-filters--stack {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

.lux-search-filter {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.45rem 0.875rem;
    border-radius: 12px;
    border: 0px solid #e2e8f0;
    background: #fff;
    font-size: 0.8125rem;
    font-weight: 700;
    color: #475569;
    cursor: pointer;
    transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
}

.lux-search-filter--stack {
    width: 100%;
    justify-content: space-between;
    text-align: left;
}

.lux-search-filter__leading {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
}

.lux-search-filter__leading i {
    font-size: 0.9375rem;
    opacity: 0.85;
}

.lux-search-filter:hover:not(:disabled) {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.25);
    color: var(--lux-primary, #5b5ff4);
}

.lux-search-filter:disabled {
    opacity: 0.45;
    cursor: not-allowed;
}

.lux-search-filter.is-active {
    color: #fff;
    border-color: transparent;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-accent, #14b8a6));
    box-shadow: 0 6px 16px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
}

.lux-search-filter__count {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 1.35rem;
    height: 1.35rem;
    padding: 0 0.35rem;
    border-radius: 9911px;
    font-size: 0.6875rem;
    font-weight: 800;
    background: rgba(15, 23, 42, 0.08);
}

.lux-search-filter.is-active .lux-search-filter__count {
    background: rgba(255, 255, 255, 0.22);
}

/* —— Sidebar insights —— */
.lux-search-insights {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0.625rem;
}

.lux-search-insights li {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    padding: 0.625rem 0.75rem;
    border-radius: 12px;
    background: #f8fafc;
    border: 0px solid #e2e8f0;
    font-size: 0.75rem;
    color: #64748b;
}

.lux-search-insights strong {
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-search-sidebar-tips {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.lux-search-sidebar-tips li {
    display: flex;
    gap: 0.75rem;
    align-items: flex-start;
}

.lux-search-sidebar-tips i {
    flex-shrink: 0;
    width: 28px;
    height: 28px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--lux-primary, #5b5ff4);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
    font-size: 0.875rem;
}

.lux-search-sidebar-tips strong {
    display: block;
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
    margin-bottom: 0.1rem;
}

.lux-search-sidebar-tips span {
    font-size: 0.75rem;
    color: #64748b;
    line-height: 1.4;
}

/* —— Results panel —— */
.lux-search-panel {
    border-radius: var(--lux-search-radius);
    border: 0px solid rgba(226, 232, 240, 0.95);
    background: #fff;
    box-shadow: 0 16px 40px rgba(15, 23, 42, 0.06);
    overflow: hidden;
    min-height: 480px;
    display: flex;
    flex-direction: column;
}

.lux-search-panel__header {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.75rem;
    padding: 1.125rem 1.25rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.9);
    background: linear-gradient(
        135deg,
        rgba(var(--lux-primary-rgb, 91, 95, 244), 0.04) 0%,
        rgba(20, 184, 166, 0.03) 100%
    );
}

.lux-search-panel__kicker {
    margin: 0 0 0.2rem;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-search-panel__title {
    margin: 0;
    font-size: 1.0625rem;
    font-weight: 700;
    color: #334155;
    line-height: 1.35;
}

.lux-search-panel__title strong {
    color: #0f172a;
    font-weight: 800;
}

.lux-search-panel__badge {
    font-size: 0.6875rem;
    font-weight: 700;
    padding: 0.4rem 0.75rem;
    border-radius: 9911px;
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16);
    white-space: nowrap;
}

.lux-search-panel__body {
    flex: 1;
    padding: 1rem 1.25rem 1.25rem;
    display: flex;
    flex-direction: column;
}

/* —— Results list —— */
.lux-search-results {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    flex: 1;
}

.lux-search-result {
    display: grid;
    grid-template-columns: auto auto minmax(0, 1fr) auto;
    gap: 0.875rem;
    align-items: start;
    padding: 1.125rem 1.25rem;
    border-radius: var(--lux-search-radius-sm);
    border: 0px solid rgba(226, 232, 240, 0.95);
    background: linear-gradient(180deg, #fff 0%, #fafbfc 100%);
    box-shadow: 0 6px 18px rgba(15, 23, 42, 0.04);
    transition: border-color 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
}

.lux-search-result:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.24);
    box-shadow: 0 14px 32px rgba(15, 23, 42, 0.08);
    transform: translateY(-1px);
}

.lux-search-result__rank-col {
    padding-top: 0.15rem;
}

.lux-search-result__rank {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 2rem;
    height: 2rem;
    padding: 0 0.35rem;
    border-radius: 12px;
    font-size: 0.75rem;
    font-weight: 800;
    color: #64748b;
    background: #f1f5f9;
    border: 0px solid #e2e8f0;
}

.lux-search-result__rank.is-top {
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.2);
}

.lux-search-result__icon {
    flex-shrink: 0;
    width: 44px;
    height: 44px;
    border-radius: 13px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.125rem;
}

.lux-search-result__icon--project {
    color: var(--lux-primary, #5b5ff4);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-search-result__icon--task {
    color: #0d9488;
    background: rgba(20, 184, 166, 0.12);
}

.lux-search-result__body {
    min-width: 0;
}

.lux-search-result__head {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.45rem;
    margin-bottom: 0.35rem;
}

.lux-search-result__type {
    font-size: 0.75rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    padding: 0.2rem 0.625rem;
    border-radius: 9911px;
}

.lux-search-result__type--project {
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-search-result__type--task {
    color: #0f766e;
    background: rgba(20, 184, 166, 0.12);
}

.lux-search-result__path {
    font-size: 0.6875rem;
    font-weight: 600;
    color: #94a3b8;
    font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}

.lux-search-result__relevance-label {
    margin-left: auto;
    font-size: 0.75rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b;
    padding: 0.15rem 0.45rem;
    border-radius: 9911px;
    background: #f8fafc;
    border: 0px solid #e2e8f0;
}

.lux-search-result__title {
    display: block;
    margin: 0 0 0.35rem;
    font-size: 1.0625rem;
    font-weight: 800;
    letter-spacing: -0.02em;
    line-height: 1.35;
    color: #0f172a;
    text-decoration: none;
    transition: color 0.15s ease;
}

.lux-search-result__title:hover {
    color: var(--lux-primary, #5b5ff4);
    text-decoration: none;
}

.lux-search-result__title del {
    color: #94a3b8;
}

.lux-search-result__summary {
    margin: 0 0 0.65rem;
    font-size: 0.8125rem;
    line-height: 1.55;
    color: #64748b;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.lux-search-result__summary mark,
.lux-search-result__title mark {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16);
    color: var(--lux-primary-dark, #3730a3);
    padding: 0 0.15rem;
    border-radius: 3px;
}

.lux-search-result__badge {
    font-size: 0.75rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    padding: 0.2rem 0.45rem;
    border-radius: 9911px;
    color: #b91c1c;
    background: #fee2e2;
}

.lux-search-result__footer {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
}

.lux-search-result__reasons {
    display: flex;
    flex-wrap: wrap;
    gap: 0.35rem;
}

.lux-search-result__reason {
    font-size: 0.75rem;
    font-weight: 700;
    padding: 0.2rem 0.625rem;
    border-radius: 9911px;
    color: #475569;
    background: #f1f5f9;
    border: 0px solid #e2e8f0;
}

.lux-search-result__meter {
    display: flex;
    align-items: center;
    gap: 0.625rem;
    min-width: 120px;
}

.lux-search-result__meter-track {
    flex: 1;
    height: 6px;
    border-radius: 9911px;
    background: #e2e8f0;
    overflow: hidden;
    min-width: 72px;
}

.lux-search-result__meter-fill {
    height: 100%;
    border-radius: inherit;
    background: linear-gradient(90deg, var(--lux-primary, #5b5ff4), var(--lux-accent, #14b8a6));
    transition: width 0.35s ease;
}

.lux-search-result__meter-value {
    font-size: 0.6875rem;
    font-weight: 800;
    color: #64748b;
    white-space: nowrap;
}

.lux-search-result__open {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 38px;
    height: 38px;
    margin-top: 0.15rem;
    border-radius: 12px;
    color: #64748b;
    background: #f8fafc;
    border: 0px solid #e2e8f0;
    text-decoration: none;
    transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease, transform 0.15s ease;
}

.lux-search-result__open:hover {
    color: #fff;
    background: var(--lux-primary, #5b5ff4);
    border-color: transparent;
    transform: translateY(-1px);
    text-decoration: none;
}

/* —— Pagination —— */
.lux-search-pagination {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 0.875rem;
    margin-top: 1.25rem;
    padding-top: 1rem;
    border-top: 1px solid #e2e8f0;
}

.lux-search-pagination__summary {
    font-size: 0.8125rem;
    color: #64748b;
}

.lux-search-pagination__summary strong {
    color: #0f172a;
    font-weight: 800;
}

.lux-search-pagination__controls {
    display: flex;
    align-items: center;
    gap: 0.35rem;
}

.lux-search-pagination__btn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    padding: 0;
    border: 0px solid #e2e8f0;
    border-radius: 12px;
    background: #fff;
    color: #475569;
    cursor: pointer;
    transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.lux-search-pagination__btn:hover:not(:disabled) {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.3);
    color: var(--lux-primary, #5b5ff4);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
}

.lux-search-pagination__btn:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.lux-search-pagination__pages {
    display: flex;
    align-items: center;
    gap: 0.25rem;
}

.lux-search-pagination__page {
    min-width: 36px;
    height: 36px;
    padding: 0 0.625rem;
    border: 0px solid transparent;
    border-radius: 12px;
    background: transparent;
    font-size: 0.8125rem;
    font-weight: 700;
    color: #64748b;
    cursor: pointer;
    transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.lux-search-pagination__page:hover {
    background: #f1f5f9;
    color: #0f172a;
}

.lux-search-pagination__page.is-active {
    color: #fff;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-accent, #14b8a6));
    border-color: transparent;
    box-shadow: 0 4px 12px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
}

.lux-search-pagination__ellipsis {
    padding: 0 0.25rem;
    color: #94a3b8;
    font-size: 0.875rem;
    user-select: none;
}

.lux-search-pagination__size {
    display: flex;
    align-items: center;
    gap: 0.625rem;
    font-size: 0.75rem;
    font-weight: 600;
    color: #64748b;
}

.lux-search-pagination__size select {
    height: 36px;
    padding: 0 0.65rem;
    border-radius: 12px;
    border: 0px solid #e2e8f0;
    background: #fff;
    font-size: 0.8125rem;
    font-weight: 700;
    color: #0f172a;
    cursor: pointer;
}

/* —— Landing / empty —— */
.lux-search-landing {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 2.5rem 1.5rem;
    border-radius: var(--lux-search-radius-sm);
    border: 0px dashed rgba(148, 163, 184, 0.4);
    background: rgba(248, 250, 252, 0.6);
    text-align: center;
    min-height: 320px;
}

.lux-search-landing__icon {
    width: 56px;
    height: 56px;
    margin: 0 auto 0.875rem;
    border-radius: 16px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.5rem;
    color: var(--lux-primary, #5b5ff4);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-search-landing__title {
    margin: 0 0 0.35rem;
    font-size: 1.0625rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-search-landing__text {
    margin: 0;
    font-size: 0.875rem;
    color: #64748b;
    line-height: 1.5;
    max-width: 32rem;
}

.lux-search-empty {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 2.5rem 1.5rem;
    text-align: center;
    min-height: 320px;
}

.lux-search-empty__icon {
    width: 64px;
    height: 64px;
    margin: 0 auto 1rem;
    border-radius: 18px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.75rem;
    color: #94a3b8;
    background: #f1f5f9;
}

.lux-search-empty__title {
    margin: 0 0 0.35rem;
    font-size: 1.125rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-search-empty__text {
    margin: 0;
    font-size: 0.875rem;
    color: #64748b;
    line-height: 1.5;
    max-width: 28rem;
}

/* —— Skeleton —— */
.lux-search-skeleton {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.lux-search-skeleton__row {
    display: grid;
    grid-template-columns: auto auto minmax(0, 1fr);
    gap: 0.875rem;
    padding: 1.125rem 1.25rem;
    border-radius: var(--lux-search-radius-sm);
    border: 0px solid #e2e8f0;
    background: #fff;
}

.lux-search-skeleton__icon {
    width: 44px;
    height: 44px;
    border-radius: 13px;
}

.lux-search-skeleton__lines {
    display: flex;
    flex-direction: column;
    gap: 0.625rem;
}

@media (max-width: 1100px) {
    .lux-search-hero__inner--split {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 900px) {
    .lux-search-layout {
        grid-template-columns: 1fr;
        min-height: auto;
    }

    .lux-search-sidebar {
        position: static;
    }

    .lux-search-filters--stack {
        flex-direction: row;
        flex-wrap: wrap;
    }

    .lux-search-filter--stack {
        width: auto;
        flex: 1;
        min-width: 140px;
    }
}

@media (max-width: 767px) {
    .lux-search-page {
        padding: 0 12px 20px;
    }

    .lux-search-hero,
    .lux-search-hero--compact {
        padding: 16px;
        border-radius: 16px;
    }

    .lux-search-bar {
        flex-wrap: wrap;
        border-radius: 16px;
        padding: 0.625rem;
    }

    .lux-search-bar__input {
        width: 100%;
        padding-left: 0.25rem;
    }

    .lux-search-bar__submit {
        width: 100%;
        min-height: 44px;
        border-radius: 12px;
    }

    .lux-search-result {
        grid-template-columns: auto minmax(0, 1fr);
        grid-template-rows: auto auto;
    }

    .lux-search-result__rank-col {
        grid-column: 1;
        grid-row: 1;
    }

    .lux-search-result__icon {
        grid-column: 2;
        grid-row: 1;
        justify-self: end;
    }

    .lux-search-result__body {
        grid-column: 1 / -1;
        grid-row: 2;
    }

    .lux-search-result__open {
        display: none;
    }

    .lux-search-pagination {
        flex-direction: column;
        align-items: stretch;
    }

    .lux-search-pagination__controls {
        justify-content: center;
    }

    .lux-search-pagination__size {
        justify-content: center;
    }
}

body.lux-shell-dark .lux-search-hero,
body.lux-shell-dark .lux-search-panel,
body.lux-shell-dark .lux-search-sidebar__card,
body.lux-shell-dark .lux-search-result {
    background: rgba(30, 41, 59, 0.92);
    border-color: rgba(51, 65, 85, 0.9);
}

body.lux-shell-dark .lux-search-hero__title,
body.lux-shell-dark .lux-search-panel__title strong,
body.lux-shell-dark .lux-search-result__title,
body.lux-shell-dark .lux-search-empty__title,
body.lux-shell-dark .lux-search-landing__title {
    color: #f8fafc;
}

body.lux-shell-dark .lux-search-bar {
    background: rgba(15, 23, 42, 0.6);
    border-color: rgba(51, 65, 85, 0.9);
}

body.lux-shell-dark .lux-search-bar__input {
    color: #f8fafc;
}

body.lux-shell-dark .lux-search-filter {
    background: rgba(30, 41, 59, 0.88);
    border-color: rgba(51, 65, 85, 0.9);
    color: #cbd5e1;
}

body.lux-shell-dark .lux-search-landing {
    background: rgba(15, 23, 42, 0.5);
    border-color: rgba(51, 65, 85, 0.7);
}

body.lux-shell-dark .lux-search-insights li,
body.lux-shell-dark .lux-search-result__reason,
body.lux-shell-dark .lux-search-result__rank {
    background: rgba(15, 23, 42, 0.55);
    border-color: rgba(51, 65, 85, 0.9);
}

body.lux-shell-dark .lux-search-insights strong {
    color: #f8fafc;
}

body.lux-shell-dark .lux-search-pagination__btn,
body.lux-shell-dark .lux-search-pagination__size select {
    background: rgba(30, 41, 59, 0.88);
    border-color: rgba(51, 65, 85, 0.9);
    color: #cbd5e1;
}

/* ========== luxury-appconfig.css ========== */

/* ========== Application Config — luxury admin layout ========== */

.lux-appconfig {
    --lux-ac-radius: 12px;
    --lux-ac-radius-sm: 12px;
    width: 100%;
    padding: 0;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    height: calc(100vh - 64px);
    min-height: 0;
}

/* —— Hero —— */
.lux-appconfig-hero {
    position: relative;
    z-index: 20;
    display: flex;
    flex-direction: column;
    gap: 0;
    margin: 0 0 4px;
    border-radius: var(--lux-ac-radius);
    border: 0px solid rgba(226, 232, 240, 0.95);
    background: linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.94));
    box-shadow: 0 6px 18px rgba(15, 23, 42, 0.04);
    overflow: visible;
    flex-shrink: 0;
}

.lux-appconfig-hero__glow {
    position: absolute;
    top: -55%;
    right: -4%;
    width: 320px;
    height: 320px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14), transparent 70%);
    pointer-events: none;
}

.lux-appconfig-hero__top {
    position: relative;
    z-index: 1;
    display: flex;
    flex-wrap: wrap;
    align-items: stretch;
    justify-content: space-between;
    gap: 0.45rem;
    padding: 8px 10px;
    border-bottom: 1px solid rgba(226, 232, 240, 0.85);
}

.lux-appconfig-hero__brand {
    display: flex;
    align-items: flex-start;
    gap: 0.65rem;
    min-width: min(100%, 320px);
    flex: 1 1 280px;
}

.lux-appconfig-hero__icon {
    flex-shrink: 0;
    width: 38px;
    height: 38px;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.05rem;
    color: var(--lux-primary, #5b5ff4);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14);
}

.lux-appconfig-hero__intro {
    min-width: 0;
}

.lux-appconfig-hero__kicker {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    margin: 0 0 0.2rem;
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-appconfig-hero__kicker i {
    color: var(--lux-primary, #5b5ff4);
}

.lux-appconfig-hero__title {
    margin: 0 0 0.2rem;
    font-size: clamp(1rem, 1.6vw, 1.25rem);
    font-weight: 800;
    letter-spacing: -0.03em;
    color: #0f172a;
    line-height: 1.15;
}

.lux-appconfig-hero__subtitle {
    margin: 0;
    font-size: 0.75rem;
    line-height: 1.45;
    color: #64748b;
    max-width: 34rem;
}

.lux-appconfig-hero__guide-links {
    display: inline-flex;
    flex-wrap: wrap;
    gap: 0.3rem;
    margin-top: 0.65rem;
}

.lux-appconfig-hero__guide-link {
    appearance: none;
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    margin: 0;
    padding: 0.35rem 0.7rem;
    border-radius: 999px;
    border: 1px solid rgba(15, 118, 110, 0.28);
    background: linear-gradient(180deg, rgba(45, 212, 191, 0.18), rgba(45, 212, 191, 0.08));
    color: #0f766e;
    font-size: 0.72rem;
    font-weight: 700;
    cursor: pointer;
}

.lux-appconfig-hero__guide-link--compact {
    gap: 0.22rem;
    padding: 0.14rem 0.35rem 0.14rem 0.14rem;
    font-size: 0.6rem;
    letter-spacing: 0.01em;
}

.lux-appconfig-hero__guide-link--compact > i:first-child {
    width: 1.05rem;
    height: 1.05rem;
    border-radius: 999px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 0.58rem;
    background: rgba(255, 255, 255, 0.85);
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.08);
}

.lux-appconfig-hero__guide-link-ext {
    margin-left: 0.02rem;
    font-size: 0.55rem;
    opacity: 0.75;
}

.lux-appconfig-hero__guide-link--ghost {
    border-color: rgba(100, 116, 139, 0.28);
    background: rgba(255, 255, 255, 0.7);
    color: #475569;
}

.lux-appconfig-hero__tip-link {
    appearance: none;
    border: 0;
    padding: 0;
    margin: 0;
    background: transparent;
    color: #0f766e;
    font-weight: 700;
    text-decoration: underline;
    cursor: pointer;
}

.lux-appconfig-hero__stats {
    display: grid;
    grid-template-columns: repeat(4, minmax(72px, 1fr));
    gap: 0.35rem;
    flex: 1 1 320px;
    max-width: 420px;
}

.lux-appconfig-hero__stat {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    min-width: 0;
    padding: 0.4rem 0.45rem;
    border-radius: 11px;
    border: 0px solid rgba(226, 232, 240, 0.95);
    background: rgba(255, 255, 255, 0.82);
}

.lux-appconfig-hero__stat-icon {
    flex-shrink: 0;
    width: 24px;
    height: 24px;
    border-radius: 7px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.75rem;
    color: var(--lux-primary, #5b5ff4);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
}

.lux-appconfig-hero__stat-body {
    display: flex;
    flex-direction: column;
    min-width: 0;
    line-height: 1.15;
}

.lux-appconfig-hero__stat-body strong {
    font-size: 0.875rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-appconfig-hero__stat-body span {
    font-size: 0.6875rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #94a3b8;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.lux-appconfig-hero__context,
.lux-appconfig-hero__guide {
    position: relative;
    z-index: 1;
    padding: 8px 12px 12px;
}

.lux-appconfig-hero__context {
    display: block;
    background: linear-gradient(
        90deg,
        rgba(var(--lux-primary-rgb, 91, 95, 244), 0.05) 0%,
        rgba(20, 184, 166, 0.04) 100%
    );
}

.lux-appconfig-hero__context-row {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.65rem 1rem;
    width: 100%;
}

.lux-appconfig-hero__context-left {
    display: flex;
    align-items: flex-start;
    gap: 0.55rem;
    flex: 1 1 280px;
    min-width: 0;
}

.lux-appconfig-hero__context-actions {
    display: flex;
    flex-wrap: wrap;
    align-items: stretch;
    justify-content: flex-end;
    gap: 0.35rem;
    flex: 0 0 auto;
    margin-left: auto;
}

.lux-appconfig-hero__context-actions .lux-appconfig-hero__meta-item {
    flex: 0 0 auto;
}

.lux-appconfig-hero__meta-static--compact {
    min-height: 40px;
    padding: 0.3rem 0.55rem;
    border-color: rgba(226, 232, 240, 0.95);
    background: #fff;
}

.lux-appconfig-hero__meta-item--compact {
    min-width: 72px;
}

/* —— Hero identity strip (Name / Parent / Type) —— */
.lux-hero-identity {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.35rem 0.65rem;
    margin-top: 0.35rem;
    width: 100%;
}

.lux-hero-identity__divider {
    flex-shrink: 0;
    width: 1px;
    height: 1.1rem;
    background: rgba(148, 163, 184, 0.45);
}

.lux-hero-identity__item {
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.35rem 0.45rem;
    min-width: 0;
    max-width: 100%;
}

.lux-hero-identity__item.is-editing {
    flex: 1 1 220px;
    align-items: flex-start;
}

.lux-hero-identity__label {
    flex-shrink: 0;
    font-size: 0.75rem;
    font-weight: 800;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    color: #94a3b8;
    line-height: 1.3;
}

.lux-hero-identity__value-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    max-width: 100%;
    min-height: 28px;
    padding: 0.2rem 0.45rem;
    border: 1px dashed rgba(148, 163, 184, 0.45);
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.85);
    cursor: pointer;
    text-align: left;
    transition:
        border-color 0.12s ease,
        background 0.12s ease,
        box-shadow 0.12s ease;
}

.lux-hero-identity__value-btn:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.4);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.04);
    box-shadow: 0 1px 4px rgba(15, 23, 42, 0.05);
}

.lux-hero-identity__value {
    font-size: 0.8125rem;
    font-weight: 700;
    color: #0f172a;
    line-height: 1.35;
    word-break: break-word;
    white-space: normal;
}

.lux-hero-identity__edit-hint {
    flex-shrink: 0;
    font-size: 0.6875rem;
    color: var(--lux-primary, #5b5ff4);
    opacity: 0.75;
}

.lux-hero-identity__value-btn:hover .lux-hero-identity__edit-hint {
    opacity: 1;
}

.lux-hero-identity__editor {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.35rem;
    flex: 1;
    min-width: min(100%, 200px);
    padding: 0.25rem 0.35rem;
    border-radius: 8px;
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.3);
    background: #fff;
    box-shadow: 0 2px 8px rgba(15, 23, 42, 0.06);
}

.lux-hero-identity__input,
.lux-hero-identity__select {
    flex: 1 1 140px;
    min-width: 0;
    height: 30px;
    padding: 0 0.625rem;
    border-radius: 7px;
    border: 1px solid #e2e8f0;
    font-size: 0.75rem;
    font-weight: 600;
    color: #0f172a;
    background: #fff;
}

.lux-hero-identity__input:focus,
.lux-hero-identity__select:focus {
    outline: none;
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.45);
    box-shadow: 0 0 0 2px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-hero-identity__editor-actions {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    flex-shrink: 0;
