}

.lux-ac-nav__search-clear {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 22px;
    height: 22px;
    padding: 0;
    border: none;
    border-radius: 9911px;
    background: #f1f5f9;
    color: #64748b;
    cursor: pointer;
}

.lux-ac-nav__add,
.lux-ac-nav__icon-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    padding: 0;
    border: none;
    border-radius: 8px;
    font-size: 0.8125rem;
    color: #64748b;
    background: #f1f5f9;
    cursor: pointer;
    flex-shrink: 0;
    transition: background 0.15s ease, color 0.15s ease;
}

.lux-ac-nav__add {
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-ac-nav__add:hover,
.lux-ac-nav__icon-btn:hover {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14);
    color: var(--lux-primary, #5b5ff4);
}

.lux-ac-nav__selection {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.35rem 0.55rem;
    margin: 0.35rem 0.55rem 0;
    border-radius: 8px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.07);
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    font-size: 0.6875rem;
    color: #64748b;
    min-width: 0;
}

.lux-ac-nav__selection strong {
    color: #0f172a;
    font-weight: 700;
    font-size: 0.75rem;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    min-width: 0;
}

.lux-ac-nav__tree-wrap {
    flex: 1;
    min-height: 0;
    overflow: auto;
    padding: 0.25rem 0.35rem 0.45rem;
    overscroll-behavior: contain;
}

.lux-ac-nav__footer {
    padding: 0.4rem 0.65rem;
    border-top: 1px solid #e2e8f0;
    background: #f8fafc;
    font-size: 0.75rem;
    font-weight: 600;
    color: #94a3b8;
}

/* —— Compact tree: single-level indent only (no depth stacking) —— */
.lux-ac-tree {
    display: flex;
    flex-direction: column;
    gap: 1px;
    min-width: 100%;
}

.lux-ac-tree-branch,
.lux-ac-tree-node {
    display: flex;
    flex-direction: column;
    min-width: 0;
}

.lux-ac-tree-children {
    margin-left: 12px;
    padding-left: 8px;
    border-left: 1px solid rgba(148, 163, 184, 0.35);
}

.lux-ac-tree-row {
    position: relative;
    display: flex;
    align-items: center;
    gap: 2px;
    min-height: 30px;
    padding: 1px 4px 1px 2px;
    border-radius: 8px;
    transition: background 0.12s ease, box-shadow 0.12s ease;
}

.lux-ac-tree-row:hover {
    background: #f1f5f9;
}

/* Tree selection — ring + solid icon + right check (not main-menu left bar) */
.lux-ac-tree-row.is-selected {
    padding-right: 22px;
    background: rgba(14, 116, 144, 0.07);
    box-shadow:
        0 0 0 1.5px rgba(14, 116, 144, 0.32),
        inset 0 1px 0 rgba(255, 255, 255, 0.55);
}

.lux-ac-tree-row.is-selected::after {
    content: "✓";
    position: absolute;
    right: 5px;
    top: 50%;
    transform: translateY(-50%);
    width: 15px;
    height: 15px;
    border-radius: 50%;
    background: linear-gradient(145deg, #0e7490 0%, #06b6d4 100%);
    color: #fff;
    font-size: 8px;
    font-weight: 800;
    line-height: 15px;
    text-align: center;
    box-shadow: 0 2px 5px rgba(14, 116, 144, 0.28);
    pointer-events: none;
}

.lux-ac-tree-row.is-selected .lux-ac-tree-name {
    font-weight: 700;
    color: var(--ac-tree-select-text);
}

.lux-ac-tree-row.is-selected .lux-ac-tree-icon--org,
.lux-ac-tree-row.is-selected .lux-ac-tree-icon--role {
    color: #fff;
    background: linear-gradient(145deg, #0e7490 0%, #06b6d4 100%);
    box-shadow: 0 2px 6px rgba(14, 116, 144, 0.22);
}

.lux-ac-tree-row.is-selected .lux-ac-tree-toggle {
    color: var(--ac-tree-select-accent);
}

.lux-ac-tree-row.is-selected .lux-ac-tree-badge {
    color: #0e7490;
    background: rgba(6, 182, 212, 0.12);
    border-color: rgba(14, 116, 144, 0.24);
}

.lux-ac-tree-row.is-disabled {
    opacity: 0.45;
}

.lux-ac-tree-toggle {
    flex-shrink: 0;
    width: 20px;
    height: 28px;
    margin: 0;
    padding: 0;
    border: none;
    border-radius: 6px;
    background: transparent;
    color: #64748b;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.75rem;
    transition: background 0.12s ease, color 0.12s ease;
}

.lux-ac-tree-toggle:hover {
    background: #e2e8f0;
    color: var(--lux-primary, #5b5ff4);
}

.lux-ac-tree-toggle.is-open i {
    transform: rotate(90deg);
}

.lux-ac-tree-toggle--spacer {
    width: 20px;
    flex-shrink: 0;
    pointer-events: none;
}

.lux-ac-tree-label {
    flex: 1;
    min-width: 0;
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 2px 4px 2px 0;
    border: none;
    background: transparent;
    text-align: left;
    cursor: pointer;
    border-radius: 6px;
}

.lux-ac-tree-label:disabled {
    cursor: not-allowed;
}

.lux-ac-tree-icon {
    flex-shrink: 0;
    width: 22px;
    height: 22px;
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.6875rem;
}

.lux-ac-tree-icon--org {
    color: var(--lux-primary, #5b5ff4);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-ac-tree-icon--role {
    color: #0d9488;
    background: rgba(20, 184, 166, 0.12);
}

.lux-ac-tree-copy {
    flex: 1;
    min-width: 0;
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 4px;
}

.lux-ac-tree-name {
    font-size: 0.75rem;
    font-weight: 600;
    color: #0f172a;
    line-height: 1.25;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    max-width: 100%;
}

.lux-ac-tree-badge {
    flex-shrink: 0;
    font-size: 0.6875rem;
    font-weight: 700;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    padding: 0.05rem 0.35rem;
    border-radius: 9911px;
    color: #64748b;
    background: #f1f5f9;
    border: 0px solid #e2e8f0;
    line-height: 1.35;
}

.lux-ac-tree-current {
    flex-shrink: 0;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    padding: 0.05rem 0.35rem;
    border-radius: 9911px;
    color: #047857;
    background: #d1fae5;
    line-height: 1.35;
}

.lux-ac-tree-create {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    margin: 2px 0 4px 28px;
    padding: 0.25rem;
    border-radius: 8px;
    background: #f8fafc;
    border: 0px dashed rgba(148, 163, 184, 0.4);
}

.lux-ac-tree-create__input {
    flex: 1;
    min-width: 0;
    height: 28px;
    padding: 0 0.625rem;
    border-radius: 6px;
    border: 0px solid #e2e8f0;
    font-size: 0.75rem;
    background: #fff;
}

.lux-ac-tree-create__input:focus {
    outline: none;
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.45);
    box-shadow: 0 0 0 3px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-ac-tree-create__btn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 30px;
    height: 30px;
    padding: 0;
    border: none;
    border-radius: 8px;
    background: #e2e8f0;
    color: #64748b;
    cursor: pointer;
}

.lux-ac-tree-create__btn--save:not(:disabled) {
    color: #fff;
    background: var(--lux-primary, #5b5ff4);
}

.lux-ac-tree-create__btn:disabled {
    opacity: 0.45;
    cursor: not-allowed;
}

.lux-ac-tree-empty {
    margin: 1rem 0.75rem;
    font-size: 0.8125rem;
    color: #64748b;
    text-align: center;
}

/* Legacy tree panel styles removed — use lux-ac-nav above */

/* —— Empty state —— */
.lux-appconfig-empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 420px;
    padding: 1.5rem 1rem;
