/* —— Config panel (right) —— */
.lux-appconfig-panel__card {
    border-radius: var(--lux-ac-radius);
    border: 0px solid rgba(226, 232, 240, 0.95);
    box-shadow: 0 8px 24px rgba(15, 23, 42, 0.05);
