}

.lux-ac-role-bar__eyebrow {
    display: block;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--lux-primary, #5b5ff4);
    margin-bottom: 0.12rem;
}

.lux-ac-role-bar__title-row {
    display: flex;
    align-items: baseline;
    gap: 0.4rem;
    flex-wrap: wrap;
}

.lux-ac-role-bar__title {
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.2;
}

.lux-ac-role-bar__id {
    font-size: 0.6875rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-ac-role-bar__hint {
    margin: 0.2rem 0 0;
    font-size: 0.75rem;
    line-height: 1.4;
    color: #64748b;
}

.lux-ac-role-bar__actions {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    flex-shrink: 0;
}

.lux-ac-role-bar__action-wrap {
    position: relative;
}

.lux-ac-role-bar__members-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    min-height: 2.5rem;
    padding: 0.35rem 0.55rem 0.35rem 0.4rem;
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18);
    border-radius: 12px;
