    border-radius: 9911px;
    font-size: 0.75rem;
    font-weight: 800;
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16);
}

.lux-ac-role-bar__refresh-btn {
    display: inline-flex;
