/* ========== luxury-auth.css ========== */

/* ========== Auth pages — luxury split layout ========== */

/* Lock auth pages to the viewport so the login card does not scroll. */
.auth {
    height: 100vh;
    height: 100dvh;
    max-height: 100vh;
    max-height: 100dvh;
    overflow: hidden;
}

body:has(.auth),
#root:has(.auth) {
    height: 100vh;
    height: 100dvh;
    overflow: hidden;
}

.auth .auth-screen {
    position: relative;
    min-height: 0;
    height: 100%;
    width: 100%;
    max-width: 100%;
    display: flex;
    overflow: hidden;
    background: #0c1222;
}

.auth-screen__backdrop {
    position: absolute;
    inset: 0;
    z-index: 0;
    background-color: #0c1222;
    background-image: url("/assets/images/login-background.jpeg");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
}

.auth-screen__backdrop::after {
    content: "";
    position: absolute;
    inset: 0;
    background:
        linear-gradient(
            112deg,
            rgba(8, 12, 28, 0.94) 0%,
            rgba(10, 22, 48, 0.88) 38%,
            rgba(13, 71, 90, 0.55) 52%,
            rgba(15, 23, 42, 0.72) 68%,
            rgba(8, 12, 28, 0.82) 100%
        ),
        radial-gradient(ellipse 80% 60% at 20% 80%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22), transparent 55%),
        radial-gradient(ellipse 60% 50% at 85% 20%, rgba(20, 184, 166, 0.12), transparent 50%);
    pointer-events: none;
}

.auth-screen__layout {
    position: relative;
    z-index: 1;
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    width: 100%;
    max-width: 100%;
    height: 100%;
    max-height: 100%;
    margin: 0;
    padding: 0;
    overflow: hidden;
}

/* —— Brand panel —— */
.auth-screen__brand {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    max-height: 100vh;
    padding: clamp(0.75rem, 2vh, 1.5rem) clamp(1.25rem, 3vw, 2rem);
    overflow: hidden;
}

.auth-screen__brand-scrim {
    position: absolute;
    inset: 0;
    background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.04) 0%, transparent 40%),
        linear-gradient(90deg, rgba(0, 0, 0, 0.35) 0%, transparent 70%);
    pointer-events: none;
}

.auth-screen__brand-content {
    position: relative;
    z-index: 1;
    width: 100%;
    max-width: 640px;
    color: #f8fafc;
}

@media (min-width: 992px) {
    .auth-screen__brand-content {
        transform: scale(min(1, calc((100vh - 2.5rem) / 940)));
        transform-origin: center center;
    }
}

.auth-screen__brand-logo {
    display: flex;
    align-items: center;
    gap: 18px;
    margin-bottom: 1.25rem;
    padding: 0;
    background: none;
    border: none;
    backdrop-filter: none;
}

.auth-screen__brand-mark {
    position: relative;
    flex-shrink: 0;
    width: 64px;
    height: 64px;
}

.auth-screen__brand-mark-glow {
    position: absolute;
    inset: -8px;
    border-radius: 22px;
    background: radial-gradient(circle, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.45), transparent 70%);
    filter: blur(8px);
    opacity: 0.85;
}

.auth-screen__brand-mark-ring {
    position: absolute;
    inset: 0;
    border-radius: 20px;
    padding: 2px;
    background: linear-gradient(145deg, rgba(255, 255, 255, 0.55), rgba(var(--lux-primary-rgb, 91, 95, 244), 0.85) 45%, rgba(20, 184, 166, 0.75));
    box-shadow:
        0 12px 32px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35),
        0 0 0 1px rgba(255, 255, 255, 0.12) inset;
}

.auth-screen__brand-mark-inner {
    position: absolute;
    inset: 2px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 18px;
    background: linear-gradient(160deg, #ffffff 0%, #f1f5f9 100%);
}

.auth-screen__brand-mark-icon {
    width: 36px;
    height: 36px;
    object-fit: contain;
}

.auth-screen__brand-wordmark {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 0;
    min-width: 0;
}

.auth-screen__brand-name-row {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
