    background: linear-gradient(
        145deg,
        rgba(255, 255, 255, 0.95) 0%,
        rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35) 42%,
        rgba(20, 184, 166, 0.28) 68%,
        rgba(255, 255, 255, 0.55) 100%
    );
