    margin: 0;
    font-size: 0.875rem;
    line-height: 1.55;
    color: #047857;
    font-weight: 500;
}

/* —— Page footer (below glass card, on backdrop) —— */
.auth-screen__footer {
    flex-shrink: 0;
    width: 100%;
    max-width: 400px;
    margin: 0.75rem auto 0;
    padding: 0 0.25rem 0.85rem;
    text-align: center;
}

.auth-screen__footer-divider {
    height: 1px;
    margin: 0 0 clamp(0.4rem, 1vh, 0.75rem);
    width: 100%;
    background: linear-gradient(
        90deg,
        transparent 0%,
        rgba(255, 255, 255, 0.1) 12%,
        rgba(20, 184, 166, 0.32) 50%,
        rgba(255, 255, 255, 0.1) 88%,
        transparent 100%
    );
    opacity: 0.9;
}

.auth-screen__footer-brand {
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: center;
    flex-wrap: wrap;
    gap: 0.4rem 0.65rem;
    margin-bottom: clamp(0.3rem, 0.8vh, 0.55rem);
}

.auth-screen__footer-tagline {
    margin: 0;
    font-size: 0.75rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: rgba(226, 232, 240, 0.82);
    line-height: 1.35;
}

.auth-screen__footer-version {
    display: inline-flex;
    align-items: center;
    padding: 0.125rem 0.625rem;
    border-radius: 9911px;
    font-size: 0.6875rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    color: rgba(226, 232, 240, 0.88);
    background: rgba(255, 255, 255, 0.06);
    border: 0px solid rgba(255, 255, 255, 0.12);
}

.auth-screen__footer-legal {
    margin: 0 0 clamp(0.3rem, 0.8vh, 0.55rem);
    max-width: none;
    font-size: 0.75rem;
    line-height: 1.4;
    color: rgba(148, 163, 184, 0.82);
}

.auth-screen__footer-nav {
    display: flex;
    align-items: center;
    justify-content: center;
    flex-wrap: wrap;
    gap: 0.35rem 0.625rem;
    margin: 0;
}

.auth-screen__footer-link {
    font-size: 0.6875rem;
    font-weight: 600;
    letter-spacing: 0.02em;
    color: rgba(203, 213, 225, 0.82);
    text-decoration: none;
    transition: color 0.18s ease, opacity 0.18s ease;
}

.auth-screen__footer-link:hover {
    color: #fff;
    text-decoration: none;
    opacity: 1;
}

.auth-screen__footer-sep {
    color: rgba(148, 163, 184, 0.4);
    font-size: 0.6875rem;
    line-height: 1;
    user-select: none;
}

.auth .auth-screen .auth-login__card .text-muted {
    color: #64748b !important;
}

.auth .auth-screen .auth-login__card .text-primary {
    color: var(--lux-primary, #5b5ff4) !important;
    font-weight: 600;
}

.auth .auth-screen .auth-login__card .auth-login__alert {
    margin-bottom: 1rem;
    border-radius: 14px;
    border: 0px solid rgba(239, 68, 68, 0.22);
    background: linear-gradient(180deg, #fef2f2, #fff5f5);
    font-size: 0.8125rem;
    font-weight: 500;
}

/* Mobile: stack — brand becomes compact header band */
@media (max-width: 991px) {
    .auth-screen__layout {
        grid-template-columns: 1fr;
        grid-template-rows: auto 1fr;
    }

    .auth-screen__brand {
        height: auto;
        max-height: none;
        flex-shrink: 0;
        padding: 0.85rem 1.25rem 0.65rem;
        align-items: flex-start;
    }

    .auth-screen__brand-content {
        transform: none;
    }

    .auth-screen__brand-headline,
    .auth-screen__brand-list {
        display: none;
    }

    .auth-screen__brand-logo {
        margin-bottom: 0;
        gap: 14px;
    }

    .auth-screen__brand-mark {
        width: 48px;
        height: 48px;
    }

    .auth-screen__brand-mark-icon {
        width: 28px;
        height: 28px;
    }

    .auth-screen__brand-name {
        font-size: 1.25rem;
    }

    .auth-screen__brand-tagline {
        font-size: 12px;
    }

    .auth-screen__form {
        align-items: stretch;
        justify-content: stretch;
        padding: 0 1.25rem 0;
        overflow: hidden;
    }

    .auth-screen__form-inner {
        transform: none;
        max-width: 100%;
        height: 100%;
        margin-left: auto;
        margin-right: auto;
    }

    .auth-screen__footer {
        margin-left: auto;
        margin-right: auto;
        text-align: center;
        margin-top: 0.65rem;
        padding-bottom: 0.85rem;
    }

    .auth-screen__footer-brand {
        flex-direction: column;
    }

    .auth-screen__footer-legal {
        font-size: 0.75rem;
    }

    .auth-screen__backdrop::after {
        background:
            linear-gradient(
                180deg,
                rgba(8, 12, 28, 0.88) 0%,
                rgba(10, 22, 48, 0.75) 28%,
                rgba(15, 23, 42, 0.65) 100%
            );
    }
}

/* Short viewports: keep form readable without hiding brand */
@media (max-height: 820px) {
    .auth-login__eyebrow {
        margin-bottom: 0.2rem;
        font-size: 0.6875rem;
    }

    .auth .auth-screen .auth-login__title.card-title {
        font-size: 1.25rem;
        margin-bottom: 0.25rem;
    }

    .auth-login__subtitle {
        font-size: 0.75rem;
        line-height: 1.35;
    }

    .auth-screen__footer-tagline {
        font-size: 0.6875rem;
    }
}

@media (max-height: 700px) {
    .auth-login__subtitle {
        display: none;
    }

    .auth-screen__footer-tagline,
    .auth-screen__footer-version {
        display: none;
    }
}

@media (max-width: 767px) {
    .auth-login__head {
        padding: 1.1rem 1.25rem 0.1rem;
    }

    .auth .auth-screen .auth-login__body.card-body,
    .auth-login__foot {
        padding-left: 1.25rem;
        padding-right: 1.25rem;
    }

    .auth .auth-screen .auth-login__title.card-title {
        font-size: 1.3125rem;
    }
}

/* ========== luxury-project-details.css ========== */

/* ========== Project Details — luxury dashboard layout ========== */

.pd-page {
    --pd-radius: 22px;
    --pd-radius-sm: 14px;
    --pd-gap: 18px;
    padding: 0 var(--lux-page-gutter-x) var(--lux-page-block-bottom);
}

.pd-page__body {
    padding-top: 4px;
}

/* Project details — align horizontal rhythm with list / deliverables pages */
.lux-project-details-page.pd-page {
    --pd-gap: 14px;
    padding: 0 var(--lux-page-gutter-x) var(--lux-page-block-bottom);
}

.lux-project-details-page .pd-page__body {
    padding-top: 0;
}

/* Unified back navigation — “Back to &lt;page&gt;”, small type */
.lux-back-nav,
.pd-back-nav {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 0.25rem 0.35rem;
    margin: 0 0 0.5rem;
    font-size: 0.6875rem;
    line-height: 1.35;
    font-family: Inter, system-ui, -apple-system, sans-serif;
}

.lux-back-nav--with-actions {
    justify-content: space-between;
    gap: 0.5rem 0.75rem;
}

.lux-back-nav__trail {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 0.25rem 0.35rem;
    min-width: 0;
}

.lux-back-nav__actions {
    display: flex;
    align-items: center;
    flex-shrink: 0;
    margin-left: auto;
}

.lux-back-nav__action-link {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    margin: 0;
    padding: 0.2rem 0.55rem;
    border-radius: 999px;
    border: 0px solid rgba(226, 232, 240, 0.95);
    background: rgba(255, 255, 255, 0.92);
    font-size: inherit;
    font-weight: 600;
    font-family: inherit;
    letter-spacing: 0.01em;
    color: #475569;
    text-decoration: none;
    transition: background 0.14s ease, border-color 0.14s ease, color 0.14s ease;
}

.lux-back-nav__action-link:hover {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
    color: var(--lux-primary-dark, #3730a3);
    text-decoration: none;
}

.lux-back-nav__link,
.lux-bid-detail__back,
.lux-inv-detail__back-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    margin: 0;
    padding: 0.2rem 0.55rem;
    border-radius: 999px;
    border: 0px solid rgba(226, 232, 240, 0.95);
    background: rgba(255, 255, 255, 0.92);
    font-size: inherit;
    font-weight: 600;
    font-family: inherit;
    letter-spacing: 0.01em;
    color: var(--lux-primary-dark, #3730a3);
    text-decoration: none;
    transition: background 0.14s ease, border-color 0.14s ease, color 0.14s ease;
}

.lux-back-nav__link:hover,
.lux-bid-detail__back:hover,
.lux-inv-detail__back-btn:hover {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
    color: var(--lux-primary-dark, #3730a3);
    text-decoration: none;
}

.lux-back-nav__icon {
    font-size: 0.75rem;
    line-height: 1;
    opacity: 0.9;
}

.lux-back-nav__text {
    font-size: inherit;
    font-weight: inherit;
}

.lux-back-nav__sep,
.lux-bid-detail__breadcrumb-sep {
    color: #cbd5e1;
    font-size: inherit;
    font-weight: 500;
}

.lux-back-nav__current,
.lux-bid-detail__breadcrumb-current {
    font-size: inherit;
    font-weight: 600;
    color: #64748b;
}

.pd-back-nav__link {
    margin: 0;
}

.lux-project-details-page .pd-hero {
    margin: 0 0 0.65rem;
}

.lux-project-details-page .pd-hero.pd-hero--dense {
    padding: 0.85rem 1rem 0.9rem;
    box-shadow: 0 14px 32px rgba(15, 23, 42, 0.06);
}

.lux-project-details-page .pd-hero--dense .pd-hero__glow {
    display: none;
}

.lux-project-details-page .pd-hero--dense .pd-hero__inner {
    gap: 0.75rem;
    align-items: center;
}

.lux-project-details-page .pd-hero--dense .pd-hero__title {
    margin: 0.25rem 0 0.4rem;
    font-size: 1.25rem;
    letter-spacing: -0.03em;
    line-height: 1.25;
}

.lux-project-details-page .pd-hero--dense .pd-hero__meta-row {
    margin-bottom: 0;
    gap: 0.35rem;
}

.lux-project-details-page .pd-hero--dense .pd-hero__badge {
    padding: 0.15rem 0.55rem;
    font-size: 0.62rem;
}

.lux-project-details-page .pd-hero--dense .pd-hero__id {
    font-size: 0.68rem;
}

.lux-project-details-page .pd-hero--dense .pd-chip {
    padding: 0.2rem 0.55rem;
    font-size: 0.68rem;
    gap: 0.3rem;
}

.lux-project-details-page .pd-hero--dense .pd-hero__chips {
    gap: 0.35rem;
}

.lux-project-details-page .pd-hero--dense .pd-hero__facts {
    margin: 0.65rem 0 0;
    padding: 0.45rem;
    gap: 0.35rem;
    border-radius: 12px;
    box-shadow: none;
    background: rgba(248, 250, 252, 0.9);
}

.lux-project-details-page .pd-hero--dense .pd-hero__fact {
    padding: 0.35rem 0.45rem;
    gap: 0.4rem;
    border-radius: 10px;
    background: #fff;
}

.lux-project-details-page .pd-hero--dense .pd-hero__fact-icon {
    width: 1.55rem;
    height: 1.55rem;
    border-radius: 8px;
    font-size: 0.75rem;
}

.lux-project-details-page .pd-hero--dense .pd-hero__fact-label {
    font-size: 0.55rem;
}

.lux-project-details-page .pd-hero--dense .pd-hero__fact-value {
    font-size: 0.78rem;
    margin-top: 0;
}

.lux-project-details-page .pd-nav {
    margin-bottom: 0.75rem;
}

.lux-project-details-page .pd-overview {
    margin: 0;
}

/* Project details — rich summary tiles */
.lux-project-details-page .pd-summary-stats {
    gap: 0.75rem;
    margin-bottom: 1rem;
}

.lux-project-details-page .pd-summary-stats .pd-stat-tile {
    border: 1px solid rgba(226, 232, 240, 0.95);
    box-shadow: 0 12px 28px rgba(15, 23, 42, 0.05);
    border-radius: 16px;
}

.lux-project-details-page .pd-summary-stats .pd-stat-tile:hover {
    transform: translateY(-1px);
    box-shadow: 0 16px 34px rgba(15, 23, 42, 0.08);
}

.lux-project-details-page .pd-stat-tile__hint {
    display: block;
    margin-top: 0.15rem;
    font-size: 0.62rem;
    font-weight: 650;
    color: #94a3b8;
}

.lux-project-details-page .lux-pd-tab .lux-settings-tab__stats {
    border-bottom: none;
    background: transparent;
}

.lux-project-details-page .lux-pd-tab .lux-settings-tab__stat {
    border: none;
    box-shadow: none;
    background: transparent;
}

.lux-project-details-page .lux-pd-dashboard__categories {
    border: none;
    background: transparent;
    padding-left: 0;
    padding-right: 0;
}

.lux-project-details-page .lux-pd-dashboard__category-row {
    border: none;
    background: transparent;
    padding-left: 0;
    padding-right: 0;
}

/* Deliverable details — same shell as project details */
.lux-deliverable-details-page.pd-page {
    --pd-gap: 14px;
    padding: 0 var(--lux-page-gutter-x) var(--lux-page-block-bottom);
}

.lux-deliverable-details-page .pd-page__body {
    padding-top: 0;
}

.lux-deliverable-details-page .pd-hero {
    margin: 0 0 0.75rem;
}

.lux-deliverable-details-page .pd-nav {
    margin-bottom: 0.75rem;
}

.lux-deliverable-details-page .pd-overview,
.lux-deliverable-details-page .lux-del-overview {
    margin: 0;
}

.lux-deliverable-details-page .pd-back-nav {
    margin: 0.65rem 0 0.5rem;
}

.lux-del-hero.pd-hero,
.lux-pd-hero.pd-hero {
    border-radius: 16px;
    border: 0px solid rgba(15, 23, 42, 0.08);
    box-shadow: 0 10px 32px rgba(15, 23, 42, 0.06);
}

.lux-pd-hero.pd-hero .pd-hero__badge {
    letter-spacing: 0.04em;
}

.lux-pd-hero.pd-hero .pd-hero__title {
    font-family: "Plus Jakarta Sans", Inter, system-ui, sans-serif;
}

.lux-del-overview.pd-workspace {
    align-items: start;
    gap: var(--pd-gap, 14px);
}

.lux-del-overview__main {
    min-width: 0;
}

.lux-del-page-loading {
    padding: 2rem 1rem;
    text-align: center;
    font-size: 0.8125rem;
    font-weight: 700;
    color: #64748b;
}

.lux-detail-page-skeleton {
    padding: 0 0 1rem;
}

.lux-detail-page-skeleton__grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 1rem;
    margin-top: 0.75rem;
}

@media (max-width: 991px) {
    .lux-detail-page-skeleton__grid {
        grid-template-columns: 1fr;
    }
}

.lux-chart-panel-skeleton {
    width: 100%;
}

.lux-item-collab__loading-row {
    display: flex;
    gap: 0.65rem;
    align-items: flex-start;
    margin-bottom: 0.85rem;
}

.lux-del-empty__icon {
    display: inline-grid;
    place-items: center;
    width: 3rem;
    height: 3rem;
    margin-bottom: 0.65rem;
    border-radius: 14px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary-dark, #3730a3);
    font-size: 1.25rem;
}

/* KPI strip */
.lux-del-kpi-strip {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.45rem;
}

.lux-del-kpi {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.5rem 0.55rem;
    border-radius: 12px;
    border: 0px solid rgba(15, 23, 42, 0.07);
    background: #f8fafc;
}

.lux-del-kpi.is-green { background: rgba(16, 185, 129, 0.08); border-color: rgba(16, 185, 129, 0.2); }
.lux-del-kpi.is-amber { background: rgba(245, 158, 11, 0.08); border-color: rgba(245, 158, 11, 0.2); }
.lux-del-kpi.is-slate { background: rgba(148, 163, 184, 0.1); }
.lux-del-kpi.is-rose { background: rgba(244, 63, 94, 0.06); border-color: rgba(244, 63, 94, 0.15); }

.lux-del-kpi__icon {
    width: 1.75rem;
    height: 1.75rem;
    display: grid;
    place-items: center;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.85);
    color: var(--lux-primary-dark, #3730a3);
    flex-shrink: 0;
}

.lux-del-kpi__value {
    display: block;
    font-size: 1.125rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.1;
}

.lux-del-kpi__label {
    display: block;
    font-size: 0.5625rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #64748b;
}

/* Inner sections */
.lux-del-section {
    border-radius: 14px;
    border: 0px solid rgba(15, 23, 42, 0.07);
    background: #fff;
    overflow: hidden;
    box-shadow: 0 4px 14px rgba(15, 23, 42, 0.04);
}

.lux-del-section__head {
    display: flex;
    align-items: flex-start;
    gap: 0.65rem;
    padding: 0.75rem 0.9rem;
    border-bottom: 1px solid rgba(15, 23, 42, 0.06);
    background: linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.04), #fff 55%);
}

.lux-del-section__icon {
    width: 2rem;
    height: 2rem;
    display: grid;
    place-items: center;
    border-radius: 10px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    color: var(--lux-primary-dark, #3730a3);
    flex-shrink: 0;
}

.lux-del-section__title {
    margin: 0;
    font-size: 0.875rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-del-section__subtitle {
    margin: 0.2rem 0 0;
    font-size: 0.6875rem;
    font-weight: 600;
    color: #64748b;
    line-height: 1.4;
}

.lux-del-section__body {
    padding: 0.85rem 0.9rem 0.95rem;
}

.lux-del-section.is-flush .lux-del-section__body {
    padding: 0;
}

.lux-del-about {
    margin: 0;
    font-size: 0.8125rem;
    line-height: 1.55;
    color: #334155;
    font-weight: 500;
}

.lux-del-fact-group {
    border-radius: 14px;
    border: 0px solid rgba(15, 23, 42, 0.07);
    overflow: hidden;
    background: #fff;
}

.lux-del-fact-group.is-delivery {
    border-color: rgba(14, 165, 233, 0.15);
    background: linear-gradient(180deg, rgba(14, 165, 233, 0.04), #fff 40%);
}

.lux-del-fact-group.is-project {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    background: linear-gradient(180deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.04), #fff 40%);
}

.lux-del-fact-group__head {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.65rem 0.85rem;
    border-bottom: 1px solid rgba(15, 23, 42, 0.06);
}

.lux-del-fact-group__emoji {
    font-size: 1.1rem;
}

.lux-del-fact-group__title {
    margin: 0;
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-del-fact-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.55rem 0.65rem;
    padding: 0.75rem 0.85rem 0.85rem;
}

.lux-del-fact--wide {
    grid-column: 1 / -1;
}

.lux-del-fact {
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
    min-width: 0;
}

.lux-del-fact__label {
    font-size: 0.5625rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-del-fact__value {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.5rem 0.55rem;
    border-radius: 10px;
    border: 0px solid #e2e8f0;
    background: #f8fafc;
    font-size: 0.75rem;
    font-weight: 700;
    color: #1e293b;
    line-height: 1.35;
    word-break: break-word;
}

.lux-del-fact__icon {
    color: var(--lux-primary, #5b5ff4);
    flex-shrink: 0;
}

.lux-del-collapsible {
    border-radius: 14px;
    border: 0px solid rgba(15, 23, 42, 0.08);
    background: #fff;
    overflow: hidden;
}

.lux-del-collapsible__summary {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.7rem 0.85rem;
    cursor: pointer;
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
    list-style: none;
}

.lux-del-collapsible__summary::-webkit-details-marker {
    display: none;
}

.lux-del-collapsible__chevron {
    margin-left: auto;
    color: #94a3b8;
    transition: transform 0.15s ease;
}

.lux-del-collapsible[open] .lux-del-collapsible__chevron {
    transform: rotate(180deg);
}

.lux-del-collapsible__body {
    padding: 0 0.85rem 0.85rem;
    border-top: 1px solid rgba(15, 23, 42, 0.06);
}

/* Right rail */
.lux-del-rail.pd-workspace__aside {
    display: flex;
    flex-direction: column;
    gap: 0.65rem;
}

.lux-del-rail__head {
