.lux-del-aside-card__body {
    padding: 0.75rem 0.8rem 0.85rem;
}

.lux-del-aside-card__body--checklist {
    padding: 0.65rem 0.75rem 0.75rem;
}

.lux-del-timeline {
    display: flex;
