}

.lux-del-timeline__step:not(:last-child)::before {
    content: "";
    position: absolute;
    left: 0.4rem;
    top: 1.35rem;
    bottom: -0.2rem;
    width: 2px;
    background: #e2e8f0;
}

.lux-del-timeline__step.is-active .lux-del-timeline__dot {
