}

.lux-del-timeline__dot {
    width: 10px;
    height: 10px;
    margin-top: 0.35rem;
    border-radius: 999px;
    background: #cbd5e1;
    flex-shrink: 0;
    z-index: 1;
}

.lux-del-timeline__label {
    display: block;
    font-size: 0.5625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-del-timeline__value {
    display: block;
    font-size: 0.75rem;
    font-weight: 700;
    color: #0f172a;
}

.lux-del-meta-list {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
    padding-top: 0.5rem;
    border-top: 1px dashed rgba(15, 23, 42, 0.1);
}

.lux-del-meta-list__row {
    display: flex;
    justify-content: space-between;
    gap: 0.5rem;
    font-size: 0.6875rem;
}

.lux-del-meta-list__row span {
    color: #64748b;
    font-weight: 600;
}

.lux-del-meta-list__row strong {
    color: #0f172a;
    font-weight: 800;
    text-align: right;
}

@media (max-width: 1100px) {
    .lux-del-kpi-strip {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .lux-del-fact-grid {
