/* Work items list — same gutter rhythm as project list */
.lux-workitem-requests {
    width: 100%;
    padding: 0 0 var(--lux-page-block-bottom);
    background:
        radial-gradient(ellipse 65% 40% at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.04), transparent 55%),
        radial-gradient(ellipse 50% 35% at 100% 0%, rgba(20, 184, 166, 0.03), transparent 50%),
        transparent;
}

.workitemslist.lux-workitem-requests {
    padding-bottom: 1rem;
}

/* Context card — horizontal gutters from lux-register-page child rule */
.lux-workitem-requests .lux-deliverable-context {
    margin-top: 0.35rem;
    margin-bottom: var(--lux-page-block-gap-y);
    padding: 0.65rem 0.85rem 0.7rem;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 14px;
    background:
        radial-gradient(110% 80% at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08), transparent 52%),
        radial-gradient(80% 60% at 100% 0%, rgba(20, 184, 166, 0.05), transparent 48%),
        linear-gradient(165deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.96));
    box-shadow:
        0 1px 0 rgba(255, 255, 255, 0.95) inset,
        0 8px 20px rgba(15, 23, 42, 0.04);
}

.lux-workitem-context .lux-deliverable-context__project-link {
    font-size: 0.625rem;
    font-weight: 700;
    color: var(--lux-primary, #5b5ff4);
    text-decoration: none;
}

.lux-workitem-context .lux-deliverable-context__project-link:hover {
    text-decoration: underline;
}

.lux-workitem-summary__stage-flow {
    margin: 0.35rem 0 0.45rem;
}

/* Work items — date toolbar (legacy; prefer PageInnerHeader date range) */
.lux-workitem-date-toolbar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 0.55rem 0.75rem;
    margin: 0 0 0.75rem;
    padding: 0.65rem 0.85rem;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 16px;
    background:
        radial-gradient(110% 80% at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.07), transparent 52%),
        linear-gradient(135deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.95));
    box-shadow:
        0 1px 0 rgba(255, 255, 255, 0.9) inset,
        0 10px 24px rgba(15, 23, 42, 0.04);
}

.lux-workitem-date-toolbar__main {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    min-width: 0;
}

.lux-workitem-date-toolbar__icon {
    width: 2rem;
    height: 2rem;
    display: grid;
    place-items: center;
    border-radius: 10px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary, #5b5ff4);
    flex-shrink: 0;
}

.lux-workitem-date-toolbar__eyebrow {
    display: block;
    font-size: 0.5rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-workitem-date-toolbar__value {
    display: block;
    font-size: 0.75rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-workitem-date-toolbar__presets {
    display: flex;
    flex-wrap: wrap;
    gap: 0.3rem;
}

.lux-workitem-date-toolbar__chip {
    padding: 0.28rem 0.55rem;
    border: 0px solid #e2e8f0;
    border-radius: 999px;
    background: #fff;
    font-size: 0.625rem;
    font-weight: 700;
    color: #64748b;
    cursor: pointer;
    transition: border-color 0.14s ease, background 0.14s ease, color 0.14s ease;
}

.lux-workitem-date-toolbar__chip:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
    color: var(--lux-primary-dark, #3730a3);
}

.lux-workitem-date-toolbar__chip.is-active {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.4);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary-dark, #3730a3);
}

/* Work items — luxury register table (fluid, no horizontal scroll) */
.lux-workitem-list,
.lux-workitem-register__list {
    --lux-bid-list-cols:
        2rem
        4.25rem
        minmax(0, 1.7fr)
        minmax(0, 0.72fr)
        minmax(0, 0.95fr)
        minmax(0, 0.82fr)
        minmax(0, 0.72fr)
        minmax(0, 0.78fr)
        5.75rem;
    width: 100%;
    max-width: 100%;
    min-width: 0;
    overflow: hidden;
}

.lux-workitem-list-shell .lux-bid-list__head,
