.lux-workitem-row__prio.is-slate { background: rgba(100, 116, 139, 0.12); color: #475569; }

.lux-workitem-row__badge {
    display: inline-flex;
    align-items: center;
    gap: 0.18rem;
    padding: 0.1rem 0.38rem;
    border-radius: 999px;
    font-size: 0.5rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
