}

.lux-workitem-row__owner-copy {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 0.02rem;
}

.lux-workitem-row__owner-name {
    display: block;
    font-size: 0.75rem;
    font-weight: 800;
    color: #0f172a;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-workitem-row__owner-copy em {
    font-style: normal;
    font-size: 0.5rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-workitem-row__dates-col {
    min-width: 0;
}

.lux-workitem-row__dates {
    display: flex;
    flex-direction: column;
    gap: 0.16rem;
    min-width: 0;
}

.lux-workitem-row__date {
    display: flex;
    flex-direction: column;
    min-width: 0;
    font-size: 0.6875rem;
    font-weight: 700;
    color: #0f172a;
    line-height: 1.3;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-workitem-row__date em {
    font-style: normal;
    font-size: 0.5rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-workitem-row__date.is-due {
    color: #b45309;
}

.lux-workitem-row__date.is-due.is-late,
.lux-workitem-row.is-overdue .lux-workitem-row__date.is-due {
    color: #be123c;
}

.lux-workitem-row__hours {
