.lux-workitem-row__hours.is-green strong { color: #047857; }
.lux-workitem-row__hours.is-amber strong { color: #b45309; }
.lux-workitem-row__hours.is-indigo strong { color: #4338ca; }

.lux-workitem-row__hours-track {
