.lux-workitem-row__status-text {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-workitem-row__status.is-sky {
    background: rgba(14, 165, 233, 0.12);
    border-color: rgba(14, 165, 233, 0.18);
    color: #0369a1;
