.lux-cal-event.is-mini {
    min-height: auto;
    padding: 0.2rem 0.35rem;
    border-radius: 6px;
}

.lux-cal-event.is-mini .lux-cal-event__title {
    font-size: 0.5625rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.lux-cal-event.is-mini .lux-cal-event__glow,
.lux-cal-event.is-mini .lux-cal-event__rail {
    display: none;
}

.lux-cal-event.is-selected {
    box-shadow: 0 0 0 2px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.4);
}

/* Week / day time grid */
.lux-custom-cal--time {
    flex: 1;
    min-height: 0;
    display: flex;
    flex-direction: column;
}

.lux-custom-cal__time-scroll {
    flex: 1;
    overflow: auto;
    min-height: 420px;
    max-height: min(68vh, 720px);
}

.lux-custom-cal__time-layout {
    display: flex;
    min-width: min(100%, 640px);
}

.lux-custom-cal__gutter {
    flex-shrink: 0;
    width: 3.25rem;
    border-right: 1px solid rgba(15, 23, 42, 0.06);
    background: linear-gradient(180deg, #f8fafc, #fff);
}

.lux-custom-cal__gutter-label {
    display: block;
    text-align: center;
    font-size: 0.5rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
    padding: 0.45rem 0.15rem;
}

.lux-custom-cal__gutter-slots {
    position: relative;
}

.lux-custom-cal__gutter-hour {
    position: absolute;
    left: 0;
    right: 0;
    transform: translateY(-50%);
    font-size: 0.5625rem;
    font-weight: 700;
    color: #94a3b8;
    text-align: center;
    padding-right: 0.25rem;
}

.lux-custom-cal__day-cols {
    display: flex;
    flex: 1;
    min-width: 0;
}

.lux-custom-cal__day-cols.is-single .lux-custom-cal__day-col {
    flex: 1;
    min-width: 0;
}

.lux-custom-cal__day-col {
    flex: 1;
    min-width: 5.5rem;
    border-right: 1px solid rgba(15, 23, 42, 0.05);
    display: flex;
    flex-direction: column;
}

.lux-custom-cal__day-col.is-today {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.03);
}

.lux-custom-cal__day-col.is-weekend:not(.is-today) {
    background: rgba(248, 250, 252, 0.8);
}

.lux-custom-cal__col-head {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.1rem;
    padding: 0.45rem 0.25rem;
    border-bottom: 1px solid rgba(15, 23, 42, 0.06);
    background: linear-gradient(180deg, #f8fafc, #fff);
}

.lux-custom-cal__day-col.is-single .lux-custom-cal__col-head {
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: center;
    gap: 0.35rem 0.5rem;
    padding: 0.55rem 0.65rem;
}

.lux-custom-cal__col-weekday {
    font-size: 0.5625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-custom-cal__day-col.is-single .lux-custom-cal__col-weekday {
    font-size: 0.75rem;
    color: #475569;
    text-transform: none;
    letter-spacing: 0;
}

.lux-custom-cal__col-date {
    width: 1.85rem;
    height: 1.85rem;
    display: grid;
    place-items: center;
    border-radius: 999px;
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-custom-cal__day-col.is-today .lux-custom-cal__col-date {
    color: #fff;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), #8b5cf6);
    box-shadow: 0 4px 12px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
}

.lux-custom-cal__allday-row {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    padding: 0.3rem 0.25rem;
    border-bottom: 1px solid rgba(15, 23, 42, 0.06);
    min-height: 2rem;
}

.lux-custom-cal__slots {
    position: relative;
    flex: 1;
}

.lux-custom-cal__hour-line {
    position: absolute;
    left: 0;
    right: 0;
    height: 1px;
    background: rgba(15, 23, 42, 0.05);
    pointer-events: none;
}

.lux-custom-cal__now-line {
    position: absolute;
    left: 0;
    right: 0;
    height: 2px;
    z-index: 3;
    background: linear-gradient(90deg, var(--lux-primary, #5b5ff4), #8b5cf6);
    box-shadow: 0 0 8px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.4);
    pointer-events: none;
}

.lux-custom-cal__now-dot {
    position: absolute;
    left: -4px;
    top: -4px;
    width: 10px;
    height: 10px;
    border-radius: 999px;
    background: var(--lux-primary, #5b5ff4);
    box-shadow: 0 0 0 3px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.25);
}

.lux-custom-cal__timed-slot {
    position: absolute;
    z-index: 2;
    padding: 0 1px;
    box-sizing: border-box;
}

.lux-custom-cal__timed-slot .lux-cal-event {
    height: 100%;
}

.lux-cal-event.is-compact {
    padding: 0.25rem 0.4rem;
}

.lux-cal-event.is-compact .lux-cal-event__desc {
    display: none;
}

/* Agenda */
.lux-custom-cal--agenda {
    padding: 0.55rem 0.65rem 0.75rem;
    overflow-y: auto;
    max-height: min(68vh, 720px);
}

.lux-custom-cal--agenda-empty {
    display: grid;
    place-items: center;
    min-height: 12rem;
    color: #64748b;
    font-size: 0.8125rem;
    font-weight: 600;
}

.lux-custom-cal__agenda-day {
    margin-bottom: 0.85rem;
}

.lux-custom-cal__agenda-day-head {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    margin-bottom: 0.4rem;
    padding-bottom: 0.35rem;
    border-bottom: 1px solid rgba(15, 23, 42, 0.06);
}

.lux-custom-cal__agenda-day-label {
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-custom-cal__agenda-day.is-today .lux-custom-cal__agenda-day-label {
    color: var(--lux-primary-dark, #3730a3);
}

.lux-custom-cal__agenda-day-count {
    margin-left: auto;
    font-size: 0.5625rem;
    font-weight: 800;
    color: #64748b;
    padding: 0.12rem 0.4rem;
    border-radius: 999px;
    background: #f1f5f9;
}

.lux-custom-cal__agenda-list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: grid;
    gap: 0.4rem;
}

.lux-custom-cal__agenda-item {
    width: 100%;
    display: grid;
    grid-template-columns: minmax(6.5rem, 8rem) minmax(0, 1fr) auto;
    align-items: start;
    gap: 0.5rem 0.65rem;
    text-align: left;
    padding: 0.55rem 0.65rem;
    border: 0px solid rgba(15, 23, 42, 0.08);
    border-radius: 12px;
    background: #fff;
    cursor: pointer;
    transition: 0.15s ease;
}

.lux-custom-cal__agenda-item:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.25);
    box-shadow: 0 4px 14px rgba(15, 23, 42, 0.06);
}

.lux-custom-cal__agenda-item.is-selected {
    box-shadow: 0 0 0 2px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
}

.lux-custom-cal__agenda-item-time {
    font-size: 0.625rem;
    font-weight: 700;
    color: #64748b;
    line-height: 1.35;
}

.lux-custom-cal__agenda-item-body {
    display: flex;
    flex-direction: column;
    gap: 0.1rem;
    min-width: 0;
}

.lux-custom-cal__agenda-item-body strong {
    font-size: 0.75rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-custom-cal__agenda-item-body span {
    font-size: 0.625rem;
    font-weight: 600;
    color: #64748b;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-custom-cal__agenda-badge {
    font-size: 0.5rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    padding: 0.15rem 0.4rem;
    border-radius: 999px;
    white-space: nowrap;
    align-self: flex-start;
}

.lux-custom-cal__agenda-badge.is-green { color: #047857; background: rgba(16, 185, 129, 0.12); }
.lux-custom-cal__agenda-badge.is-indigo { color: #4338ca; background: rgba(99, 102, 241, 0.12); }
.lux-custom-cal__agenda-badge.is-sky { color: #0369a1; background: rgba(14, 165, 233, 0.12); }
.lux-custom-cal__agenda-badge.is-amber { color: #b45309; background: rgba(245, 158, 11, 0.14); }

@media (max-width: 900px) {
    .lux-custom-cal__time-layout {
        min-width: 100%;
    }

    .lux-custom-cal__day-col {
        min-width: 4.25rem;
    }

    .lux-custom-cal__month-cell {
        min-height: 4.25rem;
    }

    .lux-custom-cal__agenda-item {
        grid-template-columns: 1fr;
        gap: 0.35rem;
    }

    .lux-custom-cal__agenda-badge {
        justify-self: start;
    }
}

@media (max-width: 600px) {
    .lux-custom-cal__month-grid {
        gap: 0.2rem;
    }

    .lux-custom-cal__month-cell {
        min-height: 3.75rem;
        padding: 0.25rem 0.2rem;
    }

    .lux-custom-cal__gutter {
        width: 2.5rem;
    }

    .lux-custom-cal__day-cols {
        overflow-x: auto;
    }
}

/* Error 500 — luxury fault page */
.lux-error-page {
    min-height: 100vh; display: grid; place-items: center; padding: 1.5rem;
    background: radial-gradient(circle at 20% 20%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08), transparent 45%),
                radial-gradient(circle at 80% 80%, rgba(244, 63, 94, 0.06), transparent 40%), #f8fafc;
    position: relative; overflow: hidden;
}
.lux-error-page__glow {
    position: absolute; width: 22rem; height: 22rem; border-radius: 999px; filter: blur(60px); opacity: 0.35;
}
.lux-error-page__glow--rose { top: -4rem; right: -4rem; background: rgba(244, 63, 94, 0.35); }
.lux-error-page__glow--indigo { bottom: -5rem; left: -5rem; background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35); }
.lux-error-page__card {
    position: relative; width: min(100%, 32rem); padding: 1.5rem 1.5rem 1.25rem;
    border-radius: 20px; border: 0px solid rgba(15, 23, 42, 0.08); background: #fff;
    box-shadow: 0 20px 50px rgba(15, 23, 42, 0.1);
}
.lux-error-page__art {
    display: flex; align-items: center; justify-content: center; gap: 0.75rem;
    margin: 1rem 0 0.75rem; padding: 1rem; border-radius: 16px;
    background: linear-gradient(135deg, rgba(244, 63, 94, 0.08), rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06));
}
.lux-error-page__code { font-size: 2.5rem; font-weight: 900; color: #0f172a; line-height: 1; }
.lux-error-page__icon { font-size: 2rem; color: #e11d48; }
.lux-error-page__eyebrow {
    display: block; font-size: 0.5625rem; font-weight: 800; letter-spacing: 0.08em;
    text-transform: uppercase; color: #e11d48;
}
.lux-error-page__title { margin: 0.25rem 0 0; font-size: 1.35rem; font-weight: 800; color: #0f172a; }
.lux-error-page__text { margin: 0.45rem 0 0; font-size: 0.8125rem; font-weight: 600; color: #64748b; line-height: 1.55; }
.lux-error-page__hints { list-style: none; margin: 0.75rem 0 0; padding: 0; display: flex; flex-direction: column; gap: 0.35rem; }
.lux-error-page__hints li {
    display: flex; align-items: flex-start; gap: 0.4rem; font-size: 0.6875rem; font-weight: 600; color: #475569;
}
.lux-error-page__hints i { color: #10b981; margin-top: 0.1rem; }
.lux-error-page__actions { display: flex; flex-wrap: wrap; gap: 0.5rem; margin-top: 1rem; }
.lux-error-page__btn {
    display: inline-flex; align-items: center; gap: 0.35rem; padding: 0.5rem 0.85rem;
    border-radius: 10px; font-size: 0.75rem; font-weight: 800; text-decoration: none; cursor: pointer; border: none;
}
.lux-error-page__btn--primary {
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), #8b5cf6); color: #fff;
    box-shadow: 0 4px 14px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
}
.lux-error-page__btn--ghost {
    background: #fff; border: 0px solid rgba(15, 23, 42, 0.12); color: #334155;
}
.lux-error-page__footer {
    margin-top: 1rem; padding-top: 0.75rem; border-top: 1px solid rgba(15, 23, 42, 0.06);
    font-size: 0.5625rem; font-weight: 700; color: #94a3b8;
}

@media (max-width: 900px) {
    .lux-chat-workspace { grid-template-columns: 1fr; min-height: auto; }
    .lux-chat-sidebar { max-height: 16rem; }
    .lux-user-calendar-workspace {
        grid-template-columns: 1fr;
    }

    .lux-user-calendar-sidebar {
        position: static;
        max-height: none;
    }

    .lux-user-calendar-toolbar__row--primary {
        flex-direction: column;
        align-items: stretch;
    }

    .lux-user-calendar-toolbar__center {
        align-items: flex-start;
    }
}

/* Deliverable details — recurring schedules */
.pd-card--recurring {
    overflow: hidden;
}

.pd-card--recurring .pd-card__body--flush {
    padding: 0;
}

.lux-recurring-panel__card-hint {
    margin: 0.12rem 0 0;
    font-size: 0.625rem;
    color: #64748b;
    line-height: 1.4;
    font-weight: 500;
}

.lux-recurring-panel {
    padding: 0.65rem 0.75rem 0.75rem;
}

.lux-recurring-panel__toolbar {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.65rem;
    margin-bottom: 0.55rem;
}

.lux-recurring-panel__toolbar-copy {
    margin: 0;
    font-size: 0.6875rem;
    line-height: 1.45;
    color: #64748b;
    font-weight: 600;
    flex: 1;
    min-width: 0;
}

.lux-recurring-panel__composer {
    margin-bottom: 0.65rem;
    padding: 0.65rem 0.7rem;
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
    border-radius: 14px;
    background: linear-gradient(180deg, #fff 0%, rgba(248, 250, 252, 0.96) 100%);
    box-shadow: 0 6px 18px rgba(15, 23, 42, 0.04);
}

.lux-recurring-panel__composer-title {
    margin: 0 0 0.5rem;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-recurring-panel__composer-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.5rem 0.6rem;
}

.lux-recurring-panel__composer-cron {
    grid-column: 1 / -1;
}

.lux-recurring-panel__composer-grid .form-group {
    margin-bottom: 0 !important;
}

.lux-recurring-panel__field-label {
    margin: 0 0 0.3rem;
    font-size: 0.625rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #94a3b8;
}

.lux-recurring-panel__cron-control {
    padding: 0.45rem 0.55rem;
    border: 0px solid #e2e8f0;
    border-radius: 12px;
    background: #fff;
}

.lux-recurring-panel__cron-value {
    flex: 1;
    min-width: 0;
    text-align: left;
}

.lux-recurring-panel__field-hint {
    margin: 0.2rem 0 0;
    font-size: 0.5625rem;
    color: #94a3b8;
    font-weight: 600;
}

.lux-recurring-panel__composer-actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.4rem;
    margin-top: 0.55rem;
    padding-top: 0.55rem;
    border-top: 1px dashed #e2e8f0;
}

.lux-recurring-panel__btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.3rem;
    min-height: 2rem;
    padding: 0 0.85rem;
    border-radius: 999px;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    cursor: pointer;
    transition: transform 0.14s ease, box-shadow 0.14s ease;
}

.lux-recurring-panel__btn.is-primary {
    border: none;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
    color: #fff;
    box-shadow: 0 6px 16px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
}

.lux-recurring-panel__btn.is-primary:hover {
    transform: translateY(-1px);
}

.lux-recurring-panel__btn.is-ghost {
    border: 0px solid #e2e8f0;
    background: #fff;
    color: #64748b;
}

.lux-recurring-panel__btn.is-compact {
    flex-shrink: 0;
}

.lux-recurring-panel__empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    padding: 1rem 0.75rem 1.1rem;
    border: 0px dashed #e2e8f0;
    border-radius: 14px;
    background: rgba(248, 250, 252, 0.7);
}

.lux-recurring-panel__empty-icon {
    width: 2.5rem;
    height: 2.5rem;
    display: grid;
    place-items: center;
    margin-bottom: 0.45rem;
    border-radius: 12px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary, #5b5ff4);
    font-size: 1.1rem;
}

.lux-recurring-panel__empty h5 {
    margin: 0 0 0.3rem;
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-recurring-panel__empty p {
    margin: 0 0 0.55rem;
    max-width: 22rem;
    font-size: 0.625rem;
    line-height: 1.45;
    color: #64748b;
    font-weight: 600;
}

.lux-recurring-panel__list {
    margin: 0;
    padding: 0;
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 0.45rem;
}

.lux-recurring-row {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: 0.55rem;
    padding: 0.55rem 0.6rem;
    border: 0px solid #e2e8f0;
    border-radius: 12px;
    background: #fff;
    box-shadow: 0 2px 8px rgba(15, 23, 42, 0.03);
}

.lux-recurring-row.is-enabled {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    background: linear-gradient(180deg, #fff 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.04) 100%);
}

.lux-recurring-row.is-paused {
    opacity: 0.72;
}

.lux-recurring-row__main {
    display: flex;
    align-items: flex-start;
    gap: 0.45rem;
    min-width: 0;
}

.lux-recurring-row__icon {
    width: 1.75rem;
    height: 1.75rem;
    display: grid;
    place-items: center;
    flex-shrink: 0;
    border-radius: 10px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary, #5b5ff4);
}

.lux-recurring-row__copy {
    min-width: 0;
}

.lux-recurring-row__copy strong {
    display: block;
    font-size: 0.75rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-recurring-row__cron {
    margin: 0.12rem 0 0;
    font-size: 0.6875rem;
    font-weight: 700;
    color: var(--lux-primary-dark, #3730a3);
    line-height: 1.35;
}

.lux-recurring-row__meta {
    margin: 0.15rem 0 0;
    font-size: 0.5625rem;
    color: #64748b;
    font-weight: 600;
}

.lux-recurring-row__dot {
    margin: 0 0.2rem;
}

.lux-recurring-row__aside {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    flex-shrink: 0;
}

.lux-recurring-row__next {
    text-align: right;
}

.lux-recurring-row__next-label {
    display: block;
    font-size: 0.5rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: #94a3b8;
}

.lux-recurring-row__next strong {
    font-size: 0.625rem;
    color: #0f172a;
}

.lux-recurring-row__actions {
    display: flex;
    align-items: center;
    gap: 0.25rem;
}

.lux-recurring-row__switch {
    position: relative;
    display: inline-flex;
    margin: 0;
    cursor: pointer;
}

.lux-recurring-row__switch input {
    position: absolute;
    opacity: 0;
    width: 0;
    height: 0;
}

.lux-recurring-row__switch-ui {
    width: 2rem;
    height: 1.15rem;
    border-radius: 999px;
    background: #cbd5e1;
    transition: background 0.15s ease;
}

.lux-recurring-row__switch-ui::after {
    content: "";
    position: absolute;
    top: 0.14rem;
    left: 0.14rem;
    width: 0.85rem;
    height: 0.85rem;
    border-radius: 50%;
    background: #fff;
    box-shadow: 0 1px 3px rgba(15, 23, 42, 0.2);
    transition: transform 0.15s ease;
}

.lux-recurring-row__switch input:checked + .lux-recurring-row__switch-ui {
    background: var(--lux-primary, #5b5ff4);
}

.lux-recurring-row__switch input:checked + .lux-recurring-row__switch-ui::after {
    transform: translateX(0.85rem);
}

.lux-recurring-row__remove {
    display: grid;
    place-items: center;
    width: 1.75rem;
    height: 1.75rem;
    border: none;
    border-radius: 8px;
    background: transparent;
    color: #94a3b8;
    cursor: pointer;
}

.lux-recurring-row__remove:hover {
    background: #fef2f2;
    color: #dc2626;
}

.lux-deliverable-details-page .custom-select__menu-portal,
.lux-deliverable-details-page .lux-date-picker-popper,
body:has(.lux-deliverable-details-page) #lux-date-picker-portal .react-datepicker-popper {
    z-index: 10150 !important;
}

@media (max-width: 768px) {
    .lux-recurring-panel__composer-grid {
        grid-template-columns: 1fr;
    }

    .lux-recurring-row {
        grid-template-columns: 1fr;
    }

    .lux-recurring-row__aside {
        justify-content: space-between;
        width: 100%;
    }
}

/* —— Hero —— */
.pd-hero {
    position: relative;
    margin: 12px 0 16px;
    padding: 22px 24px;
    border-radius: var(--pd-radius);
    border: 0px solid rgba(226, 232, 240, 0.95);
    background: linear-gradient(135deg, rgba(255, 255, 255, 0.95), rgba(248, 250, 252, 0.88));
    box-shadow: 0 24px 60px rgba(15, 23, 42, 0.07);
    overflow: hidden;
}

.pd-hero__glow {
    position: absolute;
    top: -40%;
    right: -5%;
    width: 280px;
    height: 280px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18), transparent 70%);
    pointer-events: none;
}

.pd-hero__inner {
    position: relative;
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 20px;
}

.pd-hero__badge {
    display: inline-block;
    padding: 4px 12px;
    border-radius: 9911px;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.15);
    margin-right: 8px;
}

.pd-hero__id {
    font-size: 12px;
    font-weight: 700;
    color: #94a3b8;
    letter-spacing: 0.04em;
}

.pd-hero__title {
    margin: 8px 0 12px;
    font-size: 26px;
    font-weight: 800;
    letter-spacing: -0.6px;
    line-height: 1.2;
    color: #0f172a;
}

.pd-hero__code {
    color: var(--lux-primary, #5b5ff4);
}

.pd-hero__chips {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.pd-chip {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 6px 12px;
    border-radius: 9911px;
    font-size: 12px;
    font-weight: 600;
}

.pd-chip--soft {
    color: #475569;
    background: #f1f5f9;
    border: 0px solid #e2e8f0;
}

.pd-chip--accent {
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.2);
}

.pd-hero__actions {
    display: flex;
    align-items: flex-start;
    gap: 0.55rem;
    flex-shrink: 0;
}

.pd-icon-btn {
    width: 36px;
    height: 36px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    border: 0px solid #e2e8f0;
    background: #fff;
    transition: 0.15s ease;
}

.pd-icon-btn:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
}


.pd-hero {
    position: relative;
    overflow: hidden;
}

.pd-hero__accent {
    position: absolute;
    inset: 0 auto 0 0;
    width: 4px;
    background: linear-gradient(180deg, var(--lux-primary, #5b5ff4), #14b8a6);
    z-index: 1;
}

.pd-hero__meta-row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.4rem;
    margin-bottom: 0.35rem;
}

.pd-hero__meta-chip {
    display: inline-flex;
    padding: 0.15rem 0.5rem;
    border-radius: 999px;
    font-size: 0.62rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #475569;
    background: rgba(241, 245, 249, 0.95);
    border: 1px solid #e2e8f0;
}

.pd-hero__facts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(7.25rem, 1fr));
    gap: 0.4rem;
    margin: 0.7rem 0 0;
    padding: 0.5rem;
    border-radius: 12px;
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.92), rgba(248, 250, 252, 0.96));
}

.pd-hero__fact {
    display: flex;
    align-items: flex-start;
    gap: 0.55rem;
    min-width: 0;
    padding: 0.45rem 0.5rem;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.9);
    border: 1px solid #eef2f7;
}

.pd-hero__fact-icon {
    width: 1.85rem;
    height: 1.85rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    flex-shrink: 0;
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.pd-hero__fact-label {
    display: block;
    font-size: 0.58rem;
    font-weight: 800;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    color: #94a3b8;
}

.pd-hero__fact-value {
    display: block;
    margin-top: 0.12rem;
    font-size: 0.84rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.25;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.pd-card__copy {
    min-width: 0;
}

.pd-card__eyebrow {
    display: block;
    font-size: 0.62rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #94a3b8;
}

.pd-card__subtitle {
    margin: 0.15rem 0 0;
    font-size: 0.74rem;
    font-weight: 600;
    color: #64748b;
    line-height: 1.4;
}

.pd-about-panel {
    padding: 0 1.05rem 1.05rem;
}

.lux-project-details-page .pd-about-text {
    margin: 0;
    padding: 0.95rem 1rem;
    border-radius: 14px;
    border: 1px solid #e2e8f0;
    background: linear-gradient(180deg, #fff, #f8fafc);
    font-size: 0.9rem;
    line-height: 1.6;
    color: #334155;
}

.pd-fact-group__icon {
    width: 2.15rem;
    height: 2.15rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    flex-shrink: 0;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary-dark, #3730a3);
}

.pd-fact-group--commercial .pd-fact-group__icon {
    background: rgba(245, 158, 11, 0.14);
    color: #b45309;
}

.pd-fact-group--people .pd-fact-group__icon {
    background: rgba(14, 165, 233, 0.12);
    color: #0369a1;
}

.pd-fact-group--delivery .pd-fact-group__icon {
    background: rgba(16, 185, 129, 0.12);
    color: #047857;
}

.pd-fact-group__eyebrow {
    display: block;
    font-size: 0.58rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #94a3b8;
}

.pd-fact-group__subtitle {
    margin: 0.15rem 0 0;
    font-size: 0.72rem;
    font-weight: 600;
    color: #64748b;
    line-height: 1.35;
}

.lux-project-details-page .pd-fact-group {
    border: 1px solid rgba(226, 232, 240, 0.95);
    box-shadow: 0 12px 28px rgba(15, 23, 42, 0.04);
}

.lux-project-details-page .pd-fact {
    padding: 0.7rem 0.75rem;
    border-radius: 12px;
    border: 1px solid transparent;
    background: rgba(255, 255, 255, 0.82);
    transition: border-color 0.14s ease, box-shadow 0.14s ease;
}

.lux-project-details-page .pd-fact:hover {
    border-color: #e2e8f0;
    box-shadow: 0 8px 18px rgba(15, 23, 42, 0.04);
}

.pd-rail__title {
    display: block;
    margin-top: 0.15rem;
    font-size: 0.95rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-project-details-page .pd-card--timeline {
    position: relative;
    overflow: hidden;
    border: 1px solid rgba(226, 232, 240, 0.95);
    box-shadow: 0 12px 28px rgba(15, 23, 42, 0.05);
}

.lux-project-details-page .pd-card--timeline::before {
    content: "";
    position: absolute;
    inset: 0 auto 0 0;
    width: 3px;
    background: linear-gradient(180deg, #0ea5e9, #6366f1);
}

.lux-project-details-page .pd-card--about,
.lux-project-details-page .pd-card--comments {
    border: 1px solid rgba(226, 232, 240, 0.95);
    box-shadow: 0 14px 34px rgba(15, 23, 42, 0.05);
}

.lux-project-details-page.pd-page {
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.05), transparent 42%),
        radial-gradient(circle at 100% 8%, rgba(20, 184, 166, 0.05), transparent 40%),
        transparent;
}

@media (max-width: 900px) {
    .pd-hero__facts {
        margin-left: 0.85rem;
        margin-right: 0.85rem;
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

.pd-hero--compact {
    margin: 0 0 12px;
    padding: 16px;
}

.pd-hero--compact .pd-hero__title {
    font-size: 18px;
}

/* —— Nav pills —— */
.pd-nav {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-bottom: 18px;
    padding: 6px;
    border-radius: 9911px;
    background: rgba(241, 245, 249, 0.8);
    border: 0px solid #e2e8f0;
    width: fit-content;
    max-width: 100%;
}

.pd-nav__item {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 11px 16px;
    border: none;
    border-radius: 9911px;
    background: transparent;
    font-size: 13px;
    font-weight: 700;
    color: #64748b;
    cursor: pointer;
    transition: 0.18s ease;
    text-decoration: none !important;
}

.pd-nav__item i {
    font-size: 14px;
    opacity: 0.85;
}

.pd-nav__item:hover:not(.is-disabled) {
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(255, 255, 255, 0.7);
}

.pd-nav__item.is-active {
    color: #fff;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-accent, #14b8a6));
    box-shadow: 0 8px 20px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
}

.pd-nav__item.is-disabled {
    opacity: 0.45;
    cursor: not-allowed;
}

.pd-nav__item--link {
    color: #64748b;
}

.pd-nav__item--link.active,
.pd-nav__item--link:hover {
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(255, 255, 255, 0.7);
}

/* —— Summary stat tiles —— */
.pd-summary-stats {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: var(--pd-gap);
    margin-bottom: var(--pd-gap);
}

.pd-stat-tile {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 16px 18px;
    border-radius: var(--pd-radius-sm);
    border: 0px solid transparent;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.pd-stat-tile:hover {
    transform: translateY(-2px);
    box-shadow: 0 12px 28px rgba(15, 23, 42, 0.08);
}

.pd-stat-tile__icon {
    width: 42px;
    height: 42px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 14px;
    font-size: 18px;
}

.pd-stat-tile__value {
    display: block;
    font-size: 24px;
    font-weight: 800;
    letter-spacing: -0.5px;
    line-height: 1;
    color: #0f172a;
}

.pd-stat-tile__label {
    display: block;
    margin-top: 4px;
    font-size: 12px;
    font-weight: 600;
    color: #64748b;
}

.pd-stat-tile--mint {
    background: linear-gradient(135deg, #ecfdf5, #d1fae5);
    border-color: #a7f3d0;
}
.pd-stat-tile--mint .pd-stat-tile__icon {
    background: #10b981;
    color: #fff;
}

.pd-stat-tile--sky {
    background: linear-gradient(135deg, #eff6ff, #dbeafe);
    border-color: #bfdbfe;
}
.pd-stat-tile--sky .pd-stat-tile__icon {
    background: #3b82f6;
    color: #fff;
}

.pd-stat-tile--violet {
    background: linear-gradient(135deg, #f5f3ff, #ede9fe);
    border-color: #ddd6fe;
}
.pd-stat-tile--violet .pd-stat-tile__icon {
    background: #8b5cf6;
    color: #fff;
}

.pd-stat-tile--sun {
    background: linear-gradient(135deg, #fffbeb, #fef3c7);
    border-color: #fde68a;
}
.pd-stat-tile--sun .pd-stat-tile__icon {
    background: #f59e0b;
    color: #fff;
}

/* —— Workspace grid —— */
.pd-workspace {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 320px;
    gap: var(--pd-gap);
    align-items: start;
}

.pd-workspace__main {
    display: flex;
    flex-direction: column;
    gap: var(--pd-gap);
    min-width: 0;
}

.pd-workspace__aside,
.pd-rail {
    display: flex;
    flex-direction: column;
    gap: var(--pd-gap);
    position: sticky;
    top: 80px;
    min-width: 0;
}

.pd-rail__head {
    padding: 4px 2px 0;
}

.pd-rail__eyebrow {
    display: block;
    font-size: 10px;
    font-weight: 800;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: #94a3b8;
}

.pd-rail__hint {
    margin: 4px 0 0;
    font-size: 12px;
    color: #64748b;
    line-height: 1.4;
}

.pd-rail--embedded .pd-rail__head {
    display: none;
}

.pd-rail--embedded .pd-card {
    padding: 16px 18px;
}

.pd-rail--embedded .pd-card__title {
    font-size: 14px;
}

/* —— Cards —— */
.pd-card {
    padding: 20px 22px;
    border-radius: var(--pd-radius);
    border: 0px solid rgba(226, 232, 240, 0.95);
    background: rgba(255, 255, 255, 0.9);
    box-shadow: 0 16px 40px rgba(15, 23, 42, 0.05);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
}

.pd-card__head {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 14px;
}

.pd-card__head .pd-card__actions {
    margin-left: auto;
}

.pd-card__icon {
    width: 34px;
    height: 34px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary, #5b5ff4);
    font-size: 15px;
}

.pd-card__title {
    margin: 0;
    font-size: 15px;
    font-weight: 800;
    letter-spacing: -0.2px;
    color: #1e293b;
}

.pd-about-text {
    margin: 0;
    padding: 14px 16px;
    border-radius: var(--pd-radius-sm);
    background: linear-gradient(180deg, #f8fafc, #f1f5f9);
    border: 0px solid #e2e8f0;
    color: #475569;
    font-size: 14px;
    line-height: 1.65;
}

/* —— Fact groups —— */
.pd-fact-groups {
    display: flex;
    flex-direction: column;
    gap: var(--pd-gap);
}

.pd-fact-group {
    padding: 18px 20px;
    border-radius: var(--pd-radius);
    border: 0px solid #e2e8f0;
    background: #fff;
}

.pd-fact-group__head {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 14px;
}

.pd-fact-group__emoji {
    font-size: 22px;
    line-height: 1;
}

.pd-fact-group__title {
    margin: 0;
    font-size: 14px;
    font-weight: 800;
    color: #334155;
}

.pd-fact-group--commercial {
    background: linear-gradient(180deg, #fff, #fffbeb);
    border-color: #fde68a;
}

.pd-fact-group--people {
    background: linear-gradient(180deg, #fff, #eff6ff);
    border-color: #bfdbfe;
}

.pd-fact-group--delivery {
    background: linear-gradient(180deg, #fff, #f5f3ff);
    border-color: #ddd6fe;
}

.pd-fact-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 12px;
}

.pd-fact {
    padding: 12px 14px;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.85);
    border: 0px solid rgba(226, 232, 240, 0.8);
    transition: 0.15s ease;
}

.pd-fact:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.25);
    box-shadow: 0 6px 16px rgba(15, 23, 42, 0.05);
}

.pd-fact--wide {
    grid-column: 1 / -1;
}

.pd-fact__label {
    display: block;
    margin-bottom: 4px;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #94a3b8;
}

.pd-fact__value {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 14px;
    font-weight: 600;
    color: #1e293b;
    line-height: 1.35;
}

.pd-fact__icon {
    color: var(--lux-primary, #5b5ff4);
    font-size: 13px;
}

/* —— Collapsible sections —— */
.pd-collapsible {
    border-radius: var(--pd-radius);
    border: 0px solid #e2e8f0;
    background: #fff;
    overflow: hidden;
}

.pd-collapsible__summary {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 16px 20px;
    font-size: 14px;
    font-weight: 800;
    color: #334155;
    cursor: pointer;
    list-style: none;
    user-select: none;
    transition: background 0.15s ease;
}

.pd-collapsible__summary::-webkit-details-marker {
    display: none;
}

.pd-collapsible__summary:hover {
    background: #f8fafc;
}

.pd-collapsible__summary i:first-child {
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary, #5b5ff4);
}

.pd-collapsible__chevron {
    margin-left: auto;
    transition: transform 0.2s ease;
    color: #94a3b8;
}

.pd-collapsible[open] .pd-collapsible__chevron {
    transform: rotate(180deg);
}

.pd-collapsible__body {
    padding: 0 20px 18px;
    border-top: 1px solid #f1f5f9;
}

.pd-collapsible__body--flush {
    padding: 0;
}

.pd-card--flush {
    padding: 0;
    overflow: hidden;
}

.pd-card--flush .card,
.pd-card--flush .section-banner {
    border: none !important;
    box-shadow: none !important;
    border-radius: 0 !important;
}

/* —— Timeline aside —— */
.pd-timeline {
    position: relative;
    padding-left: 8px;
}

.pd-timeline__step {
    position: relative;
    display: flex;
    gap: 14px;
    padding-bottom: 18px;
    padding-left: 20px;
}

.pd-timeline__step:not(:last-child)::before {
    content: "";
    position: absolute;
    left: 5px;
    top: 14px;
    bottom: 0;
    width: 2px;
    background: #e2e8f0;
}

.pd-timeline__step.is-active .pd-timeline__dot {
    background: var(--lux-primary, #5b5ff4);
    box-shadow: 0 0 0 4px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.2);
}

.pd-timeline__dot {
    position: absolute;
    left: 0;
    top: 4px;
    width: 12px;
    height: 12px;
    border-radius: 50%;
    background: #cbd5e1;
    border: 2px solid #fff;
    z-index: 1;
}

.pd-timeline__label {
    display: block;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #94a3b8;
}

.pd-timeline__value {
    display: block;
    font-size: 14px;
    font-weight: 700;
    color: #1e293b;
}

.pd-meta-list {
    margin-top: 8px;
    padding-top: 12px;
    border-top: 1px dashed #e2e8f0;
}

.pd-meta-list__row {
    display: flex;
    justify-content: space-between;
    gap: 8px;
    padding: 6px 0;
    font-size: 12px;
    color: #64748b;
}

.pd-meta-list__row strong {
    color: #1e293b;
    font-weight: 700;
    text-align: right;
}

/* —— Deliverables panel —— */
.pd-deliverables {
    padding: 18px 20px;
    border-radius: var(--pd-radius);
    border: 0px solid rgba(226, 232, 240, 0.95);
    background: rgba(255, 255, 255, 0.9);
    box-shadow: 0 16px 40px rgba(15, 23, 42, 0.05);
}

.pd-deliverables__head {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 12px;
}

.pd-deliverables__icon {
    width: 34px;
    height: 34px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    background: rgba(20, 184, 166, 0.12);
    color: #0d9488;
}

.pd-deliverables__title {
    margin: 0;
    font-size: 15px;
    font-weight: 800;
    color: #1e293b;
}

.pd-deliverables .card {
    border: none !important;
    box-shadow: none !important;
    background: transparent !important;
    margin: 0 !important;
}

.pd-deliverables .card-header {
    display: none;
}

.pd-deliverables .card-body {
    padding: 0 !important;
}

.pd-deliverables h4 {
    color: var(--lux-primary, #5b5ff4) !important;
    font-weight: 800 !important;
}

.pd-deliverables .progress {
    height: 6px;
    border-radius: 9911px;
    background: #e2e8f0;
    overflow: hidden;
}

.pd-deliverables .progress-bar-success {
    background: linear-gradient(90deg, var(--lux-accent, #14b8a6), var(--lux-primary, #5b5ff4)) !important;
    border-radius: 9911px;
}

/* —— Feedback teaser —— */
.pd-feedback-teaser {
    display: flex;
    align-items: center;
    gap: 16px;
    width: 100%;
    padding: 18px 22px;
    border: 0px dashed rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
    border-radius: var(--pd-radius);
    background: linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06), rgba(20, 184, 166, 0.06));
    cursor: pointer;
    text-align: left;
    transition: 0.18s ease;
}

.pd-feedback-teaser:hover {
    border-style: solid;
    transform: translateY(-1px);
    box-shadow: 0 12px 28px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.pd-feedback-teaser__icon {
    width: 44px;
    height: 44px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 14px;
    background: var(--lux-primary, #5b5ff4);
    color: #fff;
    font-size: 18px;
    flex-shrink: 0;
}

.pd-feedback-teaser__copy {
    display: flex;
    flex-direction: column;
    gap: 2px;
    flex: 1;
}

.pd-feedback-teaser__copy strong {
    font-size: 14px;
    color: #1e293b;
}

.pd-feedback-teaser__copy span {
    font-size: 12px;
    color: #64748b;
}

.pd-feedback-teaser__arrow {
    color: var(--lux-primary, #5b5ff4);
    font-size: 18px;
}

/* —— Comments card —— */
.pd-card--comments {
    padding: 0;
    overflow: hidden;
}

.pd-card__head--comments {
    padding: 18px 22px 0;
    margin-bottom: 0;
}

.pd-card--comments .card {
    border: none !important;
    box-shadow: none !important;
    margin: 0 !important;
    background: transparent !important;
}

.pd-card--comments .card-header {
    padding: 12px 22px 0 !important;
    border-bottom: 1px solid #f1f5f9 !important;
    background: transparent !important;
}

.pd-card--comments .page-header-tab .nav-link {
    border-radius: 9911px !important;
    padding: 8px 14px !important;
    font-size: 12px !important;
    font-weight: 700 !important;
    margin-right: 4px;
}

.pd-card--comments .page-header-tab .nav-link.active {
    color: var(--lux-primary-dark, #3730a3) !important;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1) !important;
}

.pd-card--checklist .section-banner,
.pd-card--checklist .subHeading {
    border-radius: 0;
}

/* —— Empty state —— */
.pd-empty {
    text-align: center;
    padding: 48px 24px;
}

.pd-empty.lux-register-empty {
    padding: 0;
    text-align: left;
}

.pd-empty.lux-register-empty .lux-register-empty__copy {
    text-align: left;
}

.pd-empty__title {
    margin: 16px 0 6px;
    font-size: 16px;
    font-weight: 700;
    color: #334155;
}

.pd-empty__hint {
    margin: 0;
    font-size: 13px;
    color: #94a3b8;
}

/* —— Embedded / sidebar —— */
.pd-overview--embedded {
    padding: 0;
}

.pd-overview--embedded .pd-summary-stats {
    grid-template-columns: repeat(2, 1fr);
}

.pd-overview--embedded .pd-workspace {
    grid-template-columns: minmax(0, 1fr) minmax(220px, 280px);
    gap: 14px;
}

.pd-overview--embedded .pd-workspace__aside,
.pd-overview--embedded .pd-rail {
    position: static;
    top: auto;
}

.view_project_right_sidebar.lux-view-project-panel .lux-create-panel__body {
    padding: 0;
    overflow: hidden;
}

.view_project_right_sidebar.lux-view-project-panel .lux-view-project-panel__scroll {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    overflow-x: hidden;
    padding: 0 18px 24px;
    -webkit-overflow-scrolling: touch;
}

.view_task_right_sidebar.lux-view-deliverable-panel .lux-create-panel__body,
.view_project_right_sidebar.lux-view-po-panel .lux-create-panel__body {
    padding: 0;
    overflow: hidden;
}

.view_task_right_sidebar.lux-view-deliverable-panel .lux-view-deliverable-panel__scroll,
.view_project_right_sidebar.lux-view-po-panel .lux-view-po-panel__scroll {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    overflow-x: hidden;
    padding: 0 18px 24px;
    -webkit-overflow-scrolling: touch;
}

.lux-create-panel--invoice .lux-invoice-generate {
    display: flex;
    flex-direction: column;
    min-height: 0;
    height: 100%;
}

.lux-invoice-generate__form {
    flex: 1 1 auto;
    min-height: 0;
    overflow: auto;
    padding: 0 0.15rem;
}

.lux-invoice-generate__items .lux-create-section__head {
    flex-wrap: wrap;
}

.lux-invoice-generate__add-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    margin-left: auto;
    padding: 0.35rem 0.6rem;
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
    border-radius: 8px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
    font-size: 0.6875rem;
    font-weight: 800;
    color: #4338ca;
    cursor: pointer;
}

.lux-invoice-generate__table-wrap {
    overflow: auto;
}

.lux-invoice-generate__table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
    font-size: 0.75rem;
}

.lux-invoice-generate__table th {
    padding: 0.4rem 0.5rem;
    border-bottom: 1px solid rgba(148, 163, 184, 0.35);
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #64748b;
    text-align: left;
}

.lux-invoice-generate__table td {
    padding: 0.35rem 0.5rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.85);
    vertical-align: middle;
}

.lux-invoice-generate__remove {
    display: inline-grid;
    place-items: center;
    width: 1.75rem;
    height: 1.75rem;
    border: none;
    border-radius: 8px;
    background: rgba(244, 63, 94, 0.08);
    color: #e11d48;
    cursor: pointer;
}

.lux-invoice-generate__remove:disabled {
    opacity: 0.35;
    cursor: not-allowed;
}



/* —— Luxury status control (details heroes) —— */
.lux-status-control {
    position: relative;
    display: inline-flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 0.2rem;
    z-index: 6;
}

.lux-status-control__eyebrow {
    font-size: 0.58rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-status-control__trigger {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    min-height: 2.15rem;
    padding: 0.35rem 0.7rem 0.35rem 0.55rem;
    border-radius: 999px;
    border: 1px solid transparent;
    background: #f8fafc;
    color: #0f172a;
    font-size: 0.8125rem;
    font-weight: 800;
    letter-spacing: 0.01em;
    box-shadow: 0 8px 20px rgba(15, 23, 42, 0.06);
    cursor: pointer;
    transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
}

.lux-status-control__trigger:hover:not(:disabled) {
    transform: translateY(-1px);
    box-shadow: 0 12px 26px rgba(15, 23, 42, 0.1);
}

.lux-status-control__trigger:disabled,
.lux-status-control__trigger.is-readonly {
    cursor: default;
    opacity: 1;
}

.lux-status-control__dot {
    width: 0.5rem;
    height: 0.5rem;
    border-radius: 50%;
    background: currentColor;
    box-shadow: 0 0 0 3px rgba(15, 23, 42, 0.06);
    flex-shrink: 0;
}

.lux-status-control__icon {
    display: grid;
    place-items: center;
    font-size: 0.9rem;
}

.lux-status-control__label {
    white-space: nowrap;
}

.lux-status-control__chevron {
    color: inherit;
    opacity: 0.7;
    font-size: 0.85rem;
}

.lux-status-control__trigger.is-sky {
    color: #0369a1;
    background: rgba(14, 165, 233, 0.12);
    border-color: rgba(14, 165, 233, 0.22);
}
.lux-status-control__trigger.is-indigo {
    color: #4338ca;
    background: rgba(99, 102, 241, 0.12);
    border-color: rgba(99, 102, 241, 0.22);
}
.lux-status-control__trigger.is-amber {
    color: #b45309;
    background: rgba(245, 158, 11, 0.14);
    border-color: rgba(245, 158, 11, 0.28);
}
.lux-status-control__trigger.is-green {
    color: #047857;
    background: rgba(16, 185, 129, 0.12);
    border-color: rgba(16, 185, 129, 0.24);
}
.lux-status-control__trigger.is-slate {
    color: #475569;
    background: rgba(100, 116, 139, 0.12);
    border-color: rgba(100, 116, 139, 0.22);
}

.lux-status-control__menu {
    position: absolute;
    top: calc(100% + 0.4rem);
    right: 0;
    width: min(18.5rem, 84vw);
    border-radius: 16px;
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: rgba(255, 255, 255, 0.98);
    box-shadow: 0 22px 48px rgba(15, 23, 42, 0.14);
    overflow: hidden;
    z-index: 40;
}

/* Portaled to document.body so project/deliverable heroes (overflow:hidden) cannot clip it */
.lux-status-control__menu--portal {
    position: fixed;
    top: auto;
    right: auto;
    z-index: 10060;
}

.lux-status-control__menu-head {
    padding: 0.7rem 0.85rem 0.55rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.9);
    background: linear-gradient(180deg, rgba(248, 250, 252, 0.98), rgba(255, 255, 255, 0.94));
}

.lux-status-control__menu-head strong {
    display: block;
    font-size: 0.78rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-status-control__menu-head span {
    display: block;
    margin-top: 0.1rem;
    font-size: 0.68rem;
    color: #64748b;
}

.lux-status-control__list {
    list-style: none;
    margin: 0;
    padding: 0.35rem;
}

.lux-status-control__option {
    width: 100%;
    display: grid;
    grid-template-columns: auto 1fr auto;
    align-items: center;
    gap: 0.55rem;
    padding: 0.55rem 0.55rem;
    border: 0;
    border-radius: 12px;
    background: transparent;
    text-align: left;
    cursor: pointer;
    transition: background 0.12s ease;
}

.lux-status-control__option:hover:not(:disabled):not(.is-current) {
    background: rgba(248, 250, 252, 0.95);
}

.lux-status-control__option.is-current {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
    cursor: default;
}

.lux-status-control__option.is-disabled,
.lux-status-control__option:disabled {
    opacity: 0.48;
    cursor: not-allowed;
}

.lux-status-control__option-icon {
    width: 1.85rem;
    height: 1.85rem;
    border-radius: 10px;
    display: grid;
    place-items: center;
    font-size: 0.85rem;
    background: rgba(241, 245, 249, 0.95);
    color: #475569;
}

.lux-status-control__option.is-sky .lux-status-control__option-icon {
    background: rgba(14, 165, 233, 0.12);
    color: #0369a1;
}
.lux-status-control__option.is-indigo .lux-status-control__option-icon {
    background: rgba(99, 102, 241, 0.12);
    color: #4338ca;
}
.lux-status-control__option.is-amber .lux-status-control__option-icon {
    background: rgba(245, 158, 11, 0.14);
    color: #b45309;
}
.lux-status-control__option.is-green .lux-status-control__option-icon {
    background: rgba(16, 185, 129, 0.12);
    color: #047857;
}
.lux-status-control__option.is-slate .lux-status-control__option-icon {
    background: rgba(100, 116, 139, 0.12);
    color: #475569;
}

.lux-status-control__option-copy {
    min-width: 0;
}

.lux-status-control__option-copy strong {
    display: block;
    font-size: 0.78rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-status-control__option-copy span {
    display: block;
    margin-top: 0.05rem;
    font-size: 0.65rem;
    color: #64748b;
    line-height: 1.3;
}

.lux-status-control__option-check {
    color: var(--lux-primary, #5b5ff4);
    font-size: 0.85rem;
}

.pd-hero--dense .lux-status-control__trigger {
    min-height: 1.9rem;
    padding: 0.28rem 0.6rem 0.28rem 0.45rem;
    font-size: 0.75rem;
}

.lux-create-panel--deliverable .lux-create-panel__body {
    display: flex;
    flex-direction: column;
    min-height: 0;
    padding: 0;
    overflow: hidden;
}

.lux-deliverable-create {
    display: flex;
    flex-direction: column;
    min-height: 0;
    flex: 1;
    height: 100%;
}

.lux-deliverable-create__scroll {
    flex: 1;
    min-height: 0;
    overflow: auto;
    padding: 0.85rem 1rem 1rem;
    background:
        radial-gradient(circle at top right, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.07), transparent 42%),
        linear-gradient(180deg, rgba(248, 250, 252, 0.96), rgba(255, 255, 255, 0.98));
}

.lux-deliverable-create__context {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(11rem, 1fr));
    gap: 0.55rem;
    margin-bottom: 0.85rem;
}

.lux-deliverable-create__context-card {
    display: flex;
    align-items: flex-start;
    gap: 0.55rem;
    min-width: 0;
    padding: 0.65rem 0.7rem;
    border-radius: 14px;
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: rgba(255, 255, 255, 0.96);
    box-shadow: 0 10px 24px rgba(15, 23, 42, 0.04);
}

.lux-deliverable-create__context-icon {
    width: 1.85rem;
    height: 1.85rem;
    border-radius: 10px;
    display: grid;
    place-items: center;
    flex-shrink: 0;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary-dark, #3730a3);
    font-size: 0.85rem;
}

.lux-deliverable-create__context-copy {
    min-width: 0;
}

.lux-deliverable-create__context-label {
    display: block;
    font-size: 0.62rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-deliverable-create__context-value {
    display: block;
    margin-top: 0.1rem;
    font-size: 0.8125rem;
    font-weight: 700;
    color: #0f172a;
    line-height: 1.3;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-deliverable-create__workspace {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.75rem;
    align-items: start;
}

.lux-deliverable-create__section--access {
    grid-column: 1 / -1;
}

.lux-deliverable-create__fields {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.15rem 0.75rem;
}

.lux-deliverable-create__field {
    min-width: 0;
}

.lux-deliverable-create__field--full {
    grid-column: 1 / -1;
}

.lux-create-panel--deliverable .lux-deliverable-create__section .lux-create-section__body {
    padding-top: 0.7rem;
}

.lux-create-panel--deliverable .lux-project-access {
    margin: 0;
}

.lux-create-panel--deliverable .lux-create-footer {
    flex-shrink: 0;
}

@media (max-width: 991px) {
    .lux-deliverable-create__workspace,
    .lux-deliverable-create__fields {
        grid-template-columns: 1fr;
    }

    .lux-deliverable-create__section--access,
    .lux-deliverable-create__field--full {
        grid-column: auto;
    }
}

.view_project_right_sidebar .pd-page,
.view_project_right_sidebar .pd-hero {
    margin: 0;
    border-radius: 0;
    box-shadow: none;
}

.view_project_right_sidebar .pd-hero--compact {
    margin-bottom: 12px;
    border-radius: var(--pd-radius-sm);
}

.view_project_right_sidebar .pd-nav {
    display: none;
}

/* —— Responsive —— */
@media (max-width: 1100px) {
    .pd-workspace {
        grid-template-columns: 1fr;
    }

    .pd-workspace__aside,
    .pd-rail {
        position: static;
        top: auto;
    }
}

@media (max-width: 991px) {
    .pd-overview--embedded .pd-workspace {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 767px) {
    .pd-page {
        padding: 0 12px 20px;
    }

    .pd-hero__inner {
        flex-direction: column;
    }

    .pd-hero__title {
        font-size: 20px;
    }

    .pd-summary-stats {
        grid-template-columns: repeat(2, 1fr);
    }

    .pd-nav {
        border-radius: 16px;
        width: 100%;
    }

    .pd-fact-grid {
        grid-template-columns: 1fr;
    }
}

/* ========== Team estimates — luxury panel & editor ========== */

/* ========== Team estimates — luxury summary & editor ========== */
.pd-estimates,
.lux-estimate-panel {
    position: relative;
    padding: 1.15rem 1.25rem 1.25rem;
    border-radius: 18px;
    border: 1px solid rgba(226, 232, 240, 0.95);
    background:
        radial-gradient(circle at 100% 0%, rgba(245, 158, 11, 0.08), transparent 42%),
        radial-gradient(circle at 0% 100%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06), transparent 48%),
        #fff;
    box-shadow: 0 18px 44px rgba(15, 23, 42, 0.06);
    overflow: hidden;
}

.pd-estimates::before {
    content: "";
    position: absolute;
    inset: 0 auto 0 0;
    width: 4px;
    background: linear-gradient(180deg, #f59e0b, var(--lux-primary, #5b5ff4));
}

.pd-estimates__head {
    display: flex;
    align-items: flex-start;
    gap: 0.85rem;
    margin-bottom: 1rem;
}

.pd-estimates__icon {
    width: 2.5rem;
    height: 2.5rem;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 14px;
    background: linear-gradient(135deg, rgba(245, 158, 11, 0.18), rgba(251, 191, 36, 0.08));
    color: #d97706;
    flex-shrink: 0;
    box-shadow: inset 0 0 0 1px rgba(245, 158, 11, 0.18);
}

.pd-estimates__icon i {
    font-size: 1.1rem;
}

.pd-estimates__titles {
    flex: 1;
    min-width: 0;
}

.pd-estimates__title {
    margin: 0;
    font-size: 1.05rem;
    font-weight: 800;
    letter-spacing: -0.02em;
    color: #0f172a;
}

.pd-estimates__subtitle {
    margin: 0.2rem 0 0;
    font-size: 0.78rem;
    line-height: 1.45;
    color: #64748b;
}

.lux-estimate-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(7.5rem, 1fr));
    gap: 0.65rem;
    margin-bottom: 1rem;
}

.lux-estimate-kpi {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
    padding: 0.85rem 0.9rem;
    border-radius: 14px;
    background: linear-gradient(180deg, #fff, #f8fafc);
    border: 1px solid #e2e8f0;
    box-shadow: 0 8px 18px rgba(15, 23, 42, 0.03);
}

.lux-estimate-kpi.is-muted {
    background: linear-gradient(180deg, #f8fafc, #f1f5f9);
}

.lux-estimate-kpi.is-accent {
    border-color: rgba(13, 148, 136, 0.28);
    background: linear-gradient(180deg, rgba(45, 212, 191, 0.08), #fff);
}

.lux-estimate-kpi__label {
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-estimate-kpi__value {
    font-size: 1.35rem;
    font-weight: 800;
    letter-spacing: -0.03em;
    color: #0f172a;
    line-height: 1;
}

.lux-estimate-kpi.is-accent .lux-estimate-kpi__value {
    color: #0f766e;
}

.pd-estimates__teams {
    display: flex;
    flex-direction: column;
    gap: 0.65rem;
}

.pd-estimates__team-card {
    border-radius: 14px;
    border: 1px solid #e2e8f0;
    background: #fff;
    overflow: hidden;
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.pd-estimates__team-card:hover,
.pd-estimates__team-card.is-expanded {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    box-shadow: 0 12px 28px rgba(15, 23, 42, 0.05);
}

.pd-estimates__team-row {
    display: grid;
    grid-template-columns: auto auto minmax(0, 1fr) auto;
    align-items: center;
    gap: 0.7rem;
    width: 100%;
    padding: 0.85rem 0.95rem;
    border: 0;
    background: transparent;
    text-align: left;
    cursor: pointer;
    transition: background 0.15s ease;
}

.pd-estimates__team-row:hover {
    background: #f8fafc;
}

.pd-estimates__team-chevron {
    width: 1.35rem;
    height: 1.35rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: #94a3b8;
    flex-shrink: 0;
}

.pd-estimates__team-avatar {
    width: 2.15rem;
    height: 2.15rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary, #5b5ff4);
    flex-shrink: 0;
}

.pd-estimates__team-info {
    min-width: 0;
}

.pd-estimates__team-name {
    display: block;
    font-size: 0.9rem;
    font-weight: 750;
    color: #0f172a;
}

.pd-estimates__team-meta {
    display: block;
    margin-top: 0.15rem;
    font-size: 0.74rem;
    color: #64748b;
    line-height: 1.4;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.pd-estimates__team-hours-wrap {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 0.12rem;
    flex-shrink: 0;
}

.pd-estimates__team-hours {
    font-size: 1.05rem;
    font-weight: 800;
    letter-spacing: -0.02em;
    color: var(--lux-primary-dark, #3730a3);
    line-height: 1;
}

.pd-estimates__team-hours-unit {
    font-size: 0.65rem;
    font-weight: 750;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
}

.pd-estimates__team-detail {
    padding: 0 0.85rem 0.9rem;
    border-top: 1px solid #f1f5f9;
    background: linear-gradient(180deg, #f8fafc, #fff);
}

.pd-estimates__team-detail-empty {
    margin: 0.75rem 0 0;
    font-size: 0.8rem;
    color: #94a3b8;
}

.lux-estimate-table {
    --est-cols: minmax(5.5rem, 0.85fr) minmax(4.5rem, 0.7fr) minmax(0, 1.4fr) 4.25rem;
    display: grid;
    gap: 0.25rem;
    margin-top: 0.75rem;
}

.lux-estimate-table.has-auto {
    --est-cols: minmax(5.5rem, 0.85fr) minmax(4.5rem, 0.7fr) minmax(0, 1.35fr) 3.75rem 3.75rem;
}

.lux-estimate-table.has-revised {
    --est-cols: minmax(5.5rem, 0.85fr) minmax(4.5rem, 0.7fr) minmax(0, 1.35fr) 3.75rem 3.75rem;
}

.lux-estimate-table.has-auto.has-revised {
    --est-cols: minmax(5rem, 0.8fr) minmax(4rem, 0.65fr) minmax(0, 1.2fr) 3.4rem 3.4rem 3.4rem;
}

.lux-estimate-table__head,
.lux-estimate-table__row {
    display: grid;
    grid-template-columns: var(--est-cols);
    align-items: center;
    gap: 0.5rem;
    min-width: 0;
}

.lux-estimate-table__head {
    padding: 0.35rem 0.55rem 0.5rem;
    font-size: 0.65rem;
    font-weight: 800;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    color: #94a3b8;
    border-bottom: 1px solid #e2e8f0;
}

.lux-estimate-table__head span:nth-child(n+4),
.lux-estimate-table__hours {
    text-align: right;
}

.lux-estimate-table__row {
    padding: 0.55rem;
    border-radius: 10px;
    background: #fff;
    border: 1px solid transparent;
    font-size: 0.8rem;
}

.lux-estimate-table__row:nth-child(even) {
    background: rgba(248, 250, 252, 0.9);
}

.lux-estimate-table__row:hover {
    border-color: #e2e8f0;
}

.lux-estimate-table__month,
.lux-estimate-table__type {
    font-weight: 700;
    color: #334155;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-estimate-table__type {
    display: inline-flex;
    width: fit-content;
    max-width: 100%;
    padding: 0.12rem 0.45rem;
    border-radius: 999px;
    font-size: 0.68rem;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-estimate-table__resource {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-weight: 600;
    color: #0f172a;
}

.lux-estimate-table__hours {
    font-weight: 800;
    color: #0f172a;
    font-variant-numeric: tabular-nums;
}

.lux-estimate-table__hours.is-muted {
    color: #64748b;
}

.lux-estimate-table__hours.is-accent {
    color: #0f766e;
}

.pd-estimates__extra {
    display: flex;
    flex-wrap: wrap;
    gap: 0.75rem;
    margin-top: 0.85rem;
    padding-top: 0.85rem;
    border-top: 1px dashed #e2e8f0;
    font-size: 0.75rem;
    font-weight: 600;
    color: #64748b;
}

.pd-estimates__empty {
    text-align: center;
    padding: 1.5rem 1rem;
    color: #94a3b8;
}

.pd-estimates__empty i {
    display: block;
    font-size: 1.75rem;
    margin-bottom: 0.55rem;
    opacity: 0.55;
}

.pd-estimates__empty p {
    margin: 0 0 0.35rem;
    font-size: 0.9rem;
    font-weight: 700;
    color: #64748b;
}

.pd-estimates__empty-hint {
    display: block;
    margin-bottom: 0.9rem;
    font-size: 0.78rem;
    line-height: 1.45;
    color: #94a3b8;
}

.pd-estimates__empty--sidebar {
    padding: 2.25rem 1.25rem;
    border-radius: 16px;
    border: 1px dashed #cbd5e1;
    background: #f8fafc;
}

.lux-estimate-kpi.is-hero {
    grid-column: span 1;
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    background: linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1), #fff);
}

.lux-estimate-kpi__unit {
    font-size: 0.65rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #94a3b8;
    font-style: normal;
}

.lux-estimate-legend {
    display: flex;
    flex-wrap: wrap;
    gap: 0.55rem 1rem;
    margin: 0 0 0.9rem;
    padding: 0.55rem 0.7rem;
    border-radius: 12px;
    background: #f8fafc;
    border: 1px solid #e2e8f0;
}

.lux-estimate-legend__item {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    font-size: 0.72rem;
    font-weight: 650;
    color: #475569;
}

.lux-estimate-legend__item i {
    width: 0.55rem;
    height: 0.55rem;
    border-radius: 999px;
    background: #94a3b8;
}

.lux-estimate-legend__item.is-primary i { background: var(--lux-primary, #5b5ff4); }
.lux-estimate-legend__item.is-muted i { background: #64748b; }
.lux-estimate-legend__item.is-accent i { background: #0d9488; }

.pd-estimates__teams-toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    margin-bottom: 0.55rem;
}

.pd-estimates__teams-hint {
    font-size: 0.74rem;
    font-weight: 650;
    color: #64748b;
}

.pd-estimates__team-types {
    display: flex;
    flex-wrap: wrap;
    gap: 0.3rem;
    margin-top: 0.35rem;
}

.pd-estimates__team-types em {
    font-style: normal;
    padding: 0.1rem 0.45rem;
    border-radius: 999px;
    font-size: 0.62rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.pd-estimates__team-share {
    margin-top: 0.45rem;
    height: 0.35rem;
    border-radius: 999px;
    background: #e2e8f0;
    overflow: hidden;
    max-width: 14rem;
}

.pd-estimates__team-share-bar {
    display: block;
    height: 100%;
    border-radius: inherit;
    background: linear-gradient(90deg, var(--lux-primary, #5b5ff4), var(--lux-accent, #14b8a6));
}

.pd-estimates__team-row {
    grid-template-columns: auto auto minmax(0, 1fr) auto;
}

.lux-estimate-detail {
    display: grid;
    gap: 0.75rem;
    padding-top: 0.15rem;
}

.lux-estimate-detail__type-strip {
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
}

.lux-estimate-detail__type-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.3rem 0.6rem;
    border-radius: 999px;
    background: #f1f5f9;
    border: 1px solid #e2e8f0;
    font-size: 0.74rem;
}

.lux-estimate-detail__type-chip em {
    font-style: normal;
    font-size: 0.62rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-estimate-detail__type-chip strong {
    font-weight: 800;
    color: #0f172a;
}

.lux-estimate-month {
    border-radius: 14px;
    border: 1px solid #e2e8f0;
    background: #fff;
    overflow: hidden;
}

.lux-estimate-month__head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    padding: 0.65rem 0.8rem;
    background: linear-gradient(180deg, #f8fafc, #f1f5f9);
    border-bottom: 1px solid #e2e8f0;
}

.lux-estimate-month__title {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    font-size: 0.86rem;
    color: #0f172a;
}

.lux-estimate-month__title i { color: #94a3b8; }

.lux-estimate-month__totals {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 0.1rem;
}

.lux-estimate-month__totals strong {
    font-size: 0.9rem;
    font-weight: 800;
    color: var(--lux-primary-dark, #3730a3);
}

.lux-estimate-month__totals span {
    font-size: 0.65rem;
    font-weight: 700;
    color: #94a3b8;
}

.lux-estimate-month__type {
    padding: 0.65rem 0.75rem 0.75rem;
    border-top: 1px solid #f1f5f9;
}

.lux-estimate-month__type-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.55rem;
    margin-bottom: 0.5rem;
}

.lux-estimate-month__type-label {
    display: inline-flex;
    padding: 0.15rem 0.5rem;
    border-radius: 999px;
    font-size: 0.65rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-estimate-month__type-total {
    font-size: 0.74rem;
    font-weight: 750;
    color: #64748b;
}

.lux-estimate-lines {
    list-style: none;
    margin: 0;
    padding: 0;
    display: grid;
    gap: 0.45rem;
}

.lux-estimate-lines__item {
    display: grid;
    grid-template-columns: minmax(0, 1.1fr) minmax(0, 1.4fr);
    gap: 0.65rem;
    align-items: center;
    padding: 0.65rem 0.7rem;
    border-radius: 12px;
    border: 1px solid #e2e8f0;
    background: #f8fafc;
}

.lux-estimate-lines__name {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    min-width: 0;
    font-size: 0.82rem;
    font-weight: 700;
    color: #0f172a;
}

.lux-estimate-lines__name i {
    color: #94a3b8;
    flex-shrink: 0;
}

.lux-estimate-lines__name span {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-estimate-facts {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: 0.4rem;
}

.lux-estimate-fact {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 0.1rem;
    min-width: 4.25rem;
    padding: 0.35rem 0.5rem;
    border-radius: 10px;
    background: #fff;
    border: 1px solid #e2e8f0;
}

.lux-estimate-fact span {
    font-size: 0.58rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-estimate-fact strong {
    font-size: 0.84rem;
    font-weight: 800;
    color: #0f172a;
    font-variant-numeric: tabular-nums;
}

.lux-estimate-fact.is-primary {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
}

.lux-estimate-fact.is-primary strong {
    color: var(--lux-primary-dark, #3730a3);
}

.lux-estimate-fact.is-muted strong { color: #64748b; }

.lux-estimate-fact.is-accent {
    border-color: rgba(13, 148, 136, 0.28);
    background: rgba(13, 148, 136, 0.06);
}

.lux-estimate-fact.is-accent strong { color: #0f766e; }


/* Right-rail Team estimates — narrow stacked readability */
.lux-estimate-panel--rail {
    padding: 0.9rem 0.85rem 1rem;
}

.lux-estimate-panel--rail .pd-estimates__head {
    margin-bottom: 0.7rem;
    gap: 0.55rem;
}

.lux-estimate-panel--rail .pd-estimates__icon {
    width: 2rem;
    height: 2rem;
    border-radius: 10px;
}

.lux-estimate-panel--rail .pd-estimates__title {
    font-size: 0.95rem;
}

.lux-estimate-panel--rail .pd-estimates__subtitle {
    font-size: 0.7rem;
}

.lux-estimate-rail-hero {
    margin-bottom: 0.75rem;
    padding: 0.75rem 0.8rem;
    border-radius: 14px;
    border: 1px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18);
    background:
        linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1), rgba(20, 184, 166, 0.06)),
        #fff;
}

.lux-estimate-rail-hero__total {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 0.65rem;
}

.lux-estimate-rail-hero__total span {
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-estimate-rail-hero__total strong {
    font-size: 1.35rem;
    font-weight: 800;
    letter-spacing: -0.03em;
    color: var(--lux-primary-dark, #3730a3);
    font-variant-numeric: tabular-nums;
}

.lux-estimate-rail-hero__meta {
    display: flex;
    flex-wrap: wrap;
    gap: 0.35rem 0.65rem;
    margin-top: 0.55rem;
    padding-top: 0.55rem;
    border-top: 1px dashed rgba(148, 163, 184, 0.45);
    font-size: 0.72rem;
    font-weight: 650;
    color: #64748b;
}

.lux-estimate-rail-hero__meta strong {
    color: #0f172a;
    font-weight: 800;
}

.pd-estimates__teams-toolbar--rail {
    margin-bottom: 0.45rem;
}

.lux-estimate-link-btn {
    border: 0;
    background: transparent;
    padding: 0;
    font-size: 0.72rem;
    font-weight: 750;
    color: var(--lux-primary, #5b5ff4);
    cursor: pointer;
}

.lux-estimate-link-btn:hover {
    text-decoration: underline;
}

.lux-estimate-panel--rail .pd-estimates__team-row {
    grid-template-columns: auto minmax(0, 1fr) auto;
    padding: 0.7rem 0.7rem;
    gap: 0.5rem;
}

.lux-estimate-panel--rail .pd-estimates__team-name {
    font-size: 0.84rem;
}

.lux-estimate-panel--rail .pd-estimates__team-meta {
    white-space: normal;
    font-size: 0.7rem;
}

.pd-estimates__team-preview {
    display: flex;
    flex-wrap: wrap;
    gap: 0.25rem;
    margin-top: 0.35rem;
}

.pd-estimates__team-preview em {
    font-style: normal;
    padding: 0.12rem 0.4rem;
    border-radius: 6px;
    font-size: 0.62rem;
    font-weight: 750;
    color: #475569;
    background: #f1f5f9;
    border: 1px solid #e2e8f0;
}

.lux-estimate-panel--rail .pd-estimates__team-share {
    max-width: 100%;
}

.lux-estimate-panel--rail .pd-estimates__team-hours {
    font-size: 0.95rem;
}

.lux-estimate-panel--rail .pd-estimates__team-detail {
    padding: 0 0.55rem 0.7rem;
}

.lux-estimate-detail.is-rail .lux-estimate-detail__type-strip {
    gap: 0.3rem;
}

.lux-estimate-detail.is-rail .lux-estimate-month__head {
    flex-wrap: wrap;
    padding: 0.55rem 0.65rem;
}

.lux-estimate-detail.is-rail .lux-estimate-lines__item {
    grid-template-columns: 1fr;
    gap: 0.45rem;
    padding: 0.55rem 0.6rem;
}

.lux-estimate-facts.is-stacked {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(4.5rem, 1fr));
    width: 100%;
    justify-content: stretch;
}

.lux-estimate-facts.is-stacked .lux-estimate-fact {
    align-items: flex-start;
    min-width: 0;
}

.pd-rail .lux-estimate-panel--rail {
    box-shadow: 0 10px 28px rgba(15, 23, 42, 0.05);
}


.lux-estimate-month-block__meta {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 0.05rem;
}

.lux-estimate-month-block__meta em {
    font-style: normal;
    font-size: 0.62rem;
    font-weight: 700;
    color: #94a3b8;
}

.lux-estimate-team-card__head-stat em {
    font-style: normal;
    font-size: 0.62rem;
    font-weight: 700;
    color: #64748b;
}

@media (max-width: 767px) {
    .lux-estimate-lines__item {
        grid-template-columns: 1fr;
    }

    .lux-estimate-facts {
        justify-content: flex-start;
    }

    .pd-estimates__teams-toolbar {
        flex-direction: column;
        align-items: stretch;
    }
}


/* Buttons */
.lux-estimate-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.7rem 1.1rem;
    border-radius: 999px;
    border: none;
    font-size: 0.82rem;
    font-weight: 750;
    cursor: pointer;
    transition: 0.18s ease;
}

.lux-estimate-btn:disabled {
    opacity: 0.45;
    cursor: not-allowed;
}

.lux-estimate-btn--sm {
    padding: 0.45rem 0.9rem;
    font-size: 0.75rem;
}

.lux-estimate-btn--primary {
    color: #fff;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-accent, #14b8a6));
    box-shadow: 0 8px 18px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
}

.lux-estimate-btn--primary:hover:not(:disabled) {
    transform: translateY(-1px);
    box-shadow: 0 12px 22px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
}

.lux-estimate-btn--ghost {
    color: #475569;
    background: #f1f5f9;
    border: 1px solid #e2e8f0;
}

.lux-estimate-btn--ghost:hover:not(:disabled) {
    background: #e2e8f0;
    color: #0f172a;
}

.pd-estimates__head .lux-estimate-btn--sm {
    flex-shrink: 0;
    margin-top: 0.15rem;
}

/* Editor sidebar */
.lux-estimate-sidebar__backdrop {
    position: fixed;
    inset: 0;
    z-index: 1000000;
    border: 0;
    margin: 0;
    padding: 0;
    background: rgba(15, 23, 42, 0.48);
    backdrop-filter: blur(5px);
    cursor: pointer;
}

.lux-estimate-sidebar {
    width: min(720px, 96vw) !important;
    z-index: 1000001 !important;
    box-shadow: -24px 0 60px rgba(15, 23, 42, 0.18) !important;
}

.right_sidebar.lux-estimate-sidebar:not(.open) {
    pointer-events: none;
    visibility: hidden;
}

.lux-estimate-sidebar__shell {
    display: flex;
    flex-direction: column;
    height: 100vh;
    background:
        radial-gradient(circle at 100% 0%, rgba(245, 158, 11, 0.1), transparent 36%),
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08), transparent 42%),
        #fff;
}

.lux-estimate-sidebar__head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 1rem;
    padding: 1.25rem 1.35rem 1rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.95);
}

.lux-estimate-sidebar__head-copy {
    min-width: 0;
}

.lux-estimate-sidebar__kicker {
    display: block;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-estimate-sidebar__title {
    margin: 0.25rem 0 0;
    font-size: 1.35rem;
    font-weight: 800;
    letter-spacing: -0.03em;
    color: #0f172a;
}

.lux-estimate-sidebar__subtitle {
    margin: 0.35rem 0 0;
    max-width: 34rem;
    font-size: 0.82rem;
    line-height: 1.5;
    color: #64748b;
}

.lux-estimate-sidebar__close {
    width: 2.25rem;
    height: 2.25rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1px solid #e2e8f0;
    border-radius: 12px;
    background: #fff;
    color: #64748b;
    cursor: pointer;
    flex-shrink: 0;
    transition: 0.15s ease;
}

.lux-estimate-sidebar__close:hover {
    color: #0f172a;
    background: #f8fafc;
    border-color: #cbd5e1;
}

.lux-estimate-sidebar__summary {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(6.5rem, 1fr));
    gap: 0.55rem;
    padding: 0.85rem 1.35rem;
    border-bottom: 1px solid #e2e8f0;
    background: rgba(248, 250, 252, 0.86);
}

.lux-estimate-sidebar__summary-kpi {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    padding: 0.7rem 0.8rem;
    border-radius: 12px;
    background: #fff;
    border: 1px solid #e2e8f0;
}

.lux-estimate-sidebar__summary-kpi span {
    font-size: 0.65rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-estimate-sidebar__summary-kpi strong {
    font-size: 1.15rem;
    font-weight: 800;
    letter-spacing: -0.02em;
    color: #0f172a;
    line-height: 1;
}

.lux-estimate-sidebar__summary-kpi.is-primary {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    background: linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08), #fff);
}

.lux-estimate-sidebar__summary-kpi.is-primary strong {
    color: var(--lux-primary-dark, #3730a3);
}

.lux-estimate-sidebar__summary-kpi.is-muted strong {
    color: #64748b;
}

.lux-estimate-sidebar__body {
    flex: 1;
    overflow-y: auto;
    padding: 1rem 1.35rem 1.25rem;
}

.lux-estimate-sidebar__foot {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding: 0.95rem 1.35rem;
    border-top: 1px solid #e2e8f0;
    background: #f8fafc;
}

.lux-estimate-sidebar__foot-hint {
    margin: 0;
    max-width: 18rem;
    font-size: 0.74rem;
    line-height: 1.45;
    color: #94a3b8;
}

.lux-estimate-sidebar__foot-actions {
    display: flex;
    gap: 0.55rem;
    flex-shrink: 0;
}

/* Team cards in editor */
.lux-estimate-team-card {
    margin-bottom: 1rem;
    padding: 1rem 1.05rem 1.05rem;
    border-radius: 16px;
    border: 1px solid #e2e8f0;
    background: #fff;
    box-shadow: 0 10px 24px rgba(15, 23, 42, 0.04);
}

.lux-estimate-team-card__head {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto auto;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 0.9rem;
    padding-bottom: 0.85rem;
    border-bottom: 1px solid #f1f5f9;
}

.lux-estimate-team-card__icon {
    width: 2.35rem;
    height: 2.35rem;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary, #5b5ff4);
}

.lux-estimate-team-card__copy {
    min-width: 0;
}

.lux-estimate-team-card__name {
    margin: 0;
    font-size: 0.95rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-estimate-team-card__types {
    display: block;
    margin-top: 0.15rem;
    font-size: 0.74rem;
    color: #64748b;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-estimate-team-card__head-stat {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 0.15rem;
    padding: 0.4rem 0.65rem;
    border-radius: 12px;
    background: linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08), rgba(20, 184, 166, 0.06));
    border: 1px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14);
}

.lux-estimate-team-card__head-stat span {
    font-size: 0.62rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-estimate-team-card__head-stat strong {
    font-size: 0.95rem;
    font-weight: 800;
    color: var(--lux-primary-dark, #3730a3);
    line-height: 1;
}

.lux-estimate-team-card__remove {
    width: 2rem;
    height: 2rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 0;
    border-radius: 10px;
    background: transparent;
    color: #ef4444 !important;
    opacity: 0.72;
    cursor: pointer;
}

.lux-estimate-team-card__remove:hover {
    opacity: 1;
    background: #fef2f2;
}

.lux-estimate-team-card__empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.25rem;
    padding: 1.15rem 0.75rem;
    margin-bottom: 0.5rem;
    border-radius: 12px;
    border: 1px dashed #cbd5e1;
    background: #f8fafc;
    text-align: center;
    color: #94a3b8;
}

.lux-estimate-team-card__empty i {
    font-size: 1.25rem;
    margin-bottom: 0.15rem;
}

.lux-estimate-team-card__empty p {
    margin: 0;
    font-size: 0.82rem;
    font-weight: 700;
    color: #64748b;
}

.lux-estimate-team-card__empty span {
    font-size: 0.74rem;
}

.lux-estimate-month-block {
    margin-bottom: 0.85rem;
    border-radius: 14px;
    border: 1px solid #e2e8f0;
    overflow: hidden;
    background: #fff;
}

.lux-estimate-month-block__head {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto auto;
    align-items: center;
    gap: 0.55rem;
    padding: 0.65rem 0.8rem;
    background: linear-gradient(180deg, #f8fafc, #f1f5f9);
}

.lux-estimate-month-block__title {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    min-width: 0;
    font-size: 0.82rem;
    color: #334155;
}

.lux-estimate-month-block__title i {
    color: #94a3b8;
}

.lux-estimate-month-block__title strong {
    font-weight: 800;
    color: #0f172a;
}

.lux-estimate-month-block__subtotal {
    font-size: 0.8rem;
    font-weight: 800;
    color: var(--lux-primary-dark, #3730a3);
    font-variant-numeric: tabular-nums;
}

.lux-estimate-month-block__remove {
    width: 1.75rem;
    height: 1.75rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 0;
    border-radius: 8px;
    background: transparent;
    color: #ef4444 !important;
    cursor: pointer;
}

.lux-estimate-month-block__remove:hover {
    background: #fef2f2;
}

.lux-estimate-type-block {
    padding: 0.7rem 0.8rem 0.85rem;
    border-top: 1px solid #f1f5f9;
}

.lux-estimate-type-block__bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.65rem;
    margin-bottom: 0.55rem;
}

.lux-estimate-type-block__label {
    display: inline-flex;
    padding: 0.18rem 0.55rem;
    border-radius: 999px;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-estimate-type-block__total {
    font-size: 0.75rem;
    font-weight: 750;
    color: #64748b;
    font-variant-numeric: tabular-nums;
}

/* Aligned hour grid */
.lux-estimate-grid {
    --grid-cols: minmax(0, 1fr) 4.5rem;
    display: grid;
    grid-template-columns: var(--grid-cols);
    align-items: center;
    gap: 0.45rem;
    padding: 0.45rem 0.35rem;
    border-bottom: 1px solid #f8fafc;
    font-size: 0.8rem;
    min-width: 0;
}

.lux-estimate-grid.has-auto {
    --grid-cols: minmax(0, 1fr) 4.25rem 4.25rem;
}

.lux-estimate-grid.has-revised {
    --grid-cols: minmax(0, 1fr) 4.25rem 4.25rem;
}

.lux-estimate-grid.has-auto.has-revised {
    --grid-cols: minmax(0, 1fr) 3.85rem 3.85rem 3.85rem;
}

.lux-estimate-grid--head {
    font-size: 0.65rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
    border-bottom: 1px solid #e2e8f0;
    padding-bottom: 0.45rem;
    margin-bottom: 0.15rem;
}

.lux-estimate-grid--head span:not(:first-child),
.lux-estimate-grid__cell.is-hours {
    text-align: right;
}

.lux-estimate-grid__cell.is-name {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-weight: 650;
    color: #0f172a;
}

.lux-estimate-grid__cell.is-hours {
    font-weight: 750;
    color: #0f172a;
    font-variant-numeric: tabular-nums;
}

.lux-estimate-grid__cell.is-muted {
    color: #64748b;
}

.lux-estimate-grid__cell.is-accent {
    color: #0f766e;
}

/* Legacy line classes kept for compatibility */
.lux-estimate-line {
    display: grid;
    grid-template-columns: 1fr repeat(3, 64px);
    gap: 8px;
    align-items: center;
    padding: 6px 0;
    border-bottom: 1px solid #f8fafc;
    font-size: 12px;
}

.lux-estimate-line--head {
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #94a3b8;
    border-bottom: 1px solid #e2e8f0;
    padding-bottom: 8px;
    margin-bottom: 4px;
}

.lux-estimate-line__name {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-weight: 600;
    color: #334155;
}

.lux-estimate-line__val {
    text-align: center;
    font-weight: 700;
    color: #1e293b;
}

.lux-estimate-line__val--muted {
    color: #64748b;
}

.lux-estimate-line__val--accent {
    color: #0d9488;
}

.lux-estimate-team-card__totals {
    margin-top: 0.75rem;
    padding-top: 0.75rem;
    border-top: 1px dashed #e2e8f0;
}

.lux-estimate-team-card__totals-label {
    display: block;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #94a3b8;
    margin-bottom: 0.45rem;
}

.lux-estimate-team-card__totals-vals {
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
}

.lux-estimate-team-card__total-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.35rem 0.65rem;
    border-radius: 999px;
    font-size: 0.74rem;
    background: #f1f5f9;
    color: #475569;
    border: 1px solid #e2e8f0;
}

.lux-estimate-team-card__total-chip em {
    font-style: normal;
    font-weight: 700;
    font-size: 0.65rem;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-estimate-team-card__total-chip strong {
    font-weight: 800;
    color: #0f172a;
}

.lux-estimate-add-line-btn,
.lux-estimate-add-team-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    width: 100%;
    padding: 0.75rem;
    margin-top: 0.65rem;
    border: 1px dashed rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
    border-radius: 12px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.04);
    color: var(--lux-primary, #5b5ff4);
    font-size: 0.78rem;
    font-weight: 750;
    cursor: pointer;
    transition: 0.15s ease;
}

.lux-estimate-add-line-btn:hover,
.lux-estimate-add-team-btn:hover {
    border-style: solid;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
}

.lux-estimate-add-team {
    padding: 1rem;
    border-radius: 14px;
    border: 1px solid #e2e8f0;
    background: #f8fafc;
    margin-top: 0.5rem;
}

.lux-estimate-add-team__head {
    display: flex;
    align-items: flex-start;
    gap: 0.7rem;
    margin-bottom: 0.85rem;
}

.lux-estimate-add-team__head i {
    width: 2rem;
    height: 2rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary, #5b5ff4);
    flex-shrink: 0;
}

.lux-estimate-add-team__head strong {
    display: block;
    font-size: 0.88rem;
    color: #0f172a;
}

.lux-estimate-add-team__head p {
    margin: 0.15rem 0 0;
    font-size: 0.74rem;
    color: #64748b;
}

.lux-estimate-add-team__actions {
    display: flex;
    gap: 0.5rem;
    margin-top: 0.85rem;
}

/* Add line modal */
.lux-estimate-line-modal {
    position: fixed;
    inset: 0;
    z-index: 1000002;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 1.25rem;
}

.lux-estimate-line-modal__backdrop {
    position: absolute;
    inset: 0;
    background: rgba(15, 23, 42, 0.48);
    backdrop-filter: blur(4px);
}

.lux-estimate-line-modal__panel {
    position: relative;
    width: min(540px, 100%);
    max-height: 90vh;
    overflow-y: auto;
    border-radius: 18px;
    border: 1px solid rgba(226, 232, 240, 0.95);
    background:
        radial-gradient(circle at 100% 0%, rgba(245, 158, 11, 0.08), transparent 40%),
        #fff;
    box-shadow: 0 32px 80px rgba(15, 23, 42, 0.22);
}

.lux-estimate-line-modal__head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.75rem;
    padding: 1.25rem 1.35rem 0;
}

.lux-estimate-line-modal__kicker {
    display: block;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-estimate-line-modal__title {
    margin: 0.25rem 0 0;
    font-size: 1.15rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-estimate-line-modal__form {
    padding: 1.1rem 1.35rem 1.35rem;
}

.lux-estimate-form-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.9rem;
}

.lux-estimate-field--wide {
    grid-column: 1 / -1;
}

.lux-estimate-field__label {
    display: block;
    margin-bottom: 0.4rem;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-estimate-input {
    border-radius: 12px !important;
    border: 1px solid #e2e8f0 !important;
    font-weight: 600;
}

.lux-estimate-line-modal__foot {
    display: flex;
    justify-content: flex-end;
    gap: 0.55rem;
    margin-top: 1.1rem;
    padding-top: 1rem;
    border-top: 1px solid #f1f5f9;
}

@media (max-width: 767px) {
    .lux-estimate-form-grid {
        grid-template-columns: 1fr;
    }

    .pd-estimates__team-row {
        grid-template-columns: auto minmax(0, 1fr) auto;
        grid-template-areas:
            "chevron info hours"
            "avatar info hours";
    }

    .pd-estimates__team-chevron { grid-area: chevron; }
    .pd-estimates__team-avatar { display: none; }
    .pd-estimates__team-info { grid-area: info; }
    .pd-estimates__team-hours-wrap { grid-area: hours; }

    .pd-estimates__team-detail {
        overflow-x: auto;
        -webkit-overflow-scrolling: touch;
    }

    .lux-estimate-table {
        min-width: 28rem;
    }

    .lux-estimate-table.has-auto,
    .lux-estimate-table.has-revised {
        min-width: 34rem;
    }

    .lux-estimate-table.has-auto.has-revised {
        min-width: 40rem;
    }

    .lux-estimate-sidebar {
        width: min(100vw, 100%) !important;
    }

    .lux-estimate-sidebar__foot {
        flex-direction: column;
        align-items: stretch;
    }

    .lux-estimate-sidebar__foot-actions {
        width: 100%;
    }

    .lux-estimate-sidebar__foot-actions .lux-estimate-btn {
        flex: 1;
    }

    .lux-estimate-team-card__head {
        grid-template-columns: auto minmax(0, 1fr) auto;
    }

    .lux-estimate-team-card__head-stat {
        grid-column: 2;
        align-items: flex-start;
        justify-self: start;
    }

    .lux-estimate-grid,
    .lux-estimate-grid.has-auto,
    .lux-estimate-grid.has-revised,
    .lux-estimate-grid.has-auto.has-revised,
    .lux-estimate-line {
        grid-template-columns: minmax(0, 1fr) repeat(3, 3.1rem);
        font-size: 0.74rem;
    }
}

/* ========== Checklist — luxury panel & editor ========== */

/* ========== Project details Checklist — luxury rail summary ========== */
.pd-checklist,
.lux-checklist-panel {
    position: relative;
    padding: 1rem 0.95rem 1.05rem;
    border-radius: 18px;
    border: 1px solid rgba(226, 232, 240, 0.95);
    background:
        radial-gradient(circle at 100% 0%, rgba(16, 185, 129, 0.1), transparent 42%),
        radial-gradient(circle at 0% 100%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06), transparent 48%),
        #fff;
    box-shadow: 0 16px 40px rgba(15, 23, 42, 0.06);
    overflow: hidden;
}

.pd-checklist::before {
    content: "";
    position: absolute;
    inset: 0 auto 0 0;
    width: 4px;
    background: linear-gradient(180deg, #10b981, var(--lux-primary, #5b5ff4));
}

.pd-checklist.is-complete::before {
    background: linear-gradient(180deg, #059669, #34d399);
}

.pd-checklist.is-progress::before {
    background: linear-gradient(180deg, #f59e0b, #10b981);
}

.pd-checklist.is-ready::before {
    background: linear-gradient(180deg, #0ea5e9, #6366f1);
}

.pd-checklist__head {
    display: flex;
    align-items: flex-start;
    gap: 0.7rem;
    margin-bottom: 0.85rem;
}

.pd-checklist__icon {
    width: 2.35rem;
    height: 2.35rem;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    background: linear-gradient(135deg, rgba(16, 185, 129, 0.18), rgba(20, 184, 166, 0.08));
    color: #059669;
    flex-shrink: 0;
    box-shadow: inset 0 0 0 1px rgba(16, 185, 129, 0.18);
}

.pd-checklist__titles {
    flex: 1;
    min-width: 0;
}

.pd-checklist__title {
    margin: 0;
    font-size: 0.98rem;
    font-weight: 800;
    letter-spacing: -0.02em;
    color: #0f172a;
}

.pd-checklist__subtitle {
    margin: 0.15rem 0 0;
    font-size: 0.72rem;
    color: #64748b;
    line-height: 1.4;
}

.pd-checklist__hero {
    padding: 0.85rem;
    margin-bottom: 0.75rem;
    border-radius: 14px;
    border: 1px solid rgba(16, 185, 129, 0.18);
    background: linear-gradient(180deg, rgba(16, 185, 129, 0.06), #fff);
}

.pd-checklist__hero-top {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 0.7rem;
}

.pd-checklist__ring {
    position: relative;
    width: 3.25rem;
    height: 3.25rem;
    flex-shrink: 0;
}

.pd-checklist__ring svg {
    width: 100%;
    height: 100%;
    transform: rotate(-90deg);
}

.pd-checklist__ring-bg {
    fill: none;
    stroke: #e2e8f0;
    stroke-width: 3;
}

.pd-checklist__ring-fill {
    fill: none;
    stroke: var(--lux-primary, #5b5ff4);
    stroke-width: 3;
    stroke-linecap: round;
    transition: stroke-dasharray 0.4s ease;
}

.pd-checklist__ring.is-complete .pd-checklist__ring-fill {
    stroke: #10b981;
}

.pd-checklist__ring-label {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.7rem;
    font-weight: 800;
    color: #0f172a;
}

.pd-checklist__hero-copy {
    min-width: 0;
}

.pd-checklist__hero-copy strong {
    display: block;
    margin-top: 0.3rem;
    font-size: 0.9rem;
    font-weight: 800;
    color: #0f172a;
}

