    max-width: 26rem;
    font-size: 0.6875rem;
    color: #94a3b8;
    line-height: 1.4;
}

.lux-checklist-editor__foot-actions {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    margin-left: auto;
}

.lux-checklist-editor__btn {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    min-height: 2.15rem;
    padding: 0 0.95rem;
    border-radius: 999px;
    border: 1px solid transparent;
    font-size: 0.75rem;
    font-weight: 800;
    cursor: pointer;
}

.lux-checklist-editor__btn.is-ghost {
    border-color: rgba(148, 163, 184, 0.35);
    background: #fff;
    color: #475569;
}

.lux-checklist-editor__btn.is-ghost:hover {
    border-color: rgba(16, 185, 129, 0.35);
    color: #047857;
}

.lux-checklist-editor__btn.is-primary {
    background: linear-gradient(135deg, #059669, #047857);
    color: #fff;
    box-shadow: 0 10px 22px rgba(5, 150, 105, 0.28);
}

.lux-checklist-editor__error {
