}

.lux-checklist-editor__error-dismiss {
    margin-left: auto;
    border: none;
    background: transparent;
    color: inherit;
    cursor: pointer;
}

.lux-checklist-sidebar__body {
    flex: 1;
    overflow-y: auto;
    padding: 18px 22px;
    display: flex;
    flex-direction: column;
    min-height: 0;
}

.lux-checklist-sidebar__foot {
    display: flex;
    justify-content: flex-end;
    flex-wrap: wrap;
    gap: 12px;
    padding: 16px 22px;
    border-top: 1px solid #e2e8f0;
    background: #f8fafc;
}

.lux-checklist-editor__status {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 16px;
    padding: 14px;
    border-radius: 14px;
    background: #f8fafc;
    border: 1px solid #e2e8f0;
}

.lux-checklist-editor__status-copy {
    margin: 6px 0 0;
    font-size: 12px;
    color: #64748b;
}

.lux-checklist-change-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    width: 100%;
    padding: 12px;
    margin-bottom: 16px;
    border: 1px dashed rgba(16, 185, 129, 0.35);
    border-radius: 12px;
    background: rgba(16, 185, 129, 0.04);
    color: #059669;
    font-size: 12px;
    font-weight: 700;
    cursor: pointer;
}

.lux-checklist-change-btn:hover {
    border-style: solid;
    background: rgba(16, 185, 129, 0.08);
}

.lux-qt {
    display: flex;
    flex-direction: column;
    gap: 0.65rem;
}

.lux-qt-empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: 0.35rem;
    padding: 1.75rem 1rem;
    border-radius: 14px;
    border: 1px dashed rgba(148, 163, 184, 0.4);
    background: linear-gradient(180deg, rgba(248, 250, 252, 0.9), #fff);
}

.lux-qt-empty__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.75rem;
    height: 2.75rem;
    margin-bottom: 0.25rem;
    border-radius: 14px;
    background: rgba(16, 185, 129, 0.12);
    color: #059669;
    font-size: 1.15rem;
}

.lux-qt-empty strong { font-size: 0.875rem; color: #0f172a; }

.lux-qt-empty p {
    margin: 0;
    max-width: 22rem;
    font-size: 0.75rem;
    color: #64748b;
    line-height: 1.45;
}

.lux-qt-card {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    gap: 0.75rem;
    padding: 0.85rem 0.9rem;
    border-radius: 14px;
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: linear-gradient(135deg, #fff, rgba(248, 250, 252, 0.92));
    box-shadow: 0 8px 18px rgba(15, 23, 42, 0.04);
}

.lux-qt-card:hover {
    border-color: rgba(16, 185, 129, 0.28);
    box-shadow: 0 12px 24px rgba(15, 23, 42, 0.06);
}

.lux-qt-card.is-required { border-color: rgba(245, 158, 11, 0.28); }
.lux-qt-card.is-answered { border-color: rgba(16, 185, 129, 0.32); }

.lux-qt-card__rail {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.35rem;
}

.lux-qt-card__index {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.85rem;
    height: 1.85rem;
    border-radius: 10px;
    background: rgba(16, 185, 129, 0.12);
    color: #047857;
    font-size: 0.6875rem;
    font-weight: 800;
}

.lux-qt-card__reorder {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
}

.lux-qt-card__reorder-btn {
    display: inline-grid;
    place-items: center;
    width: 1.45rem;
    height: 1.45rem;
    border: 1px solid rgba(226, 232, 240, 0.95);
    border-radius: 8px;
    background: #fff;
    color: #64748b;
    cursor: pointer;
}

.lux-qt-card__reorder-btn:hover:not(:disabled) {
    color: #047857;
    border-color: rgba(16, 185, 129, 0.35);
}

.lux-qt-card__reorder-btn:disabled {
    opacity: 0.35;
    cursor: not-allowed;
}

.lux-qt-card__content {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 0.65rem;
}

.lux-qt-card__field {
    display: flex;
    flex-direction: column;
    gap: 0.28rem;
}

.lux-qt-card__label {
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-qt-card__input {
    width: 100%;
    min-height: 2.25rem;
    padding: 0.45rem 0.7rem;
    border: 1px solid rgba(226, 232, 240, 0.95);
    border-radius: 11px;
    background: #fff;
    font-size: 0.8125rem;
    font-weight: 600;
    color: #0f172a;
    outline: none;
}

.lux-qt-card__input:focus {
    border-color: rgba(16, 185, 129, 0.45);
    box-shadow: 0 0 0 3px rgba(16, 185, 129, 0.12);
}

.lux-qt-card__input--comments { margin-top: 0.35rem; }

.lux-qt-card__toolbar {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-end;
    gap: 0.65rem;
}

.lux-qt-card__type {
    flex: 1 1 12rem;
    min-width: 10rem;
    display: flex;
    flex-direction: column;
    gap: 0.28rem;
}

.lux-qt-card__toggles {
    display: inline-flex;
    flex-wrap: wrap;
    gap: 0.35rem;
}

.lux-qt-toggle {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    min-height: 2rem;
    padding: 0 0.65rem;
    border-radius: 999px;
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: #fff;
    color: #64748b;
    font-size: 0.625rem;
    font-weight: 800;
    cursor: pointer;
    user-select: none;
}

.lux-qt-toggle input {
    position: absolute;
    opacity: 0;
    pointer-events: none;
}

.lux-qt-toggle.is-on {
    border-color: rgba(16, 185, 129, 0.35);
    background: rgba(16, 185, 129, 0.1);
    color: #047857;
}

.lux-qt-card__remove {
    display: inline-grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    margin-left: auto;
    border: 1px solid #fecaca;
    border-radius: 10px;
    background: #fff;
    color: #dc2626;
    cursor: pointer;
}

.lux-qt-card__remove:hover { background: #fef2f2; }

.lux-qt-card__preview-head {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

.lux-qt-card__preview-title {
    font-size: 0.875rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.35;
}

.lux-qt-card__required {
    margin-left: 0.2rem;
    color: #d97706;
}

.lux-qt-card__preview-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 0.3rem;
}

.lux-qt-meta-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.22rem;
    padding: 0.16rem 0.45rem;
    border-radius: 999px;
    font-size: 0.625rem;
    font-weight: 700;
    color: #64748b;
    background: #f1f5f9;
}

.lux-qt-answer {
    display: flex;
    flex-direction: column;
    gap: 0.45rem;
}

.lux-qt-answer--readonly .lux-qt-answer__value {
    font-size: 0.875rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-qt-answer--readonly .lux-qt-answer__comments {
    font-size: 0.75rem;
    color: #64748b;
}

.lux-qt-bool {
    display: inline-flex;
    flex-wrap: wrap;
    gap: 0.4rem;
}

.lux-qt-bool__option {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    min-height: 2.15rem;
    padding: 0 0.85rem;
    border-radius: 999px;
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: #fff;
    color: #64748b;
    font-size: 0.75rem;
    font-weight: 800;
    cursor: pointer;
}

.lux-qt-bool__option input {
    position: absolute;
    opacity: 0;
    pointer-events: none;
}

.lux-qt-bool__option.is-selected {
    border-color: rgba(16, 185, 129, 0.4);
    background: rgba(16, 185, 129, 0.12);
    color: #047857;
}

.lux-checklist-change-modal {
    position: fixed;
    inset: 0;
    z-index: 1000100;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 1rem;
}

.lux-checklist-change-modal__backdrop {
    position: absolute;
    inset: 0;
    border: none;
    background: rgba(15, 23, 42, 0.4);
    backdrop-filter: blur(4px);
}

.lux-checklist-change-modal__panel {
    position: relative;
    z-index: 1;
    width: min(28rem, 100%);
    border-radius: 18px;
    background: #fff;
    box-shadow: 0 24px 60px rgba(15, 23, 42, 0.2);
    overflow: hidden;
}

.lux-checklist-change-modal__head {
    padding: 1rem 1.1rem 0.75rem;
    border-bottom: 1px solid #e2e8f0;
}

.lux-checklist-change-modal__kicker {
    display: block;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-checklist-change-modal__title {
    margin: 0.25rem 0 0;
    font-size: 1.05rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-checklist-change-modal__body { padding: 0.9rem 1.1rem; }

.lux-checklist-change-modal__hint {
    margin: 0 0 0.75rem;
    font-size: 0.75rem;
    color: #64748b;
}

.lux-checklist-change-modal__foot {
    display: flex;
    justify-content: flex-end;
    gap: 0.5rem;
    padding: 0.75rem 1.1rem;
    border-top: 1px solid #e2e8f0;
    background: #f8fafc;
}

.lux-checklist-inline {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    padding: 16px;
    border-radius: 14px;
    background: #f8fafc;
    border: 1px solid #e2e8f0;
}

.lux-checklist-inline__head {
    display: flex;
    align-items: center;
    gap: 12px;
}

.lux-checklist-inline__title {
    margin: 0;
    font-size: 14px;
    font-weight: 800;
    color: #1e293b;
    flex: 1;
}

.lux-checklist-inline__actions {
    display: flex;
    gap: 12px;
}

.lux-checklist-inline__action {
    font-size: 12px;
    font-weight: 700;
    color: #059669 !important;
}

.lux-checklist-inline__foot {
    display: flex;
    gap: 8px;
    margin-top: 14px;
    padding-top: 14px;
    border-top: 1px solid #e2e8f0;
}

@media (max-width: 900px) {
    .lux-checklist-editor__layout {
        grid-template-columns: 1fr;
        min-height: auto;
    }

    .lux-checklist-editor__list-pane {
        max-height: 14rem;
        border-right: none;
        border-bottom: 1px solid #e2e8f0;
    }

    .lux-checklist-editor__grid {
        grid-template-columns: 1fr;
    }

    .lux-cl-hero__inner {
        flex-direction: column;
    }
}

/* ========== Service lines — luxury panel ========== */

.pd-service-lines {
    padding: 18px 20px;
    border-radius: var(--pd-radius);
    border: 0px solid rgba(226, 232, 240, 0.95);
    background: rgba(255, 255, 255, 0.9);
    box-shadow: 0 16px 40px rgba(15, 23, 42, 0.05);
}

.pd-service-lines__head {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    margin-bottom: 14px;
}

.pd-service-lines__icon {
    width: 34px;
    height: 34px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    background: rgba(99, 102, 241, 0.12);
    color: #4f46e5;
    flex-shrink: 0;
}

.pd-service-lines__titles {
    flex: 1;
    min-width: 0;
}

.pd-service-lines__title {
    margin: 0;
    font-size: 15px;
    font-weight: 800;
    color: #1e293b;
}

.pd-service-lines__subtitle {
    margin: 2px 0 0;
    font-size: 12px;
    color: #94a3b8;
}

.pd-service-lines__hero {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
    margin-bottom: 14px;
}

.pd-service-lines__hero-stat {
    padding: 12px 14px;
    border-radius: var(--pd-radius-sm);
    background: linear-gradient(135deg, rgba(99, 102, 241, 0.08), rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06));
    border: 0px solid rgba(99, 102, 241, 0.14);
    text-align: center;
}

.pd-service-lines__hero-label {
    display: block;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b;
    margin-bottom: 4px;
}

.pd-service-lines__hero-value {
    display: block;
    font-size: 22px;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #4f46e5;
    line-height: 1;
}

.pd-service-lines__hero-value--hours {
    color: var(--lux-primary, #5b5ff4);
}

.pd-service-lines__list {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.pd-service-line-row {
    padding: 12px 14px;
    border-radius: 12px;
    background: #f8fafc;
    border: 0px solid #e2e8f0;
    transition: 0.15s ease;
}

.pd-service-line-row:hover {
    border-color: rgba(99, 102, 241, 0.25);
    box-shadow: 0 6px 16px rgba(15, 23, 42, 0.04);
}

.pd-service-line-row__top {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 8px;
}

.pd-service-line-row__name {
    font-size: 13px;
    font-weight: 700;
    color: #1e293b;
    line-height: 1.35;
}

.pd-service-line-row__cost {
    font-size: 14px;
    font-weight: 800;
    color: #4f46e5;
    flex-shrink: 0;
}

.pd-service-line-row__metrics {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 12px;
    font-size: 12px;
    font-weight: 600;
    color: #64748b;
}

.pd-service-line-row__metrics i {
    margin-right: 4px;
    opacity: 0.75;
}

.pd-service-line-row__share {
    margin-left: auto;
    padding: 2px 8px;
    border-radius: 9911px;
    background: rgba(99, 102, 241, 0.1);
    color: #4f46e5;
    font-size: 12px;
    font-weight: 800;
}

.pd-service-line-row__bar {
    height: 4px;
    margin-top: 12px;
    border-radius: 9911px;
    background: #e2e8f0;
    overflow: hidden;
}

.pd-service-line-row__bar span {
    display: block;
    height: 100%;
    border-radius: 9911px;
