}

.profile-page .lux-settings-tab__body .profile-security-wrap,
.profile-page .lux-settings-tab__body .profile-access-wrap {
    padding: 0;
}

.profile-access-refresh.lux-pd-tab__link-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    margin: 0 0 0.15rem;
    padding: 0.4rem 0.7rem;
    border-radius: 999px;
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
    font-size: 0.625rem;
    font-weight: 800;
    color: var(--lux-primary-dark, #3730a3);
    cursor: pointer;
}

.profile-access-refresh.lux-pd-tab__link-btn:hover {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.profile-access-empty {
    margin: 0;
    padding: 1.25rem;
    text-align: center;
    font-size: 0.75rem;
    font-weight: 600;
    color: #64748b;
}

.profile-page .profile-access-fieldset {
    margin: 0;
    padding: 0;
    border: none;
    min-width: 0;
}

.profile-page__empty {
    text-align: center;
}

.profile-page__empty-icon {
    display: inline-grid;
    place-items: center;
    width: 3rem;
    height: 3rem;
    margin-bottom: 0.65rem;
    border-radius: 14px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary-dark, #3730a3);
    font-size: 1.25rem;
}

/* Luxury aside panels (teams / service lines) */
.lux-profile-aside-card {
    border-radius: 16px;
    border: 0px solid rgba(15, 23, 42, 0.08);
    background: #fff;
    overflow: hidden;
    box-shadow: 0 8px 22px rgba(15, 23, 42, 0.05);
}

.lux-profile-aside-card__head {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.75rem 0.85rem;
    border-bottom: 1px solid rgba(15, 23, 42, 0.06);
    background: linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.05), #fff 55%);
}

.lux-profile-aside-card__icon {
    width: 2rem;
    height: 2rem;
    display: grid;
    place-items: center;
    border-radius: 10px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    color: var(--lux-primary-dark, #3730a3);
    flex-shrink: 0;
}

.lux-profile-aside-card__title {
    margin: 0;
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-profile-aside-card__body {
    padding: 0.75rem 0.85rem 0.85rem;
}

.lux-profile-aside-meta {
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
    margin-bottom: 0.65rem;
}

.lux-profile-aside-meta__label,
.lux-profile-aside-subblock__label {
    font-size: 0.5625rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-profile-aside-meta__value {
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-profile-aside-subblock {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
}

.lux-profile-section.profile-section {
    border-color: rgba(15, 23, 42, 0.07);
    box-shadow: 0 4px 14px rgba(15, 23, 42, 0.04);
}

.profile-page .pd-workspace {
    gap: var(--pd-gap, 18px);
    align-items: start;
}

.profile-page .pd-workspace__main {
    gap: var(--pd-gap, 18px);
}

.profile-page .pd-workspace__aside {
    gap: var(--pd-gap, 18px);
}

.profile-page .pd-empty {
    margin: 0;
    padding: 2rem 1.25rem;
}

/* —— Loading skeleton (profile details) —— */
.profile-page-skeleton {
    display: flex;
    flex-direction: column;
    gap: var(--pd-gap, 14px);
}

.profile-page-skeleton__hero {
    margin: 0;
    padding: 0.85rem 0.95rem 0.95rem;
    border-radius: var(--pd-radius, 16px);
    border: 0px solid rgba(226, 232, 240, 0.95);
    background: rgba(255, 255, 255, 0.9);
    box-shadow: 0 16px 40px rgba(15, 23, 42, 0.05);
}

.profile-page-skeleton__hero-row {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
    gap: 0.85rem;
    align-items: flex-start;
}

.profile-page-skeleton__hero-copy {
    min-width: 0;
}

.profile-page-skeleton__chips {
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
    margin-top: 0.65rem;
}

.profile-page-skeleton__hero-actions {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    flex-shrink: 0;
}

.profile-page-skeleton__stats {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.625rem;
    margin-top: 0.75rem;
    padding-top: 0.75rem;
    border-top: 1px solid rgba(226, 232, 240, 0.9);
}

.profile-page-skeleton__nav {
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
    margin-bottom: 0;
}

.profile-page-skeleton__workspace.pd-workspace {
    margin: 0;
}

.profile-page-skeleton__tab {
    padding: 0;
    overflow: hidden;
}

.profile-page-skeleton__tab-head {
    display: flex;
    align-items: flex-start;
    gap: 0.75rem;
    padding: 1rem 1.1rem 0.85rem;
    border-bottom: 1px solid rgba(15, 23, 42, 0.06);
}

.profile-page-skeleton__tab-head-copy {
    flex: 1;
    min-width: 0;
}

.profile-page-skeleton__aside-card {
    padding: 0.85rem;
}

.profile-page-skeleton__form-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.75rem 1rem;
    margin-top: 1.25rem;
}

.profile-page-skeleton__field {
    min-width: 0;
}

@media (max-width: 991px) {
    .profile-page-skeleton__stats {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .profile-page-skeleton__workspace.pd-workspace {
        grid-template-columns: minmax(0, 1fr);
    }
}

@media (max-width: 575px) {
    .profile-page-skeleton__hero-row {
        grid-template-columns: auto minmax(0, 1fr);
    }

    .profile-page-skeleton__hero-actions {
        grid-column: 1 / -1;
        justify-content: flex-end;
    }

    .profile-page-skeleton__form-grid {
        grid-template-columns: minmax(0, 1fr);
    }
}

/* —— Profile hero (pd-hero + collapse, aligned with project details) —— */
.profile-hero {
    padding: 0;
}

.profile-hero__shell {
    position: relative;
    display: flex;
    flex-direction: column;
    gap: 0;
}

.profile-hero__header-bar {
    margin-bottom: 0;
    align-items: flex-start;
}

.profile-hero:not(.profile-hero--collapsed) .profile-hero__header-bar {
    margin-bottom: 0;
    padding-bottom: 0.55rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.9);
}

.profile-hero--collapsed .profile-hero__header-bar {
    margin-bottom: 0;
    padding-bottom: 0;
    border-bottom: none;
}

.profile-hero__header-actions {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    flex-wrap: wrap;
    gap: 0.4rem;
    flex-shrink: 0;
}

.profile-hero__lead {
    display: flex;
    align-items: flex-start;
    gap: 16px;
    min-width: 0;
    flex: 1;
}

.profile-hero__identity-block {
    display: flex;
    flex: 1;
    min-width: 0;
    gap: 1.25rem;
    align-items: flex-start;
}

.profile-hero__identity-block .pd-hero__identity {
    flex: 1 1 240px;
    min-width: 0;
}

.profile-hero__rail {
    flex: 1 1 300px;
    max-width: 440px;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
    align-self: stretch;
}

.profile-hero__rail-panel {
    padding: 12px 12px;
    border-radius: 14px;
    border: 0px solid rgba(226, 232, 240, 0.95);
    background: rgba(255, 255, 255, 0.92);
    box-shadow: 0 4px 12px rgba(15, 23, 42, 0.03);
    min-width: 0;
}

.profile-hero__rail .profile-hero__glance-title {
    margin-bottom: 8px;
}

.profile-hero__rail .profile-hero__skill-chips {
    margin-bottom: 6px;
}

.profile-hero__rail .profile-hero__glance-sub {
    margin-top: 2px;
}

.profile-hero__rail .profile-hero__glance-sub-label {
    margin-bottom: 4px;
}

.profile-hero__avatar-wrap {
    position: relative;
    flex-shrink: 0;
    width: 88px;
    height: 88px;
    border-radius: 22px;
    overflow: visible;
    border: 3px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.2);
    box-shadow: 0 12px 28px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16);
    background: #f8fafc;
}

.profile-hero__avatar-wrap .profile-avatar-upload,
.profile-hero__avatar-wrap .profile-avatar-upload__frame {
    width: 100%;
    height: 100%;
    margin: 0;
    border-radius: inherit;
    overflow: hidden;
}

.profile-hero--collapsed {
    padding: 0.55rem 0.65rem 0.65rem;
}

.profile-hero--collapsed .profile-hero__avatar-wrap {
    width: 64px;
    height: 64px;
    border-radius: 16px;
}

.profile-hero__avatar-wrap .card,
.profile-hero__avatar-wrap > div {
    border: none !important;
    box-shadow: none !important;
    margin: 0 !important;
    background: transparent !important;
    height: 100%;
}

.profile-hero__avatar-wrap .crop-container {
    position: relative;
    width: 100%;
    height: 100%;
}

.profile-hero__avatar-wrap .profileImgHolder {
    width: 100%;
    height: 100%;
    object-fit: cover;
    border-radius: 24px;
}

.profile-hero__avatar-wrap .imageChangeButton,
.profile-hero__avatar-wrap .profile-avatar-upload__trigger {
    position: absolute;
    bottom: 4px;
    right: 4px;
    z-index: 2;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    margin: 0;
    padding: 0;
    border: 2px solid #fff;
    background: rgba(15, 23, 42, 0.82);
    border-radius: 9911px;
    color: #fff;
    font-size: 13px;
    line-height: 1;
    cursor: pointer;
    float: none;
    top: auto;
    left: auto;
    transition: background 0.14s ease, transform 0.14s ease;
}

.profile-hero__avatar-wrap .profile-avatar-upload__trigger:hover {
    background: var(--lux-primary-dark, #3730a3);
    transform: scale(1.05);
}

/* Profile photo crop modal */
.profile-photo-crop {
    position: fixed;
    inset: 0;
    z-index: 12050;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 1rem;
}

.profile-photo-crop__backdrop {
    position: absolute;
    inset: 0;
    border: none;
    background: rgba(15, 23, 42, 0.55);
    backdrop-filter: blur(4px);
    cursor: pointer;
}

.profile-photo-crop__panel {
    position: relative;
    z-index: 1;
    width: min(100%, 420px);
    border-radius: 20px;
    border: 0px solid rgba(226, 232, 240, 0.95);
    background: #fff;
    box-shadow: 0 28px 70px rgba(15, 23, 42, 0.22);
    overflow: hidden;
}

.profile-photo-crop__head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.75rem;
    padding: 1rem 1.1rem 0.75rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.9);
}

.profile-photo-crop__kicker {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
}

.profile-photo-crop__kicker i {
    color: var(--lux-primary, #5b5ff4);
}

.profile-photo-crop__title {
    margin: 0.2rem 0 0;
    font-size: 1rem;
    font-weight: 800;
    color: #0f172a;
}

.profile-photo-crop__sub {
    margin: 0.25rem 0 0;
    font-size: 12px;
    font-weight: 600;
    color: #64748b;
}

.profile-photo-crop__close {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border: 0px solid #e2e8f0;
    border-radius: 9911px;
    background: #fff;
    color: #64748b;
    cursor: pointer;
}

.profile-photo-crop__stage {
    position: relative;
    height: 320px;
    background: #0f172a;
}

.profile-photo-crop__zoom {
    display: flex;
    align-items: center;
    gap: 0.65rem;
    padding: 0.75rem 1.1rem;
    border-top: 1px solid rgba(226, 232, 240, 0.9);
}

.profile-photo-crop__zoom-label {
    flex-shrink: 0;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.profile-photo-crop__zoom input[type="range"] {
    flex: 1;
    min-width: 0;
}

.profile-photo-crop__foot {
    display: flex;
    justify-content: flex-end;
    gap: 0.625rem;
    padding: 0.75rem 1.1rem 1rem;
    border-top: 1px solid rgba(226, 232, 240, 0.9);
}

.profile-photo-crop__btn {
    min-height: 2rem;
    padding: 0 0.9rem;
    border-radius: 9911px;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    cursor: pointer;
}

.profile-photo-crop__btn--ghost {
    border: 0px solid #e2e8f0;
    background: #fff;
    color: #475569;
}

.profile-photo-crop__btn--primary {
    border: none;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
    color: #fff;
}

.profile-photo-crop__btn--primary:disabled {
    opacity: 0.55;
    cursor: not-allowed;
}

.profile-hero__status--inline {
    display: inline-flex;
    padding: 3px 12px;
    border-radius: 9911px;
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    white-space: nowrap;
}

.profile-hero__status--inline.is-green {
    color: #047857;
    background: rgba(5, 150, 105, 0.12);
    border: 0px solid rgba(5, 150, 105, 0.25);
}

.profile-hero__status--inline.is-rose {
    color: #dc2626;
    background: rgba(220, 38, 38, 0.1);
    border: 0px solid rgba(220, 38, 38, 0.25);
}

.profile-hero__status--inline.is-slate {
    color: #475569;
    background: rgba(100, 116, 139, 0.12);
    border: 0px solid rgba(100, 116, 139, 0.2);
}

.profile-hero__eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    margin-bottom: 0.35rem;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #94a3b8;
}

.profile-hero__eyebrow i {
    color: var(--lux-primary, #5b5ff4);
}

.profile-hero__meta-row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
}

.profile-hero__collapsed-line {
    margin: 8px 0 0;
    font-size: 12px;
    font-weight: 600;
    color: #64748b;
    line-height: 1.45;
}

.profile-hero__actions {
    flex-shrink: 0;
}

.profile-hero__action {
    text-decoration: none;
    color: #64748b;
}

.profile-hero__action:hover {
    color: var(--lux-primary-dark, #3730a3);
}

/* —— At-a-glance: luxury stat ribbon (no boxed cards) —— */
.profile-hero__glance {
    margin-top: 0.85rem;
    padding: 0.75rem 0.85rem 0.8rem;
    border-radius: 16px;
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.07), transparent 48%),
        radial-gradient(circle at 100% 100%, rgba(20, 184, 166, 0.05), transparent 42%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.72), rgba(248, 250, 252, 0.55));
