.profile-hero__stat-hint {
    font-size: 12px;
    font-weight: 600;
    color: #64748b;
    line-height: 1.35;
}

.profile-hero__glance-title {
    display: flex;
    align-items: center;
    gap: 6px;
    margin: 0 0 12px;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b;
}

.profile-hero__glance-title i {
    color: var(--lux-primary, #5b5ff4);
    font-size: 13px;
}

.profile-hero__dates {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.profile-hero__dates--rail {
    gap: 6px;
}

.profile-hero__dates--rail .profile-hero__date {
    padding: 6px 8px;
}

.profile-hero__dates--rail .profile-hero__date-value {
    font-size: 12px;
}

.profile-hero__date {
    display: flex;
    flex-direction: column;
    gap: 2px;
    padding: 8px 12px;
    border-radius: 12px;
    background: rgba(248, 250, 252, 0.95);
    border: 0px solid rgba(226, 232, 240, 0.9);
}

.profile-hero__date.is-green {
    border-color: rgba(5, 150, 105, 0.22);
    background: rgba(5, 150, 105, 0.06);
}

.profile-hero__date.is-rose {
    border-color: rgba(220, 38, 38, 0.2);
    background: rgba(220, 38, 38, 0.05);
}

.profile-hero__date-label {
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #94a3b8;
}

.profile-hero__date-value {
    font-size: 13px;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.3;
}

.profile-hero__skill-chips {
    margin-bottom: 8px;
}

.profile-hero__glance-sub {
    margin-top: 4px;
}

.profile-hero__glance-sub-label {
    display: block;
    margin-bottom: 6px;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #94a3b8;
}

.profile-hero__chip-list {
    gap: 6px;
}

.profile-hero__glance-empty {
    font-size: 12px;
    font-weight: 600;
    color: #94a3b8;
}

.profile-aside-card__body {
    padding-top: 0;
}

.profile-aside-card__empty {
    margin: 0;
    font-size: 12px;
    font-weight: 600;
    color: #94a3b8;
}

.profile-aside-meta {
    display: flex;
    flex-direction: column;
    gap: 4px;
    margin-bottom: 12px;
}

.profile-aside-meta__label {
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.profile-aside-meta__value {
    font-size: 14px;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.35;
}

.profile-aside-subblock {
    margin-top: 12px;
}

.profile-aside-subblock__label {
    display: block;
    margin-bottom: 8px;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.profile-aside-chip-list {
    gap: 6px;
}

.profile-aside-expandable {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.profile-aside-expand {
    display: inline-flex;
    align-items: center;
    align-self: flex-start;
    gap: 0.3rem;
    margin: 0;
    padding: 0;
    border: none;
    background: none;
    font-size: 12px;
    font-weight: 800;
    color: var(--lux-primary-dark, #3730a3);
    cursor: pointer;
    transition: color 0.14s ease;
}

.profile-aside-expand:hover {
    color: var(--lux-primary, #5b5ff4);
}

.profile-aside-expand i {
    font-size: 12px;
}

.profile-aside-expand__meta {
    font-size: 12px;
    font-weight: 700;
    color: #94a3b8;
}

.profile-aside-skill-chips {
    margin-bottom: 4px;
}

.profile-page .profile-aside-card.pd-card {
    padding: 16px 18px;
}

.profile-aside {
    display: flex;
    flex-direction: column;
    gap: var(--pd-gap, 14px);
}

.profile-page .profile-aside-card .pd-card__head {
    margin-bottom: 4px;
}

.profile-page .profile-aside-card .pd-meta-list,
.profile-page .profile-aside-card .pd-timeline {
    margin: 0;
}

/* —— Personal information (luxury sections) —— */
.profile-page .pd-card--profile-luxury {
    padding: 0;
    overflow: hidden;
}

.profile-page .pd-card--profile-luxury > .pd-card__head {
    padding: 18px 22px 14px;
    margin-bottom: 0;
    border-bottom: 1px solid rgba(226, 232, 240, 0.9);
}

.profile-personal-wrap {
    padding: 18px 22px 22px;
}

.profile-personal {
    display: flex;
    flex-direction: column;
    gap: var(--pd-gap, 18px);
}

.profile-page .pd-card--flush.pd-card--access,
.profile-page .pd-card--flush.pd-card--security {
    padding: 0;
    overflow: hidden;
}

.profile-page .pd-card--flush.pd-card--access > .pd-card__head,
.profile-page .pd-card--flush.pd-card--security > .pd-card__head {
    padding: 18px 22px 14px;
    margin-bottom: 0;
    border-bottom: 1px solid rgba(226, 232, 240, 0.9);
}

.profile-page .pd-card--flush.pd-card--access .profile-access-fieldset,
.profile-page .pd-card--flush.pd-card--security .profile-security-wrap {
    padding: 18px 22px 22px !important;
}

/* —— Security settings —— */
.profile-security {
    display: flex;
    flex-direction: column;
    gap: var(--pd-gap, 14px);
}

.profile-security__section.profile-section {
    margin: 0;
}

.profile-section__icon--shield {
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.profile-security__identity-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 12px;
}

.profile-security__field {
    display: flex;
    flex-direction: column;
    gap: 6px;
    min-width: 0;
}

.profile-security__field-label {
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.profile-security__field-value {
    display: flex;
    align-items: center;
    gap: 8px;
    min-height: 2.5rem;
    padding: 0 12px;
    border-radius: 12px;
    border: 0px solid rgba(226, 232, 240, 0.95);
    background: linear-gradient(180deg, rgba(248, 250, 252, 0.98), rgba(241, 245, 249, 0.9));
    font-size: 13px;
    font-weight: 700;
    color: #334155;
}

.profile-security__field-value.is-readonly {
    color: #64748b;
}

.profile-security__field-icon {
    color: var(--lux-primary, #5b5ff4);
    font-size: 14px;
    flex-shrink: 0;
}

.profile-security__alerts {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-bottom: 14px;
}

.profile-security__alert {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    margin: 0;
    padding: 12px 12px;
    border-radius: 12px;
    font-size: 12px;
    font-weight: 700;
    line-height: 1.45;
}

.profile-security__alert i {
    flex-shrink: 0;
    margin-top: 1px;
    font-size: 14px;
}

.profile-security__alert.is-success {
    color: #047857;
    background: rgba(5, 150, 105, 0.1);
    border: 0px solid rgba(5, 150, 105, 0.22);
}

.profile-security__alert.is-error {
    color: #b91c1c;
    background: rgba(220, 38, 38, 0.08);
    border: 0px solid rgba(220, 38, 38, 0.2);
}

.profile-security__alert.is-warning {
    color: #b45309;
    background: rgba(251, 191, 36, 0.12);
    border: 0px solid rgba(217, 119, 6, 0.22);
}

.profile-security__section--password.is-disabled .profile-security__requirements,
.profile-security__section--password.is-disabled .profile-security__form,
.profile-security__section--password.is-disabled .profile-security__foot {
    opacity: 0.55;
    pointer-events: none;
    user-select: none;
}

.profile-security__section--password.is-disabled .profile-security__requirements {
    filter: grayscale(0.15);
}

.profile-security__submit:disabled {
    opacity: 0.5;
    cursor: not-allowed;
    transform: none;
    box-shadow: none;
}

/* —— Preferences & notifications (preview / local until API) —— */
.profile-page .pd-card--settings.pd-card--profile-luxury > .pd-card__head {
    padding: 18px 22px 14px;
    margin-bottom: 0;
    border-bottom: 1px solid rgba(226, 232, 240, 0.9);
}

.profile-settings {
    display: flex;
    flex-direction: column;
    gap: var(--pd-gap, 14px);
}

.profile-settings-banner {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    margin: 0;
    padding: 12px 12px;
    border-radius: 12px;
    font-size: 12px;
    font-weight: 600;
    line-height: 1.45;
}

.profile-settings-banner i {
    flex-shrink: 0;
    margin-top: 1px;
    font-size: 14px;
}

.profile-settings-banner.is-preview {
    color: #3730a3;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18);
}

.profile-settings-banner.is-preview i {
    color: var(--lux-primary, #5b5ff4);
}

.profile-settings-banner.is-muted {
    color: #64748b;
    background: rgba(248, 250, 252, 0.95);
    border: 0px solid rgba(226, 232, 240, 0.95);
}

.profile-settings-inline-hint {
    display: flex;
    align-items: center;
    gap: 6px;
    margin: 12px 0 0;
    font-size: 12px;
    font-weight: 600;
    color: #64748b;
}

.profile-settings-inline-hint.is-warning {
    color: #b45309;
}

.profile-setting-list {
    display: flex;
    flex-direction: column;
    gap: 0;
}

.profile-setting-row {
    display: grid;
    grid-template-columns: auto 1fr auto;
    align-items: center;
    gap: 12px;
    padding: 12px 0;
    border-bottom: 1px solid rgba(226, 232, 240, 0.75);
    cursor: pointer;
}

.profile-setting-row:last-child {
    border-bottom: none;
    padding-bottom: 0;
}

.profile-setting-row:first-child {
    padding-top: 0;
}

.profile-setting-row.is-disabled {
    opacity: 0.55;
    cursor: not-allowed;
}

.profile-setting-row__icon {
    display: grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    border-radius: 12px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary-dark, #3730a3);
    font-size: 0.875rem;
}

.profile-setting-row__copy {
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 0;
}

.profile-setting-row__label {
    font-size: 13px;
    font-weight: 800;
    color: #0f172a;
}

.profile-setting-row__desc {
    font-size: 12px;
    font-weight: 600;
    color: #64748b;
    line-height: 1.35;
}

.profile-setting-toggle__input {
    position: absolute;
    opacity: 0;
    width: 0;
    height: 0;
}

.profile-setting-toggle__track {
    position: relative;
    display: block;
    width: 2.5rem;
    height: 1.375rem;
    border-radius: 9911px;
    background: #cbd5e1;
    transition: background 0.18s ease;
}

.profile-setting-toggle__track::after {
    content: "";
    position: absolute;
    top: 2px;
    left: 2px;
    width: 1.125rem;
    height: 1.125rem;
    border-radius: 50%;
    background: #fff;
    box-shadow: 0 1px 4px rgba(15, 23, 42, 0.18);
    transition: transform 0.18s ease;
}

.profile-setting-toggle__input:checked + .profile-setting-toggle__track {
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
}

.profile-setting-toggle__input:checked + .profile-setting-toggle__track::after {
    transform: translateX(1.125rem);
}

.profile-setting-toggle__input:disabled + .profile-setting-toggle__track {
    opacity: 0.5;
}

.profile-setting-select {
    min-width: 10rem;
    max-width: 100%;
    min-height: 2.125rem;
    padding: 0 0.65rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 12px;
    background: #fff;
    font-size: 12px;
    font-weight: 700;
    color: #334155;
}

.profile-setting-select:disabled {
    background: #f1f5f9;
    color: #94a3b8;
    cursor: not-allowed;
}

.profile-channel-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 12px;
}

.profile-channel-card {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
    padding: 12px;
    border-radius: 14px;
    border: 0px solid rgba(226, 232, 240, 0.95);
    background: rgba(248, 250, 252, 0.95);
    min-height: 100%;
}

.profile-channel-card.is-on {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
    background: linear-gradient(180deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06), rgba(255, 255, 255, 0.96));
}

.profile-channel-card.is-soon {
    opacity: 0.72;
}

.profile-channel-card__icon {
    display: grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    border-radius: 12px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary-dark, #3730a3);
    font-size: 0.9375rem;
}

.profile-channel-card__copy {
    display: flex;
    flex-direction: column;
    gap: 2px;
    flex: 1;
}

.profile-channel-card__copy strong {
    font-size: 12px;
    font-weight: 800;
    color: #0f172a;
}

.profile-channel-card__copy span {
    font-size: 12px;
    font-weight: 600;
    color: #64748b;
    line-height: 1.35;
}

.profile-channel-card__badge {
    align-self: flex-start;
    padding: 2px 8px;
    border-radius: 9911px;
    background: rgba(148, 163, 184, 0.2);
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #64748b;
}

.profile-channel-card__switch {
    display: flex;
    align-items: center;
    margin-top: auto;
    cursor: pointer;
}

.profile-channel-card__switch input {
    position: absolute;
    opacity: 0;
    width: 0;
    height: 0;
}

.profile-quiet-hours {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    padding: 12px 12px;
    border-radius: 12px;
    background: rgba(248, 250, 252, 0.95);
    border: 0px solid rgba(226, 232, 240, 0.9);
}

.profile-quiet-hours.is-disabled {
    opacity: 0.5;
    pointer-events: none;
}

.profile-quiet-hours__field {
    display: flex;
    flex-direction: column;
    gap: 4px;
    margin: 0;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.profile-quiet-hours__input {
    min-height: 2.125rem;
    padding: 0 0.625rem;
    border: 0px solid #e2e8f0;
    border-radius: 12px;
    font-size: 13px;
    font-weight: 600;
    color: #0f172a;
}

body.lux-shell-dark .profile-settings-banner.is-preview {
    color: #c7d2fe;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

body.lux-shell-dark .profile-setting-row__label,
body.lux-shell-dark .profile-channel-card__copy strong {
    color: #e2e8f0;
}

body.lux-shell-dark .profile-channel-card,
body.lux-shell-dark .profile-quiet-hours {
    background: rgba(15, 23, 42, 0.55);
    border-color: rgba(51, 65, 85, 0.95);
}

body.lux-shell-dark .profile-setting-select,
body.lux-shell-dark .profile-quiet-hours__input {
    background: rgba(15, 23, 42, 0.65);
    border-color: rgba(51, 65, 85, 0.95);
    color: #e2e8f0;
}

/* —— Account activity (empty until server log) —— */
.profile-activity__empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    padding: 1.5rem 1.25rem;
    margin-bottom: var(--pd-gap, 14px);
    border-radius: 16px;
    border: 0px dashed rgba(148, 163, 184, 0.55);
    background:
        radial-gradient(circle at 50% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06), transparent 55%),
        rgba(248, 250, 252, 0.9);
}

.profile-activity__empty-icon {
    display: grid;
    place-items: center;
    width: 3rem;
    height: 3rem;
    margin-bottom: 0.75rem;
    border-radius: 14px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary, #5b5ff4);
    font-size: 1.35rem;
}

.profile-activity__empty-title {
    margin: 0 0 0.35rem;
    font-size: 1rem;
    font-weight: 800;
    color: #0f172a;
}

.profile-activity__empty-hint {
    margin: 0;
    max-width: 28rem;
    font-size: 12px;
    font-weight: 600;
    color: #64748b;
    line-height: 1.5;
}

.profile-activity__types {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0;
}

.profile-activity__type {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    padding: 12px 0;
    border-bottom: 1px solid rgba(226, 232, 240, 0.75);
}

.profile-activity__type:last-child {
    border-bottom: none;
    padding-bottom: 0;
}

.profile-activity__type:first-child {
    padding-top: 0;
}

.profile-activity__type-icon {
    display: grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    flex-shrink: 0;
    border-radius: 12px;
    background: rgba(148, 163, 184, 0.12);
    color: #64748b;
    font-size: 0.875rem;
}

.profile-activity__type-copy {
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 0;
}

.profile-activity__type-copy strong {
    font-size: 13px;
    font-weight: 800;
    color: #334155;
}

.profile-activity__type-copy span {
    font-size: 12px;
    font-weight: 600;
    color: #94a3b8;
    line-height: 1.35;
}

body.lux-shell-dark .profile-activity__empty {
    background: rgba(15, 23, 42, 0.45);
    border-color: rgba(51, 65, 85, 0.95);
}

body.lux-shell-dark .profile-activity__empty-title {
    color: #e2e8f0;
}

body.lux-shell-dark .profile-activity__type-copy strong {
    color: #cbd5e1;
}

.profile-security__input:disabled {
    background: #f1f5f9;
    color: #94a3b8;
    cursor: not-allowed;
}

.profile-security__requirements {
    margin-bottom: 14px;
    padding: 12px 14px;
    border-radius: 14px;
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    background:
        radial-gradient(circle at 100% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08), transparent 55%),
        rgba(248, 250, 252, 0.95);
}

.profile-security__requirements-label {
    display: block;
    margin-bottom: 8px;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
}

.profile-security__strength {
    height: 6px;
    border-radius: 9911px;
    background: #e2e8f0;
    overflow: hidden;
}

.profile-security__strength-bar {
    display: block;
    height: 100%;
    border-radius: inherit;
    background: #cbd5e1;
    transition: width 0.2s ease, background 0.2s ease;
}

.profile-security__strength-bar.is-weak {
    background: linear-gradient(90deg, #fbbf24, #f59e0b);
}

.profile-security__strength-bar.is-good {
    background: linear-gradient(90deg, #34d399, #059669);
}

.profile-security__requirements-hint {
    margin: 8px 0 0;
    font-size: 12px;
    font-weight: 600;
    color: #64748b;
}

.profile-security__form {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 14px;
}

.profile-security__input-group {
    display: flex;
    flex-direction: column;
    gap: 6px;
    min-width: 0;
}

.profile-security__input-label {
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.profile-security__input-wrap {
    position: relative;
    display: flex;
    align-items: center;
}

.profile-security__input-icon {
    position: absolute;
    left: 12px;
    z-index: 1;
    color: #94a3b8;
    font-size: 14px;
    pointer-events: none;
}

.profile-security__input {
    width: 100%;
    min-height: 2.625rem;
    padding: 0 2.5rem 0 2.35rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 12px;
    background: #fff;
    font-size: 13px;
    font-weight: 600;
    color: #0f172a;
    transition: border-color 0.14s ease, box-shadow 0.14s ease;
}

.profile-security__input:focus {
    outline: none;
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.45);
    box-shadow: 0 0 0 3px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.profile-security__input-toggle {
    position: absolute;
    right: 8px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border: none;
    border-radius: 9911px;
    background: transparent;
    color: #64748b;
    cursor: pointer;
}

.profile-security__input-toggle:hover {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
    color: var(--lux-primary-dark, #3730a3);
}

.profile-security__foot {
    display: flex;
    justify-content: flex-end;
    margin-top: 16px;
    padding-top: 14px;
    border-top: 1px solid rgba(226, 232, 240, 0.9);
}

.profile-security__submit {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    min-height: 2.25rem;
    padding: 0 1.1rem;
    border: none;
    border-radius: 9911px;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
    box-shadow: 0 8px 20px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #fff;
    cursor: pointer;
    transition: transform 0.14s ease, box-shadow 0.14s ease;
}

.profile-security__submit:hover {
    transform: translateY(-1px);
    box-shadow: 0 12px 24px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.32);
}

.profile-page .pd-card:not(.pd-card--flush) {
    margin: 0;
}

.profile-section {
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 18px;
    background: rgba(255, 255, 255, 0.96);
    box-shadow: 0 6px 20px rgba(15, 23, 42, 0.04);
    overflow: hidden;
}

.profile-section__head {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    padding: 16px 18px 12px;
    border-bottom: 1px solid rgba(226, 232, 240, 0.9);
    background: linear-gradient(180deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06), transparent);
}

.profile-section__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: 12px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    color: var(--lux-primary-dark, #3730a3);
    font-size: 16px;
    flex-shrink: 0;
}

.profile-section__title {
    margin: 0;
    font-size: 15px;
    font-weight: 800;
    color: #0f172a;
}

.profile-section__sub {
    margin: 4px 0 0;
    font-size: 12px;
    font-weight: 600;
    color: #64748b;
    line-height: 1.4;
}

.profile-section__body {
    padding: 14px 18px 18px;
}

.profile-section__empty {
    margin: 0;
    font-size: 12px;
    font-weight: 600;
    color: #94a3b8;
    font-style: italic;
}

.profile-field-grid {
    display: grid;
    gap: 12px 16px;
}

.profile-field-grid--2 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}

.profile-field-grid--3 {
    grid-template-columns: repeat(3, minmax(0, 1fr));
}

.profile-field {
    display: flex;
    flex-direction: column;
    gap: 4px;
    min-width: 0;
}

.profile-field--full {
    grid-column: 1 / -1;
}

.profile-field__label {
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
}

.profile-field__value {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 12px 12px;
    border-radius: 12px;
    border: 0px solid #e2e8f0;
    background: #f8fafc;
    font-size: 13px;
    font-weight: 700;
    color: #1e293b;
    line-height: 1.35;
    min-height: 40px;
    word-break: break-word;
}

.profile-field__icon {
    color: var(--lux-primary, #5b5ff4);
    font-size: 14px;
    flex-shrink: 0;
}

.profile-subblock {
    margin-top: 14px;
    padding-top: 14px;
    border-top: 1px dashed rgba(226, 232, 240, 0.95);
}

.profile-subblock__label {
    display: block;
    margin-bottom: 8px;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
}

.profile-chip-list,
.profile-chip-list--aside {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.profile-chip {
    display: inline-flex;
    align-items: center;
    padding: 6px 12px;
    border-radius: 9911px;
    font-size: 12px;
    font-weight: 700;
    color: #3730a3;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16);
}

.profile-skill-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.profile-skill-chip {
    padding: 6px 12px;
    border-radius: 12px;
    font-size: 12px;
    font-weight: 700;
    border: 0px solid #e2e8f0;
    background: #fff;
    color: #334155;
}

.profile-skill-chip.is-primary {
    border-color: rgba(5, 150, 105, 0.3);
    background: rgba(5, 150, 105, 0.08);
    color: #047857;
}

.profile-skill-chip.is-secondary {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.25);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
    color: #3730a3;
}

.profile-flag-list {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 12px;
    margin: 14px 0 0;
    padding: 0;
    list-style: none;
}

.profile-flag {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    padding: 12px 12px;
    border-radius: 14px;
    border: 0px solid #e2e8f0;
    background: #f8fafc;
    text-align: center;
}

.profile-flag i {
    font-size: 18px;
    color: #94a3b8;
}

.profile-flag span {
    font-size: 12px;
    font-weight: 700;
    color: #64748b;
}

.profile-flag strong {
    font-size: 12px;
    font-weight: 800;
}

.profile-flag.is-on {
    border-color: rgba(5, 150, 105, 0.3);
    background: rgba(5, 150, 105, 0.08);
}

.profile-flag.is-on i { color: #059669; }
.profile-flag.is-on strong { color: #047857; }

.profile-flag.is-off strong { color: #94a3b8; }

.profile-exit-admin {
    margin-top: 16px;
    padding: 16px 18px;
    border-radius: 16px;
    border: 0px dashed rgba(220, 38, 38, 0.35);
    background: rgba(254, 242, 242, 0.65);
}

.profile-exit-admin__head {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    margin-bottom: 12px;
}

.profile-exit-admin__head i {
    font-size: 20px;
    color: #dc2626;
}

.profile-exit-admin__head strong {
    display: block;
    font-size: 14px;
    font-weight: 800;
    color: #991b1b;
}

.profile-exit-admin__head span {
    display: block;
    font-size: 12px;
    font-weight: 600;
    color: #b91c1c;
}

.profile-exit-admin__body {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-end;
    gap: 12px;
}

.profile-exit-admin__btn {
    padding: 8px 18px;
    border: none;
    border-radius: 9911px;
    background: #dc2626;
    color: #fff;
    font-size: 12px;
    font-weight: 800;
    cursor: pointer;
}

.profile-exit-admin__btn:disabled {
    opacity: 0.45;
    cursor: not-allowed;
}

/* —— Aside enhancements —— */
.profile-aside-card--chart {
    padding-bottom: 8px;
}

.profile-org-list {
    margin-top: 12px;
    padding-top: 12px;
    border-top: 1px dashed rgba(226, 232, 240, 0.95);
}

.pd-timeline__step.is-green.is-active .pd-timeline__dot {
    background: #059669;
    box-shadow: 0 0 0 4px rgba(5, 150, 105, 0.2);
}

.pd-timeline__step.is-rose .pd-timeline__dot {
    background: #dc2626;
}

/* —— Nav —— */
.profile-nav {
    margin-bottom: var(--pd-gap, 18px);
}

/* Legacy form card (access/security) */
.pd-card--profile-form > .pd-card__head,
.pd-card--security > .pd-card__head,
.pd-card--access > .pd-card__head {
    padding: 18px 22px 0;
    margin-bottom: 0;
}

.pd-fact-grid--single {
    grid-template-columns: 1fr;
}

.pd-card--profile-form .card-body,
.pd-card--security .card-body,
.pd-card--access .profile-access-fieldset {
    padding: 0 22px 22px !important;
}

.pd-card--profile-form .card {
    border: none !important;
    box-shadow: none !important;
    margin-bottom: 12px !important;
    border-radius: var(--pd-radius-sm, 14px) !important;
    background: #f8fafc !important;
    overflow: hidden;
}

.pd-card--profile-form .card-header {
    padding: 14px 18px !important;
    background: linear-gradient(180deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06), transparent) !important;
    border-bottom: 1px solid #e2e8f0 !important;
    font-size: 13px;
    font-weight: 800;
    color: #475569;
}

.pd-card--security .form-control {
    border-radius: 12px !important;
    border: 0px solid #e2e8f0 !important;
}

.profile-access-fieldset {
    border: none;
    margin: 0;
    padding: 0;
}

.profile-empty {
    padding: 40px 24px;
}

.profile-empty__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 56px;
    height: 56px;
    border-radius: 18px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary, #5b5ff4);
    font-size: 24px;
    margin-bottom: 12px;
}

/* Dark shell */
body.lux-shell-dark .profile-section {
    background: rgba(15, 23, 42, 0.65);
    border-color: rgba(51, 65, 85, 0.95);
}

body.lux-shell-dark .profile-hero__glance {
    border-color: rgba(51, 65, 85, 0.95);
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12), transparent 48%),
        linear-gradient(180deg, rgba(15, 23, 42, 0.72), rgba(15, 23, 42, 0.55));
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

body.lux-shell-dark .profile-hero__glance-head {
    border-bottom-color: rgba(51, 65, 85, 0.9);
}

body.lux-shell-dark .profile-hero__glance-stats {
    background: rgba(15, 23, 42, 0.35);
}

body.lux-shell-dark .profile-hero__stat-value {
    color: #e2e8f0;
}

body.lux-shell-dark .profile-hero__stat:not(:last-child)::after {
    background: linear-gradient(
        180deg,
        transparent,
        rgba(71, 85, 105, 0.65) 20%,
        rgba(71, 85, 105, 0.65) 80%,
        transparent
    );
}

body.lux-shell-dark .profile-hero__rail-panel,
body.lux-shell-dark .profile-hero__date {
    background: rgba(15, 23, 42, 0.55);
    border-color: rgba(51, 65, 85, 0.95);
}

body.lux-shell-dark .profile-hero__date-value {
    color: #e2e8f0;
}

body.lux-shell-dark .profile-aside-meta__value {
    color: #e2e8f0;
}

body.lux-shell-dark .profile-security__field-value {
    background: rgba(15, 23, 42, 0.55);
    border-color: rgba(51, 65, 85, 0.95);
    color: #cbd5e1;
}

body.lux-shell-dark .profile-security__requirements {
    background: rgba(15, 23, 42, 0.45);
    border-color: rgba(51, 65, 85, 0.95);
}

body.lux-shell-dark .profile-security__input {
    background: rgba(15, 23, 42, 0.65);
    border-color: rgba(51, 65, 85, 0.95);
    color: #e2e8f0;
}

body.lux-shell-dark .profile-security__strength {
    background: rgba(51, 65, 85, 0.95);
}

body.lux-shell-dark .profile-field__value {
    background: rgba(15, 23, 42, 0.5);
    border-color: rgba(51, 65, 85, 0.95);
    color: #e2e8f0;
}

body.lux-shell-dark .profile-section__title,
body.lux-shell-dark .profile-hero-chart__title,
body.lux-shell-dark .profile-hero-stat__value {
    color: #e2e8f0;
}

@media (max-width: 1200px) {
    .profile-hero__stat {
        flex: 1 1 calc(50% - 1px);
    }

    .profile-hero__stat:nth-child(2n)::after {
        display: none;
    }

    .profile-field-grid--3 {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 767px) {
    .profile-page.pd-page {
        padding-left: 12px;
        padding-right: 12px;
        padding-bottom: 20px;
    }

    .profile-personal-wrap {
        padding: 14px 16px 18px;
    }

    .profile-page .pd-card--profile-luxury > .pd-card__head {
        padding: 16px 16px 12px;
    }

    .profile-hero__lead {
        flex-direction: column;
    }

    .profile-hero__identity-block {
        flex-direction: column;
        gap: 0.85rem;
    }

    .profile-hero__rail {
        max-width: none;
        width: 100%;
        grid-template-columns: 1fr;
    }

    .profile-hero__header-bar {
        flex-direction: column;
        align-items: stretch;
    }

    .profile-hero__header-actions {
        justify-content: flex-end;
    }

    .profile-hero__actions {
        justify-content: flex-end;
    }

    .profile-hero__glance-stats {
        flex-direction: column;
        background: transparent;
    }

    .profile-hero__stat {
        flex: 1 1 auto;
        padding: 0.6rem 0.15rem;
    }

    .profile-hero__stat::after {
        display: none;
    }

    .profile-hero__stat + .profile-hero__stat {
        border-top: 1px solid rgba(226, 232, 240, 0.75);
    }

    .profile-field-grid--2,
    .profile-field-grid--3 {
        grid-template-columns: 1fr;
    }

    .profile-flag-list {
        grid-template-columns: 1fr;
    }

    .profile-security__identity-grid,
    .profile-security__form {
        grid-template-columns: 1fr;
    }

    .profile-channel-grid {
        grid-template-columns: 1fr;
    }

    .profile-setting-row--select {
        grid-template-columns: auto 1fr;
    }

    .profile-setting-row--select .profile-setting-row__control {
        grid-column: 1 / -1;
    }

    .profile-setting-select {
        width: 100%;
    }

    .profile-nav {
        width: 100%;
        border-radius: 16px;
    }
}

/* ========== luxury-page-header.css ========== */

/* ========== Shared page inner header — luxury toolbar ========== */

.lux-page-header {
    position: sticky;
    top: 0;
    z-index: 12;
    padding: 0.625rem var(--lux-page-gutter-x, 0.75rem);
    border-bottom: 1px solid rgba(226, 232, 240, 0.95);
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.05), transparent 40%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.94));
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    overflow: visible;
}

.lux-page-header.is-query-open,
.lux-page-header:has(.is-open) {
    z-index: 1030;
}

.lux-page-header {
    --lux-page-header-search-width: 15.5rem;
    --lux-page-header-search-min-width: 9rem;
}

.lux-page-header__toolbar {
    display: flex;
    flex-wrap: nowrap;
    align-items: center;
    gap: 0.45rem;
    min-width: 0;
    overflow: visible;
}

.lux-page-header__group {
    display: inline-flex;
    flex-wrap: nowrap;
    align-items: center;
    gap: 0.35rem;
    min-width: 0;
}

.lux-page-header__group--filters {
    flex: 0 1 auto;
    min-width: 0;
    flex-wrap: nowrap;
}

.lux-page-header__group--actions {
    flex: 0 1 auto;
    position: relative;
    overflow: visible;
    flex-wrap: wrap;
    align-items: center;
    justify-content: flex-end;
    gap: 0.35rem;
    min-width: 0;
}

.lux-page-header__spacer {
    flex: 1 1 auto;
    min-width: 0.35rem;
}

.lux-page-header__team-wrap,
.lux-page-header__employee-wrap {
    position: relative;
    flex-shrink: 0;
}

.lux-page-header__team-btn,
.lux-page-header__employee-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    height: 2rem;
    padding: 0 0.625rem;
    border: 0px solid #e2e8f0;
    border-radius: 9911px;
    background: #fff;
    font-size: 0.75rem;
    font-weight: 700;
    color: #334155;
    white-space: nowrap;
    cursor: pointer;
    transition: border-color 0.14s ease, box-shadow 0.14s ease;
    max-width: 14rem;
}

.lux-page-header__employee-name {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    max-width: 9rem;
}

.lux-page-header__employee-btn.is-static {
    cursor: default;
    pointer-events: none;
}

.lux-page-header__team-btn:hover,
.lux-page-header__team-btn.is-open,
.lux-page-header__employee-btn:hover,
.lux-page-header__employee-btn.is-open {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    box-shadow: 0 4px 14px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
}

.lux-page-header__team-btn i,
.lux-page-header__employee-btn i {
    font-size: 0.75rem;
    color: var(--lux-primary, #5b5ff4);
}

.lux-page-header__team-count {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 1.0625rem;
    height: 1.0625rem;
    padding: 0 0.28rem;
    border-radius: 9911px;
    font-size: 0.6875rem;
    font-weight: 800;
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

/* —— Teams popover —— */
.lux-page-header__team-panel,
.lux-page-header__employee-panel {
    position: absolute;
    top: calc(100% + 0.45rem);
    left: 0;
    width: 18.5rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 16px;
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.98));
    box-shadow:
        0 0 0 1px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.04),
        0 20px 48px rgba(15, 23, 42, 0.14);
    overflow: hidden;
    z-index: 1040;
}

.lux-page-header__team-panel-head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.625rem;
    padding: 0.75rem 0.8rem 0.65rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.9);
    background:
        radial-gradient(circle at 100% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1), transparent 55%),
        linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.05), rgba(248, 250, 252, 0.96));
}

.lux-page-header__team-panel-head-main {
    display: flex;
    align-items: flex-start;
    gap: 0.625rem;
    min-width: 0;
}

.lux-page-header__team-panel-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 12px;
    flex-shrink: 0;
    color: var(--lux-primary, #5b5ff4);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14);
    font-size: 0.875rem;
}

.lux-page-header__team-panel-eyebrow {
    display: block;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--lux-primary, #5b5ff4);
    margin-bottom: 0.1rem;
}

.lux-page-header__team-panel-head strong {
    display: block;
    font-size: 0.75rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.2;
}

.lux-page-header__team-panel-meta {
    display: block;
    margin-top: 0.15rem;
    font-size: 0.6875rem;
    color: #64748b;
    line-height: 1.35;
}

.lux-page-header__team-panel-close {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.625rem;
    height: 1.625rem;
    padding: 0;
    border: 0px solid #e2e8f0;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.8);
    color: #64748b;
    font-size: 0.75rem;
    cursor: pointer;
    flex-shrink: 0;
}

.lux-page-header__team-panel-close:hover {
    color: var(--lux-primary, #5b5ff4);
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
}

.lux-page-header__team-panel-body {
    padding: 0.55rem 0.75rem 0.65rem;
}

.lux-page-header__team-search {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0 0.55rem;
    min-height: 2rem;
    border: 0px solid #e2e8f0;
    border-radius: 12px;
    background: #fff;
    margin-bottom: 0.45rem;
}

.lux-page-header__team-search i {
    color: #94a3b8;
    font-size: 0.75rem;
}

.lux-page-header__team-search input {
    width: 100%;
    border: none;
    background: transparent;
    font-size: 0.6875rem;
    color: #0f172a;
    outline: none;
}

.lux-page-header__team-all {
    position: relative;
    display: flex;
    align-items: center;
    gap: 0.45rem;
    margin-bottom: 0.4rem;
    padding: 0.35rem 0.45rem 0.35rem 1.85rem;
    border-radius: 11px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.04);
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
