.lux-ts-summary__attention--clear strong {
    display: block;
    font-size: 0.75rem;
    font-weight: 800;
    color: #065f46;
}

.lux-ts-summary__attention--clear span {
    display: block;
    font-size: 0.75rem;
    font-weight: 600;
    color: #059669;
}

.lux-ts-summary__attention-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.625rem;
    margin-bottom: 0.45rem;
}

.lux-ts-summary__attention-title {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    margin: 0;
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-ts-summary__attention-title i {
    color: #d97706;
    font-size: 0.875rem;
}

.lux-ts-summary__attention-count {
    font-size: 0.75rem;
    font-weight: 700;
    color: #64748b;
    padding: 0.15rem 0.45rem;
    border-radius: 9911px;
    background: rgba(241, 245, 249, 0.95);
}

.lux-ts-summary__attention-list {
    display: flex;
    flex-wrap: wrap;
    gap: 0.35rem;
    margin: 0;
    padding: 0;
    list-style: none;
}

.lux-ts-summary__attention-item {
    display: grid;
    grid-template-columns: auto auto 1fr;
    align-items: center;
    gap: 0.35rem 0.625rem;
    min-width: 0;
    padding: 0.35rem 0.55rem;
    border-radius: 12px;
    border: 0px solid rgba(226, 232, 240, 0.95);
    background: rgba(248, 250, 252, 0.85);
    font-size: 0.75rem;
}

.lux-ts-summary__attention-item.is-empty {
    border-color: rgba(148, 163, 184, 0.45);
    background: rgba(241, 245, 249, 0.9);
}

.lux-ts-summary__attention-item.is-under {
    border-color: rgba(217, 119, 6, 0.35);
    background: rgba(251, 191, 36, 0.1);
}

.lux-ts-summary__attention-item.is-over {
    border-color: rgba(220, 38, 38, 0.35);
    background: rgba(254, 226, 226, 0.55);
}

.lux-ts-summary__attention-day {
    font-weight: 800;
    color: #334155;
    white-space: nowrap;
}

.lux-ts-summary__attention-hours {
    font-weight: 800;
    color: #0f172a;
    white-space: nowrap;
}

.lux-ts-summary__attention-reason {
    font-weight: 600;
    color: #64748b;
    min-width: 0;
}

.lux-ts-summary__kpi-strip {
    display: grid;
    grid-template-columns: repeat(6, minmax(0, 1fr));
    gap: 0.55rem;
}

.lux-ts-summary__kpi {
    display: flex;
    flex-direction: column;
    gap: 0.18rem;
    min-height: 5.75rem;
    padding: 0.7rem 0.75rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.96);
    box-shadow: 0 4px 14px rgba(15, 23, 42, 0.04);
}

.lux-ts-summary__kpi.is-primary { border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18); }
.lux-ts-summary__kpi.is-green { border-color: rgba(5, 150, 105, 0.2); }
.lux-ts-summary__kpi.is-amber { border-color: rgba(217, 119, 6, 0.2); }
.lux-ts-summary__kpi.is-violet { border-color: rgba(124, 58, 237, 0.2); }
.lux-ts-summary__kpi.is-blue { border-color: rgba(37, 99, 235, 0.2); }
.lux-ts-summary__kpi.is-teal { border-color: rgba(20, 184, 166, 0.2); }

.lux-ts-summary__kpi-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.35rem;
}

.lux-ts-summary__kpi-label {
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-ts-summary__kpi-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.5rem;
    height: 1.5rem;
    border-radius: 11px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary-dark, #3730a3);
    font-size: 0.6875rem;
}

.lux-ts-summary__kpi.is-green .lux-ts-summary__kpi-icon {
    background: rgba(5, 150, 105, 0.12);
    color: #047857;
}

.lux-ts-summary__kpi.is-amber .lux-ts-summary__kpi-icon {
    background: rgba(217, 119, 6, 0.12);
    color: #b45309;
}

.lux-ts-summary__kpi.is-violet .lux-ts-summary__kpi-icon {
    background: rgba(124, 58, 237, 0.12);
    color: #6d28d9;
}

.lux-ts-summary__kpi.is-blue .lux-ts-summary__kpi-icon {
    background: rgba(37, 99, 235, 0.12);
    color: #1d4ed8;
}

.lux-ts-summary__kpi.is-teal .lux-ts-summary__kpi-icon {
    background: rgba(20, 184, 166, 0.12);
    color: #0f766e;
}

.lux-ts-summary__kpi-value {
    font-size: 1.125rem;
    font-weight: 900;
    color: #0f172a;
    line-height: 1.1;
}

.lux-ts-summary__kpi-value.is-alert {
    color: #dc2626;
    animation: lux-ts-summary-blink 1.2s ease-in-out infinite;
}

@keyframes lux-ts-summary-blink {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.55; }
}

.lux-ts-summary__kpi-hint {
    font-size: 0.625rem;
    font-weight: 600;
    color: #94a3b8;
    line-height: 1.35;
}

.lux-ts-summary__charts {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.55rem;
}

.lux-ts-summary__chart-panel {
    display: flex;
    flex-direction: column;
    min-height: 0;
    padding: 0.75rem 0.8rem 0.65rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 16px;
    background: rgba(255, 255, 255, 0.96);
    box-shadow: 0 4px 14px rgba(15, 23, 42, 0.04);
}

.lux-ts-summary__chart-panel--wide {
    grid-column: 1 / -1;
}

.lux-ts-summary__chart-panel--split {
    grid-column: 1 / -1;
}

.lux-ts-summary__chart-split {
    display: grid;
    grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr);
    gap: 0.65rem;
    align-items: stretch;
    min-height: 0;
}

.lux-ts-summary__chart-split-main,
.lux-ts-summary__chart-split-side {
    min-width: 0;
    min-height: 0;
}

.lux-ts-summary__chart-split-side {
    display: flex;
    flex-direction: column;
    padding-left: 0.55rem;
    border-left: 1px dashed rgba(226, 232, 240, 0.95);
}

.lux-ts-summary__split-label {
    margin: 0 0 0.25rem;
    font-size: 0.75rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-ts-summary__panel-head {
    margin-bottom: 0.35rem;
}

.lux-ts-summary__panel-title {
    margin: 0;
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-ts-summary__panel-sub {
    margin: 0.12rem 0 0;
    font-size: 0.6875rem;
    font-weight: 600;
    color: #94a3b8;
    line-height: 1.4;
}

.lux-ts-summary__chart-body {
    flex: 1;
    min-height: 0;
}

.lux-ts-summary__empty {
    margin: 0;
    padding: 2rem 0.625rem;
    text-align: center;
    font-size: 0.6875rem;
    font-weight: 600;
    color: #94a3b8;
}

/* Dark shell */
body.lux-shell-dark .lux-ts-summary {
    background:
        radial-gradient(circle at 100% 0%, rgba(5, 150, 105, 0.1), transparent 42%),
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1), transparent 45%),
        linear-gradient(180deg, rgba(15, 23, 42, 0.92), rgba(2, 6, 23, 0.88));
    border-color: rgba(51, 65, 85, 0.95);
}

body.lux-shell-dark .lux-ts-summary__title,
body.lux-shell-dark .lux-ts-summary__panel-title,
body.lux-shell-dark .lux-ts-summary__kpi-value {
    color: #e2e8f0;
}

body.lux-shell-dark .lux-ts-summary__kpi,
body.lux-shell-dark .lux-ts-summary__chart-panel,
body.lux-shell-dark .lux-ts-summary__attention {
    background: rgba(15, 23, 42, 0.65);
    border-color: rgba(51, 65, 85, 0.95);
}

body.lux-shell-dark .lux-ts-summary__attention--clear {
    background: rgba(5, 150, 105, 0.12);
    border-color: rgba(5, 150, 105, 0.35);
}

body.lux-shell-dark .lux-ts-summary__attention-title,
body.lux-shell-dark .lux-ts-summary__attention-hours {
    color: #e2e8f0;
}

body.lux-shell-dark .lux-ts-summary__chart-split-side {
    border-left-color: rgba(51, 65, 85, 0.95);
}

body.lux-shell-dark .lux-ts-summary__toggle {
    background: rgba(15, 23, 42, 0.75);
    border-color: rgba(51, 65, 85, 0.95);
    color: #94a3b8;
}

@media (max-width: 1400px) {
    .lux-ts-summary__kpi-strip {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}

@media (max-width: 992px) {
    .lux-ts-summary__charts {
        grid-template-columns: 1fr;
    }

    .lux-ts-summary__chart-panel--wide,
    .lux-ts-summary__chart-panel--split {
        grid-column: auto;
    }

    .lux-ts-summary__chart-split {
        grid-template-columns: 1fr;
    }

    .lux-ts-summary__chart-split-side {
        padding-left: 0;
        border-left: none;
        padding-top: 0.55rem;
        border-top: 1px dashed rgba(226, 232, 240, 0.95);
    }
}

@media (max-width: 768px) {
    .lux-ts-summary {
        padding: 0.65rem 0.85rem;
    }

    .lux-ts-summary__kpi-strip {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .lux-ts-summary__title-badge {
        display: block;
        margin: 0.25rem 0 0;
        width: fit-content;
    }

    .lux-ts-summary__status-badge.is-compact {
        display: inline-flex;
        margin: 0.25rem 0.15rem 0 0;
    }

    .lux-ts-summary__day-status {
        grid-template-columns: repeat(4, minmax(0, 1fr));
    }
}

/* ========== Add time entry modal ========== */

.lux-ts-add-entry {
    position: fixed;
    inset: 0;
    z-index: 1000002;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 1.25rem;
}

.lux-ts-add-entry__backdrop {
    position: absolute;
    inset: 0;
    padding: 0;
    border: none;
    background:
        radial-gradient(ellipse at 50% 20%, rgba(91, 95, 244, 0.18), transparent 55%),
        rgba(8, 12, 28, 0.58);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    cursor: pointer;
}

body.lux-ts-add-entry-open {
    overflow: hidden;
}

/* Portaled react-select menus must sit above this modal (1000002) and all sections */
body.lux-ts-add-entry-open .custom-select__menu-portal {
    z-index: 1000020 !important;
}

body.lux-ts-add-entry-open .custom-select__menu-portal .custom-select__menu {
    border-radius: 12px !important;
    border: 1px solid rgba(226, 232, 240, 0.98) !important;
    box-shadow:
        0 18px 40px rgba(15, 23, 42, 0.2),
        0 3px 10px rgba(15, 23, 42, 0.08) !important;
    overflow: hidden;
    background: #fff !important;
    margin-top: 4px !important;
}

body.lux-ts-add-entry-open .custom-select__menu-portal .custom-select__menu-list {
    padding: 0.28rem !important;
    max-height: 220px !important;
}

body.lux-ts-add-entry-open .custom-select__menu-portal .custom-select__option {
    font-size: 0.8125rem !important;
    font-weight: 600;
    padding: 0 !important;
    background: transparent !important;
    color: inherit !important;
}

body.lux-ts-add-entry-open .custom-select__menu-portal .custom-select__option--is-focused,
body.lux-ts-add-entry-open .custom-select__menu-portal .custom-select__option--is-selected {
    background: transparent !important;
    color: inherit !important;
}

.lux-page-header__create-btn.is-busy {
    opacity: 0.72;
    cursor: default;
}

.lux-ts-add-entry__panel {
    position: relative;
    width: min(580px, 100%);
    max-height: min(90vh, 740px);
    display: flex;
    flex-direction: column;
    overflow: hidden;
    border-radius: 22px;
    border: 1px solid rgba(226, 232, 240, 0.98);
    background:
        radial-gradient(circle at 100% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14), transparent 42%),
        radial-gradient(circle at 0% 0%, rgba(5, 150, 105, 0.1), transparent 40%),
        linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
    box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.8) inset,
        0 36px 90px rgba(15, 23, 42, 0.28),
        0 8px 24px rgba(91, 95, 244, 0.08);
    animation: lux-ts-add-entry-in 0.26s cubic-bezier(0.22, 1, 0.36, 1);
}

.lux-ts-add-entry__accent {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(
        90deg,
        #059669 0%,
        var(--lux-primary, #5b5ff4) 48%,
        #2563eb 100%
    );
    z-index: 1;
}

@keyframes lux-ts-add-entry-in {
    from {
        opacity: 0;
        transform: translateY(16px) scale(0.97);
    }
    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

.lux-ts-add-entry__head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.55rem;
    padding: 0.85rem 1.15rem 0.65rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.9);
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.72), transparent);
}

.lux-ts-add-entry__head-main {
    min-width: 0;
    flex: 1;
}

.lux-ts-add-entry__kicker {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    margin-bottom: 0.12rem;
    padding: 0.1rem 0.42rem;
    border-radius: 999px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--lux-primary-dark, #3730a3);
}

.lux-ts-add-entry__kicker i {
    color: var(--lux-primary, #5b5ff4);
}

.lux-ts-add-entry__title {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 900;
    color: #0f172a;
    line-height: 1.15;
    letter-spacing: -0.02em;
}

.lux-ts-add-entry__sub {
    margin: 0.18rem 0 0;
    font-size: 0.75rem;
    font-weight: 600;
    color: #64748b;
    line-height: 1.35;
}

.lux-ts-add-entry__sub strong {
    color: #334155;
}

.lux-ts-add-entry__progress {
    display: inline-flex;
    align-items: center;
    gap: 0;
    margin-top: 0.45rem;
}

.lux-ts-add-entry__progress-dot {
    width: 0.42rem;
    height: 0.42rem;
    border-radius: 999px;
    background: #e2e8f0;
    transition: background 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
}

.lux-ts-add-entry__progress-dot.is-on {
    background: var(--lux-primary, #5b5ff4);
    box-shadow: 0 0 0 2px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18);
    transform: scale(1.08);
}

.lux-ts-add-entry__progress-line {
    width: 1.5rem;
    height: 2px;
    background: linear-gradient(90deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35), #e2e8f0);
    border-radius: 999px;
}

.lux-ts-add-entry__close {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.85rem;
    height: 1.85rem;
    padding: 0;
    border: 1px solid #e2e8f0;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.96);
    color: #64748b;
    cursor: pointer;
    box-shadow: 0 2px 8px rgba(15, 23, 42, 0.06);
    transition: border-color 0.14s ease, color 0.14s ease, background 0.14s ease, transform 0.14s ease;
}

.lux-ts-add-entry__close:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
    transform: scale(1.04);
}

.lux-ts-add-entry__body {
    flex: 1;
    overflow-y: auto;
    padding: 0.75rem 1.15rem 0.9rem;
    display: flex;
    flex-direction: column;
    gap: 0.7rem;
}

.lux-ts-add-entry__section {
    display: flex;
    flex-direction: column;
    gap: 0.45rem;
    position: relative;
    transition: opacity 0.18s ease, filter 0.18s ease;
}

.lux-ts-add-entry__section.is-dimmed {
    opacity: 0.72;
}

.lux-ts-add-entry__section--elevate {
    position: relative;
    z-index: 8;
    flex: 1 1 auto;
    min-height: 0;
    padding: 0.75rem 0.85rem 0.85rem;
    border-radius: 16px;
    border: 1px solid rgba(203, 213, 225, 0.95);
    background:
        radial-gradient(circle at 100% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08), transparent 48%),
        linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
    box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.85) inset,
        0 14px 32px rgba(15, 23, 42, 0.08);
}

.lux-ts-add-entry__section--reveal {
    animation: lux-ts-add-entry-section-in 0.22s ease;
}

@keyframes lux-ts-add-entry-section-in {
    from {
        opacity: 0;
        transform: translateY(8px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.lux-ts-add-entry__section-head {
    display: flex;
    flex-direction: row;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.4rem 0.55rem;
}

.lux-ts-add-entry__step {
    display: inline-block;
    width: fit-content;
    padding: 0.1rem 0.4rem;
    border-radius: 999px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    font-size: 0.5625rem;
    font-weight: 800;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    color: var(--lux-primary-dark, #3730a3);
}

.lux-ts-add-entry__section-title {
    margin: 0;
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
    letter-spacing: -0.01em;
}

.lux-ts-add-entry__type-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.45rem;
}

.lux-ts-add-entry__type-card {
    position: relative;
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: 0.55rem;
    min-height: 0;
    padding: 0.55rem 0.7rem;
    border: 1px solid rgba(203, 213, 225, 0.95);
    border-radius: 14px;
    background:
        linear-gradient(165deg, rgba(255, 255, 255, 0.98) 0%, rgba(248, 250, 252, 0.96) 100%);
    box-shadow: 0 2px 8px rgba(15, 23, 42, 0.04);
    text-align: left;
    cursor: pointer;
    transition: border-color 0.16s ease, box-shadow 0.16s ease, transform 0.16s ease, background 0.16s ease;
}

.lux-ts-add-entry__type-card:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.32);
    box-shadow: 0 8px 18px rgba(15, 23, 42, 0.07);
    transform: translateY(-1px);
}

.lux-ts-add-entry__type-card.is-active {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.45);
    background:
        radial-gradient(circle at 100% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1), transparent 55%),
        #fff;
    box-shadow:
        0 0 0 1px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12) inset,
        0 8px 18px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.lux-ts-add-entry__type-card.is-green.is-active {
    border-color: rgba(5, 150, 105, 0.42);
    background:
        radial-gradient(circle at 100% 0%, rgba(5, 150, 105, 0.12), transparent 55%),
        #fff;
    box-shadow:
        0 0 0 1px rgba(5, 150, 105, 0.12) inset,
        0 8px 18px rgba(5, 150, 105, 0.12);
}

.lux-ts-add-entry__type-card.is-blue.is-active {
    border-color: rgba(37, 99, 235, 0.42);
    background:
        radial-gradient(circle at 100% 0%, rgba(37, 99, 235, 0.12), transparent 55%),
        #fff;
    box-shadow:
        0 0 0 1px rgba(37, 99, 235, 0.12) inset,
        0 8px 18px rgba(37, 99, 235, 0.12);
}

.lux-ts-add-entry__type-top {
    display: flex;
    align-items: center;
    justify-content: flex-start;
    flex-shrink: 0;
    width: auto;
    margin-bottom: 0;
    position: relative;
}

.lux-ts-add-entry__type-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.85rem;
    height: 1.85rem;
    border-radius: 10px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    color: var(--lux-primary-dark, #3730a3);
    font-size: 0.85rem;
    box-shadow: 0 1px 0 rgba(255, 255, 255, 0.7) inset;
}

.lux-ts-add-entry__type-card.is-green .lux-ts-add-entry__type-icon {
    background: rgba(5, 150, 105, 0.14);
    color: #047857;
}

.lux-ts-add-entry__type-card.is-blue .lux-ts-add-entry__type-icon {
    background: rgba(37, 99, 235, 0.14);
    color: #1d4ed8;
}

.lux-ts-add-entry__type-check {
    position: absolute;
    top: -0.35rem;
    right: -0.35rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1rem;
    height: 1rem;
    border-radius: 999px;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
    color: #fff;
    font-size: 0.5rem;
    box-shadow: 0 2px 6px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
}

.lux-ts-add-entry__type-card.is-green .lux-ts-add-entry__type-check {
    background: linear-gradient(135deg, #10b981, #047857);
    box-shadow: 0 2px 6px rgba(5, 150, 105, 0.28);
}

.lux-ts-add-entry__type-card.is-blue .lux-ts-add-entry__type-check {
    background: linear-gradient(135deg, #3b82f6, #1d4ed8);
    box-shadow: 0 2px 6px rgba(37, 99, 235, 0.28);
}

.lux-ts-add-entry__type-card strong {
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
    letter-spacing: -0.01em;
    line-height: 1.2;
}

.lux-ts-add-entry__type-hint {
    display: none;
}

.lux-ts-add-entry__type-card > strong,
.lux-ts-add-entry__type-card > .lux-ts-add-entry__type-hint {
    min-width: 0;
}

.lux-ts-add-entry__section:not(.is-dimmed) .lux-ts-add-entry__type-hint {
    display: block;
    font-size: 0.6875rem;
    font-weight: 600;
    color: #64748b;
    line-height: 1.3;
}

.lux-ts-add-entry__section:not(.is-dimmed) .lux-ts-add-entry__type-card {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.2rem;
    padding: 0.65rem 0.75rem;
}

.lux-ts-add-entry__section:not(.is-dimmed) .lux-ts-add-entry__type-top {
    width: 100%;
    justify-content: space-between;
    margin-bottom: 0.05rem;
}

.lux-ts-add-entry__section:not(.is-dimmed) .lux-ts-add-entry__type-check {
    position: static;
}

.lux-ts-add-entry__field {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
    padding: 0.65rem 0.75rem;
    border: 1px solid rgba(226, 232, 240, 0.98);
    border-radius: 12px;
    background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.94));
    box-shadow: 0 2px 8px rgba(15, 23, 42, 0.04);
    position: relative;
    z-index: 2;
}

.lux-ts-add-entry__field--nested {
    margin-top: 0.15rem;
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18);
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06), transparent 55%),
        linear-gradient(180deg, #fff 0%, #f8fafc 100%);
    z-index: 3;
}

.lux-ts-add-entry__label {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-ts-add-entry__label .fe {
    color: var(--lux-primary, #5b5ff4);
    font-size: 0.8rem;
}

.lux-ts-add-entry__select .custom-select__control {
    min-height: 38px !important;
    border-radius: 11px !important;
    border: 1px solid #cbd5e1 !important;
    background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%) !important;
    box-shadow: 0 1px 3px rgba(15, 23, 42, 0.05) !important;
    transition: border-color 0.14s ease, box-shadow 0.14s ease;
}

.lux-ts-add-entry__select .custom-select__control:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.4) !important;
}

.lux-ts-add-entry__select .custom-select__control--is-focused {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.55) !important;
    box-shadow: 0 0 0 3px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14) !important;
}

.lux-ts-add-entry__select .custom-select__value-container {
    padding: 0.15rem 0.65rem !important;
    font-size: 0.8125rem !important;
}

.lux-ts-add-entry__select .custom-select__placeholder {
    color: #94a3b8 !important;
    font-weight: 500 !important;
}

.lux-ts-add-entry__select .custom-select__single-value {
    color: #0f172a !important;
    font-weight: 700 !important;
}

.lux-ts-add-entry__value {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    min-width: 0;
}

.lux-ts-add-entry__value i {
    color: var(--lux-primary, #5b5ff4);
    font-size: 0.78rem;
    flex-shrink: 0;
}

.lux-ts-add-entry__value span {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-ts-add-entry__opt {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    width: 100%;
    padding: 0.4rem 0.5rem;
    border-radius: 9px;
    transition: background 0.12s ease, box-shadow 0.12s ease;
}

.lux-ts-add-entry__opt.is-focused {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
}

.lux-ts-add-entry__opt.is-selected {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    box-shadow: 0 0 0 1px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12) inset;
}

.lux-ts-add-entry__opt-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.55rem;
    height: 1.55rem;
    border-radius: 8px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    color: var(--lux-primary-dark, #3730a3);
    font-size: 0.72rem;
    flex-shrink: 0;
}

.lux-ts-add-entry__opt-copy {
    display: flex;
    flex-direction: column;
    gap: 0.05rem;
    min-width: 0;
    flex: 1;
}

.lux-ts-add-entry__opt-copy strong {
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.2;
}

.lux-ts-add-entry__opt-copy span {
    font-size: 0.625rem;
    font-weight: 600;
    color: #64748b;
    line-height: 1.25;
}

.lux-ts-add-entry__opt-check {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.05rem;
    height: 1.05rem;
    border-radius: 999px;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
    color: #fff;
    font-size: 0.55rem;
    flex-shrink: 0;
}

.lux-ts-add-entry__empty {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.75rem 0.85rem;
    border-radius: 12px;
    background: rgba(245, 158, 11, 0.08);
    border: 1px solid rgba(245, 158, 11, 0.18);
    color: #b45309;
    font-size: 0.8125rem;
    font-weight: 700;
}

.lux-ts-add-entry__hint {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
    margin: 0;
    font-size: 0.75rem;
    font-weight: 600;
    color: #94a3b8;
}

.lux-ts-add-entry__foot {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 0.55rem;
    padding: 0.7rem 1.15rem 0.85rem;
    border-top: 1px solid rgba(226, 232, 240, 0.95);
    background:
        linear-gradient(180deg, rgba(248, 250, 252, 0.7), rgba(241, 245, 249, 0.95));
}

.lux-ts-add-entry__foot-note {
    margin: 0;
    flex: 1;
    min-width: 12rem;
    font-size: 0.75rem;
    font-weight: 600;
    color: #64748b;
    line-height: 1.45;
}

.lux-ts-add-entry__foot-note strong {
    color: #0f172a;
    font-weight: 800;
}

.lux-ts-add-entry__actions {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    flex-shrink: 0;
}

.lux-ts-add-entry__btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.35rem;
    min-height: 2.35rem;
    padding: 0 1.05rem;
    border-radius: 999px;
    font-size: 0.75rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    cursor: pointer;
    transition: border-color 0.14s ease, background 0.14s ease, opacity 0.14s ease, transform 0.14s ease, box-shadow 0.14s ease;
}

.lux-ts-add-entry__btn--ghost {
    border: 1px solid #e2e8f0;
    background: #fff;
    color: #64748b;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
}

.lux-ts-add-entry__btn--ghost:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.04);
}

.lux-ts-add-entry__btn--primary {
    border: none;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
    color: #fff;
    box-shadow: 0 10px 24px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.32);
}

.lux-ts-add-entry__btn--primary:hover:not(:disabled) {
    filter: brightness(1.04);
    transform: translateY(-1px);
    box-shadow: 0 14px 28px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.36);
}

.lux-ts-add-entry__btn--primary:disabled {
    opacity: 0.45;
    cursor: not-allowed;
    box-shadow: none;
    transform: none;
}

body.lux-shell-dark .lux-ts-add-entry__panel {
    background:
        radial-gradient(circle at 100% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16), transparent 42%),
        radial-gradient(circle at 0% 0%, rgba(5, 150, 105, 0.1), transparent 40%),
        linear-gradient(180deg, rgba(15, 23, 42, 0.98), rgba(2, 6, 23, 0.96));
    border-color: rgba(51, 65, 85, 0.95);
}

body.lux-shell-dark .lux-ts-add-entry__section--elevate,
body.lux-shell-dark .lux-ts-add-entry__field,
body.lux-shell-dark .lux-ts-add-entry__field--nested {
    background: rgba(15, 23, 42, 0.72);
    border-color: rgba(51, 65, 85, 0.95);
}

body.lux-shell-dark .lux-ts-add-entry__opt-copy strong,
body.lux-shell-dark .lux-ts-add-entry__title,
body.lux-shell-dark .lux-ts-add-entry__section-title,
body.lux-shell-dark .lux-ts-add-entry__type-card strong,
body.lux-shell-dark .lux-ts-add-entry__foot-note strong {
    color: #e2e8f0;
}

body.lux-shell-dark .lux-ts-add-entry__opt.is-focused,
body.lux-shell-dark .lux-ts-add-entry__opt.is-selected {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18);
}

body.lux-shell-dark .lux-ts-add-entry__type-card,
body.lux-shell-dark .lux-ts-add-entry__close,
body.lux-shell-dark .lux-ts-add-entry__btn--ghost {
    background: rgba(15, 23, 42, 0.75);
    border-color: rgba(51, 65, 85, 0.95);
    color: #94a3b8;
}

body.lux-shell-dark .lux-ts-add-entry__type-hint,
body.lux-shell-dark .lux-ts-add-entry__sub,
body.lux-shell-dark .lux-ts-add-entry__foot-note {
    color: #94a3b8;
}

body.lux-shell-dark .lux-ts-add-entry__select .custom-select__control {
    background: rgba(2, 6, 23, 0.65) !important;
    border-color: rgba(71, 85, 105, 0.95) !important;
}

body.lux-shell-dark .lux-ts-add-entry__select .custom-select__single-value {
    color: #e2e8f0 !important;
}

body.lux-shell-dark .lux-ts-add-entry__foot {
    background: rgba(2, 6, 23, 0.65);
    border-color: rgba(51, 65, 85, 0.95);
}

body.lux-shell-dark .lux-ts-add-entry__head {
    background: transparent;
    border-color: rgba(51, 65, 85, 0.95);
}

@media (max-width: 640px) {
    .lux-ts-add-entry {
        padding: 0.75rem;
        align-items: flex-end;
    }

    .lux-ts-add-entry__panel {
        width: 100%;
        max-height: 92vh;
        border-bottom-left-radius: 0;
        border-bottom-right-radius: 0;
    }

    .lux-ts-add-entry__type-grid {
        grid-template-columns: 1fr;
    }

    .lux-ts-add-entry__foot {
        flex-direction: column;
        align-items: stretch;
    }

    .lux-ts-add-entry__actions {
        width: 100%;
        justify-content: stretch;
    }

    .lux-ts-add-entry__btn {
        flex: 1;
    }
}

/* ========== Timesheet page workspace shell ========== */

.lux-ts-page__grid-shell {
    margin: 0 0.75rem 0.65rem;
    padding: 0.45rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 14px;
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.04), transparent 42%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.96));
    box-shadow: 0 6px 20px rgba(15, 23, 42, 0.04);
    overflow: visible;
}

.lux-ts-board--skeleton {
    pointer-events: none;
}

.lux-ts-board--skeleton .lux-ts-board__week-rail {
    margin-bottom: 0.45rem;
}

.lux-ts-board__body--skeleton {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
    padding: 0.15rem 0.35rem 0.4rem;
}

.lux-ts-board__skeleton-entry {
    padding: 0.2rem 0;
}

.lux-ts-board__footer-totals--skeleton {
    margin-top: 0.35rem;
    padding: 0.45rem 0.35rem 0.625rem;
    border-top: 1px solid rgba(226, 232, 240, 0.9);
}

/* ========== Timesheet entry board (compact luxury) ========== */

.lux-ts-board {
    position: relative;
    overflow: visible;
    border-radius: 14px;
    --lux-ts-col-meta: minmax(4.75rem, 0.55fr);
    --lux-ts-col-day: minmax(2.1rem, 0.85fr);
    --lux-ts-col-tools: 5.25rem;
    --lux-ts-grid-columns: var(--lux-ts-col-meta) repeat(7, var(--lux-ts-col-day)) var(--lux-ts-col-tools);
    --lux-ts-grid-gap: 0.1rem;
    padding: 0.1rem;
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.045), transparent 42%),
        linear-gradient(180deg, rgba(248, 250, 252, 0.55), rgba(255, 255, 255, 0.2));
}

.lux-ts-board__grid-row {
    display: grid;
    grid-template-columns: var(--lux-ts-grid-columns);
    column-gap: var(--lux-ts-grid-gap);
    row-gap: 0.12rem;
    align-items: center;
}

.lux-ts-board__col-meta { grid-column: 1; }
.lux-ts-board__col-day-0 { grid-column: 2; }
.lux-ts-board__col-day-1 { grid-column: 3; }
.lux-ts-board__col-day-2 { grid-column: 4; }
.lux-ts-board__col-day-3 { grid-column: 5; }
.lux-ts-board__col-day-4 { grid-column: 6; }
.lux-ts-board__col-day-5 { grid-column: 7; }
.lux-ts-board__col-day-6 { grid-column: 8; }
.lux-ts-board__col-tools { grid-column: 9; }

.lux-ts-board__entry:not(.is-editing) > .lux-ts-board__entry-meta {
    grid-column: 1 / -1;
    grid-row: 1;
    align-self: stretch;
    padding: 0.12rem 0.35rem 0.18rem;
    border-bottom: 1px solid rgba(241, 245, 249, 0.95);
    background:
        linear-gradient(135deg, rgba(255, 255, 255, 0.72), rgba(248, 250, 252, 0.45));
}

.lux-ts-board__entry:not(.is-editing) > .lux-ts-board__day-slot,
.lux-ts-board__entry:not(.is-editing) > .lux-ts-board__col-tools {
    grid-row: 2;
}

.lux-ts-board__entry:not(.is-editing) .lux-ts-board__line-btn--compact {
    overflow: visible;
    flex-wrap: wrap;
    min-height: 1.55rem;
    padding: 0.1rem 0.12rem 0.1rem 0.08rem;
}

.lux-ts-board__entry:not(.is-editing) .lux-ts-board__line-btn--compact .lux-ts-board__line-title {
    flex: 1 1 auto;
    white-space: normal;
    overflow: visible;
    text-overflow: unset;
    line-height: 1.25;
}

.lux-ts-board__entry:not(.is-editing) .lux-ts-board__line-trail {
    max-width: none;
    white-space: normal;
    overflow: visible;
    text-overflow: unset;
}

.lux-ts-board__entry:not(.is-editing) > .lux-ts-board__col-tools {
    justify-content: flex-start;
    padding-top: 0.12rem;
}

.lux-ts-board.has-pending-save {
    padding-bottom: 4.5rem;
}

/* Week rail — aligned to entry grid */
.lux-ts-board__week-rail {
    width: 100%;
    min-width: 0;
    margin-bottom: 0.18rem;
    padding: 0.24rem 0.28rem 0.26rem;
    border: 1px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16);
    border-radius: 12px;
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.11), transparent 48%),
        radial-gradient(circle at 100% 0%, rgba(5, 150, 105, 0.07), transparent 42%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.96));
    box-shadow:
        0 1px 0 rgba(255, 255, 255, 0.9) inset,
        0 6px 18px rgba(15, 23, 42, 0.06);
}

.lux-ts-board__week-rail.is-sticky {
    position: sticky;
    top: calc(var(--lux-ts-sticky-header-offset, 4.5rem) + 0.25rem);
    z-index: 28;
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14), transparent 48%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.95));
    box-shadow:
        0 1px 0 rgba(255, 255, 255, 0.95) inset,
        0 14px 36px rgba(15, 23, 42, 0.16),
        0 0 0 1px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-ts-board__week-rail > * {
    grid-row: 1;
}

.lux-ts-board__rail-meta {
    display: flex;
    align-items: center;
    min-width: 0;
}

.lux-ts-board__rail-meta-label {
    font-size: 0.5625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #64748b;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.lux-ts-board__rail-tools {
    min-height: 0.25rem;
}

.lux-ts-board__week-day {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 0.02rem;
    min-width: 0;
    min-height: 2.1rem;
    padding: 0.14rem 0.06rem;
    border-radius: 10px;
    border: 1px solid transparent;
    text-align: center;
    margin: 0;
    font: inherit;
    color: inherit;
    background: rgba(255, 255, 255, 0.62);
    cursor: default;
}

.lux-ts-board__week-day.is-clickable {
    cursor: pointer;
    transition: border-color 0.15s ease, background 0.15s ease, transform 0.15s ease, box-shadow 0.15s ease;
}

.lux-ts-board__week-day.is-clickable:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
    box-shadow: 0 4px 12px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    transform: translateY(-1px);
}

.lux-ts-board__week-day.is-today {
    border-color: rgba(5, 150, 105, 0.38);
    background: linear-gradient(180deg, rgba(5, 150, 105, 0.16), rgba(5, 150, 105, 0.05));
    box-shadow: 0 0 0 1px rgba(5, 150, 105, 0.08) inset;
}

.lux-ts-board__week-day.is-weekend .lux-ts-board__week-day-name {
    color: #c2410c;
}

.lux-ts-board__week-day-name {
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #64748b;
    line-height: 1.1;
}

.lux-ts-board__week-day-num {
    font-size: 0.875rem;
    font-weight: 900;
    line-height: 1.05;
    color: #0f172a;
    letter-spacing: -0.02em;
}

.lux-ts-board__week-day-dot {
    position: absolute;
    top: 0.15rem;
    right: 0.15rem;
    width: 0.35rem;
    height: 0.35rem;
    border-radius: 9911px;
    background: #059669;
    box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.95);
}

/* Footer totals — aligned to entry grid */
.lux-ts-board__footer-totals {
    margin-top: 0.4rem;
    padding: 0.4rem 0.35rem;
    border: 1px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16);
    border-radius: 12px;
    background:
        radial-gradient(circle at 100% 50%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08), transparent 55%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.94));
    box-shadow:
        0 1px 0 rgba(255, 255, 255, 0.9) inset,
        0 4px 14px rgba(15, 23, 42, 0.05);
}

.lux-ts-board__footer-totals > * {
    grid-row: 1;
}

.lux-ts-board__footer-meta-label {
    display: block;
    font-size: 0.5625rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    line-height: 1.2;
}

.lux-ts-board__footer-day {
    display: flex;
    align-items: center;
    justify-content: center;
    min-width: 0;
}

.lux-ts-board__footer-day-value {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 2.35rem;
    padding: 0.2rem 0.45rem;
    border-radius: 9911px;
    background: rgba(255, 255, 255, 0.92);
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.1;
}

.lux-ts-board__footer-day.has-value .lux-ts-board__footer-day-value {
    color: var(--lux-primary-dark, #3730a3);
}

.lux-ts-board__footer-day-value.is-under-8h {
    background: rgba(251, 191, 36, 0.18);
    color: #b45309;
    box-shadow: inset 0 0 0 1px rgba(217, 119, 6, 0.28);
}

.lux-ts-board__footer-day-value.is-over-8h {
    background: rgba(220, 38, 38, 0.14);
    color: #dc2626;
    box-shadow: inset 0 0 0 1px rgba(220, 38, 38, 0.28);
    animation: lux-ts-summary-blink 1.2s ease-in-out infinite;
}

.lux-ts-board__footer-day-value.is-on-target {
    background: rgba(5, 150, 105, 0.14);
    color: #047857;
    box-shadow: inset 0 0 0 1px rgba(5, 150, 105, 0.28);
}

.lux-ts-board__footer-day-value.is-over {
    background: rgba(220, 38, 38, 0.12);
    color: #dc2626;
    animation: lux-ts-summary-blink 1.2s ease-in-out infinite;
}

.lux-ts-board__footer-grand {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 0.04rem;
    text-align: center;
}

.lux-ts-board__footer-grand-label {
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-ts-board__footer-grand-value {
    font-size: 0.9375rem;
    font-weight: 800;
    color: var(--lux-primary-dark, #3730a3);
    line-height: 1.1;
}

/* Body + empty state */
.lux-ts-board__body {
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
}

/* Group sections */
.lux-ts-board__group {
    border: 1px solid rgba(226, 232, 240, 0.95);
    border-radius: 12px;
    background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.96));
    overflow: visible;
    box-shadow:
        0 1px 0 rgba(255, 255, 255, 0.9) inset,
        0 3px 12px rgba(15, 23, 42, 0.04);
}

/* Editing rows open selects — allow menus to escape the card while portaled menus load */
.lux-ts-board__group:has(.lux-ts-board__entry.is-editing) {
    overflow: visible;
    z-index: 6;
    position: relative;
}

.lux-ts-board__group.is-project {
    border-top: 3px solid rgba(5, 150, 105, 0.55);
}

.lux-ts-board__group.is-non-project {
    border-top: 3px solid rgba(37, 99, 235, 0.45);
}

.lux-ts-board__group-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.45rem;
    padding: 0.28rem 0.5rem;
    border-bottom: 1px solid rgba(241, 245, 249, 0.95);
    background:
        linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.92)),
        linear-gradient(180deg, rgba(248, 250, 252, 0.98), rgba(241, 245, 249, 0.7));
    box-shadow: 0 1px 0 rgba(255, 255, 255, 0.85) inset;
}

.lux-ts-board__group-id {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 0.28rem 0.4rem;
    min-width: 0;
}

.lux-ts-board__group-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.2rem;
    padding: 0.12rem 0.42rem;
    border-radius: 999px;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    box-shadow: 0 1px 0 rgba(255, 255, 255, 0.55) inset;
}

.lux-ts-board__group-badge.is-billable {
    background: rgba(5, 150, 105, 0.12);
    color: #047857;
}

.lux-ts-board__group-badge.is-non-billable {
    background: rgba(37, 99, 235, 0.12);
    color: #1d4ed8;
}

.lux-ts-board__group-badge.is-leave {
    background: rgba(234, 88, 12, 0.16);
    color: #c2410c;
}

.lux-ts-board__group-badge.is-holiday {
    background: rgba(220, 38, 38, 0.14);
    color: #b91c1c;
}

.lux-ts-board__group--leave {
    border-top: 2px solid rgba(234, 88, 12, 0.65);
    background: linear-gradient(180deg, rgba(255, 247, 237, 0.65), rgba(255, 255, 255, 0.98));
}

.lux-ts-board__group--leave .lux-ts-board__group-head {
    background: rgba(255, 237, 213, 0.45);
}

.lux-ts-board__group--holiday {
    border-top: 2px solid rgba(220, 38, 38, 0.55);
    background: linear-gradient(180deg, rgba(254, 242, 242, 0.65), rgba(255, 255, 255, 0.98));
}

.lux-ts-board__group--holiday .lux-ts-board__group-head {
    background: rgba(254, 226, 226, 0.4);
}

.lux-ts-board__group.is-scroll-highlight {
    animation: lux-ts-scroll-highlight 2.4s ease-out;
}

@keyframes lux-ts-scroll-highlight {
    0% { box-shadow: 0 0 0 0 rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35); }
    40% { box-shadow: 0 0 0 4px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.2); }
    100% { box-shadow: 0 2px 12px rgba(15, 23, 42, 0.03); }
}

.lux-ts-board__group-code {
    font-size: 0.75rem;
    font-weight: 800;
    color: #0f172a;
    letter-spacing: -0.01em;
}

.lux-ts-board__group-name {
    font-size: 0.6875rem;
    font-weight: 600;
    color: #64748b;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    max-width: 14rem;
}

.lux-ts-board__group-meta {
    display: inline-flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 0.22rem;
    min-width: 0;
    margin-left: 0.1rem;
    padding-left: 0.4rem;
    border-left: 1px solid rgba(226, 232, 240, 0.95);
}

.lux-ts-board__group-chip {
    display: inline-flex;
    align-items: center;
    max-width: 8.5rem;
    padding: 0.08rem 0.38rem;
    border-radius: 999px;
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: rgba(255, 255, 255, 0.92);
    font-size: 0.6rem;
    font-weight: 700;
    letter-spacing: 0.02em;
    color: #475569;
    line-height: 1.25;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-ts-board__group-chip.is-category {
    border-color: rgba(5, 150, 105, 0.22);
    background: rgba(5, 150, 105, 0.1);
    color: #047857;
}

.lux-ts-board__group-chip.is-context {
    border-color: rgba(37, 99, 235, 0.2);
    background: rgba(37, 99, 235, 0.08);
    color: #1d4ed8;
}

.lux-ts-board__group-count {
    font-size: 0.6rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #94a3b8;
    white-space: nowrap;
}

.lux-ts-board__group-actions {
    display: inline-flex;
    align-items: center;
    justify-content: flex-end;
    gap: 0.28rem;
    flex-shrink: 0;
    min-height: 1.55rem;
}

.lux-ts-board__group-body {
    display: flex;
    flex-direction: column;
    gap: 0.12rem;
    padding: 0.12rem 0.22rem 0.18rem;
}

/* Entry rows — aligned to week rail grid */
.lux-ts-board__entry {
    padding: 0.14rem 0.1rem;
    border: 1px solid transparent;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.98);
    transition: border-color 0.14s ease, box-shadow 0.14s ease, background 0.14s ease;
}

.lux-ts-board__entry:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18);
    background:
        linear-gradient(90deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.035), rgba(255, 255, 255, 0.98));
    box-shadow: 0 2px 10px rgba(15, 23, 42, 0.045);
}

.lux-ts-board__entry.is-editing {
    position: relative;
    padding: 0.22rem 0 0.28rem;
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.24);
    background:
        radial-gradient(circle at 100% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.07), transparent 55%),
        rgba(255, 255, 255, 0.99);
    overflow: visible;
    z-index: 22;
    box-shadow: 0 8px 22px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
}

.lux-ts-board__entry.is-editing .lux-ts-board__entry-meta {
    grid-column: 1 / -1;
    grid-row: 1;
    padding: 0 0.28rem;
}

.lux-ts-board__entry.is-editing .lux-ts-board__hours-row-label {
    grid-row: 2;
    display: inline-flex;
    align-items: center;
    gap: 0.22rem;
    min-width: 0;
    padding-left: 0.2rem;
    font-size: 0.5625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #64748b;
    white-space: nowrap;
    overflow: hidden;
}

.lux-ts-board__hours-row-label-text {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
}

.lux-ts-board__entry.is-editing .lux-ts-board__day-slot,
.lux-ts-board__entry.is-editing .lux-ts-board__col-tools {
    grid-row: 2;
}

.lux-ts-board__entry.is-editing .lux-ts-board__day-slot.is-editable {
    background:
        linear-gradient(180deg, #ffffff 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06) 100%);
    border: 1.5px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.45);
}

.lux-ts-board__entry.is-editing .lux-ts-board__day-slot.is-disabled {
    background:
        repeating-linear-gradient(
            -45deg,
            rgba(241, 245, 249, 0.95),
            rgba(241, 245, 249, 0.95) 4px,
            rgba(226, 232, 240, 0.75) 4px,
            rgba(226, 232, 240, 0.75) 8px
        );
    border: 1px solid rgba(203, 213, 225, 0.85);
}

.lux-ts-board__entry.needs-hours:not(:focus-within) .lux-ts-board__day-slot.is-editable-empty {
    animation: lux-ts-hours-glow 2.2s ease-in-out infinite;
}

.lux-ts-board__entry.needs-hours:focus-within .lux-ts-board__day-slot.is-editable-empty {
    animation: none;
}

@keyframes lux-ts-hours-glow {
    0%, 100% { border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18); }
    50% { border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.38); }
}

.lux-ts-board__section-label {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.4rem;
    width: 100%;
    margin-bottom: 0.16rem;
    font-size: 0.58rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-ts-board__section-label-main {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    min-width: 0;
}

.lux-ts-board__section-label-main > .fe {
    font-size: 0.7rem;
    color: var(--lux-primary, #5b5ff4);
}

.lux-ts-board__entry.is-focus-pulse {
    animation: lux-ts-entry-pulse 2.4s ease-out;
}

@keyframes lux-ts-entry-pulse {
    0% { box-shadow: 0 0 0 0 rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35); }
    35% { box-shadow: 0 0 0 5px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12); }
    100% { box-shadow: none; }
}

.lux-ts-board__entry.is-new-row {
    border-left: 2px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.5);
}

.lux-ts-board__entry.has-hours {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.02);
}

.lux-ts-board__entry--leave {
    background: rgba(255, 237, 213, 0.35);
    border-color: rgba(234, 88, 12, 0.28);
    border-left: 3px solid rgba(234, 88, 12, 0.7);
}

.lux-ts-board__entry--holiday {
    background: rgba(254, 226, 226, 0.35);
    border-color: rgba(220, 38, 38, 0.26);
    border-left: 3px solid rgba(220, 38, 38, 0.65);
}

.lux-ts-board__entry-meta {
    min-width: 0;
    padding-left: 0.2rem;
    align-self: center;
}

.lux-ts-board__entry-tools {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    justify-content: center;
    gap: 0.22rem;
    flex-shrink: 0;
    padding-right: 0.15rem;
    min-height: 1.7rem;
}

.lux-ts-board__entry-total {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    min-width: 0;
    padding: 0.2rem 0.35rem;
    border-radius: 999px;
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: linear-gradient(180deg, #fff 0%, #f8fafc 100%);
    font-size: 0.75rem;
    font-weight: 800;
    color: #64748b;
    white-space: nowrap;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
}

.lux-ts-board__section-step {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 0.95rem;
    height: 0.95rem;
    border-radius: 9911px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    font-size: 0.55rem;
    font-weight: 800;
    color: var(--lux-primary-dark, #3730a3);
}

.lux-ts-board__section-hint {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    padding: 0.06rem 0.35rem;
    border-radius: 9911px;
    background: rgba(234, 88, 12, 0.12);
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #c2410c;
}

.lux-ts-board__section-hint.is-icon {
    width: 1.05rem;
    height: 1.05rem;
    padding: 0;
    border-radius: 999px;
    background: rgba(234, 88, 12, 0.16);
    box-shadow: inset 0 0 0 1px rgba(234, 88, 12, 0.22);
}

.lux-ts-board__section-hint.is-icon i {
    font-size: 0.62rem;
    line-height: 1;
}

.lux-ts-board__entry.is-editing .lux-ts-board__entry-tools {
    justify-content: center;
}

.lux-ts-board__entry-total.has-value {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    background: linear-gradient(180deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14), rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08));
    color: var(--lux-primary-dark, #3730a3);
}

/* Compact inline readout */
.lux-ts-board__line {
    margin: 0;
    font-size: 0.75rem;
    font-weight: 700;
    line-height: 1.3;
    color: #334155;
    min-width: 0;
}

.lux-ts-board__line strong {
    font-weight: 800;
    color: #0f172a;
}

.lux-ts-board__line-sep {
    margin: 0 0.2rem;
    color: #cbd5e1;
    font-weight: 400;
}

.lux-ts-board__line-muted {
    color: #64748b;
    font-weight: 600;
}

.lux-ts-board__line-btn {
    display: block;
    width: 100%;
    padding: 0.22rem 0.35rem;
    border: 1px solid transparent;
    border-radius: 9px;
    background: linear-gradient(180deg, rgba(248, 250, 252, 0.92), rgba(255, 255, 255, 0.98));
    text-align: left;
    cursor: pointer;
    transition: border-color 0.15s ease, background 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
}

.lux-ts-board__line-btn:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.07);
    box-shadow: 0 4px 12px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-ts-board__line-btn--rich {
    display: flex;
    align-items: flex-start;
    gap: 0.45rem;
    padding: 0.35rem 0.4rem 0.38rem;
    border: 1px solid rgba(226, 232, 240, 0.98);
    border-radius: 11px;
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08), transparent 55%),
        linear-gradient(165deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.96));
    box-shadow:
        0 1px 0 rgba(255, 255, 255, 0.9) inset,
        0 3px 10px rgba(15, 23, 42, 0.04);
    overflow: hidden;
}

.lux-ts-board__line-btn--rich:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.32);
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12), transparent 55%),
        linear-gradient(165deg, #fff, rgba(248, 250, 252, 0.98));
    box-shadow:
        0 1px 0 rgba(255, 255, 255, 0.95) inset,
        0 8px 18px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    transform: translateY(-0.5px);
}

/* Compact row identity — matches group-head language, single line */
.lux-ts-board__line-btn--compact {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    width: 100%;
    min-height: 1.7rem;
    padding: 0.18rem 0.28rem 0.18rem 0.22rem;
    border: 1px solid transparent;
    border-radius: 9px;
    background: transparent;
    text-align: left;
    cursor: pointer;
    overflow: hidden;
    transition: border-color 0.14s ease, background 0.14s ease, box-shadow 0.14s ease;
}

.lux-ts-board__line-btn--compact:hover {
    border-color: rgba(226, 232, 240, 0.98);
    background:
        linear-gradient(90deg, rgba(248, 250, 252, 0.98), rgba(255, 255, 255, 0.96));
    box-shadow: 0 1px 0 rgba(255, 255, 255, 0.9) inset;
}

.lux-ts-board__line-btn--compact:focus-visible {
    outline: none;
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.45);
    box-shadow: 0 0 0 2px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16);
}

.lux-ts-board__line-pill {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    max-width: 5.75rem;
    min-height: 1.2rem;
    padding: 0.08rem 0.36rem;
    border-radius: 999px;
    font-size: 0.5625rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    line-height: 1.2;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    box-shadow: 0 1px 0 rgba(255, 255, 255, 0.55) inset;
}

.lux-ts-board__line-pill.is-category {
    padding: 0.1rem 0.48rem 0.1rem 0.5rem;
    background: rgba(5, 150, 105, 0.12);
    color: #047857;
}

.lux-ts-board__line-pill.is-project {
    width: 1.2rem;
    max-width: 1.2rem;
    padding: 0;
    background: rgba(5, 150, 105, 0.12);
    color: #047857;
    font-size: 0.62rem;
    text-transform: none;
    letter-spacing: 0;
}

.lux-ts-board__line-pill.is-non-project {
    width: 1.2rem;
    max-width: 1.2rem;
    padding: 0;
    background: rgba(37, 99, 235, 0.12);
    color: #1d4ed8;
    font-size: 0.62rem;
    text-transform: none;
    letter-spacing: 0;
}

.lux-ts-board__line-pill.is-leave {
    width: 1.2rem;
    max-width: 1.2rem;
    padding: 0;
    background: rgba(234, 88, 12, 0.14);
    color: #c2410c;
    font-size: 0.62rem;
    text-transform: none;
    letter-spacing: 0;
}

.lux-ts-board__line-pill.is-holiday {
    width: 1.2rem;
    max-width: 1.2rem;
    padding: 0;
    background: rgba(220, 38, 38, 0.12);
    color: #b91c1c;
    font-size: 0.62rem;
    text-transform: none;
    letter-spacing: 0;
}

.lux-ts-board__line-btn--compact .lux-ts-board__line-title {
    flex: 0 1 auto;
    min-width: 0;
    font-size: 0.72rem;
    font-weight: 800;
    letter-spacing: -0.01em;
    color: #0f172a;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-ts-board__line-trail {
    display: inline-flex;
    align-items: center;
    flex: 0 1 auto;
    min-width: 0;
    max-width: 6.5rem;
    font-size: 0.625rem;
    font-weight: 600;
    color: #94a3b8;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-ts-board__line-trail::before {
    content: "·";
    margin-right: 0.28rem;
    color: #cbd5e1;
    font-weight: 700;
