.lux-ts-board__line-open {
    display: inline-grid;
    place-items: center;
    margin-left: auto;
    flex-shrink: 0;
    width: 1.35rem;
    height: 1.35rem;
    border-radius: 8px;
    border: 1px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.2);
    background:
        linear-gradient(145deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12), rgba(var(--lux-primary-rgb, 91, 95, 244), 0.05));
    color: var(--lux-primary-dark, #3730a3);
    box-shadow: 0 1px 0 rgba(255, 255, 255, 0.75) inset;
    transition: background 0.14s ease, border-color 0.14s ease, color 0.14s ease, transform 0.14s ease, box-shadow 0.14s ease;
}

.lux-ts-board__line-open i {
    font-size: 0.68rem;
    line-height: 1;
}

.lux-ts-board__line-btn--compact:hover .lux-ts-board__line-open {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.42);
    background:
        linear-gradient(145deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.2), rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1));
    box-shadow:
        0 1px 0 rgba(255, 255, 255, 0.8) inset,
        0 3px 8px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18);
    transform: translateY(-0.5px);
}

.lux-ts-board__line-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.55rem;
    height: 1.55rem;
    flex-shrink: 0;
    border-radius: 9px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    color: var(--lux-primary-dark, #3730a3);
    font-size: 0.72rem;
    box-shadow: 0 1px 0 rgba(255, 255, 255, 0.7) inset;
}

.lux-ts-board__line-badge.is-project {
    background: rgba(5, 150, 105, 0.14);
    color: #047857;
}

.lux-ts-board__line-badge.is-non-project {
    background: rgba(37, 99, 235, 0.12);
    color: #1d4ed8;
}

.lux-ts-board__line-badge.is-leave {
    background: rgba(234, 88, 12, 0.14);
    color: #c2410c;
}

.lux-ts-board__line-badge.is-holiday {
    background: rgba(220, 38, 38, 0.12);
    color: #b91c1c;
}

.lux-ts-board__line-body {
    display: flex;
    flex-direction: column;
    gap: 0.22rem;
    min-width: 0;
    flex: 1;
}

.lux-ts-board__line-title {
    display: block;
    font-size: 0.75rem;
    font-weight: 800;
    line-height: 1.25;
    color: #0f172a;
    letter-spacing: -0.01em;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-ts-board__line-meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.22rem;
    min-width: 0;
}

.lux-ts-board__line-chip {
    display: inline-flex;
    align-items: center;
    max-width: 100%;
    padding: 0.08rem 0.38rem;
    border-radius: 999px;
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: rgba(255, 255, 255, 0.92);
    font-size: 0.6rem;
    font-weight: 700;
    letter-spacing: 0.02em;
    color: #475569;
    line-height: 1.3;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-ts-board__line-chip.is-category {
    border-color: rgba(5, 150, 105, 0.22);
    background: rgba(5, 150, 105, 0.1);
    color: #047857;
}

.lux-ts-board__line-chip.is-work {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.2);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
    color: var(--lux-primary-dark, #3730a3);
}

.lux-ts-board__line-chip.is-division {
    border-color: rgba(14, 165, 233, 0.22);
    background: rgba(14, 165, 233, 0.1);
    color: #0369a1;
}

.lux-ts-board__line-chip.is-account {
    border-color: rgba(99, 102, 241, 0.22);
    background: rgba(99, 102, 241, 0.1);
    color: #4338ca;
}

.lux-ts-board__line-chip.is-partner {
    border-color: rgba(168, 85, 247, 0.22);
    background: rgba(168, 85, 247, 0.1);
    color: #7e22ce;
}

.lux-ts-board__line-chip.is-team {
    border-color: rgba(245, 158, 11, 0.28);
    background: rgba(245, 158, 11, 0.12);
    color: #b45309;
}

.lux-ts-board__line-btn--rich .lux-ts-board__line-icon {
    margin: 0.1rem 0 0;
    flex-shrink: 0;
    opacity: 0.55;
    transition: opacity 0.15s ease, color 0.15s ease;
}

.lux-ts-board__line-btn--rich:hover .lux-ts-board__line-icon {
    opacity: 1;
    color: var(--lux-primary, #5b5ff4);
}

.lux-ts-board__line-icon {
    margin-left: 0.35rem;
    font-size: 0.6875rem;
    color: #94a3b8;
    vertical-align: middle;
}

.lux-ts-board__day-slot.is-inspectable {
    cursor: pointer;
}

.lux-ts-board__day-slot.is-inspectable:hover:not(:focus-within) {
    box-shadow: inset 0 0 0 1px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18);
}

.lux-ts-board__footer-day.is-clickable {
    cursor: default;
}

.lux-ts-board__footer-day.is-clickable:hover {
    background: transparent;
}

/* Editable field grid */
.lux-ts-board__fields {
    display: grid;
    gap: 0.3rem;
}

.lux-ts-board__fields--project {
    display: flex;
    flex-wrap: nowrap;
    align-items: flex-end;
    gap: 0.35rem;
}

.lux-ts-board__fields--project .lux-ts-board__field {
    flex: 1 1 0;
    min-width: 0;
}

.lux-ts-board__fields--non-project {
    grid-template-columns: repeat(4, minmax(0, 1fr));
}

.lux-ts-board__fields--non-project.lux-ts-board__fields--rich {
    display: flex;
    flex-direction: column;
}

.lux-ts-board__fields--non-project .lux-ts-board__fields-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
}

.lux-ts-board__fields--rich {
    display: flex;
    flex-direction: column;
    gap: 0.22rem;
    margin: 0.02rem 0 0.06rem;
    padding: 0.32rem 0.4rem 0.36rem 0.48rem;
    border-radius: 11px;
    border: 1px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16);
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1), transparent 46%),
        radial-gradient(circle at 100% 100%, rgba(5, 150, 105, 0.05), transparent 40%),
        linear-gradient(165deg, rgba(255, 255, 255, 0.99) 0%, rgba(248, 250, 252, 0.96) 100%);
    box-shadow:
        0 1px 0 rgba(255, 255, 255, 0.95) inset,
        0 6px 16px rgba(15, 23, 42, 0.05),
        0 0 0 1px rgba(255, 255, 255, 0.45) inset;
    position: relative;
    z-index: 12;
    overflow: visible;
}

.lux-ts-board__fields--rich::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0.4rem;
    bottom: 0.4rem;
    width: 2.5px;
    border-radius: 999px;
    background: linear-gradient(180deg, var(--lux-primary, #5b5ff4), #0ea5e9 55%, var(--lux-primary-dark, #3730a3));
    opacity: 0.9;
}

.lux-ts-board__fields--rich .lux-ts-board__fields-grid,
.lux-ts-board__fields--rich .lux-ts-board__field {
    padding-left: 0.2rem;
}

.lux-ts-board__fields-grid--project {
    grid-template-columns: repeat(3, minmax(0, 1fr));
}

.lux-ts-board__fields--project.lux-ts-board__fields--rich {
    display: flex;
    flex-direction: column;
    flex-wrap: nowrap;
    align-items: stretch;
}

/* Board row selects must float above neighboring timesheet sections */
.lux-ts-board__entry.is-editing .lux-ts-board__fields--rich {
    z-index: 26;
}

.lux-ts-board__fields-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.35rem;
    flex-wrap: nowrap;
    min-height: 1.1rem;
    padding-left: 0.28rem;
}

.lux-ts-board__fields-kicker {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    font-family: "Plus Jakarta Sans", "Avenir Next", system-ui, sans-serif;
    font-size: 0.58rem;
    font-weight: 800;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    color: var(--lux-primary-dark, #3730a3);
}

.lux-ts-board__fields-kicker .fe {
    font-size: 0.68rem;
    color: var(--lux-primary, #5b5ff4);
}

.lux-ts-board__fields-hint {
    font-size: 0.58rem;
    font-weight: 600;
    color: #94a3b8;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.lux-ts-board__fields-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.22rem 0.28rem;
}

.lux-ts-board__fields--rich .lux-ts-board__field--wide {
    grid-column: 1 / -1;
}

.lux-ts-board__fields--rich .lux-ts-board__field-label {
    display: inline-flex;
    align-items: center;
    gap: 0.22rem;
    margin-bottom: 0.08rem;
    font-size: 0.55rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-ts-board__fields--rich .lux-ts-board__field-label .fe {
    font-size: 0.62rem;
    color: var(--lux-primary, #5b5ff4);
    opacity: 0.95;
}

.lux-ts-board__fields--rich .lux-ts-board__select .custom-select__control {
    min-height: 1.65rem !important;
    border-radius: 8px !important;
    border: 1px solid rgba(203, 213, 225, 0.95) !important;
    background:
        linear-gradient(180deg, #ffffff 0%, #f8fafc 100%) !important;
    box-shadow:
        0 1px 0 rgba(255, 255, 255, 0.9) inset,
        0 1px 4px rgba(15, 23, 42, 0.04) !important;
    font-size: 0.72rem !important;
    transition: border-color 0.14s ease, box-shadow 0.14s ease, transform 0.14s ease;
}

.lux-ts-board__fields--rich .lux-ts-board__select .custom-select__control:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.42) !important;
    box-shadow:
        0 1px 0 rgba(255, 255, 255, 0.9) inset,
        0 4px 12px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1) !important;
}

.lux-ts-board__fields--rich .lux-ts-board__select .custom-select__control--is-focused {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.6) !important;
    box-shadow:
        0 0 0 3px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14),
        0 4px 12px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12) !important;
}

.lux-ts-board__fields--rich .lux-ts-board__select .custom-select__control--menu-is-open {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.65) !important;
    background: #fff !important;
}

.lux-ts-board__fields--rich .lux-ts-board__select .custom-select__value-container {
    padding: 0.12rem 0.45rem !important;
    font-size: 0.75rem !important;
}

.lux-ts-board__fields--rich .lux-ts-board__select .custom-select__placeholder {
    color: #94a3b8 !important;
    font-weight: 600;
    font-size: 0.72rem !important;
}

.lux-ts-board__fields--rich .lux-ts-board__select .custom-select__single-value {
    color: #0f172a !important;
    font-weight: 700;
    font-size: 0.75rem !important;
}

.lux-ts-board__fields--rich .lux-ts-board__select .custom-select__indicator {
    color: var(--lux-primary, #5b5ff4) !important;
    padding: 0.1rem !important;
}

.lux-ts-board__fields--rich .lux-ts-board__select .custom-select__dropdown-indicator {
    padding: 0 0.28rem !important;
}

.lux-ts-board__fields--rich .lux-ts-board__text-input {
    min-height: 1.65rem !important;
    border-radius: 8px !important;
    border: 1px solid rgba(203, 213, 225, 0.95) !important;
    font-size: 0.72rem !important;
    font-weight: 600;
    padding: 0.18rem 0.4rem !important;
    background: linear-gradient(180deg, #fff 0%, #f8fafc 100%);
    box-shadow:
        0 1px 0 rgba(255, 255, 255, 0.9) inset,
        0 1px 4px rgba(15, 23, 42, 0.04);
}

.lux-ts-board__fields--rich .lux-ts-board__text-input:focus {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.6) !important;
    box-shadow:
        0 0 0 2px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12),
        0 3px 10px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1) !important;
    outline: none;
}

/* Portaled menus for timesheet board selects (escape overflow:hidden groups) */
.custom-select__menu-portal {
    z-index: 10140 !important;
}

body:has(.lux-ts-board__entry.is-editing) .custom-select__menu-portal {
    z-index: 10060 !important;
}

.custom-select__menu-portal .custom-select__menu {
    border-radius: 12px !important;
    border: 1px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16) !important;
    box-shadow:
        0 20px 44px rgba(15, 23, 42, 0.18),
        0 4px 12px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08) !important;
    overflow: hidden;
    margin-top: 4px !important;
    background:
        linear-gradient(180deg, #ffffff 0%, #f8fafc 100%) !important;
    padding: 0.2rem !important;
}

.custom-select__menu-portal .custom-select__option {
    font-size: 0.75rem !important;
    font-weight: 650;
    padding: 0.42rem 0.6rem !important;
    border-radius: 8px !important;
    margin: 0.08rem !important;
}

.custom-select__menu-portal .custom-select__option--is-focused {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1) !important;
    color: var(--lux-primary-dark, #3730a3) !important;
}

.custom-select__menu-portal .custom-select__option--is-selected {
    background:
        linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16), rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1)) !important;
    color: var(--lux-primary-dark, #3730a3) !important;
    font-weight: 800;
    box-shadow: inset 3px 0 0 var(--lux-primary, #5b5ff4);
}

.custom-select__menu-portal .custom-select__group-heading {
    font-size: 0.625rem !important;
    font-weight: 800 !important;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b !important;
    padding: 0.35rem 0.65rem 0.2rem !important;
}

@media (max-width: 900px) {
    .lux-ts-board__fields-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 560px) {
    .lux-ts-board__fields-grid {
        grid-template-columns: 1fr;
    }
}

.lux-ts-board__field {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
    min-width: 0;
}

.lux-ts-board__field-label {
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #64748b;
}

/* Day hour cells */
.lux-ts-board__day-slot {
    display: flex;
    align-items: center;
    justify-content: center;
    min-width: 0;
    min-height: 1.7rem;
    padding: 0.04rem 0.04rem;
    border-radius: 7px;
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: #fff;
    transition: border-color 0.08s ease, box-shadow 0.08s ease;
}

.lux-ts-board__day-slot.is-today:not(.is-disabled) {
    border-color: rgba(5, 150, 105, 0.35);
    background: rgba(5, 150, 105, 0.06);
}

.lux-ts-board__field--wide {
    grid-column: span 2;
}

/* Editable — clear “you can type here” affordance */
.lux-ts-board__day-slot.is-editable {
    border: 1.5px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.42);
    background:
        linear-gradient(180deg, #ffffff 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.05) 100%);
    box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.8) inset,
        0 2px 8px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    cursor: text;
}

.lux-ts-board__day-slot.is-editable:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.58);
    box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.85) inset,
        0 4px 12px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16);
}

.lux-ts-board__day-slot.is-editable:focus-within {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.7);
    box-shadow:
        0 0 0 3px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16),
        0 4px 12px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14);
}

.lux-ts-board__day-slot.is-editable-empty {
    border-style: dashed;
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.48);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
}

.lux-ts-board__day-slot.is-editable.has-value {
    border-style: solid;
    background:
        linear-gradient(180deg, #ffffff 0%, rgba(5, 150, 105, 0.08) 100%);
    border-color: rgba(5, 150, 105, 0.4);
    box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.8) inset,
        0 2px 8px rgba(5, 150, 105, 0.12);
}

/* Disabled — clearly unavailable */
.lux-ts-board__day-slot.is-disabled {
    opacity: 1;
    border: 1px solid rgba(203, 213, 225, 0.85);
    background:
        repeating-linear-gradient(
            -45deg,
            rgba(241, 245, 249, 0.95),
            rgba(241, 245, 249, 0.95) 4px,
            rgba(226, 232, 240, 0.75) 4px,
            rgba(226, 232, 240, 0.75) 8px
        );
    box-shadow: none;
    cursor: not-allowed;
    pointer-events: none;
}

.lux-ts-board__day-slot.is-disabled .lux-ts-board__hour-empty,
.lux-ts-board__day-slot.is-disabled .lux-ts-board__hour-empty.has-value {
    color: #94a3b8;
    background: transparent;
    border: none;
    box-shadow: none;
    font-weight: 700;
}

/* Readonly / locked — value visible, not editable */
.lux-ts-board__day-slot.is-readonly {
    border: 1px solid rgba(148, 163, 184, 0.55);
    background: rgba(241, 245, 249, 0.95);
    cursor: default;
    box-shadow: none;
}

.lux-ts-board__day-slot.is-readonly .lux-ts-board__hour-readonly {
    background: rgba(226, 232, 240, 0.65);
    border-color: rgba(148, 163, 184, 0.45);
    color: #475569;
}

.lux-ts-board__entry--leave .lux-ts-board__day-slot.is-editable,
.lux-ts-board__entry--leave .lux-ts-board__day-slot.is-editable-empty {
    border-color: rgba(234, 88, 12, 0.42);
    background: rgba(255, 237, 213, 0.65);
    box-shadow: 0 2px 8px rgba(234, 88, 12, 0.1);
}

.lux-ts-board__entry--holiday .lux-ts-board__day-slot.is-editable,
.lux-ts-board__entry--holiday .lux-ts-board__day-slot.is-editable-empty {
    border-color: rgba(220, 38, 38, 0.38);
    background: rgba(254, 226, 226, 0.65);
    box-shadow: 0 2px 8px rgba(220, 38, 38, 0.1);
}

.lux-ts-board__day-slot.has-value.is-level-1:not(.is-disabled):not(.is-editable) {
    background: rgba(5, 150, 105, 0.1);
    border-color: rgba(5, 150, 105, 0.22);
}

.lux-ts-board__day-slot.has-value.is-level-2:not(.is-disabled):not(.is-editable) {
    background: rgba(5, 150, 105, 0.14);
    border-color: rgba(5, 150, 105, 0.28);
}

.lux-ts-board__day-slot.has-value.is-level-3:not(.is-disabled):not(.is-editable) {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.24);
}

.lux-ts-board__day-slot.has-value.is-level-4:not(.is-disabled):not(.is-editable) {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16);
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.3);
}

.lux-ts-board__day-slot-body {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 0.12rem;
    width: 100%;
    min-width: 0;
}

.lux-ts-board__day-remove {
    position: absolute;
    top: 0.08rem;
    right: 0.08rem;
    z-index: 2;
    display: inline-grid;
    place-items: center;
    width: 1rem;
    height: 1rem;
    padding: 0;
    border: none;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.92);
    color: #b91c1c;
    box-shadow: 0 1px 4px rgba(15, 23, 42, 0.12);
    cursor: pointer;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.14s ease, transform 0.14s ease;
}

.lux-ts-board__day-slot.is-editable:hover .lux-ts-board__day-remove,
.lux-ts-board__day-slot.is-editable:focus-within .lux-ts-board__day-remove {
    opacity: 1;
    pointer-events: auto;
}

.lux-ts-board__day-remove:hover {
    transform: scale(1.06);
    background: rgba(254, 226, 226, 0.96);
}

.lux-ts-board__day-remove .fe {
    font-size: 0.62rem;
    line-height: 1;
}

/* Timesheet approval — cell layers (flag on) */
.lux-ts-board__day-slot.is-layer-approved.is-readonly-approved {
    border: 1px solid rgba(5, 150, 105, 0.22);
    background: rgba(5, 150, 105, 0.07);
}

.lux-ts-board__day-slot.is-layer-staged {
    border: 1px dashed rgba(var(--lux-primary-rgb, 91, 95, 244), 0.42);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
}

.lux-ts-board__day-slot.is-layer-both {
    border: 1px solid rgba(217, 119, 6, 0.35);
