    background: linear-gradient(135deg, rgba(240, 253, 244, 0.98), rgba(220, 252, 231, 0.45));
}

.lux-ts-compliance--collapsed {
    padding: 0;
    border: none;
    background: transparent;
    box-shadow: none;
}

.lux-ts-compliance__collapsed-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    width: 100%;
    padding: 0.85rem 1rem;
    border-radius: 14px;
    border: 1px solid rgba(148, 163, 184, 0.28);
    background: rgba(248, 250, 252, 0.98);
    cursor: pointer;
    text-align: left;
}

.lux-ts-compliance.is-warning .lux-ts-compliance__collapsed-bar,
.lux-ts-compliance--collapsed.is-warning .lux-ts-compliance__collapsed-bar {
    border-color: rgba(245, 158, 11, 0.5);
    background: linear-gradient(135deg, rgba(255, 251, 235, 0.98), rgba(254, 243, 199, 0.7));
}

.lux-ts-compliance.is-ok .lux-ts-compliance__collapsed-bar,
.lux-ts-compliance--collapsed.is-ok .lux-ts-compliance__collapsed-bar {
    border-color: rgba(34, 197, 94, 0.35);
    background: linear-gradient(135deg, rgba(240, 253, 244, 0.98), rgba(220, 252, 231, 0.55));
}

.lux-ts-compliance__collapsed-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 999px;
    flex-shrink: 0;
    background: rgba(148, 163, 184, 0.16);
    color: #475569;
    font-size: 1rem;
}

.lux-ts-compliance.is-warning .lux-ts-compliance__collapsed-icon {
    background: rgba(245, 158, 11, 0.2);
    color: #b45309;
}

.lux-ts-compliance.is-ok .lux-ts-compliance__collapsed-icon {
    background: rgba(34, 197, 94, 0.18);
    color: #15803d;
}

.lux-ts-compliance__collapsed-copy {
    flex: 1;
    min-width: 0;
}

.lux-ts-compliance__count {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 1.75rem;
    height: 1.75rem;
    padding: 0 0.4rem;
    border-radius: 999px;
    font-size: 0.75rem;
    font-weight: 700;
    background: rgba(245, 158, 11, 0.22);
    color: #b45309;
}

.lux-ts-compliance.is-warning .lux-ts-compliance__eyebrow {
    color: #b45309;
}

.lux-ts-compliance.is-warning .lux-ts-compliance__head h3 {
    color: #92400e;
}

.lux-ts-compliance.is-warning .lux-ts-compliance__head p {
    color: #a16207;
}

.lux-ts-compliance.is-warning .lux-ts-compliance__collapsed-bar strong {
    color: #92400e;
}

.lux-ts-compliance.is-warning .lux-ts-compliance__row {
    border-color: rgba(245, 158, 11, 0.28);
}

.lux-ts-compliance__collapsed-bar strong {
    display: block;
    font-size: 0.875rem;
    color: #334155;
}

.lux-ts-compliance__collapsed-bar em {
    display: block;
    font-style: normal;
    font-size: 0.75rem;
    color: #64748b;
}

.lux-ts-compliance__collapsed-expand {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    font-size: 0.75rem;
    font-weight: 700;
    color: #475569;
}

.lux-ts-compliance__head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 1rem;
    margin-bottom: 0.85rem;
}

.lux-ts-compliance__head-actions {
    display: flex;
    align-items: center;
    gap: 0.45rem;
}

.lux-ts-compliance__eyebrow {
    display: block;
    font-size: 0.6875rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-ts-compliance__head h3 {
    margin: 0.15rem 0 0;
    font-size: 1rem;
    color: #334155;
}

.lux-ts-compliance__head p {
    margin: 0.2rem 0 0;
    font-size: 0.8125rem;
    color: #64748b;
}

.lux-ts-compliance__toggle {
    display: inline-flex;
    align-items: center;
    width: auto;
    height: auto;
    min-width: 0;
    min-height: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    font-size: 0.75rem;
    font-weight: 800;
    color: #475569;
    cursor: pointer;
    padding: 0.35rem 0.2rem;
}

.lux-ts-compliance.is-warning .lux-ts-compliance__toggle {
    color: #b45309;
}

.lux-ts-compliance.is-ok .lux-ts-compliance__toggle {
    color: #15803d;
}

.lux-ts-compliance__lock-btn {
    display: inline-flex;
    align-items: center;
    padding: 0.45rem 0.85rem;
    border-radius: 999px;
    border: 1px solid rgba(13, 148, 136, 0.28);
    background: rgba(13, 148, 136, 0.1);
    color: #0f766e;
    font-size: 0.75rem;
    font-weight: 800;
    cursor: pointer;
}

.lux-ts-compliance__lock-btn:disabled {
    opacity: 0.55;
    cursor: not-allowed;
}

.lux-ts-compliance__list {
    display: grid;
    gap: 0.45rem;
    margin: 0;
    padding: 0;
    list-style: none;
}

.lux-ts-compliance__row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    padding: 0.65rem 0.75rem;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.78);
    border: 1px solid rgba(148, 163, 184, 0.16);
}

.lux-ts-compliance__row strong {
    display: block;
    font-size: 0.8125rem;
    color: #1f2937;
}

.lux-ts-compliance__row span,
.lux-ts-compliance__row em {
    display: block;
    font-size: 0.75rem;
    color: #64748b;
    font-style: normal;
}

.lux-ts-compliance__status {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.2rem 0.55rem;
    border-radius: 999px;
    font-size: 0.6875rem;
    font-weight: 700;
    background: rgba(255, 255, 255, 0.9);
    border: 1px solid rgba(148, 163, 184, 0.2);
    flex-shrink: 0;
}

.lux-ts-compliance__empty {
    margin: 0;
    font-size: 0.8125rem;
    color: #64748b;
}

/* Sticky bottom action dock — Save + Submit always reachable */
.lux-ts-board.has-action-dock {
    padding-bottom: 0.35rem;
}

.lux-ts-board__action-dock {
    position: sticky;
    bottom: 0.75rem;
    z-index: 32;
    margin-top: 0.85rem;
    padding-bottom: env(safe-area-inset-bottom, 0);
}

.lux-ts-board__action-dock-error {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    margin-bottom: 0.45rem;
    padding: 0.55rem 0.7rem;
    border: 1px solid rgba(220, 38, 38, 0.22);
    border-radius: 12px;
    background: rgba(254, 226, 226, 0.92);
    font-size: 0.75rem;
    font-weight: 700;
    color: #b91c1c;
    box-shadow: 0 8px 20px rgba(185, 28, 28, 0.08);
}

.lux-ts-board__action-dock-error-dismiss {
    margin-left: auto;
    width: 1.25rem;
    height: 1.25rem;
    padding: 0;
    border: none;
    border-radius: 999px;
    background: rgba(220, 38, 38, 0.14);
    cursor: pointer;
}

.lux-ts-board__action-dock-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.85rem;
    padding: 0.85rem 1rem;
    border: 1px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
    border-radius: 18px;
    background:
        radial-gradient(circle at 0% 50%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12), transparent 52%),
        radial-gradient(circle at 100% 0%, rgba(5, 150, 105, 0.08), transparent 45%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.97), rgba(248, 250, 252, 0.95));
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.75) inset,
        0 18px 48px rgba(15, 23, 42, 0.18),
        0 4px 14px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-ts-board__action-dock-copy {
    display: flex;
    align-items: center;
    gap: 0.7rem;
    min-width: 0;
    flex: 1;
}

.lux-ts-board__action-dock-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    flex-shrink: 0;
    padding: 0.28rem 0.6rem;
    border-radius: 999px;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    border: 1px solid transparent;
}

.lux-ts-board__action-dock-chip.is-draft {
    color: #475569;
    background: rgba(148, 163, 184, 0.16);
    border-color: rgba(100, 116, 139, 0.22);
}

.lux-ts-board__action-dock-chip.is-unsaved {
    color: #c2410c;
    background: rgba(251, 146, 60, 0.16);
    border-color: rgba(234, 88, 12, 0.28);
}

.lux-ts-board__action-dock-chip.is-ready {
    color: #3730a3;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14);
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
}

.lux-ts-board__action-dock-chip.is-pending {
    color: #b45309;
    background: rgba(251, 191, 36, 0.18);
    border-color: rgba(217, 119, 6, 0.28);
}

.lux-ts-board__action-dock-inner.is-submit-ready {
    align-items: center;
    gap: 0.65rem;
}

.lux-ts-board__action-dock-copy.is-compact {
    flex: 0;
}

.lux-ts-board__action-dock-inner.is-submit-ready .lux-ts-board__action-dock-actions {
    flex: 1;
    justify-content: flex-end;
}

.lux-ts-board__action-dock-text {
    display: flex;
    flex-direction: column;
    gap: 0.1rem;
    min-width: 0;
}

.lux-ts-board__action-dock-text strong {
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
    letter-spacing: -0.01em;
}

.lux-ts-board__action-dock-text span {
    font-size: 0.72rem;
    font-weight: 600;
    color: #64748b;
    line-height: 1.35;
}

.lux-ts-board__action-dock-actions {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    flex-shrink: 0;
    flex-wrap: wrap;
}

.lux-ts-board__partial-days {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    flex-wrap: wrap;
    margin-right: 0.25rem;
}

.lux-ts-board__partial-days-label {
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-ts-board__partial-day-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.25rem 0.55rem;
    border-radius: 999px;
    border: 1px solid #e2e8f0;
    background: #fff;
    font-size: 0.72rem;
    font-weight: 600;
    color: #475569;
    cursor: pointer;
}

.lux-ts-board__partial-day-chip input {
    margin: 0;
}

.lux-ts-board__partial-day-chip.is-selected {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.45);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
    color: var(--lux-primary-dark, #3730a3);
}

.lux-ts-board__action-dock-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.35rem;
    min-height: 2.45rem;
    padding: 0 1.05rem;
    border-radius: 999px;
    font-size: 0.75rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    cursor: pointer;
    transition: transform 0.14s ease, box-shadow 0.14s ease, filter 0.14s ease, opacity 0.14s ease;
}

.lux-ts-board__action-dock-btn--ghost {
    border: 1px solid #e2e8f0;
    background: #fff;
    color: #64748b;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
}

.lux-ts-board__action-dock-btn--ghost:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    color: var(--lux-primary-dark, #3730a3);
}

.lux-ts-board__action-dock-btn--save {
    border: none;
    min-width: 9.5rem;
    padding: 0 1.25rem;
    background: linear-gradient(135deg, #4f46e5 0%, var(--lux-primary, #5b5ff4) 45%, #6366f1 100%);
    color: #fff;
    box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.18) inset,
        0 10px 24px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.38),
        0 2px 6px rgba(15, 23, 42, 0.12);
    animation: lux-ts-save-pulse 2.4s ease-in-out infinite;
}

.lux-ts-board__action-dock-btn--save:hover {
    filter: brightness(1.05);
    transform: translateY(-1px);
    box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.22) inset,
        0 14px 30px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.46),
        0 4px 10px rgba(15, 23, 42, 0.14);
    animation: none;
}

.lux-ts-board__action-dock-btn--save .fe {
    font-size: 0.9rem;
}

@keyframes lux-ts-save-pulse {
    0%, 100% {
        box-shadow:
            0 0 0 1px rgba(255, 255, 255, 0.18) inset,
            0 10px 24px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.38),
            0 2px 6px rgba(15, 23, 42, 0.12);
    }
    50% {
        box-shadow:
            0 0 0 1px rgba(255, 255, 255, 0.22) inset,
            0 12px 28px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.5),
            0 0 0 4px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14);
    }
}

.lux-ts-board__action-dock-btn--submit {
    border: none;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
    color: #fff;
    box-shadow: 0 12px 28px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.36);
    min-width: 11.5rem;
}

.lux-ts-board__action-dock-btn--submit:hover:not(:disabled) {
    filter: brightness(1.04);
    transform: translateY(-1px);
    box-shadow: 0 16px 32px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.42);
}

.lux-ts-board__action-dock-btn--submit:disabled {
    opacity: 0.55;
    cursor: not-allowed;
    transform: none;
    box-shadow: none;
}

@media (max-width: 720px) {
    .lux-ts-board__action-dock-inner {
        flex-direction: column;
        align-items: stretch;
        gap: 0.7rem;
        padding: 0.8rem 0.85rem;
    }

    .lux-ts-board__action-dock-inner.is-submit-ready {
        flex-direction: row;
        flex-wrap: wrap;
        align-items: center;
    }

    .lux-ts-board__action-dock-copy {
        flex-direction: column;
        align-items: flex-start;
    }

    .lux-ts-board__action-dock-copy.is-compact {
        flex-direction: row;
        align-items: center;
    }

    .lux-ts-board__action-dock-actions {
        width: 100%;
        flex-wrap: wrap;
    }

    .lux-ts-board__action-dock-inner.is-submit-ready .lux-ts-board__action-dock-actions {
        width: auto;
        flex: 1 1 12rem;
        justify-content: flex-end;
    }

    .lux-ts-board__action-dock-btn {
        flex: 1 1 auto;
        min-width: 0;
    }

    .lux-ts-board__action-dock-btn--submit {
        flex: 1 1 100%;
        min-width: 0;
    }

    .lux-ts-board__action-dock-inner.is-submit-ready .lux-ts-board__action-dock-btn--submit {
        flex: 0 1 auto;
    }
}

body.lux-shell-dark .lux-ts-board__action-dock-inner {
    background:
        radial-gradient(circle at 0% 50%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18), transparent 52%),
