    border-color: rgba(51, 65, 85, 0.95);
}

body.lux-shell-dark .lux-ts-board__action-dock-text strong {
    color: #e2e8f0;
}

body.lux-shell-dark .lux-ts-board__action-dock-btn--ghost {
    background: rgba(15, 23, 42, 0.85);
    border-color: rgba(71, 85, 105, 0.95);
    color: #cbd5e1;
}

body.lux-shell-dark .lux-ts-board__action-dock-btn--save {
    background: linear-gradient(135deg, #4f46e5 0%, var(--lux-primary, #5b5ff4) 45%, #6366f1 100%);
    border: none;
    color: #fff;
}

