    position: sticky;
    bottom: 0.65rem;
    z-index: 20;
    margin-top: 0.65rem;
}

.lux-ts-board__save-error {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    margin-bottom: 0.45rem;
    padding: 0.55rem 0.65rem;
    border: 0px solid rgba(220, 38, 38, 0.22);
    border-radius: 12px;
    background: rgba(220, 38, 38, 0.08);
    font-size: 0.75rem;
    font-weight: 700;
    color: #b91c1c;
}

.lux-ts-board__save-error-dismiss {
    margin-left: auto;
    width: 1.25rem;
    height: 1.25rem;
    padding: 0;
    border: none;
