.lux-ts-addl-fields__panel-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.35rem;
    padding: 0.55rem 0.65rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.9);
    font-size: 0.6875rem;
    font-weight: 800;
    color: #334155;
}

.lux-ts-addl-fields__close {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.35rem;
    height: 1.35rem;
    padding: 0;
    border: none;
    border-radius: 9911px;
    background: rgba(241, 245, 249, 0.95);
    color: #64748b;
    cursor: pointer;
}

.lux-ts-addl-fields__panel-body {
    max-height: 14rem;
    overflow-y: auto;
    padding-top: 0.35rem;
}

.lux-ts-addl-fields__panel-foot {
    display: flex;
    justify-content: flex-end;
    padding: 0.45rem 0.65rem 0.55rem;
    border-top: 1px solid rgba(241, 245, 249, 0.95);
}

.lux-ts-addl-fields__done {
    min-height: 1.65rem;
    padding: 0 0.65rem;
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
    border-radius: 9911px;
