}

.lux-emp-card__avatar-ring {
    position: absolute;
    inset: -3px;
    border-radius: 9911px;
    background: linear-gradient(
        135deg,
        rgba(var(--lux-primary-rgb, 91, 95, 244), 0.55),
        rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12)
