}

.lux-emp-card__avatar {
    position: relative;
    z-index: 1;
    width: 4.25rem !important;
    height: 4.25rem !important;
    object-fit: cover;
    border: 2.5px solid #fff !important;
    border-radius: 9911px !important;
    box-shadow: 0 6px 18px rgba(15, 23, 42, 0.14);
    padding: 0 !important;
    background: #f8fafc;
