    color: #fff;
    font-size: 0.6875rem;
    font-weight: 800;
    display: grid;
    place-items: center;
    box-shadow: 0 2px 8px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
}

.lux-emp-card__status-dot {
    position: absolute;
    top: 0.15rem;
    left: 0.15rem;
    z-index: 3;
    width: 0.6rem;
    height: 0.6rem;
    border: 2px solid #fff;
    border-radius: 9911px;
    box-shadow: 0 1px 4px rgba(15, 23, 42, 0.12);
