    flex-wrap: wrap;
    gap: 0.3rem;
    margin-bottom: 0.4rem;
}

.lux-bid-detail__ref-pill,
.lux-bid-detail__status-pill,
.lux-bid-detail__type-pill,
.lux-bid-detail__flag-pill {
    display: inline-flex;
    padding: 0.15rem 0.625rem;
    border-radius: 9911px;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
}

.lux-bid-detail__ref-pill {
    background: rgba(15, 23, 42, 0.08);
    color: #475569;
}

.lux-bid-detail__status-pill.is-sky { background: rgba(14, 165, 233, 0.14); color: #0369a1; }
.lux-bid-detail__status-pill.is-indigo { background: rgba(99, 102, 241, 0.14); color: #4338ca; }
.lux-bid-detail__status-pill.is-amber { background: rgba(245, 158, 11, 0.14); color: #b45309; }
.lux-bid-detail__status-pill.is-green { background: rgba(16, 185, 129, 0.14); color: #047857; }
.lux-bid-detail__status-pill.is-rose { background: rgba(244, 63, 94, 0.14); color: #be123c; }
.lux-bid-detail__status-pill.is-slate { background: rgba(148, 163, 184, 0.18); color: #475569; }

.lux-bid-detail__type-pill.is-indigo { background: rgba(99, 102, 241, 0.1); color: #4338ca; }
.lux-bid-detail__type-pill.is-violet { background: rgba(139, 92, 246, 0.1); color: #6d28d9; }
.lux-bid-detail__type-pill.is-sky { background: rgba(14, 165, 233, 0.1); color: #0369a1; }
.lux-bid-detail__type-pill.is-amber { background: rgba(245, 158, 11, 0.1); color: #b45309; }
.lux-bid-detail__type-pill.is-teal { background: rgba(20, 184, 166, 0.1); color: #0f766e; }
.lux-bid-detail__type-pill.is-green { background: rgba(16, 185, 129, 0.1); color: #047857; }
.lux-bid-detail__type-pill.is-slate { background: rgba(148, 163, 184, 0.12); color: #475569; }

.lux-bid-detail__flag-pill.is-muted {
    background: rgba(148, 163, 184, 0.15);
    color: #64748b;
}

.lux-bid-detail__flag-pill.is-danger {
    background: rgba(244, 63, 94, 0.12);
    color: #be123c;
}

.lux-bid-detail__title {
    margin: 0;
    font-size: clamp(1.25rem, 2.5vw, 1.65rem);
    font-weight: 800;
    line-height: 1.2;
    color: #0f172a;
    letter-spacing: -0.02em;
}

.lux-bid-detail__subtitle {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.35rem;
    margin: 0.35rem 0 0;
    font-size: 0.6875rem;
    color: #64748b;
}

.lux-bid-detail__subtitle i {
    font-size: 0.75rem;
    color: #94a3b8;
}

.lux-bid-detail__dot {
    color: #cbd5e1;
}

.lux-bid-detail__hero-aside {
    padding: 0.55rem 0.65rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.85);
    min-width: 10rem;
}

.lux-bid-detail__status-label {
    display: block;
    margin-bottom: 0.3rem;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-bid-detail__status-select {
    padding: 0.2rem 0.45rem;
    border-radius: 12px;
    border: 0px solid rgba(226, 232, 240, 0.95);
    background: #fff;
}

.lux-bid-detail__status-select.is-sky { border-color: rgba(14, 165, 233, 0.35); }
.lux-bid-detail__status-select.is-indigo { border-color: rgba(99, 102, 241, 0.35); }
.lux-bid-detail__status-select.is-amber { border-color: rgba(245, 158, 11, 0.35); }
.lux-bid-detail__status-select.is-green { border-color: rgba(16, 185, 129, 0.35); }

.lux-bid-detail__status-input,
.lux-bid-detail__status-input.badge {
    margin: 0 !important;
    border: none !important;
    background: transparent !important;
    font-size: 0.6875rem !important;
    font-weight: 800 !important;
    text-transform: uppercase;
    box-shadow: none !important;
}

.lux-bid-detail__facts {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.45rem;
    margin-top: 0.85rem;
    padding-top: 0.75rem;
    border-top: 1px solid rgba(226, 232, 240, 0.9);
}

.lux-bid-detail__fact {
    display: flex;
    align-items: flex-start;
    gap: 0.4rem;
    padding: 0.45rem 0.625rem;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.7);
    border: 0px solid rgba(241, 245, 249, 0.95);
}

.lux-bid-detail__fact-icon {
    width: 1.65rem;
    height: 1.65rem;
    border-radius: 8px;
    display: grid;
    place-items: center;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary, #5b5ff4);
    font-size: 0.75rem;
    flex-shrink: 0;
}

.lux-bid-detail__fact-label {
    display: block;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-bid-detail__fact-value {
    display: block;
    margin-top: 0.1rem;
    font-size: 0.6875rem;
    font-weight: 700;
    color: #0f172a;
    line-height: 1.3;
}

.lux-bid-detail__layout {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 17.5rem;
    gap: 0.65rem;
    align-items: start;
}

.lux-bid-detail--compact .lux-bid-detail__layout {
    grid-template-columns: 1fr;
}

.lux-bid-detail__section {
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 18px;
    background: #fff;
    overflow: hidden;
    box-shadow: 0 6px 18px rgba(15, 23, 42, 0.04);
}

.lux-bid-detail__section-head {
    padding: 0.65rem 0.85rem;
    border-bottom: 1px solid rgba(241, 245, 249, 0.95);
    background: rgba(248, 250, 252, 0.9);
}

.lux-bid-detail__section-eyebrow {
    display: block;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--lux-primary, #5b5ff4);
}

.lux-bid-detail__section-title {
    margin: 0.1rem 0 0;
    font-size: 0.9375rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-bid-detail__section-subtitle {
    margin: 0.35rem 0 0;
    font-size: 0.82rem;
    color: #64748b;
    line-height: 1.45;
    max-width: 52ch;
}

.lux-bid-detail__form-shell {
    padding: 0.65rem 0.75rem 0.85rem;
}

.lux-bid-detail__form-shell .lux-bid-form--full .lux-bid-form__layout--split {
    grid-template-columns: 1fr;
}

.lux-bid-detail__rail {
    display: flex;
    flex-direction: column;
    gap: 0.625rem;
}

.lux-bid-detail__card {
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 16px;
    background: rgba(255, 255, 255, 0.96);
    overflow: hidden;
    box-shadow: 0 4px 12px rgba(15, 23, 42, 0.03);
}

.lux-bid-detail__card-head {
    padding: 0.625rem 0.65rem;
    border-bottom: 1px solid rgba(241, 245, 249, 0.95);
    background: rgba(248, 250, 252, 0.95);
}

.lux-bid-detail__card-head h2 {
    margin: 0;
    font-size: 0.75rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-bid-detail__card-body {
    padding: 0.625rem 0.65rem 0.6rem;
}

.lux-bid-detail__card-body .lux-bid-detail__fact {
    margin-bottom: 0.35rem;
    background: transparent;
    border: none;
    padding: 0.25rem 0;
}

.lux-bid-detail__tag-group {
    margin-bottom: 0.45rem;
}

.lux-bid-detail__tag-group:last-child {
    margin-bottom: 0;
}

.lux-bid-detail__tag-label {
    display: block;
    margin-bottom: 0.25rem;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-bid-detail__tags {
    display: flex;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.lux-bid-detail__tag {
    padding: 0.15rem 0.45rem;
    border-radius: 9911px;
    font-size: 0.6875rem;
    font-weight: 700;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary-dark, #3730a3);
}

.lux-bid-detail__tag.is-geo {
    background: rgba(14, 165, 233, 0.1);
    color: #0369a1;
}

.lux-bid-detail__comments-panel {
    margin-top: 0.65rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 18px;
    background: #fff;
    overflow: hidden;
    box-shadow: 0 6px 18px rgba(15, 23, 42, 0.04);
}

.lux-bid-detail__comments-body {
    padding: 0.65rem 0.85rem 0.85rem;
}

/* Shared entity Activity & audit panels (PO / bid / deliverable) */
.lux-bid-detail__comments-panel,
.lux-entity-collab-panel {
    position: relative;
    margin-top: 0.85rem;
    border: 1px solid rgba(226, 232, 240, 0.95);
    border-radius: 20px;
    background:
        radial-gradient(circle at 100% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.07), transparent 42%),
        radial-gradient(circle at 0% 100%, rgba(20, 184, 166, 0.05), transparent 48%),
        #fff;
    overflow: hidden;
    box-shadow: 0 16px 40px rgba(15, 23, 42, 0.06);
}

.lux-bid-detail__comments-panel::before,
.lux-entity-collab-panel::before {
    content: "";
    position: absolute;
    inset: 0 auto 0 0;
    width: 4px;
    background: linear-gradient(180deg, var(--lux-primary, #5b5ff4), #14b8a6);
}

.lux-entity-collab-panel__head {
    display: flex;
    align-items: flex-start;
    gap: 0.85rem;
    padding: 1.15rem 1.25rem 0.85rem;
}

.lux-entity-collab-panel__icon {
    width: 2.6rem;
    height: 2.6rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 14px;
    flex-shrink: 0;
    color: var(--lux-primary-dark, #3730a3);
    background: linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16), rgba(20, 184, 166, 0.1));
    box-shadow: inset 0 0 0 1px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.lux-entity-collab-panel__intro {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.65rem;
    padding: 0 1.25rem 0.85rem;
}

.lux-entity-collab-panel__intro--single {
    grid-template-columns: 1fr;
}

.lux-entity-collab-panel__intro-card {
    display: flex;
    align-items: flex-start;
    gap: 0.65rem;
    padding: 0.75rem 0.85rem;
    border-radius: 14px;
    border: 1px solid #e2e8f0;
    background: rgba(255, 255, 255, 0.9);
}

.lux-entity-collab-panel__intro-card > i {
    width: 1.85rem;
    height: 1.85rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    flex-shrink: 0;
}

.lux-entity-collab-panel__intro-card.is-comments > i {
    color: #4338ca;
    background: rgba(99, 102, 241, 0.12);
}

.lux-entity-collab-panel__intro-card.is-audit > i {
    color: #0f766e;
    background: rgba(20, 184, 166, 0.12);
}

.lux-entity-collab-panel__intro-card strong {
    display: block;
    font-size: 0.82rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-entity-collab-panel__intro-card span {
    display: block;
    margin-top: 0.15rem;
    font-size: 0.74rem;
    line-height: 1.4;
    color: #64748b;
}

.lux-entity-collab-panel__body,
.lux-bid-detail__comments-body.lux-entity-collab-panel__body {
    padding: 0.35rem 1.1rem 1.15rem;
}

.lux-entity-collab-panel--deliverable {
    margin-top: 0.5rem;
}

@media (max-width: 767px) {
    .lux-entity-collab-panel__intro {
        grid-template-columns: 1fr;
    }
}


.lux-bid-detail__view-body {
    padding: 0 0.625rem 1rem;
}

.lux-bid-detail--compact .lux-bid-detail__hero {
    margin-bottom: 0.625rem;
    padding: 0.75rem;
}

.lux-bid-detail--compact .lux-bid-detail__facts {
    display: none;
}

@media (max-width: 1100px) {
    .lux-bid-detail__layout {
        grid-template-columns: 1fr;
    }

    .lux-bid-detail__facts {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .lux-bid-detail-page__loading-grid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 768px) {
    .lux-bid-detail__hero-inner {
        grid-template-columns: 1fr;
    }

    .lux-bid-detail__facts {
        grid-template-columns: 1fr;
    }
}

/* Question blocks in create form */
.lux-bid-questions {
    margin-top: 0.65rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 16px;
    background: rgba(255, 255, 255, 0.92);
