.lux-proj-dash__kpi-strip {
    margin-top: 0.15rem;
}

.lux-proj-dash__command {
    display: grid;
    grid-template-columns: minmax(220px, 0.9fr) minmax(0, 1.1fr);
    gap: 1rem 1.15rem;
    margin-top: 0.85rem;
    padding: 1.05rem 1.15rem 1.15rem;
    border-radius: 20px;
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1), transparent 46%),
        radial-gradient(circle at 100% 100%, rgba(14, 165, 233, 0.07), transparent 42%),
        linear-gradient(145deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.94));
    box-shadow:
        0 1px 0 rgba(255, 255, 255, 0.92) inset,
        0 14px 36px rgba(15, 23, 42, 0.06);
