.lux-proj-dash__command-chip.is-slate > i { background: rgba(148, 163, 184, 0.16); color: #475569; }

.lux-proj-dash__command-chip strong {
    display: block;
    font-size: 0.9375rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.1;
}

.lux-proj-dash__command-chip span {
    display: block;
    margin-top: 0.12rem;
    font-size: 0.625rem;
    font-weight: 700;
    letter-spacing: 0.02em;
    color: #64748b;
}

.lux-proj-dash__command-meters {
