.lux-att-summary__month-pill i,
.lux-planner-shell__range-pill i {
    font-size: 0.75rem;
    color: var(--lux-primary, #5b5ff4);
}

.lux-att-summary__body {
    display: flex;
    flex-direction: column;
    gap: 0.65rem;
}

/* Eyebrow — see luxury-summary-shared.css (.lux-summary-eyebrow) */

.lux-att-summary__title {
    margin: 0.12rem 0 0;
    font-size: 1.25rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.2;
}

.lux-att-summary__title--compact {
    font-size: 0.9375rem;
}

.lux-att-summary__title--bar {
    font-size: 1.05rem;
}

.lux-att-summary__hero {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.65rem;
}

.lux-att-summary__hero-copy {
    flex: 1 1 14rem;
    min-width: 0;
}

.lux-att-summary__month {
    margin: 0;
    font-size: 1.15rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-att-summary__subtitle {
    margin: 0.2rem 0 0;
    font-size: 0.75rem;
    font-weight: 600;
    line-height: 1.45;
    color: #64748b;
}

.lux-att-summary__hero-rate {
    flex: 0 0 auto;
    display: flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.45rem 0.6rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.82);
}

.lux-att-summary__rate-ring {
    --lux-active-pct: 0%;
    position: relative;
    width: 3rem;
    height: 3rem;
    border-radius: 9911px;
    background: conic-gradient(
        var(--lux-primary, #5b5ff4) calc(var(--lux-active-pct) * 1%),
        rgba(226, 232, 240, 0.95) 0
    );
    display: grid;
    place-items: center;
}

.lux-att-summary__rate-ring::before {
    content: "";
    position: absolute;
    inset: 4px;
    border-radius: 9911px;
    background: #fff;
}

.lux-att-summary__rate-ring span {
    position: relative;
    z-index: 1;
    font-size: 0.6875rem;
    font-weight: 800;
    color: var(--lux-primary-dark, #3730a3);
}

.lux-att-summary__rate-copy strong {
    display: block;
    font-size: 0.75rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-att-summary__rate-copy span {
    display: block;
    margin-top: 0.06rem;
    font-size: 0.6875rem;
    font-weight: 600;
    color: #64748b;
}

.lux-att-summary__today-card {
    flex: 0 0 auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    min-width: 5rem;
    padding: 0.45rem 0.65rem;
    border: 0px solid rgba(16, 185, 129, 0.22);
    border-radius: 14px;
    background: rgba(16, 185, 129, 0.08);
}

.lux-att-summary__today-label {
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #059669;
}

.lux-att-summary__today-card strong {
    margin-top: 0.08rem;
    font-size: 1rem;
    font-weight: 800;
    color: #047857;
    line-height: 1.1;
}

.lux-att-summary__today-card > span:last-child {
    font-size: 0.6875rem;
    font-weight: 600;
    color: #64748b;
}

.lux-att-summary__metrics {
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 0.45rem;
}

.lux-att-summary__metric {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    min-width: 0;
    padding: 0.55rem 0.6rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.82);
}

.lux-att-summary__metric > i {
    flex-shrink: 0;
    width: 1.65rem;
    height: 1.65rem;
    display: grid;
    place-items: center;
    border-radius: 11px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary, #5b5ff4);
    font-size: 0.75rem;
}

.lux-att-summary__metric strong {
    display: block;
    font-size: 0.875rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.15;
}

.lux-att-summary__metric span {
    display: block;
    font-size: 0.6875rem;
    font-weight: 600;
    color: #64748b;
    line-height: 1.3;
}

.lux-att-summary__insights {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.55rem;
}

.lux-att-summary__insights--skeleton {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.55rem;
}

.lux-att-summary__insight {
    display: flex;
    flex-direction: column;
    gap: 0.55rem;
    min-width: 0;
    padding: 0.65rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.78);
}

.lux-att-summary__insight--wide {
    grid-column: 1 / -1;
}

.lux-att-summary__insight header {
    display: flex;
    align-items: flex-start;
    gap: 0.45rem;
}

.lux-att-summary__insight header > i {
    flex-shrink: 0;
    width: 1.75rem;
    height: 1.75rem;
    display: grid;
    place-items: center;
    border-radius: 12px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary, #5b5ff4);
    font-size: 0.8125rem;
}

.lux-att-summary__insight header strong {
    display: block;
    font-size: 0.6875rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.25;
}

.lux-att-summary__insight header span {
    display: block;
    margin-top: 0.06rem;
    font-size: 0.6875rem;
    font-weight: 600;
    color: #64748b;
    line-height: 1.35;
}

.lux-att-summary__bar {
    display: flex;
    height: 0.45rem;
    border-radius: 9911px;
    overflow: hidden;
    background: rgba(226, 232, 240, 0.95);
}

.lux-att-summary__bar--empty {
    display: grid;
    place-items: center;
    height: 2rem;
    font-size: 0.75rem;
    font-weight: 600;
    color: #94a3b8;
}

.lux-att-summary__bar-segment.is-green { background: #10b981; }
.lux-att-summary__bar-segment.is-red { background: #ef4444; }
.lux-att-summary__bar-segment.is-blue { background: #3b82f6; }
.lux-att-summary__bar-segment.is-amber { background: #f59e0b; }

.lux-att-summary__legend {
    display: flex;
    flex-direction: column;
    gap: 0.28rem;
    margin: 0;
    padding: 0;
    list-style: none;
}

.lux-att-summary__legend li {
    display: grid;
    grid-template-columns: auto 1fr auto auto;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.75rem;
}

.lux-att-summary__legend-dot {
    width: 0.45rem;
    height: 0.45rem;
    border-radius: 9911px;
}

.lux-att-summary__legend-dot.is-green { background: #10b981; }
.lux-att-summary__legend-dot.is-red { background: #ef4444; }
.lux-att-summary__legend-dot.is-blue { background: #3b82f6; }
.lux-att-summary__legend-dot.is-amber { background: #f59e0b; }

.lux-att-summary__legend-label {
    font-weight: 600;
    color: #64748b;
}

.lux-att-summary__legend li strong {
    font-weight: 800;
    color: #0f172a;
}

.lux-att-summary__legend-pct {
    font-weight: 700;
    color: #94a3b8;
    min-width: 2rem;
    text-align: right;
}

.lux-att-summary__daily-chart {
    width: 100%;
    overflow-x: auto;
    padding-bottom: 0.15rem;
    -webkit-overflow-scrolling: touch;
}

.lux-att-summary__daily-bars {
    display: flex;
    align-items: flex-end;
    gap: clamp(0.12rem, 0.35vw, 0.28rem);
    width: 100%;
    min-height: 5.5rem;
    padding: 0.15rem 0 0;
}

.lux-att-summary__daily-col {
    flex: 1 1 0;
    min-width: 1.15rem;
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 0.22rem;
}

.lux-att-summary__daily-bar-wrap {
    display: flex;
    align-items: flex-end;
    width: 100%;
    height: 4.5rem;
    border-radius: 6px 6px 2px 2px;
    background: rgba(248, 250, 252, 0.95);
    border: 0px solid rgba(226, 232, 240, 0.95);
}

.lux-att-summary__daily-bar {
    width: 100%;
    min-height: 0;
    border-radius: 5px 5px 2px 2px;
    background: linear-gradient(180deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
    transition: height 0.3s ease;
}

.lux-att-summary__daily-col.is-saturday .lux-att-summary__daily-bar-wrap {
    background: var(--lux-att-optional-sat-bg);
    border-color: var(--lux-att-optional-sat-border);
}

.lux-att-summary__daily-col.is-saturday .lux-att-summary__daily-bar {
    background: var(--lux-att-optional-sat-bar);
}

.lux-att-summary__daily-col.is-saturday .lux-att-summary__daily-label {
    color: var(--lux-att-optional-sat-text);
    font-weight: 800;
}

.lux-att-summary__daily-col.is-sunday .lux-att-summary__daily-bar-wrap {
    background: var(--lux-att-optional-sun-bg);
    border-color: var(--lux-att-optional-sun-border);
}

.lux-att-summary__daily-col.is-sunday .lux-att-summary__daily-bar {
    background: var(--lux-att-optional-sun-bar);
}

.lux-att-summary__daily-col.is-sunday .lux-att-summary__daily-label {
    color: var(--lux-att-optional-sun-text);
    font-weight: 800;
}

.lux-att-summary__daily-col.is-today .lux-att-summary__daily-bar-wrap {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
    box-shadow: 0 0 0 1px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.lux-att-summary__daily-label {
    font-size: clamp(0.6875rem, 0.55vw, 0.625rem);
    font-weight: 700;
    color: #94a3b8;
    text-align: center;
    line-height: 1.1;
}

.lux-att-summary__daily-col.is-today .lux-att-summary__daily-label {
    color: var(--lux-primary-dark, #3730a3);
    font-weight: 800;
}

.lux-att-summary__daily-col.is-future {
    opacity: 0.55;
    pointer-events: none;
}

.lux-att-summary__daily-col.is-future .lux-att-summary__daily-bar-wrap {
    background: repeating-linear-gradient(
        -45deg,
        rgba(248, 250, 252, 0.95),
        rgba(248, 250, 252, 0.95) 4px,
        rgba(226, 232, 240, 0.65) 4px,
        rgba(226, 232, 240, 0.65) 8px
    );
    border-color: rgba(203, 213, 225, 0.85);
    border-style: dashed;
}

.lux-att-summary__daily-col.is-future .lux-att-summary__daily-label {
    color: #cbd5e1;
    font-weight: 600;
}

.lux-att-summary__weekly-row.is-future {
    opacity: 0.5;
}

.lux-att-summary__weekly-row.is-future .lux-att-summary__weekly-fill {
    background: #e2e8f0;
}

.lux-att-summary__weekly-row.is-partial .lux-att-summary__weekly-copy span::after {
    content: " · partial";
    color: #94a3b8;
    font-weight: 600;
}

.lux-att-summary__weekly-list {
    display: flex;
    flex-direction: column;
    gap: 0.45rem;
}

.lux-att-summary__weekly-row {
    display: grid;
    grid-template-columns: minmax(5rem, 1fr) 1fr auto;
    align-items: center;
    gap: 0.45rem;
}

.lux-att-summary__weekly-copy strong {
    display: block;
    font-size: 0.75rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-att-summary__weekly-copy span {
    display: block;
    font-size: 0.625rem;
    font-weight: 600;
    color: #94a3b8;
}

.lux-att-summary__weekly-track {
    height: 0.4rem;
    border-radius: 9911px;
    background: rgba(226, 232, 240, 0.95);
    overflow: hidden;
}

.lux-att-summary__weekly-fill {
    height: 100%;
    border-radius: 9911px;
    background: linear-gradient(90deg, var(--lux-primary, #5b5ff4), #818cf8);
}

.lux-att-summary__weekly-rate {
    font-size: 0.75rem;
    font-weight: 800;
    color: var(--lux-primary-dark, #3730a3);
    min-width: 2.25rem;
    text-align: right;
}

.lux-att-summary__leaderboard {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
    margin: 0;
    padding: 0;
    list-style: none;
}

.lux-att-summary__leader {
    display: grid;
    grid-template-columns: auto 1fr auto;
    align-items: center;
    gap: 0.45rem;
    padding: 0.4rem 0.45rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.88);
}

.lux-att-summary__leader.is-you {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
}

.lux-att-summary__leader-rank {
    display: grid;
    place-items: center;
    width: 1.35rem;
    height: 1.35rem;
    border-radius: 8px;
    font-size: 0.6875rem;
    font-weight: 800;
    color: #fff;
    background: var(--lux-primary, #5b5ff4);
}

.lux-att-summary__leader.is-green .lux-att-summary__leader-rank {
    background: #059669;
}

.lux-att-summary__leader.is-amber .lux-att-summary__leader-rank {
    background: #d97706;
}

.lux-att-summary__leader-copy {
    min-width: 0;
}

.lux-att-summary__leader-copy strong {
    display: flex;
    align-items: center;
    gap: 0.28rem;
    font-size: 0.75rem;
    font-weight: 800;
    color: #0f172a;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-att-summary__leader-copy strong em {
    flex-shrink: 0;
    font-style: normal;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    padding: 0.06rem 0.28rem;
    border-radius: 9911px;
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.lux-att-summary__leader-copy span {
    display: block;
    font-size: 0.625rem;
    font-weight: 600;
    color: #94a3b8;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-att-summary__leader-stats {
    text-align: right;
}

.lux-att-summary__leader-stats strong {
    display: block;
    font-size: 0.6875rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-att-summary__leader-stats span {
    display: block;
    font-size: 0.625rem;
    font-weight: 600;
    color: #64748b;
}

.lux-att-summary__empty-note {
    margin: 0;
    font-size: 0.75rem;
    font-weight: 600;
    color: #94a3b8;
    line-height: 1.45;
}

@media (max-width: 1199px) {
    .lux-att-summary__insights,
    .lux-att-summary__insights--skeleton {
        grid-template-columns: 1fr 1fr;
    }

    .lux-att-summary__insight--wide {
        grid-column: 1 / -1;
    }

    .lux-att-summary__metrics {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}

@media (max-width: 767px) {
    .lux-att-summary__insights,
    .lux-att-summary__insights--skeleton {
        grid-template-columns: 1fr;
    }

    .lux-att-summary__metrics {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .lux-att-summary__hero {
        flex-direction: column;
        align-items: stretch;
    }
}

/* Current user panel */

.lux-att-you {
    position: relative;
    margin: 0 0.75rem 0.55rem;
    padding: 0.85rem;
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
    border-radius: 18px;
    background:
        radial-gradient(circle at 100% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12), transparent 50%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.96));
    box-shadow:
        0 0 0 1px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06),
        0 12px 32px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    overflow: visible;
}

.lux-att-you__glow {
    position: absolute;
    inset: 0 0 auto 0;
    height: 3px;
    background: linear-gradient(
        90deg,
        var(--lux-primary, #5b5ff4),
        rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35)
    );
    pointer-events: none;
}

.lux-att-you__head {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 0.65rem;
    margin-bottom: 0.65rem;
}

.lux-att-you__identity {
    display: flex;
    align-items: center;
    gap: 0.65rem;
    min-width: 0;
}

.lux-att-you__avatar-wrap {
    position: relative;
    flex-shrink: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    overflow: visible;
    padding-bottom: 0.85rem;
}

.lux-att-you__avatar {
    width: 3.25rem !important;
    height: 3.25rem !important;
    object-fit: cover;
    border: 2.5px solid #fff !important;
    border-radius: 9911px !important;
    box-shadow: 0 4px 16px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.2);
    padding: 0 !important;
}

.lux-att-you__badge {
    position: absolute;
    left: 50%;
    bottom: 0;
    transform: translateX(-50%);
    padding: 0.12rem 0.55rem;
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.2);
    border-radius: 9911px;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
    color: #fff;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    white-space: nowrap;
    z-index: 1;
    box-shadow: 0 2px 8px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.25);
}

.lux-att-you__name {
    margin: 0;
    font-size: 1rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-att-you__name a {
    color: inherit;
    text-decoration: none;
}

.lux-att-you__name a:hover {
    color: var(--lux-primary, #5b5ff4);
}

.lux-att-you__designation {
    margin: 0.12rem 0 0;
    font-size: 0.75rem;
    font-weight: 600;
    color: #64748b;
}

.lux-att-you__stats {
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
}

.lux-att-you__stat {
    display: flex;
    flex-direction: column;
    align-items: center;
    min-width: 4rem;
    padding: 0.4rem 0.55rem;
    border-radius: 12px;
    border: 0px solid rgba(226, 232, 240, 0.95);
    background: rgba(255, 255, 255, 0.88);
}

.lux-att-you__stat strong {
    font-size: 1rem;
    font-weight: 800;
    line-height: 1.1;
}

.lux-att-you__stat span {
    font-size: 0.625rem;
    font-weight: 700;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-att-you__stat.is-present strong { color: #059669; }
.lux-att-you__stat.is-absent strong { color: #dc2626; }
.lux-att-you__stat.is-rate strong { color: var(--lux-primary-dark, #3730a3); }

.lux-att-you__strip {
    display: flex;
    flex-wrap: nowrap;
    gap: 0.28rem;
    overflow-x: auto;
    padding: 0.35rem 0.1rem 0.15rem;
    -webkit-overflow-scrolling: touch;
}

.lux-att-you__day {
    flex: 0 0 auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.2rem;
    min-width: 1.85rem;
    padding: 0.28rem 0.15rem;
    border-radius: 12px;
    border: 0px solid transparent;
}

.lux-att-you__day.is-today {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
}

.lux-att-you__day.is-saturday:not(.is-today) {
    border-color: var(--lux-att-optional-sat-border);
    background: var(--lux-att-optional-sat-bg);
}

.lux-att-you__day.is-sunday:not(.is-today) {
    border-color: var(--lux-att-optional-sun-border);
    background: var(--lux-att-optional-sun-bg);
}

.lux-att-you__day.is-holiday:not(.is-today) {
    border-color: rgba(14, 165, 233, 0.35);
    background: rgba(14, 165, 233, 0.1);
}

.lux-att-you__day.is-holiday:not(.is-today) .lux-att-you__day-label {
    color: #0369a1;
}

.lux-att-you__day.is-saturday:not(.is-today) .lux-att-you__day-label {
    color: var(--lux-att-optional-sat-text);
}

.lux-att-you__day.is-sunday:not(.is-today) .lux-att-you__day-label {
    color: var(--lux-att-optional-sun-text);
}

.lux-att-you__day.is-saturday .lux-att-you__day-mark.is-absent {
    background: rgba(245, 158, 11, 0.14);
    color: #d97706;
}

.lux-att-you__day.is-sunday .lux-att-you__day-mark.is-absent {
    background: rgba(139, 92, 246, 0.12);
    color: #7c3aed;
}

.lux-att-you__day-label {
    font-size: 0.625rem;
    font-weight: 700;
    color: #94a3b8;
}

.lux-att-you__day.is-today .lux-att-you__day-label {
    color: var(--lux-primary-dark, #3730a3);
    font-weight: 800;
}

.lux-att-you__day-mark {
    display: grid;
    place-items: center;
    width: 1.35rem;
    height: 1.35rem;
    padding: 0;
    border: none;
    border-radius: 8px;
    font-size: 0.75rem;
    cursor: default;
}

.lux-att-you__day-mark.is-present {
    background: rgba(16, 185, 129, 0.14);
    color: #059669;
}

.lux-att-you__day-mark.is-absent {
    background: rgba(239, 68, 68, 0.08);
    color: #dc2626;
}

.lux-att-you__day-mark.is-future {
    display: inline-grid;
    place-items: center;
    width: 1.35rem;
    height: 1.35rem;
    border-radius: 8px;
    background: linear-gradient(145deg, rgba(186, 230, 253, 0.55), rgba(224, 242, 254, 0.95));
    border: 1px dashed rgba(14, 165, 233, 0.4);
    color: #0284c7;
    font-size: 0.62rem;
}

.lux-att-you__day.is-clickable .lux-att-you__day-mark {
    cursor: pointer;
    transition: transform 0.12s ease, box-shadow 0.12s ease;
}

.lux-att-you__day.is-clickable .lux-att-you__day-mark:hover {
    transform: scale(1.08);
    box-shadow: 0 2px 8px rgba(15, 23, 42, 0.1);
}

/* Matrix */

.lux-att-matrix {
    margin: 0 0.75rem 1rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 18px;
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.96));
    box-shadow: 0 12px 28px rgba(15, 23, 42, 0.06);
    overflow: hidden;
}

.lux-att-matrix__legend {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.55rem 0.85rem;
    padding: 0.55rem 0.85rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.9);
    background: rgba(248, 250, 252, 0.92);
}

.lux-att-matrix__legend-item {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    font-size: 0.6875rem;
    font-weight: 700;
    color: #64748b;
}

.lux-att-matrix__legend-item.is-present i { color: #059669; }
.lux-att-matrix__legend-item.is-pending i { color: #d97706; }
.lux-att-matrix__legend-item.is-rejected i { color: #be185d; }
.lux-att-matrix__legend-item.is-absent i { color: #dc2626; }

.lux-att-matrix__legend-dot {
    width: 0.625rem;
    height: 0.625rem;
    border-radius: 9911px;
    background: var(--lux-primary, #5b5ff4);
    box-shadow: 0 0 0 2px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.2);
}

.lux-att-matrix__legend-item.is-optional-sat,
.lux-att-matrix__legend-item.is-optional-sun {
    gap: 0.35rem;
}

.lux-att-matrix__legend-swatch {
    width: 0.65rem;
    height: 0.65rem;
    border-radius: 4px;
    flex-shrink: 0;
}

.lux-att-matrix__legend-swatch.is-sat {
    background: var(--lux-att-optional-sat-bg);
    border: 0px solid var(--lux-att-optional-sat-border);
}

.lux-att-matrix__legend-swatch.is-sun {
    background: var(--lux-att-optional-sun-bg);
    border: 0px solid var(--lux-att-optional-sun-border);
}

.lux-att-matrix__legend-item.is-future {
    color: #0369a1;
}

.lux-att-matrix__legend-item.is-future i {
    color: #0284c7;
}

.lux-att-matrix__scroll {
    overflow: auto;
    max-height: calc(100vh - 22rem);
    -webkit-overflow-scrolling: touch;
}

.lux-att-matrix__table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
    min-width: max-content;
}

.lux-att-matrix__table thead {
    position: sticky;
    top: 0;
    z-index: 4;
}

.lux-att-matrix__th-employee {
    position: sticky;
    left: 0;
    z-index: 5;
    min-width: 14rem;
    max-width: 18rem;
    padding: 0.45rem 0.65rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.95);
    border-right: 1px solid rgba(226, 232, 240, 0.95);
    background: rgba(248, 250, 252, 0.98);
    text-align: left;
    vertical-align: middle;
}

.lux-att-matrix__th-employee-inner {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 0.35rem;
}

.lux-att-matrix__th-employee-label {
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    color: #64748b;
}

/* Attendance employee filter (header + matrix) */
.lux-att-employee-filter {
    position: relative;
}

.lux-att-employee-filter.is-matrix {
    width: 100%;
}

.lux-att-employee-filter__trigger {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    width: 100%;
    min-height: 1.85rem;
    padding: 0.2rem 0.45rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.98);
    font-size: 0.6875rem;
    font-weight: 700;
    color: #334155;
    cursor: pointer;
    text-align: left;
}

.lux-att-employee-filter.is-header .lux-att-employee-filter__trigger {
    min-height: 2rem;
    min-width: 10.5rem;
    max-width: 14rem;
    padding: 0.25rem 0.55rem;
    font-size: 0.75rem;
}

.lux-att-employee-filter__trigger:hover,
.lux-att-employee-filter__trigger.is-open {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
    color: var(--lux-primary-dark, #3730a3);
}

.lux-att-employee-filter__trigger i.fe-filter {
    color: var(--lux-primary-dark, #3730a3);
    flex-shrink: 0;
}

.lux-att-employee-filter__label {
    flex: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-att-employee-filter__chevron {
    flex-shrink: 0;
    font-size: 0.75rem;
    opacity: 0.65;
}

.lux-att-employee-filter__panel {
    position: absolute;
    top: calc(100% + 0.3rem);
    left: 0;
    z-index: 30;
    width: min(18rem, 72vw);
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.98);
    box-shadow: 0 16px 40px rgba(15, 23, 42, 0.14);
    overflow: hidden;
}

.lux-att-employee-filter.is-header .lux-att-employee-filter__panel {
    z-index: 1200;
}

.lux-att-employee-filter__panel-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.5rem;
    padding: 0.55rem 0.65rem;
    border-bottom: 1px solid rgba(241, 245, 249, 0.98);
    background: rgba(248, 250, 252, 0.95);
}

.lux-att-employee-filter__panel-head strong {
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #475569;
}

.lux-att-employee-filter__panel-close {
    display: inline-grid;
    place-items: center;
    width: 1.6rem;
    height: 1.6rem;
    border: none;
    border-radius: 8px;
    background: transparent;
    color: #64748b;
    cursor: pointer;
}

.lux-att-employee-filter__search {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    margin: 0.5rem 0.55rem 0.35rem;
    padding: 0.3rem 0.45rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 10px;
    background: #fff;
}

.lux-att-employee-filter__search input {
    flex: 1;
    min-width: 0;
    border: none;
    outline: none;
    font-size: 0.75rem;
    font-weight: 600;
    color: #0f172a;
    background: transparent;
}

.lux-att-employee-filter__list {
    list-style: none;
    margin: 0;
    padding: 0.25rem 0.35rem 0.45rem;
    max-height: 14rem;
    overflow-y: auto;
}

.lux-att-employee-filter__option {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    width: 100%;
    padding: 0.4rem 0.45rem;
    border: none;
    border-radius: 10px;
    background: transparent;
    font-size: 0.75rem;
    font-weight: 700;
    color: #334155;
    text-align: left;
    cursor: pointer;
}

.lux-att-employee-filter__option em {
    margin-left: auto;
    font-style: normal;
    font-size: 0.625rem;
    font-weight: 600;
    color: #94a3b8;
    max-width: 42%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-att-employee-filter__option:hover {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
}

.lux-att-employee-filter__option.is-selected {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary-dark, #3730a3);
}

.lux-att-employee-filter__option.is-self span {
    font-weight: 800;
}

.lux-att-employee-filter__empty {
    padding: 0.55rem 0.65rem;
    font-size: 0.6875rem;
    font-weight: 600;
    color: #94a3b8;
}

.lux-attendance-empty--filter {
    margin-top: 0.75rem;
    padding: 1.25rem 1rem;
    border: 0px dashed rgba(226, 232, 240, 0.95);
    border-radius: 14px;
    text-align: center;
    background: rgba(248, 250, 252, 0.7);
}

.lux-attendance-empty--filter i {
    display: block;
    margin-bottom: 0.35rem;
    font-size: 1.25rem;
    color: #94a3b8;
}

.lux-att-matrix__th-day {
    min-width: 2.35rem;
    padding: 0.4rem 0.2rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.95);
    background: rgba(248, 250, 252, 0.98);
    text-align: center;
    vertical-align: middle;
}

.lux-att-matrix__th-day.is-weekend-sat {
    background: var(--lux-att-optional-sat-bg);
    box-shadow: inset 0 -2px 0 rgba(245, 158, 11, 0.55);
}

.lux-att-matrix__th-day.is-weekend-sun {
    background: var(--lux-att-optional-sun-bg);
    box-shadow: inset 0 -2px 0 rgba(139, 92, 246, 0.55);
}

.lux-att-matrix__th-day.is-weekend-sat .lux-att-matrix__day-num {
    color: var(--lux-att-optional-sat-text);
}

.lux-att-matrix__th-day.is-weekend-sun .lux-att-matrix__day-num {
    color: var(--lux-att-optional-sun-text);
}

.lux-att-matrix__th-day.is-weekend-sat .lux-att-matrix__day-label,
.lux-att-matrix__th-day.is-weekend-sun .lux-att-matrix__day-label {
    font-weight: 800;
}

.lux-att-matrix__day-optional {
    display: block;
    margin-top: 0.06rem;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    line-height: 1;
}

.lux-att-matrix__th-day.is-weekend-sat .lux-att-matrix__day-optional {
    color: var(--lux-att-optional-sat-text);
}

.lux-att-matrix__th-day.is-weekend-sun .lux-att-matrix__day-optional {
    color: var(--lux-att-optional-sun-text);
}

.lux-att-matrix__th-day.is-today {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    box-shadow: inset 0 -2px 0 var(--lux-primary, #5b5ff4);
}

.lux-att-matrix__th-day.is-future {
    opacity: 0.65;
}

.lux-att-matrix__day-num {
    display: block;
    font-size: 0.6875rem;
    font-weight: 800;
    color: #334155;
    line-height: 1.1;
}

.lux-att-matrix__day-label {
    display: block;
    font-size: 0.6875rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #94a3b8;
    line-height: 1.2;
}

.lux-att-matrix__th-day.is-today .lux-att-matrix__day-num {
    color: var(--lux-primary-dark, #3730a3);
}

/* Rows */

.lux-att-row__employee {
    position: sticky;
    left: 0;
    z-index: 2;
    min-width: 14rem;
    max-width: 16rem;
    padding: 0.45rem 0.65rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.85);
    border-right: 1px solid rgba(226, 232, 240, 0.95);
    background: rgba(255, 255, 255, 0.98);
    vertical-align: middle;
}

.lux-att-row.is-current-user .lux-att-row__employee {
    background: linear-gradient(
        90deg,
        rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1),
        rgba(255, 255, 255, 0.98) 55%
    );
    box-shadow: inset 3px 0 0 var(--lux-primary, #5b5ff4);
}

.lux-att-row.is-current-user {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.03);
}

.lux-att-row:hover .lux-att-row__employee {
    background: rgba(248, 250, 252, 0.98);
}

.lux-att-row.is-current-user:hover .lux-att-row__employee {
    background: linear-gradient(
        90deg,
        rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12),
        rgba(248, 250, 252, 0.98) 55%
    );
}

.lux-att-row__employee-inner {
    display: flex;
    align-items: center;
    gap: 0.625rem;
    min-width: 0;
}

.lux-att-row__avatar-wrap {
    position: relative;
    flex-shrink: 0;
}

.lux-att-row__avatar {
    width: 2.25rem !important;
    height: 2.25rem !important;
    object-fit: cover;
    border: 2px solid #fff !important;
    border-radius: 9911px !important;
    box-shadow: 0 2px 8px rgba(15, 23, 42, 0.1);
    padding: 0 !important;
}

.lux-att-row__you-badge {
    position: absolute;
    right: -0.25rem;
    bottom: -0.15rem;
    padding: 0.05rem 0.28rem;
    border: 0px solid #fff;
    border-radius: 9911px;
    background: var(--lux-primary, #5b5ff4);
    color: #fff;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.lux-att-row__copy {
    flex: 1;
    min-width: 0;
}

.lux-att-row__name {
    font-size: 0.6875rem;
    font-weight: 800;
    color: #0f172a;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-att-row__name a {
    color: inherit;
    text-decoration: none;
}

.lux-att-row__name a:hover {
    color: var(--lux-primary, #5b5ff4);
}

.lux-att-row__designation,
.lux-att-row__code {
    font-size: 0.625rem;
    font-weight: 600;
    color: #94a3b8;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-att-row__stats {
    flex-shrink: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    min-width: 2rem;
    padding: 0.2rem 0.35rem;
    border-radius: 8px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
}

.lux-att-row__stats strong {
    font-size: 0.75rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1;
}

.lux-att-row__stats span {
    font-size: 0.6875rem;
    font-weight: 700;
    color: var(--lux-primary-dark, #3730a3);
}

/* Day cells */

.lux-att-day {
    padding: 0.28rem 0.15rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.85);
    text-align: center;
    vertical-align: middle;
}

.lux-att-day.is-weekend-sat {
    background: var(--lux-att-optional-sat-bg);
    box-shadow: inset 0 0 0 1px rgba(245, 158, 11, 0.12);
}

.lux-att-day.is-weekend-sun {
    background: var(--lux-att-optional-sun-bg);
    box-shadow: inset 0 0 0 1px rgba(139, 92, 246, 0.12);
}

.lux-att-day.is-holiday {
    background: rgba(14, 165, 233, 0.08);
    box-shadow: inset 0 0 0 1px rgba(14, 165, 233, 0.16);
}

.lux-att-matrix__th-day.is-holiday {
    color: #0369a1;
}

.lux-att-day.is-weekend-sat .lux-att-day__btn.is-absent {
    background: rgba(245, 158, 11, 0.12);
    border-color: rgba(245, 158, 11, 0.22);
    color: #d97706;
}

.lux-att-day.is-weekend-sun .lux-att-day__btn.is-absent {
    background: rgba(139, 92, 246, 0.1);
    border-color: rgba(139, 92, 246, 0.22);
    color: #7c3aed;
}

.lux-att-day.is-today {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.07);
    box-shadow: inset 0 0 0 1px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.lux-att-day.is-future {
    background: linear-gradient(180deg, rgba(240, 249, 255, 0.7), rgba(248, 250, 252, 0.55));
}

.lux-att-row.is-current-user .lux-att-day.is-today {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14);
}

.lux-att-day__future {
    display: inline-grid;
    place-items: center;
    width: 1.65rem;
    height: 1.65rem;
    border-radius: 11px;
    background: linear-gradient(145deg, rgba(186, 230, 253, 0.55), rgba(224, 242, 254, 0.9));
    border: 1px dashed rgba(14, 165, 233, 0.38);
    color: #0284c7;
    font-size: 0.6875rem;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.65);
}

.lux-att-day__future.is-weekend {
    background: linear-gradient(145deg, rgba(226, 232, 240, 0.7), rgba(241, 245, 249, 0.95));
    border-color: rgba(148, 163, 184, 0.4);
    color: #64748b;
}

.lux-att-day__future.is-leave {
    background: rgba(99, 102, 241, 0.12);
    border-style: solid;
    border-color: rgba(99, 102, 241, 0.28);
    color: #4f46e5;
}

.lux-att-day__future.is-holiday {
    background: rgba(244, 63, 94, 0.1);
    border-style: solid;
    border-color: rgba(244, 63, 94, 0.28);
    color: #be123c;
}

.lux-att-day__btn {
    display: inline-grid;
    place-items: center;
    width: 1.65rem;
    height: 1.65rem;
    padding: 0;
    border: 0px solid transparent;
    border-radius: 11px;
    background: transparent;
    font-size: 0.6875rem;
    cursor: default;
    transition: transform 0.12s ease, box-shadow 0.12s ease, background 0.12s ease;
}

.lux-att-day__btn.is-present {
    background: rgba(16, 185, 129, 0.14);
    border-color: rgba(16, 185, 129, 0.22);
    color: #059669;
}

.lux-att-day__btn.is-leave,
.lux-att-you__day-mark.is-leave {
    background: rgba(99, 102, 241, 0.12);
    border-color: rgba(99, 102, 241, 0.22);
    color: #4f46e5;
}

.lux-att-day.is-leave {
    background: rgba(99, 102, 241, 0.04);
}

.lux-att-day__btn.is-absent {
    background: rgba(239, 68, 68, 0.06);
    border-color: rgba(239, 68, 68, 0.12);
    color: #dc2626;
}

@keyframes lux-att-pending-glow {
    0%,
    100% {
        border-color: rgba(217, 119, 6, 0.34);
        box-shadow: inset 0 0 0 1px rgba(245, 158, 11, 0.06), 0 0 0 0 rgba(245, 158, 11, 0);
    }

    50% {
        border-color: rgba(217, 119, 6, 0.62);
        box-shadow: inset 0 0 0 1px rgba(245, 158, 11, 0.14), 0 0 0 3px rgba(245, 158, 11, 0.12);
    }
}

@keyframes lux-att-pending-icon {
    0%,
    100% {
        opacity: 1;
        transform: scale(1);
    }

    50% {
        opacity: 0.55;
        transform: scale(0.92);
    }
}

@keyframes lux-att-pending-bg {
    0%,
    100% {
        background-color: rgba(245, 158, 11, 0.03);
    }

    50% {
        background-color: rgba(245, 158, 11, 0.08);
    }
}

.lux-att-day__btn.is-pending,
.lux-att-you__day-mark.is-pending {
    background: #fff;
    border: 2px dashed rgba(217, 119, 6, 0.45);
    color: #d97706;
    box-shadow: inset 0 0 0 1px rgba(245, 158, 11, 0.08);
    animation: lux-att-pending-glow 2.2s ease-in-out infinite;
}

.lux-att-day__btn.is-pending > i,
.lux-att-you__day-mark.is-pending > i {
    animation: lux-att-pending-icon 2.2s ease-in-out infinite;
}

.lux-att-day__btn.is-rejected,
.lux-att-you__day-mark.is-rejected {
    background: #fff;
    border: 2px solid rgba(190, 24, 93, 0.42);
    color: #be185d;
    box-shadow: inset 0 0 0 1px rgba(190, 24, 93, 0.06);
}

.lux-att-day__btn.is-pending-removal,
.lux-att-you__day-mark.is-pending-removal {
    background: #fff;
    border: 2px dashed rgba(79, 70, 229, 0.42);
    color: #4f46e5;
    box-shadow: inset 0 0 0 1px rgba(99, 102, 241, 0.08);
}

.lux-att-day.is-pending,
.lux-att-you__day.is-pending {
    background: rgba(245, 158, 11, 0.04);
    animation: lux-att-pending-bg 2.2s ease-in-out infinite;
}

.lux-att-day.is-pending-removal,
.lux-att-you__day.is-pending-removal {
    background: rgba(99, 102, 241, 0.04);
}

.lux-att-day.is-rejected,
.lux-att-you__day.is-rejected {
    background: rgba(190, 24, 93, 0.03);
}

.lux-att-pending {
    margin: 1rem 0 1.25rem;
    padding: 1rem 1.1rem;
    border-radius: 14px;
    border: 1px solid rgba(245, 158, 11, 0.2);
    background: linear-gradient(135deg, rgba(255, 251, 235, 0.95), rgba(254, 243, 199, 0.5));
}

.lux-att-pending--collapsed {
    padding: 0;
    border: none;
    background: transparent;
}

.lux-att-pending__collapsed-bar {
    display: flex;
    align-items: center;
    gap: 0.85rem;
    width: 100%;
    padding: 0.85rem 1rem;
    border-radius: 14px;
    border: 1px solid rgba(245, 158, 11, 0.28);
    background: linear-gradient(135deg, rgba(255, 251, 235, 0.98), rgba(254, 243, 199, 0.72));
    box-shadow: 0 8px 24px rgba(245, 158, 11, 0.12);
    cursor: pointer;
    text-align: left;
    transition: transform 0.12s ease, box-shadow 0.12s ease;
}

.lux-att-pending__collapsed-bar:hover {
    transform: translateY(-1px);
    box-shadow: 0 10px 28px rgba(245, 158, 11, 0.16);
}

.lux-att-pending__collapsed-icon {
    display: inline-grid;
    place-items: center;
    width: 2.25rem;
    height: 2.25rem;
    border-radius: 10px;
    background: rgba(245, 158, 11, 0.16);
    color: #d97706;
    flex-shrink: 0;
    animation: lux-att-pending-icon 2.2s ease-in-out infinite;
}

.lux-att-pending__collapsed-copy {
    display: grid;
    gap: 0.15rem;
    flex: 1;
    min-width: 0;
}

.lux-att-pending__collapsed-copy strong {
    color: #78350f;
    font-size: 0.875rem;
}

.lux-att-pending__collapsed-copy em {
    font-style: normal;
    font-size: 0.75rem;
    color: #92400e;
}

.lux-att-pending__collapsed-expand {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    font-size: 0.75rem;
    font-weight: 700;
    color: #b45309;
    flex-shrink: 0;
}

.lux-att-pending__head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 1rem;
    margin-bottom: 0.85rem;
}

.lux-att-pending__head-actions {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    flex-shrink: 0;
}

.lux-att-pending__toggle {
    display: inline-flex;
    align-items: center;
    width: auto;
    height: auto;
    min-width: 0;
    min-height: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    font-size: 0.75rem;
    font-weight: 800;
    color: #b45309;
    cursor: pointer;
    padding: 0.35rem 0.2rem;
}

.lux-att-pending__summary-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
    margin-top: 0.55rem;
}

.lux-att-pending__chip {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.2rem 0.55rem;
    border-radius: 999px;
    font-size: 0.6875rem;
    font-weight: 700;
}

.lux-att-pending__chip.is-approval {
    background: rgba(255, 255, 255, 0.72);
    border: 1px dashed rgba(217, 119, 6, 0.35);
    color: #d97706;
}

.lux-att-pending__chip.is-removal {
    background: rgba(255, 255, 255, 0.72);
    border: 1px dashed rgba(79, 70, 229, 0.32);
    color: #4f46e5;
}

.lux-att-pending__eyebrow {
    display: block;
    font-size: 0.6875rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #b45309;
}

.lux-att-pending__head h3 {
    margin: 0.15rem 0 0;
    font-size: 1rem;
    color: #78350f;
}

.lux-att-pending__head p {
    margin: 0.2rem 0 0;
    font-size: 0.8125rem;
    color: #92400e;
}

.lux-att-pending__count {
    min-width: 2rem;
    height: 2rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 999px;
    background: #f59e0b;
    color: #fff;
    font-size: 0.8125rem;
    font-weight: 700;
}

.lux-att-pending__list {
    display: grid;
    gap: 0.65rem;
}

.lux-att-pending__card {
    display: grid;
    gap: 0.65rem;
    padding: 0.75rem 0.85rem;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.72);
    border: 1px solid rgba(245, 158, 11, 0.16);
}

.lux-att-pending__card-main {
    display: grid;
    gap: 0.15rem;
}

.lux-att-pending__card-main strong {
    color: #1f2937;
    font-size: 0.875rem;
}

.lux-att-pending__card-main span,
.lux-att-pending__card-main em {
    font-size: 0.75rem;
    color: #6b7280;
    font-style: normal;
}

.lux-att-pending__dates {
    display: grid;
    gap: 0.35rem;
    margin: 0;
    padding: 0;
    list-style: none;
}

.lux-att-pending__date-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.65rem;
    padding: 0.45rem 0.55rem;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.55);
    border: 1px solid rgba(245, 158, 11, 0.12);
}

.lux-att-pending__date-row.is-pending {
    border-style: dashed;
    border-color: rgba(217, 119, 6, 0.28);
    background: rgba(255, 255, 255, 0.82);
    animation: lux-att-pending-glow 2.2s ease-in-out infinite;
}

.lux-att-pending__date-row.is-pending-removal {
    border-style: dashed;
    border-color: rgba(79, 70, 229, 0.28);
    background: rgba(255, 255, 255, 0.82);
}

.lux-att-pending__date-type {
    display: inline-grid;
    place-items: center;
    width: 1.5rem;
    height: 1.5rem;
    border-radius: 7px;
    flex-shrink: 0;
    font-size: 0.75rem;
}

.lux-att-pending__date-row.is-pending .lux-att-pending__date-type {
    color: #d97706;
    background: rgba(245, 158, 11, 0.1);
    animation: lux-att-pending-icon 2.2s ease-in-out infinite;
}

.lux-att-pending__date-row.is-pending-removal .lux-att-pending__date-type {
    color: #4f46e5;
    background: rgba(99, 102, 241, 0.1);
}

.lux-att-pending__date-summary {
    display: grid;
    gap: 0.2rem;
    flex: 1;
    min-width: 0;
    font-size: 0.75rem;
    color: #475569;
    line-height: 1.35;
}

.lux-att-pending__date-error {
    display: block;
    font-style: normal;
    font-size: 0.6875rem;
    font-weight: 600;
    color: #b91c1c;
}

.lux-att-pending__date-actions {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    flex-shrink: 0;
}

.lux-att-pending__date-view {
    border: 1px solid rgba(15, 23, 42, 0.1);
    background: #fff;
    color: #334155;
    border-radius: 7px;
    padding: 0.2rem 0.55rem;
    font-size: 0.6875rem;
    font-weight: 600;
}

.lux-att-pending__date-icon {
    display: inline-grid;
    place-items: center;
    width: 1.65rem;
    height: 1.65rem;
    border-radius: 8px;
    border: 1px solid transparent;
    padding: 0;
    font-size: 0.8125rem;
    cursor: pointer;
    transition: transform 0.12s ease, box-shadow 0.12s ease;
}

.lux-att-pending__date-icon:hover:not(:disabled) {
    transform: scale(1.06);
}

.lux-att-pending__date-icon.is-approve {
    background: rgba(16, 185, 129, 0.12);
    border-color: rgba(16, 185, 129, 0.22);
    color: #059669;
}

.lux-att-pending__date-icon.is-reject {
    background: rgba(239, 68, 68, 0.08);
    border-color: rgba(239, 68, 68, 0.18);
    color: #dc2626;
}

.lux-att-pending__date-icon:disabled {
    opacity: 0.55;
    cursor: not-allowed;
}

.lux-att-pending__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
    justify-self: end;
}

.lux-att-pending__btn {
    border: 1px solid rgba(15, 23, 42, 0.12);
    background: #fff;
    color: #334155;
    border-radius: 8px;
    padding: 0.35rem 0.7rem;
    font-size: 0.75rem;
    font-weight: 600;
}

.lux-att-pending__btn.is-primary {
    background: var(--lux-primary, #059669);
    border-color: transparent;
    color: #fff;
}

.lux-att-pending__btn.is-danger {
    background: rgba(239, 68, 68, 0.08);
    border-color: rgba(239, 68, 68, 0.2);
    color: #b91c1c;
}

.lux-att-mark-popover__intro.is-pending {
    background: rgba(255, 251, 235, 0.9);
    color: #92400e;
    border: 1px dashed rgba(217, 119, 6, 0.28);
    animation: lux-att-pending-glow 2.2s ease-in-out infinite;
}

@media (prefers-reduced-motion: reduce) {
    .lux-att-day__btn.is-pending,
    .lux-att-you__day-mark.is-pending,
    .lux-att-day__btn.is-pending > i,
    .lux-att-you__day-mark.is-pending > i,
    .lux-att-day.is-pending,
    .lux-att-you__day.is-pending,
    .lux-att-pending__date-row.is-pending,
    .lux-att-pending__date-row.is-pending .lux-att-pending__date-type,
    .lux-att-pending__collapsed-icon,
    .lux-att-mark-popover__intro.is-pending {
        animation: none;
    }
}

.lux-att-mark-popover__intro.is-rejected {
    background: rgba(190, 24, 93, 0.08);
    color: #9d174d;
    border: 1px solid rgba(190, 24, 93, 0.22);
}

.lux-att-mark-popover__intro.is-pending-removal {
    background: rgba(99, 102, 241, 0.08);
    color: #4338ca;
}

.lux-att-approval-comment {
    display: grid;
    gap: 0.35rem;
    margin-top: 0.85rem;
}

.lux-att-approval-comment span {
    font-size: 0.75rem;
    font-weight: 600;
    color: #475569;
}

.lux-att-approval-comment__input {
    width: 100%;
    border: 1px solid rgba(15, 23, 42, 0.12);
    border-radius: 10px;
    padding: 0.65rem 0.75rem;
    font-size: 0.8125rem;
    resize: vertical;
    min-height: 4.5rem;
    background: #fff;
}

.lux-att-approval-comment.has-error .lux-att-approval-comment__input {
    border-color: rgba(239, 68, 68, 0.55);
    box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.08);
}

.lux-att-approval-comment__error {
    font-size: 0.75rem;
    font-weight: 600;
    color: #b91c1c;
    line-height: 1.35;
}

.lux-att-pending__card .lux-att-approval-comment {
    margin-top: 0;
}

.lux-att-day.is-clickable .lux-att-day__btn {
    cursor: pointer;
}

.lux-att-day.is-clickable .lux-att-day__btn:hover {
    transform: scale(1.08);
    box-shadow: 0 2px 12px rgba(15, 23, 42, 0.1);
}

.lux-att-day__btn:disabled {
    cursor: default;
    opacity: 0.85;
}

/* Responsive (matrix) */

@media (max-width: 767px) {
    .lux-att-matrix__scroll {
        max-height: calc(100vh - 18rem);
    }
}

/* Dark mode */

body.lux-shell-dark .lux-attendance__month-pill {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.24);
    color: #c7d2fe;
}

body.lux-shell-dark .lux-att-summary,
body.lux-shell-dark .lux-att-you,
body.lux-shell-dark .lux-att-matrix,
body.lux-shell-dark .lux-attendance-empty {
    background: linear-gradient(180deg, rgba(15, 23, 42, 0.96), rgba(15, 23, 42, 0.9));
    border-color: rgba(51, 65, 85, 0.9);
}

body.lux-shell-dark .lux-att-summary__title,
body.lux-shell-dark .lux-att-summary__month,
body.lux-shell-dark .lux-att-you__name,
body.lux-shell-dark .lux-att-row__name,
body.lux-shell-dark .lux-att-summary__metric strong,
body.lux-shell-dark .lux-att-summary__insight header strong,
body.lux-shell-dark .lux-att-summary__leader-copy strong {
    color: #f1f5f9;
}

body.lux-shell-dark .lux-att-summary__subtitle,
body.lux-shell-dark .lux-att-summary__collapsed-line,
body.lux-shell-dark .lux-att-summary__insight header span {
    color: #94a3b8;
}

body.lux-shell-dark .lux-att-summary__toggle,
body.lux-shell-dark .lux-att-summary__metric,
body.lux-shell-dark .lux-att-summary__insight,
body.lux-shell-dark .lux-att-summary__hero-rate,
body.lux-shell-dark .lux-att-summary__leader,
body.lux-shell-dark .lux-att-you__stat,
body.lux-shell-dark .lux-att-matrix__legend {
    background: rgba(15, 23, 42, 0.55);
    border-color: rgba(51, 65, 85, 0.9);
}

body.lux-shell-dark .lux-att-summary__rate-ring::before {
    background: rgba(15, 23, 42, 0.95);
}

body.lux-shell-dark .lux-att-summary__rate-ring span {
    color: #c7d2fe;
}

body.lux-shell-dark .lux-att-summary__rate-copy strong {
    color: #e2e8f0;
}

body.lux-shell-dark .lux-att-summary:not(.is-collapsed) .lux-att-summary__header-bar {
    border-bottom-color: rgba(51, 65, 85, 0.9);
}

body.lux-shell-dark .lux-att-matrix__th-employee,
body.lux-shell-dark .lux-att-matrix__th-day,
body.lux-shell-dark .lux-att-row__employee {
    background: rgba(15, 23, 42, 0.92);
    border-color: rgba(51, 65, 85, 0.9);
}

body.lux-shell-dark .lux-att-row.is-current-user .lux-att-row__employee {
    background: linear-gradient(
        90deg,
        rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18),
        rgba(15, 23, 42, 0.92) 55%
    );
}

body.lux-shell-dark .lux-att-matrix__day-num {
    color: #e2e8f0;
}

body.lux-shell-dark .lux-attendance-empty span {
    color: #e2e8f0;
}

/* Mark attendance popover */
.lux-att-mark-popover__backdrop {
    position: fixed;
    inset: 0;
    z-index: 1200;
    border: none;
    background: rgba(15, 23, 42, 0.42);
    backdrop-filter: blur(2px);
    cursor: pointer;
}

.lux-att-mark-popover {
    position: fixed;
    z-index: 1201;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: min(92vw, 28rem);
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 18px;
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08), transparent 55%),
        rgba(255, 255, 255, 0.98);
    box-shadow: 0 24px 60px rgba(15, 23, 42, 0.18);
    overflow: hidden;
}

.lux-att-mark-popover__head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.75rem;
    padding: 0.85rem 1rem 0.75rem;
    border-bottom: 1px solid rgba(241, 245, 249, 0.98);
    background: rgba(248, 250, 252, 0.95);
}

.lux-att-mark-popover__eyebrow {
    display: block;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-att-mark-popover__head h2 {
    margin: 0.12rem 0 0;
    font-size: 1rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.2;
}

.lux-att-mark-popover__head p {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.35rem;
    margin: 0.2rem 0 0;
    font-size: 0.75rem;
    font-weight: 600;
    color: #64748b;
}

.lux-att-mark-popover__today,
.lux-att-mark-popover__optional {
    display: inline-flex;
    align-items: center;
    padding: 0.08rem 0.4rem;
    border-radius: 999px;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
}

.lux-att-mark-popover__today {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    color: var(--lux-primary-dark, #3730a3);
}

.lux-att-mark-popover__optional {
    background: rgba(245, 158, 11, 0.12);
    color: #b45309;
}

.lux-att-mark-popover__close {
    display: inline-grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.95);
    color: #64748b;
    cursor: pointer;
    flex-shrink: 0;
}

.lux-att-mark-popover__close:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    color: var(--lux-primary-dark, #3730a3);
}

.lux-att-mark-popover__body {
    padding: 0.85rem 1rem 1rem;
}

.lux-att-mark-popover__intro {
    display: flex;
    align-items: flex-start;
    gap: 0.45rem;
    margin-bottom: 0.75rem;
    padding: 0.55rem 0.65rem;
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14);
    border-radius: 12px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.05);
    font-size: 0.6875rem;
    font-weight: 600;
    color: #475569;
    line-height: 1.45;
}

.lux-att-mark-popover__intro i {
    margin-top: 0.1rem;
    color: var(--lux-primary-dark, #3730a3);
}

.lux-att-mark-popover__intro.is-present {
    border-color: rgba(16, 185, 129, 0.22);
    background: rgba(16, 185, 129, 0.06);
}

.lux-att-mark-popover__intro.is-present i {
    color: #059669;
}

.lux-att-mark-popover__value {
    display: flex;
    align-items: center;
    width: 100%;
    min-height: 2.2rem;
    padding: 0.35rem 0.55rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 10px;
    background: rgba(248, 250, 252, 0.98);
    font-size: 0.875rem;
    font-weight: 700;
    color: #0f172a;
}

.lux-att-mark-popover__field.is-highlight .lux-att-mark-popover__value {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
    background: linear-gradient(180deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.04), rgba(248, 250, 252, 0.98));
}

.lux-att-mark-popover__btn.is-danger {
    border-color: rgba(239, 68, 68, 0.28);
    background: rgba(254, 242, 242, 0.98);
    color: #dc2626;
}

.lux-att-mark-popover__btn.is-danger:hover:not(:disabled) {
    border-color: rgba(239, 68, 68, 0.45);
    background: rgba(254, 226, 226, 0.98);
    color: #b91c1c;
}

.lux-att-mark-popover__grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.55rem;
}

.lux-att-mark-popover__field {
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
    margin: 0;
}

.lux-att-mark-popover__field.is-wide {
    grid-column: 1 / -1;
}

.lux-att-mark-popover__field > span {
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-att-mark-popover__field.is-highlight > span {
    color: #475569;
}

.lux-att-mark-popover__input {
    width: 100%;
    min-height: 2.2rem;
    padding: 0.35rem 0.55rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.98);
    font-size: 0.875rem;
    font-weight: 700;
    color: #0f172a;
}

.lux-att-mark-popover__field.is-highlight .lux-att-mark-popover__input {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
    background: linear-gradient(180deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.04), rgba(255, 255, 255, 0.98));
}

.lux-att-mark-popover__input:focus {
    outline: none;
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.45);
    box-shadow: 0 0 0 3px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.lux-att-mark-popover__field em {
    font-style: normal;
    font-size: 0.625rem;
    font-weight: 600;
    color: #64748b;
}

.lux-att-mark-popover__foot {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 0.45rem;
    margin-top: 0.85rem;
    padding-top: 0.75rem;
    border-top: 1px solid rgba(241, 245, 249, 0.98);
}

.lux-att-mark-popover__btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.3rem;
    min-height: 2rem;
    padding: 0 0.85rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.95);
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    color: #64748b;
    cursor: pointer;
}

.lux-att-mark-popover__btn.is-primary {
    border: none;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
    color: #fff;
    box-shadow: 0 8px 20px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.25);
}

.lux-att-mark-popover__btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

body.lux-shell-dark .lux-att-mark-popover {
    background: linear-gradient(180deg, rgba(15, 23, 42, 0.98), rgba(15, 23, 42, 0.94));
