/* ========== luxury-invoice.css ========== */

/* ========== Invoice page — luxury UI ========== */

.lux-invoice {
    padding-bottom: 1rem;
}

/* Empty state */

.lux-invoice-empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 0.35rem;
    margin: 1.5rem 0.75rem;
    padding: 2.5rem 1rem;
    border: 0px dashed rgba(226, 232, 240, 0.95);
    border-radius: 18px;
    background: rgba(248, 250, 252, 0.8);
    text-align: center;
}

.lux-invoice-empty img {
    max-width: 8rem;
    opacity: 0.85;
    margin-bottom: 0.625rem;
}

.lux-invoice-empty span {
    font-size: 0.9375rem;
    font-weight: 800;
    color: #334155;
}

.lux-invoice-empty p {
    margin: 0;
    font-size: 0.6875rem;
    color: #64748b;
    max-width: 22rem;
}

.lux-invoice-empty__create-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    margin-top: 0.65rem;
    min-height: 2.125rem;
    padding: 0 0.85rem;
    border: none;
    border-radius: 9911px;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
    font-size: 0.6875rem;
    font-weight: 800;
    color: #fff;
    cursor: pointer;
    box-shadow: 0 8px 20px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    transition: transform 0.14s ease, box-shadow 0.14s ease;
}

.lux-invoice-empty__create-btn:hover {
    transform: translateY(-1px);
    box-shadow: 0 12px 24px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.34);
}

/* Summary dashboard */

.lux-inv-summary {
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 18px;
    background:
        radial-gradient(circle at 100% 0%, rgba(16, 185, 129, 0.06), transparent 42%),
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.07), transparent 45%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.96));
    box-shadow: 0 8px 24px rgba(15, 23, 42, 0.06);
}

.lux-inv-summary.is-collapsed {
    padding-bottom: 0.65rem;
}

.lux-inv-summary__header-bar {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.55rem;
    margin-bottom: 0.55rem;
}

.lux-inv-summary:not(.is-collapsed) .lux-inv-summary__header-bar {
    padding-bottom: 0.55rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.9);
}

.lux-inv-summary__header-main {
    min-width: 0;
}

/* Eyebrow — see luxury-summary-shared.css (.lux-summary-eyebrow) */

.lux-inv-summary__title {
    margin: 0;
    font-size: 1.0625rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.25;
}

.lux-inv-summary__title-amount {
    display: inline-block;
    margin-left: 0.45rem;
    padding: 0.12rem 0.45rem;
    border-radius: 9911px;
    background: rgba(16, 185, 129, 0.1);
    font-size: 0.75rem;
    font-weight: 800;
    color: #047857;
    vertical-align: middle;
}

.lux-inv-summary__body {
    display: flex;
    flex-direction: column;
    gap: 0.65rem;
}

.lux-inv-summary__hero {
    display: grid;
    grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr);
    gap: 0.65rem;
}

.lux-inv-summary__hero-main {
    padding: 0.75rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.88);
}

.lux-inv-summary__hero-label {
    display: block;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-inv-summary__hero-value {
    margin-top: 0.2rem;
    font-size: 1.75rem;
    font-weight: 900;
    line-height: 1.1;
    color: #0f172a;
    letter-spacing: -0.02em;
}

.lux-inv-summary__hero-sub {
    display: block;
    margin-top: 0.15rem;
    font-size: 0.75rem;
    font-weight: 700;
    color: #64748b;
}

.lux-inv-summary__hero-masked {
    font-size: 1.25rem;
    color: #94a3b8;
}

.lux-inv-summary__hero-stats {
    display: flex;
    flex-wrap: wrap;
    gap: 0.55rem;
    margin-top: 0.55rem;
    padding-top: 0.55rem;
    border-top: 1px solid rgba(226, 232, 240, 0.9);
}

.lux-inv-summary__hero-stats span {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    font-size: 0.75rem;
    font-weight: 700;
    color: #475569;
}

.lux-inv-summary__hero-stats i {
    color: var(--lux-primary, #5b5ff4);
}

.lux-inv-summary__hero-cards {
    display: grid;
    grid-template-rows: 1fr 1fr;
    gap: 0.45rem;
}

.lux-inv-summary__flow-card {
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 0.08rem;
    padding: 0.65rem 0.75rem;
    border-radius: 14px;
    border: 0px solid rgba(226, 232, 240, 0.95);
}

.lux-inv-summary__flow-card span {
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-inv-summary__flow-card strong {
    font-size: 1.0625rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-inv-summary__flow-card small {
    font-size: 0.6875rem;
    font-weight: 700;
    color: #64748b;
}

.lux-inv-summary__flow-card.is-outstanding {
    background: linear-gradient(135deg, rgba(251, 191, 36, 0.12), rgba(255, 255, 255, 0.95));
    border-color: rgba(245, 158, 11, 0.22);
}

.lux-inv-summary__flow-card.is-collected {
    background: linear-gradient(135deg, rgba(16, 185, 129, 0.12), rgba(255, 255, 255, 0.95));
    border-color: rgba(16, 185, 129, 0.22);
}

.lux-inv-summary__metrics {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.45rem;
}

.lux-inv-summary__metric {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.55rem 0.65rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.88);
}

.lux-inv-summary__metric-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 1.75rem;
    height: 1.75rem;
    border-radius: 12px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary, #5b5ff4);
    flex-shrink: 0;
}

.lux-inv-summary__metric.is-blue .lux-inv-summary__metric-icon {
    background: rgba(59, 130, 246, 0.12);
    color: #2563eb;
}

.lux-inv-summary__metric.is-amber .lux-inv-summary__metric-icon {
    background: rgba(245, 158, 11, 0.12);
    color: #d97706;
}

.lux-inv-summary__metric.is-green .lux-inv-summary__metric-icon {
    background: rgba(16, 185, 129, 0.12);
    color: #059669;
}

.lux-inv-summary__metric.is-violet .lux-inv-summary__metric-icon {
    background: rgba(139, 92, 246, 0.12);
    color: #7c3aed;
}

.lux-inv-summary__metric-label {
    display: block;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-inv-summary__metric-value {
    display: block;
    font-size: 0.9375rem;
    font-weight: 900;
    color: #0f172a;
    line-height: 1.2;
}

.lux-inv-summary__panels {
    display: grid;
    grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
    gap: 0.55rem;
    align-items: stretch;
}

.lux-inv-summary__panels-main {
    display: flex;
    flex-direction: column;
    gap: 0.55rem;
    min-width: 0;
}

.lux-inv-summary__panel {
    padding: 0.65rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.88);
}

.lux-inv-summary__panel-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.45rem;
    margin-bottom: 0.45rem;
}

.lux-inv-summary__panel-head h3 {
    margin: 0;
    font-size: 0.6875rem;
    font-weight: 800;
    color: #334155;
}

.lux-inv-summary__bar {
    display: flex;
    height: 0.55rem;
    border-radius: 9911px;
    overflow: hidden;
    background: #e2e8f0;
}

.lux-inv-summary__bar--empty {
