.lux-inv-summary__list-fy-toggle {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    margin: 0;
    font-size: 0.75rem;
    font-weight: 700;
    color: #475569;
    cursor: pointer;
}

.lux-inv-summary__list-fy-toggle input {
    accent-color: var(--lux-primary, #5b5ff4);
}

.lux-inv-summary__panel--monthly {
