    display: flex;
    flex-direction: column;
    gap: 0.15rem;
}

.lux-invoice-load-more__meta span {
    font-size: 0.6875rem;
    color: #475569;
}

.lux-invoice-load-more__meta strong {
    color: #0f172a;
}

.lux-invoice-load-more__hint {
    font-size: 0.6875rem !important;
    color: #94a3b8 !important;
}

.lux-invoice-load-more__btn {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    min-height: 2.125rem;
    padding: 0 0.95rem;
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.24);
    border-radius: 9911px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
    font-size: 0.6875rem;
    font-weight: 800;
    color: var(--lux-primary-dark, #3730a3);
    cursor: pointer;
    transition: all 0.14s ease;
}

.lux-invoice-load-more__btn:hover:not(:disabled) {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14);
    transform: translateY(-1px);
}

.lux-invoice-load-more__btn:disabled {
    opacity: 0.7;
    cursor: wait;
}

.lux-invoice-load-more__done {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    font-size: 0.75rem;
    font-weight: 800;
    color: #059669;
}

.lux-invoice-load-more__spin {
    animation: lux-invoice-spin 0.8s linear infinite;
}

@keyframes lux-invoice-spin {
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
}

.lux-invoice-empty__create-btn--secondary {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary-dark, #3730a3);
    box-shadow: none;
}

.lux-invoice-empty__create-btn--secondary:hover {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16);
    box-shadow: none;
}

/* Outstanding / pending invoices panel */

.lux-inv-outstanding {
    margin-top: 0.15rem;
    padding: 0.85rem;
    border: 0px solid rgba(59, 130, 246, 0.18);
    border-radius: 16px;
    background:
        radial-gradient(circle at 0% 0%, rgba(59, 130, 246, 0.08), transparent 42%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.96));
    box-shadow: 0 6px 18px rgba(15, 23, 42, 0.05);
}

.lux-inv-outstanding__head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.55rem;
    margin-bottom: 0.65rem;
    padding-bottom: 0.55rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.95);
}

.lux-inv-outstanding__eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    margin-bottom: 0.15rem;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #2563eb;
}

.lux-inv-outstanding__head h3 {
    margin: 0;
    font-size: 0.9375rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-inv-outstanding__head p {
    margin: 0.15rem 0 0;
    font-size: 0.75rem;
    color: #64748b;
}

.lux-inv-outstanding__head-btn {
    flex-shrink: 0;
    min-height: 1.75rem;
    padding: 0 0.65rem;
    border: 0px solid rgba(37, 99, 235, 0.24);
    border-radius: 9911px;
    background: rgba(37, 99, 235, 0.08);
    font-size: 0.6875rem;
    font-weight: 800;
    color: #1d4ed8;
    cursor: pointer;
    transition: background 0.14s ease;
}

.lux-inv-outstanding__head-btn:hover {
    background: rgba(37, 99, 235, 0.14);
}

.lux-inv-outstanding__summary {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.45rem;
    margin-bottom: 0.65rem;
}

.lux-inv-outstanding__pill {
    display: flex;
    flex-direction: column;
    gap: 0.05rem;
    padding: 0.625rem 0.6rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.9);
}

.lux-inv-outstanding__pill span {
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-inv-outstanding__pill strong {
    font-size: 1rem;
    font-weight: 900;
    color: #0f172a;
    line-height: 1.1;
}

.lux-inv-outstanding__pill em {
    font-style: normal;
    font-size: 0.75rem;
    font-weight: 800;
    color: #047857;
}

.lux-inv-outstanding__pill.is-blue {
    border-color: rgba(37, 99, 235, 0.2);
    background: rgba(37, 99, 235, 0.06);
}

.lux-inv-outstanding__pill.is-amber {
    border-color: rgba(217, 119, 6, 0.2);
    background: rgba(217, 119, 6, 0.06);
}

.lux-inv-outstanding__subsection {
    margin-bottom: 0.55rem;
}

.lux-inv-outstanding__subsection h4 {
    margin: 0 0 0.4rem;
    font-size: 0.6875rem;
    font-weight: 800;
    color: #334155;
}

.lux-inv-outstanding__subsection.is-empty p {
    margin: 0;
    padding: 0.65rem;
    border: 0px dashed #e2e8f0;
    border-radius: 12px;
    font-size: 0.75rem;
    color: #94a3b8;
    text-align: center;
}

.lux-inv-outstanding__rows {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

.lux-inv-outstanding__row {
    display: grid;
    grid-template-columns: minmax(0, 1.4fr) minmax(0, 1.2fr) auto;
    gap: 0.55rem;
    align-items: center;
    padding: 0.65rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.94);
    transition: border-color 0.14s ease, box-shadow 0.14s ease;
}

.lux-inv-outstanding__row.is-highlight,
.lux-inv-outstanding__row.is-pending {
    border-color: rgba(37, 99, 235, 0.22);
    background: linear-gradient(180deg, rgba(239, 246, 255, 0.95), rgba(255, 255, 255, 0.96));
}

.lux-inv-outstanding__row:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
    box-shadow: 0 6px 16px rgba(15, 23, 42, 0.06);
}

.lux-inv-outstanding__row-top {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 0.35rem;
    margin-bottom: 0.12rem;
}

.lux-inv-outstanding__number {
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-inv-outstanding__status {
    display: inline-flex;
    align-items: center;
    min-height: 1.2rem;
    padding: 0 0.38rem;
    border-radius: 9911px;
    font-size: 0.625rem;
    font-weight: 800;
    text-transform: uppercase;
}

.lux-inv-outstanding__status.is-blue { background: rgba(37, 99, 235, 0.12); color: #1d4ed8; }
.lux-inv-outstanding__status.is-slate { background: rgba(100, 116, 139, 0.12); color: #475569; }
.lux-inv-outstanding__status.is-amber { background: rgba(217, 119, 6, 0.12); color: #b45309; }

.lux-inv-outstanding__title {
    display: inline-flex;
    align-items: center;
    gap: 0.22rem;
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
    text-decoration: none;
}

.lux-inv-outstanding__title:hover {
    color: var(--lux-primary-dark, #3730a3);
}

.lux-inv-outstanding__description {
    margin: 0.12rem 0 0;
    font-size: 0.75rem;
    color: #64748b;
    line-height: 1.4;
}

.lux-inv-outstanding__row-facts {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.35rem 0.55rem;
}

.lux-inv-outstanding__row-facts span {
    display: block;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-inv-outstanding__row-facts strong {
    display: block;
    font-size: 0.6875rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-inv-outstanding__amount {
    color: #047857 !important;
}

.lux-inv-outstanding__row-action {
    display: flex;
    flex-direction: column;
    gap: 0.28rem;
    align-items: stretch;
}

.lux-inv-outstanding__view-btn,
.lux-inv-outstanding__filter-btn {
    min-height: 1.75rem;
    padding: 0 0.65rem;
    border-radius: 9911px;
    font-size: 0.6875rem;
    font-weight: 800;
    text-align: center;
    text-decoration: none;
    cursor: pointer;
    transition: background 0.14s ease;
}

.lux-inv-outstanding__view-btn {
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.24);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
    color: var(--lux-primary-dark, #3730a3);
}

.lux-inv-outstanding__filter-btn {
    border: 0px solid #e2e8f0;
    background: rgba(255, 255, 255, 0.95);
    color: #64748b;
}

.lux-inv-outstanding__view-btn:hover {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14);
}

.lux-inv-outstanding__filter-btn:hover {
    border-color: rgba(37, 99, 235, 0.24);
    color: #1d4ed8;
}

.lux-inv-outstanding__secondary {
    display: flex;
    flex-direction: column;
    gap: 0.45rem;
    padding-top: 0.15rem;
    border-top: 1px dashed rgba(226, 232, 240, 0.95);
}

.lux-inv-outstanding__all-clear {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.35rem;
    padding: 0.75rem;
    border-radius: 12px;
    background: rgba(16, 185, 129, 0.08);
    font-size: 0.6875rem;
    font-weight: 800;
    color: #047857;
}

.lux-inv-outstanding__all-clear i {
    font-size: 0.875rem;
}

/* Collections aging */

.lux-invoice > .lux-inv-aging {
    margin: 0.55rem 0.75rem 0.75rem;
}

.lux-inv-aging {
    margin-top: 0.55rem;
    padding: 0.85rem;
    border: 0 solid rgba(244, 63, 94, 0.14);
    border-radius: 16px;
    background:
        radial-gradient(circle at 100% 0%, rgba(244, 63, 94, 0.07), transparent 46%),
        radial-gradient(circle at 0% 100%, rgba(245, 158, 11, 0.06), transparent 42%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(255, 251, 247, 0.96));
    box-shadow: 0 6px 18px rgba(15, 23, 42, 0.05);
}

.lux-inv-aging.has-filter {
    box-shadow:
        0 0 0 1px rgba(244, 63, 94, 0.18),
        0 6px 18px rgba(15, 23, 42, 0.05);
}

.lux-inv-aging.is-error {
    background: linear-gradient(180deg, #fff, #fff7ed);
}

.lux-inv-aging__head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.55rem;
    margin-bottom: 0.65rem;
    padding-bottom: 0.55rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.95);
}

.lux-inv-aging__eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    margin-bottom: 0.15rem;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #e11d48;
}

.lux-inv-aging__head h3 {
    margin: 0;
    font-size: 0.9375rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-inv-aging__head p {
    margin: 0.15rem 0 0;
    font-size: 0.75rem;
    color: #64748b;
}

.lux-inv-aging__head-btn {
    flex-shrink: 0;
    min-height: 1.75rem;
    padding: 0 0.65rem;
    border: 0 solid rgba(225, 29, 72, 0.22);
    border-radius: 999px;
    background: rgba(225, 29, 72, 0.08);
    font-size: 0.6875rem;
    font-weight: 800;
    color: #be123c;
    cursor: pointer;
}

.lux-inv-aging__head-btn:hover {
    background: rgba(225, 29, 72, 0.14);
}

.lux-inv-aging__hero {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.45rem;
    margin-bottom: 0.55rem;
}

.lux-inv-aging__hero-card {
    display: flex;
    flex-direction: column;
    gap: 0.1rem;
    padding: 0.625rem 0.65rem;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.92);
    border: 0 solid rgba(226, 232, 240, 0.95);
}

.lux-inv-aging__hero-card span {
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-inv-aging__hero-card strong {
    font-size: 1.05rem;
    font-weight: 900;
    color: #0f172a;
    line-height: 1.15;
}

.lux-inv-aging__hero-card small {
    font-size: 0.6875rem;
    font-weight: 700;
    color: #94a3b8;
}

.lux-inv-aging__hero-card.is-open {
    background: rgba(16, 185, 129, 0.07);
}

.lux-inv-aging__hero-card.is-overdue {
    background: rgba(245, 158, 11, 0.08);
}

.lux-inv-aging__hero-card.is-critical {
    background: rgba(244, 63, 94, 0.08);
}

.lux-inv-aging__stack {
    display: flex;
    width: 100%;
    height: 0.5rem;
    margin-bottom: 0.55rem;
    overflow: hidden;
    border-radius: 999px;
    background: #f1f5f9;
}

.lux-inv-aging__stack-seg {
    min-width: 0;
    height: 100%;
    padding: 0;
    border: 0;
    cursor: pointer;
    transition: filter 0.14s ease, opacity 0.14s ease;
}

.lux-inv-aging__stack-seg.is-green { background: #10b981; }
.lux-inv-aging__stack-seg.is-blue { background: #3b82f6; }
.lux-inv-aging__stack-seg.is-amber { background: #f59e0b; }
.lux-inv-aging__stack-seg.is-orange { background: #f97316; }
.lux-inv-aging__stack-seg.is-rose { background: #f43f5e; }

.lux-inv-aging__stack-seg:hover,
.lux-inv-aging__stack-seg.is-active {
    filter: brightness(1.05);
}

.lux-inv-aging__buckets {
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 0.4rem;
}

.lux-inv-aging__bucket {
    display: flex;
    flex-direction: column;
    gap: 0.08rem;
    align-items: flex-start;
    min-height: 5.25rem;
    padding: 0.55rem 0.5rem;
    border: 0 solid rgba(226, 232, 240, 0.95);
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.95);
    text-align: left;
    cursor: pointer;
    transition: transform 0.12s ease, box-shadow 0.12s ease, background 0.12s ease;
}

.lux-inv-aging__bucket:hover:not(:disabled) {
    transform: translateY(-1px);
    box-shadow: 0 6px 14px rgba(15, 23, 42, 0.06);
}

.lux-inv-aging__bucket:disabled {
    opacity: 0.55;
    cursor: default;
}

.lux-inv-aging__bucket.is-active {
    box-shadow: 0 0 0 1px rgba(225, 29, 72, 0.28), 0 6px 14px rgba(15, 23, 42, 0.06);
}

.lux-inv-aging__bucket.is-green { background: rgba(16, 185, 129, 0.07); }
.lux-inv-aging__bucket.is-blue { background: rgba(59, 130, 246, 0.07); }
.lux-inv-aging__bucket.is-amber { background: rgba(245, 158, 11, 0.08); }
.lux-inv-aging__bucket.is-orange { background: rgba(249, 115, 22, 0.08); }
.lux-inv-aging__bucket.is-rose { background: rgba(244, 63, 94, 0.08); }

.lux-inv-aging__bucket-label {
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-inv-aging__bucket-count {
    font-size: 1.05rem;
    font-weight: 900;
    color: #0f172a;
    line-height: 1.1;
}

.lux-inv-aging__bucket-amount {
    font-style: normal;
    font-size: 0.75rem;
    font-weight: 800;
    color: #047857;
}

.lux-inv-aging__bucket-share {
    margin-top: auto;
    font-size: 0.625rem;
    font-weight: 800;
    color: #94a3b8;
}

.lux-inv-aging__hint {
    display: flex;
    align-items: center;
    gap: 0.3rem;
    margin: 0.55rem 0 0;
    font-size: 0.6875rem;
    font-weight: 700;
    color: #64748b;
}

.lux-inv-aging__hint i {
    color: #e11d48;
}

.lux-inv-aging__all-clear {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.35rem;
    padding: 0.85rem;
    border-radius: 12px;
    background: rgba(16, 185, 129, 0.08);
    font-size: 0.75rem;
    font-weight: 800;
    color: #047857;
}

@media (max-width: 900px) {
    .lux-inv-aging__buckets {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .lux-inv-aging__hero {
        grid-template-columns: 1fr;
    }
}

/* Invoice list */

.lux-inv-list {
    --lux-inv-list-cols: minmax(16rem, 2.2fr) minmax(7rem, 0.95fr) minmax(4rem, 0.55fr) minmax(7rem, 0.85fr) minmax(7rem, 0.85fr) 2.75rem;
    margin: 0 0.75rem;
}

.lux-inv-list__head,
.lux-inv-list__item {
    display: grid;
    grid-template-columns: var(--lux-inv-list-cols);
    align-items: center;
    gap: 0.55rem;
}

.lux-inv-list__head {
    position: sticky;
    top: calc(var(--lux-page-header-height, 0.25rem));
    z-index: 2;
    padding: 0.35rem 0.65rem;
    margin-bottom: 0.35rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 12px;
    background: rgba(248, 250, 252, 0.96);
    backdrop-filter: blur(8px);
}

.lux-inv-list__head-cell {
    min-width: 0;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-inv-list__head-cell.is-center {
    text-align: center;
}

.lux-inv-list__head-label {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
}

.lux-inv-list__head-label i {
    font-size: 0.75rem;
    color: var(--lux-primary, #5b5ff4);
}

.lux-inv-list__body {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

.lux-inv-list__item {
    position: relative;
    padding: 0.65rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 16px;
    background: rgba(255, 255, 255, 0.96);
    box-shadow: 0 4px 14px rgba(15, 23, 42, 0.04);
    transition: border-color 0.14s ease, box-shadow 0.14s ease, transform 0.14s ease;
}

.lux-inv-list__item::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0.65rem;
    bottom: 0.65rem;
    width: 3px;
    border-radius: 0 4px 4px 0;
    background: linear-gradient(180deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
    opacity: 0.55;
}

.lux-inv-list__item.is-status-blue::before {
    background: linear-gradient(180deg, #60a5fa, #2563eb);
}

.lux-inv-list__item.is-status-amber::before {
    background: linear-gradient(180deg, #fbbf24, #d97706);
}

.lux-inv-list__item.is-status-green::before {
    background: linear-gradient(180deg, #34d399, #059669);
}

.lux-inv-list__item.is-status-violet::before {
    background: linear-gradient(180deg, #c4b5fd, #7c3aed);
}

.lux-inv-list__item.is-status-slate::before {
    background: linear-gradient(180deg, #94a3b8, #64748b);
}

.lux-inv-list__item:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
    box-shadow: 0 8px 22px rgba(15, 23, 42, 0.07);
    transform: translateY(-1px);
}

.lux-inv-list__item.is-menu-open {
    z-index: 3;
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    box-shadow: 0 12px 28px rgba(15, 23, 42, 0.1);
}

.lux-inv-list__item.is-skeleton {
    pointer-events: none;
    cursor: default;
    transform: none;
}

.lux-inv-list__item.is-skeleton::before {
    display: none;
}

.lux-inv-list__item.is-skeleton:hover {
    transform: none;
}

.lux-inv-list__col {
    min-width: 0;
}

.lux-inv-list__col.is-center {
    text-align: center;
}

.lux-inv-list__col--actions {
    position: relative;
}

.lux-inv-list__col--invoice {
    display: flex;
    align-items: flex-start;
    gap: 0.55rem;
}

.lux-inv-list__invoice-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 2.25rem;
    height: 2.25rem;
    border-radius: 12px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary, #5b5ff4);
    flex-shrink: 0;
}

.lux-inv-list__invoice-copy {
    min-width: 0;
}

.lux-inv-list__invoice-top {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 0.35rem;
    margin-bottom: 0.12rem;
}

.lux-inv-list__number {
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-inv-list__status-pill {
    display: inline-flex;
    align-items: center;
    min-height: 1.25rem;
