    height: 2rem;
    border: 0px solid #e2e8f0;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.95);
    color: #64748b;
    cursor: pointer;
    transition: all 0.14s ease;
}

.lux-inv-list__menu-btn:hover,
.lux-inv-list__item.is-menu-open .lux-inv-list__menu-btn {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.24);
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
}

.lux-inv-list__menu {
    position: absolute;
    top: calc(100% + 0.25rem);
    right: 0;
    z-index: 10;
    min-width: 10.625rem;
    padding: 0.35rem;
    border: 0px solid rgba(226, 232, 240, 0.98);
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.98);
    box-shadow: 0 12px 32px rgba(15, 23, 42, 0.12);
}

.lux-inv-list__menu-item {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    width: 100%;
    min-height: 2rem;
    padding: 0 0.55rem;
    border: none;
    border-radius: 8px;
    background: transparent;
    font-size: 0.6875rem;
    font-weight: 700;
    color: #334155;
    text-decoration: none;
    cursor: pointer;
    transition: background 0.12s ease, color 0.12s ease;
}

.lux-inv-list__menu-item i {
    width: 0.875rem;
    text-align: center;
    color: #64748b;
}

.lux-inv-list__menu-item:hover {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
    color: var(--lux-primary-dark, #3730a3);
}

.lux-inv-list__menu-item.is-danger {
    color: #dc2626;
}

.lux-inv-list__menu-item.is-danger:hover {
    background: rgba(220, 38, 38, 0.08);
    color: #b91c1c;
}

.lux-inv-list__menu-item.is-confirm {
    background: rgba(220, 38, 38, 0.1);
    font-weight: 800;
}

/* Responsive */

@media (max-width: 1100px) {
    .lux-inv-summary__hero,
    .lux-inv-summary__panels {
        grid-template-columns: 1fr;
    }

    .lux-inv-summary__panel--monthly {
        order: -1;
    }

    .lux-inv-summary__metrics {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .lux-inv-list {
        --lux-inv-list-cols: 1fr;
    }

    .lux-inv-list__head {
        display: none;
    }

    .lux-inv-list__item {
        grid-template-columns: 1fr;
        gap: 0.45rem;
    }

    .lux-inv-list__col--actions {
        position: absolute;
        top: 0.65rem;
        right: 0.65rem;
    }

    .lux-inv-list__col--invoice {
        padding-right: 2.5rem;
    }
}

@media (max-width: 640px) {
    .lux-inv-summary__metrics {
        grid-template-columns: 1fr;
    }

    .lux-inv-summary__legend {
        grid-template-columns: 1fr;
    }

    .lux-inv-summary__monthly-grid {
        grid-template-columns: repeat(6, minmax(0, 1fr));
        min-height: 6.5rem;
    }

    .lux-inv-summary__monthly-cell-bar {
        height: 3.5rem;
    }

    .lux-inv-summary__monthly-kpis {
        grid-template-columns: 1fr;
    }

    .lux-inv-outstanding__summary {
        grid-template-columns: 1fr;
    }

    .lux-inv-outstanding__row {
        grid-template-columns: 1fr;
    }

    .lux-inv-outstanding__row-action {
        flex-direction: row;
    }
}

/* ========== luxury-invoice-details.css ========== */

/* ========== Invoice details — luxury full-page document UI ========== */

.lux-inv-detail {
    width: 100%;
    max-width: none;
    margin: 0;
    padding: 0;
}

.lux-inv-detail--fullpage {
    box-sizing: border-box;
    min-height: auto;
    overflow: visible;
    padding: 0.75rem;
    padding-bottom: calc(1.25rem + 4.5rem);
    background: #f8fafc;
}

.lux-inv-detail-page .lux-inv-page-hero {
    margin: 0 0 0.65rem;
    padding: 1rem var(--lux-page-gutter-x, 1.25rem) 0.35rem;
}

.lux-inv-detail-page .lux-inv-page-quick-nav {
    margin: 0 var(--lux-page-gutter-x, 1.25rem) 0.85rem;
}

.lux-po-detail-page.lux-bid-detail-page {
    padding-bottom: var(--lux-page-block-bottom, 1.5rem);
}

/* Unlock fixed-height shell so the full invoice document can scroll */
body.lux-inv-detail-page-open {
    overflow-y: auto !important;
}

body.lux-inv-detail-page-open #main_content {
    min-height: 100vh;
    height: auto;
    justify-content: flex-start;
    overflow: visible;
}

body.lux-inv-detail-page-open .page.h-100vh,
.page:has(.lux-inv-detail--fullpage) {
    height: auto !important;
    min-height: 0;
    max-height: none !important;
    overflow: visible !important;
    flex: 0 0 auto;
}

body.lux-inv-detail-page-open .page.h-100vh > .vleft,
.page:has(.lux-inv-detail--fullpage) > .vleft {
    flex: 1 0 auto;
    min-height: auto;
    overflow: visible;
}

body.lux-inv-detail-page-open .page.h-100vh > .vright,
.page:has(.lux-inv-detail--fullpage) > .vright {
    flex: 0 0 auto;
}

