}

.lux-inv-detail__summary-card.is-primary {
    grid-column: 1 / -1;
    border-color: rgba(5, 150, 105, 0.22);
    background: linear-gradient(135deg, rgba(16, 185, 129, 0.12), rgba(255, 255, 255, 0.96));
}

.lux-inv-detail__summary-card.is-primary strong {
    font-size: 1.375rem;
    color: #047857;
}

.lux-inv-detail__summary-card.is-status.is-blue {
    border-color: rgba(37, 99, 235, 0.2);
    background: rgba(37, 99, 235, 0.06);
}

.lux-inv-detail__summary-card.is-status.is-amber {
    border-color: rgba(217, 119, 6, 0.2);
    background: rgba(217, 119, 6, 0.06);
}

.lux-inv-detail__summary-card.is-status.is-green {
    border-color: rgba(5, 150, 105, 0.2);
    background: rgba(5, 150, 105, 0.06);
}

.lux-inv-detail__summary-card.is-status.is-violet {
    border-color: rgba(124, 58, 237, 0.2);
    background: rgba(124, 58, 237, 0.06);
}

.lux-inv-detail__summary-card.is-status.is-slate {
    border-color: rgba(100, 116, 139, 0.2);
    background: rgba(100, 116, 139, 0.06);
}

/* Line items */

.lux-inv-detail__items {
    margin: 0 1.75rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 16px;
    overflow: hidden;
    background: rgba(255, 255, 255, 0.98);
    box-shadow: 0 8px 24px rgba(15, 23, 42, 0.04);
}

.lux-inv-detail__items-head,
.lux-inv-detail__item-row {
    display: grid;
    grid-template-columns: minmax(0, 2fr) minmax(5rem, 0.75fr) minmax(3.5rem, 0.45fr) minmax(6rem, 0.75fr);
    gap: 0.55rem;
    align-items: center;
}

.lux-inv-detail__items-head {
    padding: 0.55rem 0.85rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.95);
    background: rgba(248, 250, 252, 0.96);
}

.lux-inv-detail__items-head span {
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-inv-detail__items-head span:not(:first-child),
.lux-inv-detail__item-row > div:not(:first-child) {
    text-align: center;
}

.lux-inv-detail__item-row {
    padding: 0.65rem 0.85rem;
    border-bottom: 1px solid rgba(241, 245, 249, 0.98);
    font-size: 0.75rem;
    font-weight: 700;
    color: #334155;
}

.lux-inv-detail__item-row:last-child {
    border-bottom: none;
}

.lux-inv-detail__item-row:nth-child(even) {
    background: rgba(248, 250, 252, 0.72);
}

.lux-inv-detail__item-desc strong {
    display: block;
    font-size: 0.8125rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-inv-detail__item-desc p {
    margin: 0.18rem 0 0;
    font-size: 0.6875rem;
    font-weight: 600;
    line-height: 1.45;
    color: #64748b;
}

.lux-inv-detail__item-total {
    font-size: 0.8125rem !important;
    font-weight: 900 !important;
    color: #047857 !important;
}

/* Settlement */

.lux-inv-detail__settlement {
    display: grid;
    grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
    gap: 0.85rem;
    padding: 0.85rem 1.75rem 1rem;
}

.lux-inv-detail__payment h3,
.lux-inv-detail__terms h3 {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    margin: 0 0 0.45rem;
    font-size: 0.8125rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-inv-detail__payment h3 i {
    color: var(--lux-primary, #5b5ff4);
}

.lux-inv-detail__payment-method {
    margin: 0 0 0.65rem;
    font-size: 0.75rem;
    font-weight: 800;
    color: #334155;
}

.lux-inv-detail__tax-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.35rem;
    margin-bottom: 0.55rem;
}

.lux-inv-detail__tax-grid span {
    display: block;
    font-size: 0.5rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-inv-detail__tax-grid strong {
    display: block;
    font-size: 0.6875rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-inv-detail__bank-card {
    padding: 0.75rem;
    border: 1px solid rgba(226, 232, 240, 0.95);
    border-radius: 14px;
    background: linear-gradient(180deg, rgba(248, 250, 252, 0.96), rgba(255, 255, 255, 0.98));
}

.lux-inv-detail__bank-label {
    display: block;
    margin-bottom: 0.15rem;
    font-size: 0.5625rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-inv-detail__bank-card strong {
    display: block;
    font-size: 0.8125rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-inv-detail__bank-card p {
    margin: 0.12rem 0 0;
    font-size: 0.6875rem;
    font-weight: 600;
    line-height: 1.45;
    color: #475569;
}


.lux-inv-detail__config-hint {
    margin: 0.35rem 0 0;
    font-size: 0.6875rem;
    font-weight: 600;
    color: #64748b;
}

.lux-inv-detail__config-hint code {
    font-size: 0.625rem;
}

.lux-inv-detail__totals-rows {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
    margin-bottom: 0.55rem;
}

.lux-inv-detail__totals-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.55rem;
    padding: 0.35rem 0;
    border-bottom: 1px dashed rgba(226, 232, 240, 0.95);
    font-size: 0.75rem;
    color: #475569;
}

.lux-inv-detail__totals-row strong {
    font-size: 0.8125rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-inv-detail__totals-row.is-discount strong {
    color: #dc2626;
}

.lux-inv-detail__totals-due {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.55rem;
    padding: 0.75rem 0.85rem;
    border-radius: 14px;
    background: linear-gradient(135deg, #059669, #047857);
    color: #fff;
}

.lux-inv-detail__totals-due span {
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.lux-inv-detail__totals-due strong {
    font-size: 1.25rem;
    font-weight: 900;
}

.lux-inv-detail__signature {
    margin-top: 0.65rem;
    text-align: center;
}

.lux-inv-detail__signature img {
    width: 5.5rem;
    max-width: 40%;
    margin-bottom: 0.35rem;
}

.lux-inv-detail__signature p {
    margin: 0;
    font-size: 0.75rem;
    font-weight: 700;
    color: #334155;
}

.lux-inv-detail__signature strong {
    font-size: 0.6875rem;
    font-weight: 800;
    color: #64748b;
}

.lux-inv-detail__terms {
    padding: 0 1.75rem 1rem;
}

.lux-inv-detail__terms p {
    margin: 0;
    padding: 0.65rem 0.75rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.88);
    font-size: 0.6875rem;
    line-height: 1.5;
    color: #475569;
}

.lux-inv-detail__footer {
    display: grid;
    grid-template-columns: minmax(0, 1.2fr) repeat(3, minmax(0, 0.8fr));
    gap: 0.55rem;
    align-items: center;
    padding: 0.75rem 1.75rem 1rem;
    border-top: 1px solid rgba(226, 232, 240, 0.95);
    background: linear-gradient(180deg, #f8fafc, #f1f5f9);
}

.lux-inv-detail__footer img {
    width: 3rem;
    height: auto;
}

.lux-inv-detail__footer div {
    display: flex;
    flex-direction: column;
    gap: 0.08rem;
    padding-left: 0.55rem;
    border-left: 1px solid rgba(226, 232, 240, 0.95);
}

.lux-inv-detail__footer span {
    font-size: 0.75rem;
    font-weight: 600;
    line-height: 1.35;
    color: #64748b;
}

/* Billed employees modal */

body.lux-inv-emp-modal-open {
    overflow: hidden;
}

.lux-inv-emp-modal {
    position: fixed;
    inset: 0;
    z-index: 1200;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 1rem;
}

.lux-inv-emp-modal__backdrop {
    position: absolute;
    inset: 0;
    border: none;
    background: rgba(15, 23, 42, 0.52);
    backdrop-filter: blur(6px);
    cursor: pointer;
}

.lux-inv-emp-modal__dialog {
    position: relative;
    z-index: 1;
    display: flex;
    flex-direction: column;
    width: min(640px, 100%);
    max-height: min(82vh, 720px);
    border: 0px solid rgba(226, 232, 240, 0.98);
    border-radius: 20px;
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08), transparent 42%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.98));
    box-shadow: 0 24px 64px rgba(15, 23, 42, 0.22);
    overflow: hidden;
}

.lux-inv-emp-modal__header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.65rem;
    padding: 1rem 1rem 0.75rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.95);
}

.lux-inv-emp-modal__header-main {
    display: flex;
    align-items: flex-start;
    gap: 0.65rem;
    min-width: 0;
}

.lux-inv-emp-modal__icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 14px;
    background: linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16), rgba(16, 185, 129, 0.14));
    color: var(--lux-primary, #5b5ff4);
    flex-shrink: 0;
}

.lux-inv-emp-modal__eyebrow {
    display: block;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-inv-emp-modal__header h2 {
    margin: 0.08rem 0 0;
    font-size: 1rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-inv-emp-modal__header p {
    margin: 0.15rem 0 0;
    font-size: 0.75rem;
    font-weight: 700;
    color: #64748b;
}

.lux-inv-emp-modal__close {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border: 0px solid #e2e8f0;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.95);
    color: #64748b;
    cursor: pointer;
    flex-shrink: 0;
    transition: all 0.14s ease;
}

.lux-inv-emp-modal__close:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.24);
    color: var(--lux-primary-dark, #3730a3);
}

.lux-inv-emp-modal__search-wrap {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.65rem 1rem;
}

.lux-inv-emp-modal__search {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    flex: 1;
    min-height: 2.25rem;
    padding: 0 0.65rem;
    border: 0px solid #e2e8f0;
    border-radius: 9911px;
    background: rgba(255, 255, 255, 0.96);
}

.lux-inv-emp-modal__search i {
    color: #94a3b8;
    flex-shrink: 0;
}

.lux-inv-emp-modal__search input {
    flex: 1;
    min-width: 0;
    border: none;
    background: transparent;
    font-size: 0.6875rem;
    font-weight: 600;
    color: #0f172a;
    outline: none;
}

.lux-inv-emp-modal__search-clear {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.25rem;
    height: 1.25rem;
    border: none;
    border-radius: 9911px;
    background: rgba(148, 163, 184, 0.16);
    color: #64748b;
    cursor: pointer;
}

.lux-inv-emp-modal__count-pill {
    flex-shrink: 0;
    min-height: 2rem;
    padding: 0 0.55rem;
    border-radius: 9911px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    font-size: 0.6875rem;
    font-weight: 800;
    color: var(--lux-primary-dark, #3730a3);
    display: inline-flex;
    align-items: center;
}

.lux-inv-emp-modal__list {
    flex: 1;
    overflow: auto;
    padding: 0 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
}

.lux-inv-emp-modal__row {
    display: grid;
    grid-template-columns: auto 1fr auto;
    gap: 0.55rem;
    align-items: center;
    padding: 0.6rem 0.65rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.94);
    transition: border-color 0.14s ease, box-shadow 0.14s ease;
}

.lux-inv-emp-modal__row:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
    box-shadow: 0 4px 14px rgba(15, 23, 42, 0.05);
}

.lux-inv-emp-modal__avatar {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.125rem;
    height: 2.125rem;
    border-radius: 12px;
    background: linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14), rgba(16, 185, 129, 0.12));
    font-size: 0.6875rem;
    font-weight: 900;
    color: var(--lux-primary-dark, #3730a3);
}

.lux-inv-emp-modal__row-copy strong {
    display: block;
    font-size: 0.75rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-inv-emp-modal__row-copy a {
    display: block;
    margin-top: 0.05rem;
    font-size: 0.75rem;
    font-weight: 700;
    color: var(--lux-primary-dark, #3730a3);
    text-decoration: none;
}

.lux-inv-emp-modal__row-copy a:hover {
    text-decoration: underline;
}

.lux-inv-emp-modal__row-index {
    font-size: 0.6875rem;
    font-weight: 800;
    color: #94a3b8;
}

.lux-inv-emp-modal__empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.35rem;
    padding: 2rem 1rem;
    text-align: center;
    color: #94a3b8;
    font-size: 0.6875rem;
    font-weight: 700;
}

.lux-inv-emp-modal__empty i {
    font-size: 1.25rem;
}

.lux-inv-emp-modal__footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.55rem;
    padding: 0.75rem 1rem;
    border-top: 1px solid rgba(226, 232, 240, 0.95);
    background: rgba(248, 250, 252, 0.96);
}

.lux-inv-emp-modal__footer span {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    font-size: 0.6875rem;
    font-weight: 700;
    color: #64748b;
}

.lux-inv-emp-modal__done-btn {
    min-height: 2rem;
    padding: 0 0.85rem;
    border: none;
    border-radius: 9911px;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
    font-size: 0.6875rem;
    font-weight: 800;
    color: #fff;
    cursor: pointer;
    box-shadow: 0 6px 16px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
}

/* Responsive */

@media (max-width: 900px) {
    .lux-inv-detail__brand-contacts {
        gap: 0.28rem;
    }

    .lux-inv-detail__hero,
    .lux-inv-detail__settlement,
    .lux-inv-detail__footer {
        grid-template-columns: 1fr;
    }

    .lux-inv-detail__summary-title {
        text-align: left;
    }

    .lux-inv-detail__tax-grid {
        grid-template-columns: 1fr;
    }

    .lux-inv-detail__items-head {
        display: none;
    }

    .lux-inv-detail__item-row {
        grid-template-columns: 1fr;
        gap: 0.35rem;
    }

    .lux-inv-detail__item-row > div:not(:first-child) {
        text-align: left;
    }

    .lux-inv-detail__footer div {
        border-left: none;
        padding-left: 0;
    }
}

@media (max-width: 640px) {
    .lux-inv-detail__toolbar-inner {
        flex-direction: column;
        align-items: stretch;
        padding: 0.7rem 0.9rem 0.8rem;
    }

    .lux-inv-detail__toolbar-actions {
        justify-content: flex-start;
        flex-wrap: wrap;
        width: 100%;
    }

    .lux-inv-detail__toolbar-identity {
        align-items: flex-start;
    }
}

    .lux-inv-detail__summary-grid {
        grid-template-columns: 1fr;
    }

    .lux-inv-detail__hero,
    .lux-inv-detail__settlement,
    .lux-inv-detail__items {
        padding-left: 1rem;
        padding-right: 1rem;
        margin-left: 0;
        margin-right: 0;
    }

    .lux-inv-detail__brand {
        padding-left: 1rem;
        padding-right: 1rem;
    }

    .lux-inv-detail__terms,
    .lux-inv-detail__footer {
        padding-left: 1rem;
        padding-right: 1rem;
    }

    .lux-inv-emp-modal {
        padding: 0.625rem;
    }

    .lux-inv-emp-modal__footer {
        flex-direction: column;
        align-items: stretch;
    }
}

/* Print — match on-screen invoice document layout */

@media print {
    @page {
        size: A4 portrait;
        margin: 10mm 12mm;
    }

    /* Hide application chrome */
    .no-print,
    .theme_div,
    .user_div,
    .right_sidebar,
    .bottonrighthelpmenu,
    .lux-assist-dock,
    .lux-assist-dock__backdrop,
    .react-notification-container,
    .NotificationContainer,
    .alert,
    .custom-alert-bar,
    .lux-page-alert,
    .lux-connection-error-shell,
    .page-footer-modern,
    .vright,
    .lux-inv-emp-modal,
    #header_top,
    #left-sidebar,
    #page_top {
        display: none !important;
    }

    html,
    body.lux-inv-detail-page-open,
    body:has(.lux-inv-detail__sheet) {
        background: #fff !important;
        height: auto !important;
        min-height: 0 !important;
        max-height: none !important;
        overflow: visible !important;
        margin: 0 !important;
        padding: 0 !important;
    }

    body.lux-inv-detail-page-open #main_content,
    body:has(.lux-inv-detail__sheet) #main_content {
        display: block !important;
        justify-content: flex-start !important;
        background: #fff !important;
        height: auto !important;
        overflow: visible !important;
    }

    body.lux-inv-detail-page-open .page,
    body.lux-inv-detail-page-open .page.h-100vh,
    body.lux-inv-detail-page-open .vleft,
    body:has(.lux-inv-detail__sheet) .page,
    body:has(.lux-inv-detail__sheet) .page.h-100vh,
    body:has(.lux-inv-detail__sheet) .vleft {
        display: block !important;
        position: static !important;
        left: 0 !important;
        right: auto !important;
        top: auto !important;
        width: 100% !important;
        max-width: 100% !important;
        height: auto !important;
        min-height: 0 !important;
        max-height: none !important;
        margin: 0 !important;
        padding: 0 !important;
        overflow: visible !important;
        flex: none !important;
        transform: none !important;
    }

    .lux-inv-detail,
    .lux-inv-detail--fullpage {
        display: block !important;
        width: 100% !important;
        max-width: 100% !important;
        margin: 0 !important;
        padding: 0 !important;
        background: #fff !important;
        overflow: visible !important;
    }

    .lux-inv-detail__sheet {
        display: block !important;
        width: 100% !important;
        max-width: 100% !important;
        margin: 0 !important;
        padding: 0 !important;
        border: none !important;
        border-radius: 0 !important;
        box-shadow: none !important;
        background: #fff !important;
        overflow: visible !important;
        min-height: auto !important;
    }

    .lux-inv-detail__sheet-body {
        padding: 0 0 0.35rem !important;
    }

    .lux-inv-detail__accent {
        display: block !important;
        height: 0.28rem !important;
        background: linear-gradient(
            90deg,
            var(--lux-primary, #5b5ff4) 0%,
            #059669 50%,
            #7c3aed 100%
        ) !important;
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }

    /* Force desktop layout — print often triggers max-width breakpoints */
        .lux-inv-detail__brand {
        padding: 1rem 1.75rem 0.85rem !important;
        background:
            radial-gradient(ellipse at 15% 0%, rgba(167, 139, 250, 0.28), transparent 52%),
            radial-gradient(ellipse at 85% 100%, rgba(16, 185, 129, 0.2), transparent 48%),
            linear-gradient(125deg, #0b1220 0%, #162032 45%, #1e1b4b 100%) !important;
        color: #f8fafc !important;
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
        break-inside: avoid;
        page-break-inside: avoid;
    }

    .lux-inv-detail__supplier-name {
        color: #ffffff !important;
    }

    .lux-inv-detail__hero {
        display: grid !important;
        grid-template-columns: minmax(0, 1.1fr) minmax(0, 0.9fr) !important;
        gap: 0.85rem !important;
        padding: 1rem 1.75rem 0.85rem !important;
        break-inside: avoid;
        page-break-inside: avoid;
    }

    .lux-inv-detail__summary-title {
        text-align: right !important;
    }

    .lux-inv-detail__summary-grid {
        display: grid !important;
        grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
