/* ========== luxury-mobile-app.css ========== */

/* ========== Mobile app registration — luxury panel ========== */

.lux-mobile-app {
    --lux-mobile-radius: 16px;
    color: #0f172a;
}

/* —— Hero —— */
.lux-mobile-app__hero {
    display: flex;
    align-items: flex-start;
    gap: 14px;
    margin-bottom: 1rem;
    padding-bottom: 0.875rem;
    border-bottom: 1px solid rgba(148, 163, 184, 0.22);
}

.lux-mobile-app__hero-icon {
    flex-shrink: 0;
    width: 48px;
    height: 48px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 14px;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-accent, #14b8a6));
    color: #fff;
    font-size: 1.25rem;
    box-shadow: 0 8px 20px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.26);
}

.lux-mobile-app__kicker {
    margin: 0 0 4px;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-mobile-app__title {
    margin: 0 0 6px;
    font-size: 1.25rem;
    font-weight: 800;
    letter-spacing: -0.03em;
    color: #0f172a;
    line-height: 1.2;
}

.lux-mobile-app__subtitle {
    margin: 0;
    font-size: 0.8125rem;
    line-height: 1.5;
    color: #64748b;
    max-width: 40rem;
}

/* —— Split: download | separator | register —— */
.lux-mobile-app__split {
    display: grid;
    grid-template-columns: minmax(0, 1.05fr) auto minmax(0, 0.95fr);
    gap: 0;
    align-items: stretch;
    margin-bottom: 0.875rem;
}

.lux-mobile-app__divider {
    width: 1px;
    margin: 0 1rem;
    background: linear-gradient(
        180deg,
        transparent 0%,
        rgba(148, 163, 184, 0.35) 12%,
        rgba(var(--lux-primary-rgb, 91, 95, 244), 0.25) 50%,
        rgba(148, 163, 184, 0.35) 88%,
        transparent 100%
    );
    flex-shrink: 0;
}

.lux-mobile-app__zone {
    min-width: 0;
    padding: 0.875rem 1rem;
    border-radius: var(--lux-mobile-radius);
    border: 0px solid rgba(148, 163, 184, 0.22);
    background: #fff;
    box-shadow: 0 6px 20px rgba(15, 23, 42, 0.04);
}

.lux-mobile-app__zone--download {
    background:
        linear-gradient(180deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.04) 0%, #fff 38%),
        #fff;
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14);
}

.lux-mobile-app__zone--register {
    background:
        linear-gradient(180deg, rgba(20, 184, 166, 0.05) 0%, #fff 38%),
        #fff;
    border-color: rgba(20, 184, 166, 0.16);
}

.lux-mobile-app__zone-head {
    margin-bottom: 0.75rem;
}

.lux-mobile-app__zone-title {
    margin: 0 0 0.25rem;
    font-size: 0.9375rem;
    font-weight: 700;
    color: #0f172a;
    line-height: 1.3;
}

.lux-mobile-app__zone-desc {
    margin: 0;
    font-size: 0.8125rem;
    line-height: 1.45;
    color: #64748b;
}

/* —— Download: Android + iOS side by side —— */
.lux-mobile-app__platform-row {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.75rem;
}

.lux-mobile-app__platform {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    padding: 0.75rem 0.75rem;
    border-radius: 14px;
    border: 0px solid #e2e8f0;
    background: #fff;
}

.lux-mobile-app__platform--android {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16);
    box-shadow: 0 4px 14px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
}

.lux-mobile-app__platform--disabled {
    opacity: 0.52;
    filter: grayscale(0.4);
    background: #f8fafc;
    border-style: dashed;
    border-color: #cbd5e1;
    pointer-events: none;
    user-select: none;
}

.lux-mobile-app__pill {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    margin-bottom: 0.4rem;
    padding: 0.2rem 0.55rem;
    border-radius: 9911px;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #475569;
    background: #f1f5f9;
    border: 0px solid #e2e8f0;
}

.lux-mobile-app__pill--accent {
    color: var(--lux-primary, #5b5ff4);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16);
}

.lux-mobile-app__pill--muted {
    color: #94a3b8;
}

.lux-mobile-app__platform-title {
    margin: 0 0 2px;
    font-size: 0.875rem;
    font-weight: 700;
    color: #0f172a;
}

.lux-mobile-app__platform-text {
    margin: 0 0 0.625rem;
    font-size: 0.75rem;
    color: #64748b;
}

.lux-mobile-app__qr-frame {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0.625rem;
    margin-bottom: 0.75rem;
    border-radius: 12px;
    background: #fff;
    border: 0px solid #e2e8f0;
    box-shadow: 0 4px 12px rgba(15, 23, 42, 0.06);
}

.lux-mobile-app__qr-frame--sm {
    width: 100%;
    max-width: 128px;
}

.lux-mobile-app__qr-frame--register {
    width: 100%;
    max-width: 148px;
}

.lux-mobile-app__qr-frame svg {
    display: block;
    width: 100% !important;
    height: auto !important;
}

.lux-mobile-app__qr-frame--placeholder {
    flex-direction: column;
    gap: 0.35rem;
    min-height: 128px;
    background: #f1f5f9;
    border-style: dashed;
}

.lux-mobile-app__apple-icon {
    font-size: 2rem;
    color: #94a3b8;
}

.lux-mobile-app__soon-badge {
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-mobile-app__store-link {
    display: inline-block;
    border-radius: 12px;
    overflow: hidden;
    transition: transform 0.18s ease, box-shadow 0.18s ease;
    box-shadow: 0 6px 16px rgba(15, 23, 42, 0.1);
}

.lux-mobile-app__store-link:hover {
    transform: translateY(-2px);
    box-shadow: 0 12px 22px rgba(15, 23, 42, 0.14);
    text-decoration: none;
}

.lux-mobile-app__store-link--disabled {
    box-shadow: none;
    cursor: not-allowed;
}

.lux-mobile-app__store-link img {
    display: block;
    width: auto;
    height: 40px;
    max-width: 100%;
}

.lux-mobile-app__coming-soon {
    margin-top: 0.35rem;
    font-size: 0.75rem;
    font-weight: 600;
    color: #94a3b8;
    font-style: italic;
}

/* —— Registration zone —— */
.lux-mobile-app__register-body {
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 200px;
}

.lux-mobile-app__register-qr {
    flex-shrink: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
}

.lux-mobile-app__scan-label {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    margin: 0.625rem 0 0;
    font-size: 0.75rem;
    font-weight: 600;
    color: #475569;
    padding: 0.35rem 0.65rem;
    border-radius: 8px;
    background: #f1f5f9;
}

.lux-mobile-app__scan-label i {
    color: var(--lux-accent, #14b8a6);
}

/* —— Quick guide bar —— */
.lux-mobile-app__steps-bar {
    padding: 0.75rem 1rem;
    border-radius: var(--lux-mobile-radius);
    border: 0px solid rgba(148, 163, 184, 0.2);
    background: #f8fafc;
    margin-bottom: 0.75rem;
}

.lux-mobile-app__section-title {
    margin: 0 0 0.75rem;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-mobile-app__steps {
    list-style: none;
    margin: 0;
    padding: 0;
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.75rem 0.875rem;
}

.lux-mobile-app__step {
    display: flex;
    align-items: flex-start;
    gap: 0.625rem;
    min-width: 0;
}

.lux-mobile-app__step-num {
    flex-shrink: 0;
    width: 24px;
    height: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 9911px;
    font-size: 12px;
    font-weight: 800;
    color: #fff;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-accent, #14b8a6));
    box-shadow: 0 4px 12px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
}

.lux-mobile-app__step-body strong {
    display: block;
    margin-bottom: 2px;
    font-size: 0.8125rem;
    font-weight: 700;
    color: #0f172a;
    line-height: 1.3;
}

.lux-mobile-app__step-body p {
    margin: 0;
    font-size: 0.75rem;
    line-height: 1.45;
    color: #64748b;
}

.lux-mobile-app__tip {
    display: flex;
    align-items: flex-start;
    gap: 0.625rem;
    padding: 0.75rem 0.75rem;
    border-radius: 12px;
    font-size: 0.75rem;
    line-height: 1.45;
    color: #64748b;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.05);
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.lux-mobile-app__tip i {
    flex-shrink: 0;
    margin-top: 2px;
    color: var(--lux-primary, #5b5ff4);
}

/* —— Popup —— */
.lux-mobile-app--popup .lux-mobile-app__split {
    margin-bottom: 0.75rem;
}

/* —— Embedded —— */
.lux-mobile-app--embedded {
    max-width: 1060px;
    margin: 0 auto;
    padding: 0.625rem;
}

.lux-mobile-app--embedded .lux-mobile-app__hero {
    padding: 1rem 1.125rem;
    margin-bottom: 1rem;
    border-bottom: none;
    border-radius: var(--lux-mobile-radius);
    background:
        linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.07) 0%, rgba(20, 184, 166, 0.06) 100%),
        #fff;
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    box-shadow: 0 8px 24px rgba(15, 23, 42, 0.05);
}

@media (max-width: 960px) {
    .lux-mobile-app__split {
        grid-template-columns: 1fr;
        gap: 0.75rem;
    }

    .lux-mobile-app__divider {
        width: 100%;
        height: 1px;
        margin: 0;
        background: linear-gradient(
            90deg,
            transparent 0%,
            rgba(148, 163, 184, 0.35) 20%,
            rgba(var(--lux-primary-rgb, 91, 95, 244), 0.25) 50%,
            rgba(148, 163, 184, 0.35) 80%,
            transparent 100%
        );
    }

    .lux-mobile-app__steps {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 640px) {
    .lux-mobile-app__platform-row {
        grid-template-columns: 1fr;
    }

    .lux-mobile-app__register-body {
        flex-direction: column;
        align-items: center;
    }

    .lux-mobile-app__steps {
        grid-template-columns: 1fr;
    }
}

/* —— Accounts directory (lux-accounts) —— */
.lux-accounts__body {
    padding-top: 0.25rem;
}

.lux-acct-toolbar {
    border-bottom: 1px solid rgba(226, 232, 240, 0.95) !important;
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.94));
    box-shadow: 0 4px 18px rgba(15, 23, 42, 0.04);
    z-index: 12;
}

.lux-acct-toolbar__row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 0.65rem 1rem;
    padding: 0.55rem 0;
}

.lux-acct-toolbar__crumbs {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.2rem 0.35rem;
    min-width: 0;
}

.lux-acct-toolbar__crumb {
    border: none;
    background: transparent;
    padding: 0.2rem 0.35rem;
    font-size: 0.8125rem;
    font-weight: 700;
    color: var(--lux-primary, #5b5ff4);
    cursor: pointer;
    border-radius: 8px;
}

.lux-acct-toolbar__crumb:hover {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
}

.lux-acct-toolbar__crumb.is-current {
    color: #0f172a;
