    font-weight: 800;
}

.lux-acct-toolbar__crumb-sep {
    font-size: 0.75rem;
    color: #94a3b8;
}

.lux-acct-toolbar__right {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: flex-end;
    gap: 0.45rem;
}

.lux-acct-toolbar__search {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    min-width: min(100%, 240px);
    padding: 0.35rem 0.65rem;
    border: 0px solid #e2e8f0;
    border-radius: 12px;
    background: #fff;
}

.lux-acct-toolbar__search i {
    color: #94a3b8;
    font-size: 0.9rem;
}

.lux-acct-toolbar__search input {
    border: none;
    background: transparent;
    width: 100%;
    font-size: 0.8125rem;
    outline: none;
}

.lux-acct-toolbar__view-toggle {
    display: inline-flex;
    padding: 3px;
    border-radius: 12px;
    background: #f1f5f9;
    border: 0px solid #e2e8f0;
}

.lux-acct-toolbar__view-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.35rem 0.65rem;
    border: none;
    border-radius: 9px;
    background: transparent;
    font-size: 0.75rem;
    font-weight: 700;
    color: #64748b;
