}

.lux-tb-config__error {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.5rem 0.65rem;
  margin-bottom: 0.65rem;
  border-radius: 10px;
  background: rgba(244, 63, 94, 0.08);
  border: 0px solid rgba(244, 63, 94, 0.2);
  color: #be123c;
  font-size: 0.75rem;
  font-weight: 600;
}

.lux-tb-config__sections {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  flex: 1;
}

.lux-tb-config__section {
  padding: 0.75rem 0.85rem;
  border-radius: 14px;
  border: 0px solid rgba(148, 163, 184, 0.14);
  background: rgba(248, 250, 252, 0.6);
}

.lux-tb-config__section-title {
  display: flex;
  align-items: center;
  gap: 0.35rem;
