}

.lux-tb-config__fields--2 {
  grid-template-columns: 1fr 1fr;
}

.lux-tb-config__add-member {
  display: grid;
  grid-template-columns: 1fr 1fr auto;
  gap: 0.5rem;
  align-items: end;
  margin-bottom: 0.65rem;
}

.lux-tb-config__roster-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.lux-tb-config__roster-item {
  display: grid;
  grid-template-columns: 1.5rem 1fr auto;
  gap: 0.5rem;
  align-items: center;
  padding: 0.5rem 0.6rem;
  border-radius: 10px;
  border: 0px solid rgba(148, 163, 184, 0.14);
  background: #fff;
}

.lux-tb-config__roster-index {
  font-size: 0.6875rem;
  font-weight: 800;
  color: #94a3b8;
}

.lux-tb-config__roster-person strong {
  display: block;
  font-size: 0.8125rem;
  color: #0f172a;
}

.lux-tb-config__roster-person span {
  font-size: 0.625rem;
  color: #64748b;
}

.lux-tb-config__roster-empty {
  text-align: center;
  padding: 1rem;
  border-radius: 10px;
  border: 0px dashed rgba(148, 163, 184, 0.25);
  color: #94a3b8;
  font-size: 0.75rem;
}

.lux-tb-config__roster-empty i {
  display: block;
  font-size: 1.25rem;
  margin-bottom: 0.35rem;
  color: #cbd5e1;
}

.lux-tb-config__footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
  flex-shrink: 0;
  margin: 0;
  padding: 0.75rem 1rem;
  border-top: 1px solid rgba(148, 163, 184, 0.18);
  background: #fff;
  box-shadow: 0 -6px 16px rgba(15, 23, 42, 0.05);
  z-index: 2;
}

.lux-tb-config__footer .lux-planner-btn {
  min-height: 2.125rem;
}

/* Legacy configure (unused) */
.lux-taskboard-config {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.lux-taskboard-config__form-card,
.lux-taskboard-config__list-card {
