  text-transform: uppercase;
  color: #94a3b8;
  background: #f8fafc;
}

.lux-taskboard-config__roster-row {
  display: grid;
  grid-template-columns: 40px 1fr 1fr 40px;
  gap: 0.5rem;
  align-items: center;
  padding: 0.45rem 0.65rem;
  border-top: 1px solid rgba(148, 163, 184, 0.1);
  font-size: 0.8125rem;
}

.lux-taskboard-config__add-row {
  display: grid;
  grid-template-columns: 1fr 1fr auto;
  gap: 0.5rem;
  align-items: end;
  margin-bottom: 0.65rem;
}

.lux-taskboard-config__boards {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.lux-taskboard-config__board-row {
  display: grid;
  grid-template-columns: 32px 1fr 1.2fr auto;
  gap: 0.65rem;
  align-items: center;
  padding: 0.7rem 0.85rem;
  border-radius: 12px;
  border: 0px solid rgba(148, 163, 184, 0.16);
  background: #f8fafc;
}

.lux-taskboard-config__board-row.is-editing {
