/* Taskboard complete / start — TimesheetLuxuryDialog body */
.lux-ts-detail__panel.lux-task-complete-dialog {
  width: min(860px, 100%);
}

.lux-ts-detail__panel.lux-task-complete-dialog .lux-ts-detail__foot {
  padding-top: 0.4rem;
}

.lux-ts-detail__panel.lux-task-complete-dialog .lux-create-footer {
  margin: 0;
  padding: 0;
  border: none;
  background: transparent;
}

.lux-task-complete {
  display: flex;
  flex-direction: column;
  gap: 0.95rem;
}

.lux-task-complete__hero {
  position: relative;
  overflow: hidden;
  border-radius: 16px;
  padding: 0.95rem 1.05rem;
  border: 0 solid transparent;
  background:
    linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1), rgba(5, 150, 105, 0.06)),
    #ffffff;
}

.lux-task-complete__hero-glow {
  position: absolute;
  inset: auto -20% -60% auto;
  width: 220px;
  height: 220px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18), transparent 70%);
  pointer-events: none;
}

.lux-task-complete__hero-main {
  position: relative;
  z-index: 1;
}

.lux-task-complete__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin-bottom: 0.45rem;
}

.lux-task-complete__chip {
  display: inline-flex;
  align-items: center;
  padding: 0.16rem 0.55rem;
  border-radius: 999px;
  font-size: 0.625rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.lux-task-complete__chip.is-category {
  background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
  color: #3730a3;
}

.lux-task-complete__chip.is-type {
  background: rgba(100, 116, 139, 0.12);
  color: #475569;
}

.lux-task-complete__name {
  margin: 0;
  font-size: 1.05rem;
  font-weight: 800;
  color: #0f172a;
  line-height: 1.25;
  letter-spacing: -0.015em;
}

.lux-task-complete__deliverable {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  margin: 0.35rem 0 0;
  font-size: 0.8125rem;
  font-weight: 600;
  color: #475569;
}

.lux-task-complete__deliverable i {
  color: #94a3b8;
}

.lux-task-complete__desc {
  margin: 0.45rem 0 0;
  font-size: 0.75rem;
  line-height: 1.45;
  color: #64748b;
}

.lux-task-complete__meta-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.5rem;
}

.lux-task-complete__meta-grid.is-complete {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.lux-task-complete__meta {
  display: flex;
  align-items: flex-start;
  gap: 0.55rem;
  padding: 0.65rem 0.7rem;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.92);
  border: 0 solid transparent;
  box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.95);
}

.lux-task-complete__meta-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.75rem;
  height: 1.75rem;
  border-radius: 10px;
  background: rgba(148, 163, 184, 0.12);
  color: #64748b;
  flex-shrink: 0;
}

.lux-task-complete__meta.is-blue .lux-task-complete__meta-icon {
  background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
  color: #4338ca;
}

.lux-task-complete__meta.is-green .lux-task-complete__meta-icon {
  background: rgba(5, 150, 105, 0.12);
  color: #047857;
}

.lux-task-complete__meta.is-amber .lux-task-complete__meta-icon {
  background: rgba(217, 119, 6, 0.12);
  color: #b45309;
}

.lux-task-complete__meta-copy {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.12rem;
}

.lux-task-complete__meta-copy span {
  font-size: 0.625rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #94a3b8;
}

.lux-task-complete__meta-copy strong {
  font-size: 0.8125rem;
  font-weight: 700;
  color: #0f172a;
  line-height: 1.25;
  word-break: break-word;
}

.lux-task-complete__readonly {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  min-height: 2.15rem;
  justify-content: center;
  padding: 0.45rem 0.7rem;
  border-radius: 12px;
  background: rgba(248, 250, 252, 0.95);
  box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.95);
}

.lux-task-complete__readonly-label {
  font-size: 0.625rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #94a3b8;
}

.lux-task-complete__readonly strong {
  font-size: 0.8125rem;
  font-weight: 700;
  color: #0f172a;
}

.lux-task-complete__history {
  border-radius: 14px;
  background: rgba(248, 250, 252, 0.9);
  box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.95);
  overflow: hidden;
}

.lux-task-complete__history-toggle {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.7rem 0.85rem;
  border: none;
  background: transparent;
  cursor: pointer;
  color: #0f172a;
  font-size: 0.8125rem;
  font-weight: 700;
  text-align: left;
}

.lux-task-complete__history-toggle span {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
}

.lux-task-complete__history-toggle em {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.35rem;
  height: 1.35rem;
  padding: 0 0.35rem;
  border-radius: 999px;
  font-style: normal;
  font-size: 0.6875rem;
  font-weight: 800;
  background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
  color: #4338ca;
}

.lux-task-complete__history-list {
  list-style: none;
  margin: 0;
  padding: 0 0.85rem 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.lux-task-complete__history-list li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.45rem 0.6rem;
  border-radius: 10px;
  background: #fff;
  box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.9);
  font-size: 0.75rem;
  color: #475569;
}

.lux-task-complete__history-list strong {
  font-weight: 800;
  color: #0f172a;
}

.lux-task-complete__dropzone {
  border-radius: 14px;
  padding: 0.15rem;
  background: rgba(248, 250, 252, 0.85);
}

@media (max-width: 720px) {
  .lux-task-complete__meta-grid,
  .lux-task-complete__meta-grid.is-complete {
    grid-template-columns: 1fr;
  }
}

