  gap: 0.45rem;
  margin: 0.25rem 0 0;
  font-size: 0.6875rem;
  color: #64748b;
}

.lux-delivery-sprint__card-sub code {
  padding: 0.05rem 0.35rem;
  border-radius: 6px;
  background: rgba(148, 163, 184, 0.12);
  font-size: 0.625rem;
}

.lux-delivery-sprint__ring {
  flex-shrink: 0;
  width: 3rem;
  height: 3rem;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background:
    radial-gradient(circle at center, #fff 58%, transparent 59%),
    conic-gradient(#10b981 var(--delivery-pct, 0%), rgba(226, 232, 240, 0.95) 0);
}

.lux-delivery-sprint__ring strong {
  font-size: 0.6875rem;
  font-weight: 800;
  color: #0f172a;
}

.lux-delivery-sprint__bar {
  height: 0.35rem;
  border-radius: 999px;
  background: rgba(226, 232, 240, 0.95);
  overflow: hidden;
}

.lux-delivery-sprint__bar > span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #6366f1, #10b981);
}

.lux-delivery-sprint__task-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.lux-delivery-sprint__task-list.is-register {
  gap: 0.55rem;
}

.lux-delivery-sprint__task {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 0.55rem;
  align-items: start;
  padding: 0.55rem 0.6rem;
  border-radius: 12px;
  background: rgba(248, 250, 252, 0.85);
  box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.9);
}

.lux-delivery-sprint__task.is-selected {
  background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
  box-shadow: inset 0 0 0 1px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.25);
}

.lux-delivery-sprint__check {
  margin: 0.15rem 0 0;
}

.lux-delivery-sprint__task-title-row {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.35rem 0.65rem;
}

.lux-delivery-sprint__task-name {
  font-size: 0.8125rem;
  font-weight: 700;
  color: #0f172a;
  text-decoration: none;
}

.lux-delivery-sprint__task-name:hover {
  color: #4338ca;
}

.lux-delivery-sprint__project-link {
  font-size: 0.6875rem;
  font-weight: 600;
  color: #64748b;
  text-decoration: none;
}

.lux-delivery-sprint__project-link:hover {
  color: #4338ca;
}

.lux-delivery-sprint__task-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.3rem;
  margin-top: 0.3rem;
}

.lux-delivery-sprint__pill {
  display: inline-flex;
  align-items: center;
  padding: 0.1rem 0.45rem;
  border-radius: 999px;
  font-size: 0.625rem;
  font-weight: 800;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  background: rgba(148, 163, 184, 0.14);
  color: #475569;
}

.lux-delivery-sprint__pill.is-green { background: rgba(16, 185, 129, 0.14); color: #047857; }
.lux-delivery-sprint__pill.is-blue { background: rgba(59, 130, 246, 0.14); color: #1d4ed8; }
.lux-delivery-sprint__pill.is-amber { background: rgba(245, 158, 11, 0.16); color: #b45309; }
.lux-delivery-sprint__pill.is-rose { background: rgba(244, 63, 94, 0.14); color: #e11d48; }
.lux-delivery-sprint__pill.is-slate { background: rgba(148, 163, 184, 0.14); color: #475569; }

.lux-delivery-sprint__muted {
  font-size: 0.6875rem;
  color: #94a3b8;
}

.lux-delivery-sprint__task-actions .lux-delivery-sprint__select {
  min-width: 8.5rem;
  height: 2rem;
}

.lux-delivery-sprint__more {
  align-self: flex-start;
  margin-top: 0.15rem;
  padding: 0;
  border: none;
  background: transparent;
  color: #4338ca;
  font-size: 0.75rem;
  font-weight: 700;
  cursor: pointer;
}

.lux-delivery-sprint__register {
  border-radius: 16px;
  padding: 0.65rem;
  background: rgba(248, 250, 252, 0.55);
  box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.9);
}

.lux-delivery-sprint__pulse {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.lux-delivery-sprint__pulse-row {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 1.6fr) auto;
  gap: 0.75rem;
  align-items: center;
  padding: 0.7rem 0.85rem;
  border-radius: 14px;
  background: #fff;
  box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.95);
}

.lux-delivery-sprint__pulse-copy {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  min-width: 0;
}

.lux-delivery-sprint__pulse-copy strong {
  font-size: 0.875rem;
  color: #0f172a;
}

.lux-delivery-sprint__pulse-copy span {
  font-size: 0.6875rem;
  color: #64748b;
}

.lux-delivery-sprint__pulse-track {
  display: flex;
  height: 0.55rem;
  border-radius: 999px;
  overflow: hidden;
  background: rgba(226, 232, 240, 0.9);
}

.lux-delivery-sprint__pulse-track .is-done {
  background: #10b981;
}

.lux-delivery-sprint__pulse-track .is-open {
  background: #f59e0b;
}

.lux-delivery-sprint__pulse-pct {
  font-size: 0.8125rem;
  font-weight: 800;
  color: #0f172a;
}

.lux-delivery-sprint__skeleton {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.85rem;
}

.lux-delivery-sprint__skeleton-card {
  min-height: 160px;
  border-radius: 18px;
  background: linear-gradient(90deg, #f1f5f9 25%, #e2e8f0 37%, #f1f5f9 63%);
  background-size: 400% 100%;
  animation: lux-delivery-skeleton 1.2s ease infinite;
}

@keyframes lux-delivery-skeleton {
  0% { background-position: 100% 0; }
  100% { background-position: 0 0; }
}

@media (max-width: 900px) {
  .lux-delivery-sprint__pulse-row {
    grid-template-columns: 1fr;
  }
  .lux-delivery-sprint__skeleton {
    grid-template-columns: 1fr;
  }
  .lux-delivery-sprint__task {
    grid-template-columns: auto minmax(0, 1fr);
  }
  .lux-delivery-sprint__task-actions {
    grid-column: 1 / -1;
  }
}

@media (max-width: 1200px) {
  .lux-taskboard-kanban {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 768px) {
  .lux-taskboard-kanban {
    grid-template-columns: 1fr;
  }
  .lux-taskboard-list__head,
  .lux-taskboard-list__item {
    min-width: 0;
    grid-template-columns: 1fr;
  }

  .lux-taskboard-list__col--actions {
    justify-self: stretch;
  }

  .lux-taskboard-list__actions {
    justify-content: flex-start;
  }
  .lux-tb-config__layout {
    grid-template-columns: 1fr;
  }
  .lux-tb-config__hero {
    grid-template-columns: 1fr;
  }
  .lux-tb-config__fields--2,
  .lux-tb-config__add-member {
    grid-template-columns: 1fr;
  }
  .lux-taskboard-config__grid {
    grid-template-columns: 1fr;
  }
  .lux-taskboard-modal__layout {
    grid-template-columns: 1fr;
  }
}
/* Team capacity — luxury planner (fresh redesign) */
.lux-planner-page {
