    background: rgba(59, 130, 246, 0.12);
}

.lux-planner-legend__swatch.is-high {
    border-color: #f59e0b;
    background: rgba(245, 158, 11, 0.14);
}

.lux-planner-legend__swatch.is-critical {
    border-color: #ef4444;
    background: rgba(239, 68, 68, 0.12);
