.lux-planner-panel-head {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    gap: 0.5rem;
    margin-bottom: 0.65rem;
}

/* Overview */
.lux-planner-overview__top {
    display: grid;
    grid-template-columns: minmax(200px, 260px) 1fr;
    gap: 1rem;
    margin-bottom: 1rem;
}

.lux-planner-health {
    padding: 1rem;
    border-radius: 16px;
    border: 0px solid rgba(148, 163, 184, 0.2);
    background: #fff;
}

.lux-planner-health__ring {
    width: 88px;
    height: 88px;
    border-radius: 50%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    margin-bottom: 0.5rem;
    background: conic-gradient(
        var(--lux-primary, #5b5ff4) calc(var(--score) * 1%),
        #e2e8f0 0
    );
    position: relative;
}

.lux-planner-health__ring::after {
    content: "";
    position: absolute;
    inset: 8px;
    border-radius: 50%;
    background: #fff;
}

.lux-planner-health__ring strong,
.lux-planner-health__ring span {
    position: relative;
    z-index: 1;
    line-height: 1.1;
}

.lux-planner-health__ring strong {
    font-size: 1.25rem;
    color: #0f172a;
}

.lux-planner-health__ring span {
    font-size: 0.625rem;
    color: #64748b;
    text-transform: uppercase;
}

.lux-planner-health p {
    margin: 0;
    font-size: 0.75rem;
    color: #64748b;
    line-height: 1.45;
}

.lux-planner-alert-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 0.5rem;
}

.lux-planner-alert-card {
    display: flex;
    gap: 0.5rem;
    padding: 0.6rem 0.7rem;
    border-radius: 12px;
    border: 0px solid rgba(148, 163, 184, 0.2);
    background: #fff;
    font-size: 0.75rem;
}

.lux-planner-alert-card strong {
    display: block;
    color: #0f172a;
}

.lux-planner-alert-card span {
    color: #64748b;
}

.lux-planner-alert-card.is-critical { border-left: 3px solid #ef4444; }
.lux-planner-alert-card.is-warning { border-left: 3px solid #f59e0b; }
.lux-planner-alert-card.is-info { border-left: 3px solid #3b82f6; }

.lux-planner-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
    gap: 0.6rem;
    margin-bottom: 1rem;
}

.lux-planner-kpi-card {
    padding: 0.75rem;
    border-radius: 14px;
    background: #fff;
    border: 0px solid rgba(148, 163, 184, 0.18);
    box-shadow: 0 4px 14px rgba(15, 23, 42, 0.04);
}

.lux-planner-kpi-card__icon {
    width: 28px;
    height: 28px;
    border-radius: 8px;
