    background: linear-gradient(160deg, #fefce8, #fef9c3);
    border: 0px dashed rgba(234, 179, 8, 0.45);
    box-shadow: 0 14px 32px rgba(180, 130, 0, 0.12);
    transform: rotate(-0.6deg);
}

.lux-notes-overlay__empty-card i {
    font-size: 1.75rem;
    color: var(--lux-primary, #5b5ff4);
    margin-bottom: 0.5rem;
}

.lux-notes-overlay__empty-card strong {
    display: block;
    font-size: 1rem;
    color: #0f172a;
    margin-bottom: 0.35rem;
}

.lux-notes-overlay__empty-card p {
    margin: 0 0 1rem;
    font-size: 0.8125rem;
    color: #64748b;
    line-height: 1.5;
}

/* Note cards */
.lux-note-card.is-sticky {
    background: linear-gradient(165deg, #fefce8 0%, #fef9c3 48%, #fff 100%);
    transform: rotate(-0.6deg);
}

.lux-note-card__pin {
    position: absolute;
    top: 0.45rem;
    right: 0.75rem;
    width: 0.65rem;
    height: 0.65rem;
    border-radius: 50%;
    background: radial-gradient(circle at 30% 30%, #f43f5e, #be123c);
    box-shadow: 0 1px 3px rgba(15, 23, 42, 0.25);
}

.lux-note-card__badges {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    flex-shrink: 0;
}

.lux-note-card__remind {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.5rem;
    height: 1.5rem;
    border-radius: 8px;
    background: rgba(245, 158, 11, 0.16);
    color: #b45309;
    font-size: 0.75rem;
}

.lux-note-card {
    position: relative;
    padding: 1rem 1rem 0.875rem 1.125rem;
    border-radius: 16px;
    background: linear-gradient(165deg, #fffefb 0%, #fff 55%, #f8fafc 100%);
    border: 0px solid rgba(148, 163, 184, 0.28);
    box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.75) inset,
        0 14px 32px rgba(15, 23, 42, 0.1);
    overflow: hidden;
}

.lux-note-card.is-compact {
    padding: 0.875rem 0.875rem 0.75rem 1rem;
}

.lux-note-card__accent {
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 4px;
    background: var(--lux-primary, #5b5ff4);
}

.lux-note-card.is-today .lux-note-card__accent {
    background: #0ea5e9;
}

.lux-note-card.is-overdue .lux-note-card__accent {
    background: #f43f5e;
}

.lux-note-card.is-upcoming .lux-note-card__accent {
    background: #8b5cf6;
}

.lux-note-card.is-done .lux-note-card__accent {
    background: #22c55e;
}

.lux-note-card.is-done {
    opacity: 0.88;
    background: linear-gradient(165deg, #f8fafc 0%, #f1f5f9 100%);
}

.lux-note-card__head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.5rem;
    margin-bottom: 0.5rem;
}

.lux-note-card__title {
    margin: 0;
    font-size: 0.9375rem;
    font-weight: 800;
    letter-spacing: -0.02em;
    color: #0f172a;
    line-height: 1.3;
    flex: 1;
}

.lux-note-card__status {
    flex-shrink: 0;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    padding: 0.2rem 0.45rem;
    border-radius: 999px;
}

.lux-note-card__status.is-open {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    color: var(--lux-primary-dark, #3730a3);
}

.lux-note-card__status.is-done {
    background: rgba(34, 197, 94, 0.14);
    color: #15803d;
}

.lux-note-card__body {
    margin: 0 0 0.75rem;
    font-size: 0.8125rem;
    line-height: 1.55;
    color: #475569;
    white-space: pre-wrap;
    word-break: break-word;
}

.lux-note-card__body.is-empty {
    font-style: italic;
    color: #94a3b8;
}

.lux-note-card__foot {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.5rem;
    padding-top: 0.5rem;
    border-top: 1px solid rgba(148, 163, 184, 0.18);
}

.lux-note-card__when {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.75rem;
    font-weight: 600;
    color: #64748b;
}

.lux-note-card__actions {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
}

.lux-note-card__icon-btn {
    width: 2rem;
    height: 2rem;
    border: 0px solid rgba(148, 163, 184, 0.3);
    border-radius: 9px;
    background: #fff;
    color: #475569;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.lux-note-card__icon-btn:hover {
    background: #f8fafc;
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
    color: var(--lux-primary, #5b5ff4);
}

.lux-note-card__icon-btn.is-done:hover {
    color: #16a34a;
    border-color: rgba(34, 197, 94, 0.4);
}

.lux-note-card__icon-btn.is-delete:hover {
    color: #dc2626;
    border-color: rgba(220, 38, 38, 0.35);
    background: #fef2f2;
}

/* Note editor — centered luxury modal */
.lux-note-editor-modal__backdrop {
    position: fixed;
    inset: 0;
    z-index: 10050;
    border: none;
    padding: 0;
    background: rgba(15, 23, 42, 0.58);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    cursor: pointer;
    animation: luxNoteEditorBackdropIn 0.2s ease;
}

@keyframes luxNoteEditorBackdropIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

.lux-note-editor-modal {
    position: fixed;
    z-index: 10060;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: min(560px, calc(100vw - 1.25rem));
    max-height: min(90vh, 780px);
    display: flex;
    flex-direction: column;
    border-radius: 20px;
    overflow: hidden;
    background: linear-gradient(180deg, #fff 0%, #f8fafc 100%);
    border: 0px solid rgba(148, 163, 184, 0.32);
    box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.8) inset,
        0 28px 64px rgba(15, 23, 42, 0.24);
    animation: luxNoteEditorModalIn 0.24s cubic-bezier(0.22, 1, 0.36, 1);
}

@keyframes luxNoteEditorModalIn {
    from {
        opacity: 0;
        transform: translate(-50%, -48%) scale(0.97);
    }
    to {
        opacity: 1;
        transform: translate(-50%, -50%) scale(1);
    }
}

.lux-note-editor-modal__glow {
    position: absolute;
    inset: 0;
    pointer-events: none;
    background:
        radial-gradient(circle at 0% 0%, rgba(254, 240, 138, 0.22), transparent 45%),
        radial-gradient(circle at 100% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08), transparent 40%);
}

.lux-note-editor-modal__hero {
    position: relative;
    flex-shrink: 0;
    padding: 0.85rem 1rem 0.75rem;
    border-bottom: 1px solid rgba(148, 163, 184, 0.22);
    background:
        linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.07), rgba(254, 240, 138, 0.14)),
        #fff;
}

.lux-note-editor-modal__hero-top {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.65rem;
}

.lux-note-editor-modal__hero-brand {
    display: flex;
    align-items: flex-start;
    gap: 0.65rem;
    min-width: 0;
}

.lux-note-editor-modal__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.35rem;
    height: 2.35rem;
    border-radius: 12px;
    background: linear-gradient(135deg, #fef08a, #fde047);
    color: #a16207;
    flex-shrink: 0;
    font-size: 1rem;
    box-shadow: 0 4px 12px rgba(234, 179, 8, 0.25);
}

.lux-note-editor-modal__hero-copy h2 {
    margin: 0.15rem 0 0;
    font-size: 1.05rem;
    font-weight: 800;
    letter-spacing: -0.03em;
    color: #0f172a;
    line-height: 1.2;
}

.lux-note-editor-modal__eyebrow {
    margin-bottom: 0.2rem;
}

.lux-note-editor-modal__subtitle {
    margin: 0.2rem 0 0;
    font-size: 0.6875rem;
    line-height: 1.45;
    color: #64748b;
}

.lux-note-editor-modal__close {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border: 0px solid rgba(148, 163, 184, 0.35);
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.95);
    color: #475569;
    cursor: pointer;
    flex-shrink: 0;
}

.lux-note-editor-modal__close:hover {
    color: #0f172a;
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
}

.lux-note-editor-modal__body {
    position: relative;
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    padding: 0.85rem 1rem 0.5rem;
    -webkit-overflow-scrolling: touch;
}

.lux-note-editor-modal .lux-note-editor-footer {
    flex-shrink: 0;
    border-radius: 0 0 20px 20px;
}

.lux-note-editor-form .lux-create-field-group + .lux-create-field-group {
    margin-top: 0.75rem;
    padding-top: 0.75rem;
}

.lux-note-editor-form textarea.form-control {
    min-height: 6.5rem;
    resize: vertical;
}

.lux-note-editor-status {
    margin-top: 0.25rem;
}

/* Live preview card */
.lux-note-editor-preview {
    position: relative;
    margin: 0 0 0.85rem;
    padding: 0.95rem 1rem 0.85rem 1.1rem;
    border-radius: 16px;
    background: linear-gradient(165deg, #fefce8 0%, #fef9c3 42%, #fff 100%);
    border: 0px solid rgba(234, 179, 8, 0.28);
    box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.8) inset,
        0 12px 28px rgba(15, 23, 42, 0.08);
    transform: rotate(-0.5deg);
}

.lux-note-editor-preview.is-done {
    background: linear-gradient(165deg, #f8fafc 0%, #f1f5f9 100%);
    border-color: rgba(148, 163, 184, 0.35);
    transform: none;
}

.lux-note-editor-preview__pin {
    position: absolute;
    top: 0.5rem;
    right: 0.75rem;
    width: 0.65rem;
    height: 0.65rem;
    border-radius: 50%;
    background: radial-gradient(circle at 30% 30%, #f43f5e, #be123c);
    box-shadow: 0 1px 3px rgba(15, 23, 42, 0.2);
}

.lux-note-editor-preview__head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.5rem;
    margin-bottom: 0.45rem;
}

.lux-note-editor-preview__title {
    margin: 0;
    font-size: 0.9375rem;
    font-weight: 800;
    letter-spacing: -0.02em;
    color: #0f172a;
    line-height: 1.3;
}

.lux-note-editor-preview__badges {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    flex-shrink: 0;
}

.lux-note-editor-preview__remind {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.5rem;
    height: 1.5rem;
    border-radius: 8px;
    background: rgba(245, 158, 11, 0.18);
    color: #b45309;
    font-size: 0.75rem;
}

.lux-note-editor-preview__status {
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    padding: 0.2rem 0.45rem;
    border-radius: 999px;
}

.lux-note-editor-preview__status.is-open {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    color: var(--lux-primary-dark, #3730a3);
}

.lux-note-editor-preview__status.is-done {
    background: rgba(34, 197, 94, 0.14);
    color: #15803d;
}

.lux-note-editor-preview__body {
    margin: 0 0 0.6rem;
    font-size: 0.8125rem;
    line-height: 1.55;
    color: #475569;
    white-space: pre-wrap;
    word-break: break-word;
}

.lux-note-editor-preview__foot {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.75rem;
    font-weight: 600;
    color: #64748b;
    padding-top: 0.45rem;
    border-top: 1px solid rgba(148, 163, 184, 0.2);
}

/* Remind toggle card */
.lux-note-editor-option {
    display: flex;
    align-items: center;
    gap: 0.65rem;
    width: 100%;
    padding: 0.65rem 0.75rem;
    border: 0px solid rgba(203, 213, 225, 0.95);
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.9);
    text-align: left;
    cursor: pointer;
    transition: border-color 0.15s ease, background 0.15s ease, box-shadow 0.15s ease;
}

.lux-note-editor-option:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.3);
    background: #fff;
}

.lux-note-editor-option.is-active {
    border-color: rgba(245, 158, 11, 0.45);
    background: linear-gradient(135deg, rgba(254, 243, 199, 0.5), rgba(255, 255, 255, 0.95));
    box-shadow: 0 4px 16px rgba(245, 158, 11, 0.12);
}

.lux-note-editor-option__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.25rem;
    height: 2.25rem;
    border-radius: 11px;
    background: rgba(248, 250, 252, 0.95);
    color: #64748b;
    flex-shrink: 0;
}

.lux-note-editor-option.is-active .lux-note-editor-option__icon {
    background: rgba(245, 158, 11, 0.18);
    color: #b45309;
}

.lux-note-editor-option__copy {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 0.1rem;
}

.lux-note-editor-option__copy strong {
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-note-editor-option__copy span {
    font-size: 0.6875rem;
    color: #64748b;
    line-height: 1.4;
}

.lux-note-editor-option__switch {
    width: 2.35rem;
    height: 1.35rem;
    border-radius: 999px;
    background: rgba(203, 213, 225, 0.9);
    position: relative;
    flex-shrink: 0;
    transition: background 0.18s ease;
}

.lux-note-editor-option__switch.is-on {
    background: linear-gradient(135deg, #f59e0b, #d97706);
}

.lux-note-editor-option__knob {
    position: absolute;
    top: 2px;
    left: 2px;
    width: 1rem;
    height: 1rem;
    border-radius: 50%;
    background: #fff;
    box-shadow: 0 1px 4px rgba(15, 23, 42, 0.18);
    transition: transform 0.18s ease;
}

.lux-note-editor-option__switch.is-on .lux-note-editor-option__knob {
    transform: translateX(1rem);
}

.lux-note-editor-footer .lux-note-editor-footer__hint {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.6875rem;
    font-weight: 600;
    color: #64748b;
}

.lux-note-editor-footer .lux-note-editor-footer__hint .fe {
    color: #94a3b8;
}

/* Notes page */
.lux-rail__notes-btn.active {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14);
    color: var(--lux-primary, #5b5ff4);
    box-shadow: 0 0 0 1px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.25);
}

.lux-notes-page__grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 1rem;
}

.lux-notes-page__list {
    display: flex;
    flex-direction: column;
    gap: 0.65rem;
}

.lux-notes-register-row {
    display: grid;
    grid-template-columns: minmax(0, 1.4fr) minmax(0, 2fr) 8rem 7rem;
    gap: 0.75rem;
    align-items: center;
    padding: 0.875rem 1rem;
    border-radius: 14px;
    background: #fff;
    border: 0px solid rgba(148, 163, 184, 0.25);
    box-shadow: 0 8px 20px rgba(15, 23, 42, 0.05);
}

.lux-notes-register-row.is-done {
    background: #f8fafc;
}

.lux-notes-register-row__title {
    margin: 0;
    font-size: 0.875rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-notes-register-row__desc {
    margin: 0;
    font-size: 0.8125rem;
    color: #64748b;
    line-height: 1.45;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.lux-notes-register-row__when {
    font-size: 0.75rem;
    font-weight: 600;
    color: #64748b;
}

.lux-notes-register-row__actions {
    display: flex;
    justify-content: flex-end;
    gap: 0.25rem;
}

.lux-rail__notes-btn {
    position: relative;
}

.lux-rail__notes-badge {
    position: absolute;
    top: 2px;
    right: 2px;
    min-width: 1rem;
    height: 1rem;
    padding: 0 0.25rem;
    border-radius: 999px;
    background: #f43f5e;
    color: #fff;
    font-size: 0.625rem;
    font-weight: 800;
    line-height: 1rem;
    text-align: center;
    pointer-events: none;
}

@media (max-width: 900px) {
    .lux-notes-overlay__float-head {
        left: 0.75rem;
        width: calc(100vw - 1.5rem);
    }

    .lux-notes-overlay__deck {
        left: 0.75rem;
        width: calc(100vw - 1.5rem);
    }

    .lux-notes-register-row {
        grid-template-columns: 1fr;
    }

    .lux-notes-register-row__actions {
        justify-content: flex-start;
    }

    .lux-note-editor-modal {
        width: calc(100vw - 1rem);
        max-height: 94vh;
    }
}
/* ========== Feedback — workspace page, campaigns, recipients, templates ========== */

.lux-feedback-page {
    width: 100%;
    padding-bottom: 1rem;
}

.lux-feedback-page.lux-register-page {
    padding-bottom: 1rem;
}

/* Allow the main app shell to grow and scroll (fixed .page.h-100vh otherwise clips content) */
.page:has(.lux-feedback-page) {
    height: auto !important;
    min-height: 100vh;
    max-height: none !important;
    overflow: visible !important;
}

.page:has(.lux-feedback-page) > .vleft {
    flex: 1 0 auto;
    min-height: auto;
    overflow: visible;
}

.pd-page:has(.lux-feedback-page) .pd-page__body {
    overflow: visible;
}

.lux-feedback-page .lux-page-header {
    margin-top: 0;
    margin-bottom: 0;
}

.lux-feedback-summary__context {
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
    margin: 0.35rem 0 0.65rem;
}

.lux-feedback-summary__chip {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.28rem 0.65rem;
    border-radius: 999px;
    border: 1px solid rgba(148, 163, 184, 0.35);
    background: rgba(255, 255, 255, 0.92);
    font-size: 0.6875rem;
    font-weight: 700;
    color: #475569;
}

.lux-feedback-summary__insights {
