.lux-feedback-summary__insights-list li {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.5rem;
    font-size: 0.75rem;
    color: #64748b;
}

.lux-feedback-summary__insights-list strong {
    color: #0f172a;
    font-weight: 800;
}

.lux-feedback-summary__tips {
    margin-top: 0.85rem;
    padding: 0.75rem 0.85rem;
    border-radius: 14px;
