    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.04);
}

.lux-feedback-summary__tips-list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0.55rem;
}

.lux-feedback-summary__tips-list li {
    display: flex;
    align-items: flex-start;
    gap: 0.55rem;
    font-size: 0.75rem;
    color: #475569;
}

.lux-feedback-summary__tips-list li i {
    color: var(--lux-primary, #5b5ff4);
    margin-top: 0.15rem;
}

.lux-feedback-summary__tips-list strong {
    display: block;
    color: #0f172a;
    font-weight: 700;
}

.lux-feedback-summary__tips-list span {
    display: block;
    color: #64748b;
    line-height: 1.4;
}

.lux-feedback-header-extra .lux-planner-btn {
    white-space: nowrap;
}

/* Create request panel */
.lux-feedback-create {
    display: flex;
    flex-direction: column;
    margin: 0 0.65rem 0.85rem;
    border-radius: 16px;
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
    background: linear-gradient(180deg, #fff 0%, #f8fafc 100%);
    box-shadow: 0 14px 32px rgba(15, 23, 42, 0.08);
    overflow: hidden;
    max-height: min(88vh, 920px);
}

.lux-feedback-create__head {
    display: flex;
    align-items: flex-start;
    gap: 0.65rem;
    flex-shrink: 0;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid rgba(148, 163, 184, 0.2);
    background: linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.09), rgba(14, 165, 233, 0.05));
}

.lux-feedback-create__head-icon {
    width: 2.25rem;
    height: 2.25rem;
    display: grid;
    place-items: center;
    border-radius: 12px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    color: var(--lux-primary, #5b5ff4);
    font-size: 1rem;
    flex-shrink: 0;
}

.lux-feedback-create__kicker {
    display: block;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-feedback-create__head-copy h3 {
    margin: 0.12rem 0 0;
    font-size: 1rem;
    font-weight: 800;
    color: #0f172a;
    letter-spacing: -0.02em;
}

.lux-feedback-create__head-copy p {
    margin: 0.2rem 0 0;
    font-size: 0.75rem;
    color: #64748b;
    line-height: 1.4;
}

.lux-feedback-create__body {
    flex: 1;
    min-height: 0;
    overflow: auto;
    padding: 0;
}

/* New feedback request — luxury form */
.lux-fb-create-form {
    display: flex;
    flex-direction: column;
    min-height: 0;
}

.lux-fb-create-form--panel .lux-fb-create-form__scroll {
    flex: 1;
    min-height: 0;
}

.lux-fb-create-form__layout {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(280px, 340px);
    gap: 0.75rem;
    padding: 0.75rem 1rem;
    align-items: start;
}

.lux-fb-create-form__main {
    display: flex;
    flex-direction: column;
    gap: 0.6rem;
    min-width: 0;
}

.lux-fb-create-form__aside {
    min-width: 0;
    position: sticky;
    top: 0;
}

.lux-fb-create-section {
    border: 0px solid #e2e8f0;
    border-radius: 14px;
    background: #fff;
    box-shadow: 0 4px 14px rgba(15, 23, 42, 0.04);
    overflow: hidden;
}

.lux-fb-create-section__head {
    display: flex;
    align-items: flex-start;
    gap: 0.5rem;
    padding: 0.55rem 0.7rem;
    border-bottom: 1px solid #e2e8f0;
    background: rgba(248, 250, 252, 0.9);
}

.lux-fb-create-section__icon {
    width: 1.75rem;
    height: 1.75rem;
    display: grid;
    place-items: center;
    border-radius: 10px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary, #5b5ff4);
    flex-shrink: 0;
}

.lux-fb-create-section__head h4 {
    margin: 0;
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-fb-create-section__head p {
    margin: 0.1rem 0 0;
    font-size: 0.625rem;
    color: #94a3b8;
    line-height: 1.35;
}

.lux-fb-create-section__body {
    padding: 0.65rem 0.7rem 0.7rem;
}

.lux-fb-create-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.5rem 0.6rem;
}

.lux-fb-create-grid__full {
    grid-column: 1 / -1;
}

.lux-fb-create-grid .form-group {
    margin-bottom: 0 !important;
}

.lux-fb-create-grid .form-control,
.lux-fb-create-grid textarea.form-control {
    border-radius: 12px !important;
    border-color: #e2e8f0 !important;
    font-weight: 600;
}

/* Schedule section — aligned date + toggle rows */
.lux-fb-create-schedule__dates {
    align-items: start;
}

.lux-fb-create-schedule__dates .react-datepicker-wrapper {
    display: block;
    width: 100%;
}

.lux-fb-create-schedule__dates .react-datepicker-wrapper .form-control {
    width: 100%;
    min-height: 2.25rem;
}

.lux-fb-create-schedule__end-date .form-group {
    margin-bottom: 0 !important;
}

.lux-fb-create-schedule__end-date.is-inactive .form-control {
    background: #f8fafc;
}

.lux-fb-create-schedule__end-hint {
    margin: 0.2rem 0 0;
    font-size: 0.5625rem;
    font-weight: 600;
    line-height: 1.3;
    color: #94a3b8;
}

.lux-fb-create-schedule__toggles {
    margin-top: 0.5rem;
    align-items: end;
}

.lux-fb-create-schedule__toggles .form-group {
    margin-bottom: 0 !important;
}

.lux-fb-create-schedule__toggles .custom-controls-stacked {
    margin-top: 0.28rem !important;
    min-height: 2.25rem;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
}

.lux-fb-create-recurring {
    margin-top: 0.55rem;
    padding-top: 0.55rem;
    border-top: 1px dashed #e2e8f0;
}

.lux-fb-create-recurring__schedule {
    margin-top: 0.5rem;
}

.lux-fb-create-recurring__schedule-label {
    margin: 0 0 0.35rem;
    font-size: 0.625rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #94a3b8;
}

.lux-fb-create-form .lux-create-footer {
    flex-shrink: 0;
    margin: 0;
    border-top: 1px solid #e2e8f0;
    border-radius: 0;
    background: #f8fafc;
}

/* Recipients panel */
.lux-fb-recipients {
    display: flex;
    flex-direction: column;
    height: 100%;
    min-height: 320px;
    border: 1px solid rgba(148, 163, 184, 0.22);
    border-radius: 16px;
    background: linear-gradient(180deg, #fff 0%, rgba(248, 250, 252, 0.96) 100%);
    box-shadow: 0 12px 28px rgba(15, 23, 42, 0.06);
    overflow: hidden;
}

.lux-fb-recipients.has-recipients {
    border-color: rgba(16, 185, 129, 0.28);
    box-shadow: 0 14px 32px rgba(16, 185, 129, 0.08);
}

.lux-fb-recipients.is-empty .lux-fb-recipients__list-wrap.has-error {
    border-color: #fca5a5;
    background: #fffafb;
}

.lux-fb-recipients__head {
    display: flex;
    align-items: flex-start;
    gap: 0.55rem;
    padding: 0.75rem 0.8rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.95);
    background: linear-gradient(135deg, rgba(16, 185, 129, 0.08), rgba(255, 255, 255, 0.96));
}

.lux-fb-recipients__head-icon {
    width: 2.1rem;
    height: 2.1rem;
    display: grid;
    place-items: center;
    border-radius: 12px;
    background: linear-gradient(145deg, rgba(16, 185, 129, 0.18), rgba(255, 255, 255, 0.95));
    color: #059669;
    flex-shrink: 0;
    box-shadow: inset 0 0 0 1px rgba(16, 185, 129, 0.16);
}

.lux-fb-recipients__head-copy {
    min-width: 0;
    flex: 1;
}

.lux-fb-recipients__head h4 {
    margin: 0;
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-fb-recipients__head p {
    margin: 0.12rem 0 0;
    font-size: 0.625rem;
    color: #64748b;
    line-height: 1.4;
}

.lux-fb-recipients__count {
    margin-left: auto;
    min-width: 1.65rem;
    height: 1.65rem;
    display: grid;
    place-items: center;
    padding: 0 0.4rem;
    border-radius: 999px;
    font-size: 0.75rem;
    font-weight: 800;
    color: #64748b;
    background: rgba(148, 163, 184, 0.16);
}

.lux-fb-recipients__count.is-filled {
    color: #047857;
    background: rgba(16, 185, 129, 0.16);
}

.lux-fb-recipients__summary {
    display: flex;
    flex-wrap: wrap;
    gap: 0.35rem;
    padding: 0.45rem 0.8rem 0;
}

.lux-fb-recipients__summary-pill {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    padding: 0.22rem 0.55rem;
    border-radius: 999px;
    background: rgba(248, 250, 252, 0.95);
    box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.95);
    font-size: 0.5625rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-fb-recipients__summary-pill.is-ready {
    background: rgba(16, 185, 129, 0.12);
    box-shadow: inset 0 0 0 1px rgba(16, 185, 129, 0.18);
    color: #047857;
}

.lux-fb-recipients__body {
    flex: 1;
    min-height: 0;
    display: flex;
    flex-direction: column;
    margin: 0.5rem 0.65rem 0;
    overflow: hidden;
}

.lux-fb-recipients__list-wrap {
    flex: 1;
    min-height: 0;
    border: 1px solid rgba(226, 232, 240, 0.95);
    border-radius: 14px;
    overflow: auto;
    background: linear-gradient(180deg, #f8fafc, #fff);
}

.lux-fb-recipients__list-wrap.is-filled {
    border-color: rgba(16, 185, 129, 0.18);
    background: linear-gradient(180deg, rgba(236, 253, 245, 0.55), #fff 40%);
}

.lux-fb-recipients__footer {
    flex-shrink: 0;
    padding: 0.55rem 0.65rem 0.7rem;
    border-top: 1px solid rgba(226, 232, 240, 0.95);
    background: rgba(248, 250, 252, 0.95);
}

.lux-fb-recipients__list-wrap.has-error {
    border-color: #f87171;
}

/* Recipients empty — rich illustration */
.lux-fb-recipients__list-wrap .lux-fb-recipients-empty {
    height: 100%;
    min-height: 100%;
}

.lux-fb-recipients-empty {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;
    min-height: min-content;
    padding: 0.75rem 0.65rem 0.85rem;
    text-align: center;
}

.lux-fb-recipients-empty__glow {
    position: absolute;
    inset: 0;
    border-radius: inherit;
    background: linear-gradient(105deg, transparent 40%, rgba(255, 255, 255, 0.55) 50%, transparent 60%);
    pointer-events: none;
    opacity: 0.5;
}

.lux-fb-recipients-empty__art {
    position: relative;
    width: 100%;
    max-width: 8.5rem;
    margin: 0 auto 0.45rem;
}

.lux-fb-recipients-empty__art svg {
    display: block;
    width: 100%;
    height: auto;
    filter: drop-shadow(0 10px 22px rgba(15, 23, 42, 0.08));
}

.lux-fb-recipients-empty__copy {
    position: relative;
    width: 100%;
    min-width: 0;
}

.lux-fb-recipients-empty__eyebrow {
    display: inline-flex;
    align-items: center;
    margin-bottom: 0.35rem;
    padding: 0.15rem 0.5rem;
    border-radius: 999px;
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
    font-size: 0.5625rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--lux-primary-dark, #3730a3);
}

.lux-fb-recipients-empty__title {
    margin: 0 0 0.3rem;
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
    letter-spacing: -0.02em;
    line-height: 1.25;
}

.lux-fb-recipients-empty__text {
    margin: 0;
    font-size: 0.625rem;
    line-height: 1.45;
    color: #64748b;
}

.lux-fb-recipients-empty__hints {
    list-style: none;
    margin: 0.5rem 0 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0.28rem;
    text-align: left;
}

.lux-fb-recipients-empty__hints li {
    display: flex;
    align-items: flex-start;
    gap: 0.28rem;
    font-size: 0.5625rem;
    line-height: 1.35;
    color: #64748b;
    font-weight: 600;
}

.lux-fb-recipients-empty__hints li .fe {
    flex-shrink: 0;
    margin-top: 0.05rem;
    font-size: 0.6875rem;
    color: #10b981;
}

.lux-fb-recipients-empty__cta {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.3rem;
    margin-top: 0.55rem;
    min-height: 2rem;
    padding: 0 0.85rem;
    border: none;
    border-radius: 999px;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
    color: #fff;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    cursor: pointer;
    box-shadow: 0 6px 18px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    transition: transform 0.14s ease, box-shadow 0.14s ease;
}

.lux-fb-recipients-empty__cta:hover {
    transform: translateY(-1px);
    box-shadow: 0 10px 22px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.34);
}

.lux-fb-recipients.is-empty .lux-fb-recipients__list-wrap.has-error .lux-fb-recipients-empty__eyebrow {
    border-color: rgba(248, 113, 113, 0.35);
    background: rgba(254, 226, 226, 0.5);
    color: #b91c1c;
}

.lux-fb-recipients__list {
    margin: 0;
    padding: 0.45rem;
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 0.45rem;
}

.lux-fb-recipients__row {
    position: relative;
    display: grid;
    grid-template-columns: auto 1fr auto;
    align-items: center;
    gap: 0.65rem;
    padding: 0.7rem 0.75rem;
    border-radius: 14px;
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: linear-gradient(135deg, #fff, rgba(248, 250, 252, 0.96));
    box-shadow: 0 8px 18px rgba(15, 23, 42, 0.04);
    overflow: hidden;
    transition: border-color 0.14s ease, box-shadow 0.14s ease, transform 0.14s ease;
}

.lux-fb-recipients__row::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 3px;
    background: #94a3b8;
}

.lux-fb-recipients__row.is-tone-1::before { background: linear-gradient(180deg, #0ea5e9, #38bdf8); }
.lux-fb-recipients__row.is-tone-2::before { background: linear-gradient(180deg, #10b981, #34d399); }
.lux-fb-recipients__row.is-tone-3::before { background: linear-gradient(180deg, #f59e0b, #fbbf24); }
.lux-fb-recipients__row.is-tone-4::before { background: linear-gradient(180deg, #f43f5e, #fb7185); }
.lux-fb-recipients__row.is-tone-5::before { background: linear-gradient(180deg, #6366f1, #818cf8); }

.lux-fb-recipients__row:hover {
    border-color: rgba(16, 185, 129, 0.35);
    box-shadow: 0 12px 24px rgba(15, 23, 42, 0.07);
    transform: translateY(-1px);
}

.lux-fb-recipients__avatar {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.35rem;
    height: 2.35rem;
    border-radius: 12px;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.02em;
    color: #0f172a;
    background: linear-gradient(145deg, rgba(14, 165, 233, 0.16), rgba(255, 255, 255, 0.95));
    box-shadow: inset 0 0 0 1px rgba(14, 165, 233, 0.16);
    flex-shrink: 0;
}

.lux-fb-recipients__row.is-tone-2 .lux-fb-recipients__avatar {
    background: linear-gradient(145deg, rgba(16, 185, 129, 0.16), rgba(255, 255, 255, 0.95));
    box-shadow: inset 0 0 0 1px rgba(16, 185, 129, 0.16);
    color: #047857;
}

.lux-fb-recipients__row.is-tone-3 .lux-fb-recipients__avatar {
    background: linear-gradient(145deg, rgba(245, 158, 11, 0.18), rgba(255, 255, 255, 0.95));
    box-shadow: inset 0 0 0 1px rgba(245, 158, 11, 0.18);
    color: #b45309;
}

.lux-fb-recipients__row.is-tone-4 .lux-fb-recipients__avatar {
    background: linear-gradient(145deg, rgba(244, 63, 94, 0.14), rgba(255, 255, 255, 0.95));
    box-shadow: inset 0 0 0 1px rgba(244, 63, 94, 0.16);
    color: #be123c;
}

.lux-fb-recipients__row.is-tone-5 .lux-fb-recipients__avatar {
    background: linear-gradient(145deg, rgba(99, 102, 241, 0.16), rgba(255, 255, 255, 0.95));
    box-shadow: inset 0 0 0 1px rgba(99, 102, 241, 0.16);
    color: #4338ca;
}

.lux-fb-recipients__identity {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 0.18rem;
}

.lux-fb-recipients__name-row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.35rem;
    min-width: 0;
}

.lux-fb-recipients__identity strong {
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-fb-recipients__ready-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.2rem;
    padding: 0.12rem 0.4rem;
    border-radius: 999px;
    background: rgba(16, 185, 129, 0.12);
    color: #047857;
    font-size: 0.5625rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
}

.lux-fb-recipients__email {
    font-size: 0.6875rem;
    font-weight: 600;
    color: #475569;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-fb-recipients__domain {
    display: inline-flex;
    align-self: flex-start;
    padding: 0.1rem 0.4rem;
    border-radius: 999px;
    background: rgba(248, 250, 252, 0.95);
    box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.95);
    font-size: 0.5625rem;
    font-weight: 700;
    color: #64748b;
}

.lux-fb-recipients__remove {
    display: grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    padding: 0;
    border: 1px solid rgba(254, 202, 202, 0.95);
    border-radius: 10px;
    background: #fff;
    color: #dc2626;
    cursor: pointer;
    transition: background 0.14s ease, border-color 0.14s ease;
}

.lux-fb-recipients__remove:hover {
    background: #fef2f2;
    border-color: rgba(248, 113, 113, 0.75);
}

.lux-fb-recipients__footer .lux-fb-recipients__add-trigger {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.35rem;
    width: 100%;
    min-height: 2.25rem;
    margin: 0;
    padding: 0 0.85rem;
    border: none;
    border-radius: 999px;
    background: linear-gradient(135deg, #059669, #047857);
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #fff;
    cursor: pointer;
    box-shadow: 0 8px 20px rgba(5, 150, 105, 0.28);
    transition: transform 0.14s ease, box-shadow 0.14s ease;
}

.lux-fb-recipients__footer .lux-fb-recipients__add-trigger:hover {
    transform: translateY(-1px);
    box-shadow: 0 12px 24px rgba(5, 150, 105, 0.34);
}

.lux-fb-recipients__add-panel {
    flex-shrink: 0;
    margin: 0 0.65rem 0.7rem;
    padding: 0.7rem 0.75rem;
    border: 1px solid rgba(16, 185, 129, 0.22);
    border-radius: 14px;
    background: linear-gradient(180deg, rgba(236, 253, 245, 0.55), #fff);
    box-shadow: 0 10px 22px rgba(15, 23, 42, 0.05);
}

.lux-fb-recipients__add-panel-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.5rem;
    margin-bottom: 0.45rem;
}

.lux-fb-recipients__add-title {
    margin: 0;
    font-size: 0.625rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: #047857;
}

.lux-fb-recipients__add-hint {
    font-size: 0.5625rem;
    font-weight: 600;
    color: #94a3b8;
}

.lux-fb-recipients__add-fields {
    display: grid;
    grid-template-columns: 1fr;
    gap: 0.4rem;
}

.lux-fb-recipients__add-fields .form-group {
    margin-bottom: 0 !important;
}

.lux-fb-recipients__add-actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: flex-end;
    gap: 0.4rem;
    margin-top: 0.5rem;
    padding-top: 0.45rem;
    border-top: 1px solid #f1f5f9;
}

.lux-fb-recipients__btn {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    padding: 0.38rem 0.7rem;
    border-radius: 10px;
    border: 0px solid #e2e8f0;
    font-size: 0.6875rem;
    font-weight: 800;
    cursor: pointer;
    white-space: nowrap;
}

.lux-fb-recipients__btn.is-primary {
    color: #fff;
    border-color: transparent;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-accent, #14b8a6));
}

.lux-fb-recipients__btn.is-primary:disabled {
    opacity: 0.45;
    cursor: not-allowed;
}

.lux-fb-recipients__btn.is-ghost {
    color: #64748b;
    background: #f8fafc;
}

.lux-fb-recipients__btn.is-ghost:hover {
    color: #0f172a;
    border-color: #cbd5e1;
}

@media (max-width: 960px) {
    .lux-fb-create-form__layout {
        grid-template-columns: 1fr;
    }

    .lux-fb-create-form__aside {
