}

/* Campaign list — gutters come from .lux-register-list-section */
.lux-register-list-section.lux-feedback-list-section {
    padding: 0;
}

.lux-feedback-list {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.lux-feedback-list__section-head {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    margin: 0.35rem 0 0.15rem;
    padding: 0.45rem 0.7rem;
    border-radius: 12px;
    background: linear-gradient(135deg, rgba(14, 165, 233, 0.1), rgba(255, 255, 255, 0.92));
    border: 1px solid rgba(14, 165, 233, 0.16);
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #0369a1;
}

.lux-feedback-list__section-head i {
    font-size: 0.875rem;
}

.lux-feedback-list__section-count {
    margin-left: auto;
    min-width: 1.4rem;
    height: 1.4rem;
    padding: 0 0.4rem;
    border-radius: 999px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: rgba(3, 105, 161, 0.12);
    color: #0369a1;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0;
    text-transform: none;
}

.lux-feedback-recurring-label {
    margin: 0.75rem 0 0.35rem;
    padding: 0.35rem 0.65rem;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b;
    border-radius: 8px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
}

/* Project / item groups */
.lux-feedback-groups {
    display: flex;
    flex-direction: column;
    gap: 0.85rem;
}

.lux-feedback-group {
    border-radius: 18px;
    border: 1px solid rgba(148, 163, 184, 0.22);
    background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.96));
    box-shadow: 0 14px 34px rgba(15, 23, 42, 0.06);
    overflow: hidden;
}

.lux-feedback-group.is-expanded {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    box-shadow: 0 18px 40px rgba(15, 23, 42, 0.08);
}

.lux-feedback-group__header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    padding: 0.85rem 1rem;
    background: linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08), rgba(255, 255, 255, 0.96));
    border-bottom: 1px solid rgba(148, 163, 184, 0.14);
}

.lux-feedback-group__header:hover {
    background: linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12), rgba(255, 255, 255, 0.98));
}

.lux-feedback-group__toggle {
    display: inline-flex;
    align-items: center;
    gap: 0.7rem;
    min-width: 0;
    flex: 1;
    border: none;
    background: none;
    padding: 0;
    text-align: left;
    cursor: pointer;
    color: inherit;
}

.lux-feedback-group__chevron {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.6rem;
    height: 1.6rem;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.9);
    color: #64748b;
    flex-shrink: 0;
}

.lux-feedback-group__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.4rem;
    height: 2.4rem;
    border-radius: 12px;
    background: linear-gradient(145deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16), rgba(255, 255, 255, 0.95));
    color: var(--lux-primary, #5b5ff4);
    flex-shrink: 0;
    box-shadow: inset 0 0 0 1px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.lux-feedback-group__copy {
    display: flex;
    flex-direction: column;
    gap: 0.12rem;
    min-width: 0;
}

.lux-feedback-group__id {
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--lux-primary, #5b5ff4);
}

.lux-feedback-group__name {
    font-size: 0.9375rem;
    font-weight: 800;
    color: #0f172a;
    letter-spacing: -0.01em;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.lux-feedback-group__meta {
    font-size: 0.6875rem;
    font-weight: 600;
    color: #64748b;
}

.lux-feedback-group__stats {
    display: none;
    flex-shrink: 0;
}

@media (min-width: 720px) {
    .lux-feedback-group__stats {
        display: block;
    }
}

.lux-feedback-group__stat {
    display: inline-flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 0.05rem;
    padding: 0.35rem 0.65rem;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.88);
    box-shadow: inset 0 0 0 1px rgba(148, 163, 184, 0.18);
}

.lux-feedback-group__stat strong {
    font-size: 0.875rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1;
}

.lux-feedback-group__stat em {
    font-style: normal;
    font-size: 0.625rem;
    font-weight: 700;
    color: #94a3b8;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.lux-feedback-group__open {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.15rem;
    height: 2.15rem;
    border-radius: 11px;
    border: 1px solid rgba(148, 163, 184, 0.28);
    background: #fff;
    color: #475569;
    flex-shrink: 0;
    transition: border-color 0.14s ease, color 0.14s ease, background 0.14s ease;
}

.lux-feedback-group__open:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
    color: var(--lux-primary, #5b5ff4);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
}

.lux-feedback-group__body {
    padding: 0.75rem 0.85rem 0.9rem;
    background: linear-gradient(180deg, rgba(248, 250, 252, 0.7), rgba(255, 255, 255, 0.95));
}

/* Project details embedded banner */
.lux-feedback-page--embedded {
    padding: 0.15rem 0 1rem;
}

.lux-feedback-project-banner {
    position: relative;
    display: grid;
    gap: 1rem;
    margin: 0 var(--lux-page-gutter-x, 0.75rem) 0.85rem;
    padding: 1.15rem 1.2rem;
    border-radius: 20px;
    overflow: hidden;
    border: 1px solid rgba(148, 163, 184, 0.2);
    background:
        linear-gradient(135deg, rgba(124, 58, 237, 0.1), rgba(255, 255, 255, 0.96) 42%, rgba(14, 165, 233, 0.08));
    box-shadow: 0 18px 42px rgba(15, 23, 42, 0.07);
}

@media (min-width: 900px) {
    .lux-feedback-project-banner {
        grid-template-columns: minmax(0, 1.4fr) minmax(16rem, 1fr);
        align-items: center;
    }
}

.lux-feedback-project-banner__glow {
    position: absolute;
    inset: auto -10% -40% auto;
    width: 18rem;
    height: 18rem;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18), transparent 68%);
    pointer-events: none;
}

.lux-feedback-project-banner__copy {
    position: relative;
    z-index: 1;
    min-width: 0;
}

.lux-feedback-project-banner__eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    margin-bottom: 0.4rem;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #7c3aed;
}

.lux-feedback-project-banner__title {
    margin: 0;
    font-size: clamp(1.2rem, 1.8vw, 1.55rem);
    font-weight: 800;
    letter-spacing: -0.02em;
    color: #0f172a;
    line-height: 1.2;
}

.lux-feedback-project-banner__lede {
    margin: 0.4rem 0 0;
    max-width: 38rem;
    font-size: 0.8125rem;
    line-height: 1.5;
    color: #64748b;
}

.lux-feedback-project-banner__kpis {
    position: relative;
    z-index: 1;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.55rem;
}

.lux-feedback-project-banner__kpi {
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
    padding: 0.7rem 0.8rem;
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.88);
    box-shadow: inset 0 0 0 1px rgba(148, 163, 184, 0.18);
}

.lux-feedback-project-banner__kpi span {
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-feedback-project-banner__kpi strong {
    font-size: 1.125rem;
    font-weight: 800;
    color: #0f172a;
    letter-spacing: -0.02em;
    line-height: 1;
}

/* Campaign card */
.lux-feedback-card {
    position: relative;
    border-radius: 18px;
    border: 1px solid rgba(148, 163, 184, 0.22);
    background:
        linear-gradient(180deg, #ffffff 0%, #f8fafc 140%);
    box-shadow: 0 12px 28px rgba(15, 23, 42, 0.06);
    overflow: hidden;
    transition: border-color 0.16s ease, box-shadow 0.16s ease, transform 0.16s ease;
}

.lux-feedback-card:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    box-shadow: 0 18px 36px rgba(15, 23, 42, 0.09);
    transform: translateY(-1px);
}

.lux-feedback-card__accent {
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 4px;
    background: linear-gradient(180deg, #94a3b8, #cbd5e1);
}

/* Distinct status accent colors */
.lux-feedback-card.is-tone-draft .lux-feedback-card__accent {
    background: linear-gradient(180deg, #0284c7, #38bdf8);
}
.lux-feedback-card.is-tone-requested .lux-feedback-card__accent {
    background: linear-gradient(180deg, #d97706, #fbbf24);
}
.lux-feedback-card.is-tone-received .lux-feedback-card__accent {
    background: linear-gradient(180deg, #0d9488, #2dd4bf);
}
.lux-feedback-card.is-tone-reviewed .lux-feedback-card__accent {
    background: linear-gradient(180deg, #16a34a, #4ade80);
}
.lux-feedback-card.is-tone-closed .lux-feedback-card__accent {
    background: linear-gradient(180deg, #475569, #94a3b8);
}
.lux-feedback-card.is-tone-recurring .lux-feedback-card__accent {
    background: linear-gradient(180deg, #0891b2, #22d3ee);
}
.lux-feedback-card.is-tone-progress .lux-feedback-card__accent,
.lux-feedback-card.is-tone-default .lux-feedback-card__accent {
    background: linear-gradient(180deg, #4f46e5, #818cf8);
}
.lux-feedback-card.is-tone-expired .lux-feedback-card__accent {
    background: linear-gradient(180deg, #dc2626, #fb7185);
}
.lux-feedback-card.is-tone-off .lux-feedback-card__accent,
.lux-feedback-card.is-tone-paused .lux-feedback-card__accent {
    background: linear-gradient(180deg, #64748b, #cbd5e1);
}
.lux-feedback-card.is-tone-empty .lux-feedback-card__accent {
    background: linear-gradient(180deg, #a855f7, #c084fc);
}

.lux-feedback-card.is-expanded {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
    box-shadow: 0 10px 26px rgba(15, 23, 42, 0.08);
}

.lux-feedback-card__bar {
    display: grid;
    gap: 0.85rem;
    padding: 0.95rem 1rem 0.95rem 1.15rem;
    cursor: pointer;
}

@media (min-width: 960px) {
    .lux-feedback-card__bar {
        grid-template-columns: minmax(0, 1.45fr) minmax(15rem, 0.9fr);
        align-items: start;
    }
}

.lux-feedback-card__main {
    display: flex;
    align-items: flex-start;
    gap: 0.75rem;
    min-width: 0;
}

.lux-feedback-card__badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.55rem;
    height: 2.55rem;
    border-radius: 14px;
    flex-shrink: 0;
    background: rgba(148, 163, 184, 0.14);
    color: #475569;
    box-shadow: inset 0 0 0 1px rgba(148, 163, 184, 0.18);
}

.lux-feedback-card__badge.is-draft {
    background: rgba(2, 132, 199, 0.14);
    color: #0369a1;
}
.lux-feedback-card__badge.is-requested {
    background: rgba(217, 119, 6, 0.16);
    color: #b45309;
}
.lux-feedback-card__badge.is-received {
    background: rgba(13, 148, 136, 0.14);
    color: #0f766e;
}
.lux-feedback-card__badge.is-reviewed {
    background: rgba(22, 163, 74, 0.14);
    color: #15803d;
}
.lux-feedback-card__badge.is-closed {
    background: rgba(71, 85, 105, 0.14);
    color: #334155;
}
.lux-feedback-card__badge.is-recurring {
    background: rgba(8, 145, 178, 0.14);
    color: #0e7490;
}
.lux-feedback-card__badge.is-progress,
.lux-feedback-card__badge.is-default {
    background: rgba(79, 70, 229, 0.14);
    color: #4338ca;
}
.lux-feedback-card__badge.is-expired {
    background: rgba(220, 38, 38, 0.14);
    color: #b91c1c;
}
.lux-feedback-card__badge.is-off,
.lux-feedback-card__badge.is-paused {
    background: rgba(100, 116, 139, 0.14);
    color: #475569;
}
.lux-feedback-card__badge.is-empty {
    background: rgba(168, 85, 247, 0.14);
    color: #7e22ce;
}

.lux-feedback-card__status-icon {
    flex-shrink: 0;
    font-size: 1rem;
}

.lux-feedback-card__status-icon.is-on { color: #16a34a; }
.lux-feedback-card__status-icon.is-off { color: #dc2626; }
.lux-feedback-card__status-icon.is-warn { color: #d97706; }
.lux-feedback-card__status-icon.is-info { color: #2563eb; }
.lux-feedback-card__status-icon.is-spin { color: #d97706; }

.lux-feedback-card__id {
    font-size: 0.6875rem;
    font-weight: 800;
    color: var(--lux-primary, #5b5ff4);
}

.lux-feedback-card__name {
    margin: 0;
    font-size: 0.9375rem;
    font-weight: 800;
    letter-spacing: -0.015em;
    color: #0f172a;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.lux-feedback-card__side {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 0.65rem;
    min-width: 0;
}

.lux-feedback-card__metrics {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.4rem;
}

.lux-feedback-card__metric {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
    padding: 0.45rem 0.5rem;
    border-radius: 12px;
    background: rgba(248, 250, 252, 0.95);
    box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.95);
}

.lux-feedback-card__metric span {
    font-size: 0.5625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-feedback-card__metric strong {
    font-size: 0.875rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1;
}

.lux-feedback-card__metric.is-good strong { color: #15803d; }
.lux-feedback-card__metric.is-warn strong { color: #b45309; }
.lux-feedback-card__metric.is-rate strong { color: var(--lux-primary, #5b5ff4); }

.lux-feedback-card__actions {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 0.4rem;
    flex-wrap: wrap;
}

.lux-feedback-card__counts {
    display: inline-flex;
    align-items: center;
    gap: 0.15rem;
    font-size: 0.6875rem;
    font-weight: 700;
}

.lux-feedback-card__count-received {
    padding: 0.12rem 0.4rem;
    border-radius: 999px;
    background: rgba(22, 163, 74, 0.12);
    color: #15803d;
}

.lux-feedback-card__count-pending {
    padding: 0.12rem 0.4rem;
    border-radius: 999px;
    background: rgba(245, 158, 11, 0.15);
    color: #b45309;
}

.lux-feedback-card__date {
    font-size: 0.6875rem;
    font-weight: 600;
    color: #64748b;
    white-space: nowrap;
}

.lux-feedback-card__cron {
    font-size: 0.6875rem;
    color: #94a3b8;
    max-width: 10rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.lux-feedback-card__progress {
    grid-column: 1 / -1;
}

.lux-feedback-card__progress-track {
    height: 0.35rem;
    border-radius: 999px;
    background: rgba(226, 232, 240, 0.95);
    overflow: hidden;
}

.lux-feedback-card__progress-fill {
    height: 100%;
    border-radius: inherit;
    background: linear-gradient(90deg, var(--lux-primary, #5b5ff4), #34d399);
    transition: width 0.25s ease;
}

.lux-feedback-card__icon-btn {
    width: 2rem;
    height: 2rem;
    border: 1px solid rgba(148, 163, 184, 0.28);
    border-radius: 10px;
    background: #fff;
    color: #475569;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: border-color 0.14s ease, color 0.14s ease, background 0.14s ease;
}

.lux-feedback-card__icon-btn:hover:not(:disabled) {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
    color: var(--lux-primary, #5b5ff4);
}

.lux-feedback-card__icon-btn:disabled {
    opacity: 0.45;
    cursor: not-allowed;
}

.lux-feedback-card__icon-btn.is-delete:hover {
    color: #dc2626;
    border-color: rgba(220, 38, 38, 0.35);
    background: #fef2f2;
}

.lux-feedback-card__detail {
    padding: 0.65rem 0.85rem 0.75rem;
    border-top: 1px solid rgba(148, 163, 184, 0.18);
    background: linear-gradient(180deg, #f8fafc, #fff);
}

.lux-feedback-detail-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.55rem 0.75rem;
}

.lux-feedback-detail-item label {
    display: block;
    margin: 0 0 0.15rem;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-feedback-detail-item span,
.lux-feedback-detail-item a {
    display: block;
    font-size: 0.75rem;
    font-weight: 600;
    color: #0f172a;
    line-height: 1.4;
}

.lux-feedback-detail-item a {
    color: var(--lux-primary, #5b5ff4);
}

.lux-feedback-recipients {
    grid-column: 1 / -1;
    margin-top: 0.35rem;
    padding: 0.65rem 0.75rem;
    border-radius: 12px;
    border: 0px solid rgba(148, 163, 184, 0.25);
    background: #fff;
}

.lux-feedback-recipients__title {
    margin: 0 0 0.5rem;
    font-size: 0.75rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-feedback-recipients__empty {
    text-align: center;
    padding: 1rem;
    font-size: 0.8125rem;
    color: #64748b;
}

/* Recipient row */
.lux-feedback-recipient {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    padding: 0.7rem 0.75rem 0.7rem 0.85rem;
    margin-bottom: 0.45rem;
    border-radius: 14px;
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: linear-gradient(135deg, #fff, rgba(248, 250, 252, 0.96));
    box-shadow: 0 8px 18px rgba(15, 23, 42, 0.04);
    overflow: hidden;
}

.lux-feedback-recipient:last-child {
    margin-bottom: 0;
}

.lux-feedback-recipient__accent {
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 3px;
    background: #94a3b8;
}

.lux-feedback-recipient.is-status-draft .lux-feedback-recipient__accent { background: linear-gradient(180deg, #0284c7, #38bdf8); }
.lux-feedback-recipient.is-status-requested .lux-feedback-recipient__accent { background: linear-gradient(180deg, #d97706, #fbbf24); }
.lux-feedback-recipient.is-status-received .lux-feedback-recipient__accent { background: linear-gradient(180deg, #0d9488, #2dd4bf); }
.lux-feedback-recipient.is-status-reviewed .lux-feedback-recipient__accent { background: linear-gradient(180deg, #16a34a, #4ade80); }
.lux-feedback-recipient.is-status-closed .lux-feedback-recipient__accent { background: linear-gradient(180deg, #475569, #94a3b8); }
.lux-feedback-recipient.is-status-default .lux-feedback-recipient__accent { background: linear-gradient(180deg, #4f46e5, #818cf8); }
.lux-feedback-recipient.is-expired .lux-feedback-recipient__accent { background: linear-gradient(180deg, #dc2626, #fb7185); }

.lux-feedback-recipient__main {
    display: flex;
    align-items: center;
    gap: 0.65rem;
    min-width: 0;
    flex: 1;
}

.lux-feedback-recipient__avatar {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.25rem;
    height: 2.25rem;
    border-radius: 11px;
    font-size: 0.6875rem;
    font-weight: 800;
    flex-shrink: 0;
    background: rgba(148, 163, 184, 0.14);
    color: #475569;
    box-shadow: inset 0 0 0 1px rgba(148, 163, 184, 0.18);
}

.lux-feedback-recipient__avatar.is-draft { background: rgba(2, 132, 199, 0.14); color: #0369a1; box-shadow: inset 0 0 0 1px rgba(2, 132, 199, 0.18); }
.lux-feedback-recipient__avatar.is-requested { background: rgba(217, 119, 6, 0.16); color: #b45309; box-shadow: inset 0 0 0 1px rgba(217, 119, 6, 0.2); }
.lux-feedback-recipient__avatar.is-received { background: rgba(13, 148, 136, 0.14); color: #0f766e; box-shadow: inset 0 0 0 1px rgba(13, 148, 136, 0.18); }
.lux-feedback-recipient__avatar.is-reviewed { background: rgba(22, 163, 74, 0.14); color: #15803d; box-shadow: inset 0 0 0 1px rgba(22, 163, 74, 0.18); }
.lux-feedback-recipient__avatar.is-closed { background: rgba(71, 85, 105, 0.14); color: #334155; box-shadow: inset 0 0 0 1px rgba(71, 85, 105, 0.18); }

.lux-feedback-recipient__copy {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
}

.lux-feedback-recipient__title-row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.35rem;
    min-width: 0;
}

.lux-feedback-recipient__icon {
    font-size: 0.9rem;
    flex-shrink: 0;
}

.lux-feedback-recipient__name {
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.lux-feedback-recipient__email {
    font-size: 0.6875rem;
    font-weight: 600;
    color: #64748b;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.lux-feedback-recipient__actions {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    flex-shrink: 0;
}

.lux-feedback-recipient__date {
    font-size: 0.6875rem;
    color: #94a3b8;
    white-space: nowrap;
}

.lux-feedback-status-pill {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.18rem 0.5rem;
    border-radius: 999px;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    white-space: nowrap;
}

.lux-feedback-status-pill.is-draft {
    background: rgba(2, 132, 199, 0.14);
    color: #0369a1;
}
.lux-feedback-status-pill.is-requested {
    background: rgba(217, 119, 6, 0.16);
    color: #b45309;
}
.lux-feedback-status-pill.is-received {
    background: rgba(13, 148, 136, 0.14);
    color: #0f766e;
}
.lux-feedback-status-pill.is-reviewed {
    background: rgba(22, 163, 74, 0.14);
    color: #15803d;
}
.lux-feedback-status-pill.is-closed {
    background: rgba(71, 85, 105, 0.16);
    color: #334155;
}
.lux-feedback-status-pill.is-default {
    background: rgba(79, 70, 229, 0.12);
    color: #4338ca;
}
.lux-feedback-status-pill.is-expired,
.lux-feedback-status-pill.is-off {
    background: rgba(220, 38, 38, 0.12);
    color: #b91c1c;
}

/* Template config panel */
.right_sidebar.lux-create-panel--feedback-template {
    width: min(1120px, 96vw) !important;
    right: calc(-1 * min(1120px, 96vw) - 24px) !important;
}

.right_sidebar.lux-create-panel--feedback-template.open {
    right: 0 !important;
}

.right_sidebar.lux-create-panel--feedback-template .lux-create-panel__body {
    display: flex;
    flex-direction: column;
    min-height: 0;
    overflow: hidden;
    padding: 0;
}

.lux-feedback-template-panel__body {
    flex: 1;
    min-height: 0;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

/* Feedback request create panel */
.right_sidebar.lux-create-panel--feedback-request {
    width: min(1080px, 96vw) !important;
    right: calc(-1 * min(1080px, 96vw) - 24px) !important;
}

.right_sidebar.lux-create-panel--feedback-request.open {
    right: 0 !important;
}

.right_sidebar.lux-create-panel--feedback-request .lux-create-panel__body {
    display: flex;
    flex-direction: column;
    min-height: 0;
    overflow: hidden;
    padding: 0;
}

.lux-feedback-request-panel__body {
    flex: 1;
    min-height: 0;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.lux-create-panel--feedback-request .lux-fb-create-form--panel {
    flex: 1;
    min-height: 0;
    height: 100%;
}

.lux-create-panel--feedback-request .lux-fb-create-form__scroll {
    flex: 1;
    min-height: 0;
    overflow: auto;
}

.lux-create-panel--feedback-request .lux-fb-create-form__aside {
    position: static;
    top: auto;
}

.lux-create-panel--feedback-request .lux-fb-create-section--schedule {
