    width: 100%;
}

.lux-create-panel--feedback-request .react-datepicker-wrapper .form-control {
    width: 100%;
}

/* Feedback template editor */
.lux-feedback-template-editor {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-height: 0;
    height: 100%;
}

.lux-feedback-template-editor__layout {
    display: grid;
    grid-template-columns: minmax(16rem, 19rem) minmax(0, 1fr);
    flex: 1;
    min-height: 0;
    margin: 0 0.85rem;
    border: 1px solid rgba(226, 232, 240, 0.95);
    border-radius: 18px;
    overflow: hidden;
    background: rgba(255, 255, 255, 0.96);
    box-shadow: 0 16px 40px rgba(15, 23, 42, 0.07);
    position: relative;
    z-index: 1;
}

.lux-feedback-template-editor__list-pane {
    display: flex;
    flex-direction: column;
    min-height: 0;
    border-right: 1px solid #e2e8f0;
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06), transparent 55%),
        #f8fafc;
}

.lux-feedback-template-editor__list-head {
    padding: 0.85rem 0.75rem 0.7rem;
    border-bottom: 1px solid #e2e8f0;
}

.lux-feedback-template-editor__list-title-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.5rem;
}

.lux-feedback-template-editor__list-label {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-feedback-template-editor__count {
    padding: 0.1rem 0.45rem;
    border-radius: 999px;
    font-size: 0.625rem;
    font-weight: 800;
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18);
}

.lux-feedback-template-editor__filter {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    margin-top: 0.45rem;
    padding: 0.45rem 0.6rem;
    border: 1px solid #e2e8f0;
    border-radius: 12px;
    background: #fff;
    color: #94a3b8;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.8);
}

.lux-feedback-template-editor__filter input {
    flex: 1;
    min-width: 0;
    border: none;
    outline: none;
    background: transparent;
    font-size: 0.75rem;
    font-weight: 600;
    color: #0f172a;
}

.lux-feedback-template-editor__new {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.35rem;
    width: 100%;
    margin-top: 0.55rem;
    padding: 0.5rem 0.65rem;
    border: 1px dashed rgba(var(--lux-primary-rgb, 91, 95, 244), 0.4);
    border-radius: 12px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
    font-size: 0.6875rem;
    font-weight: 800;
    color: var(--lux-primary-dark, #3730a3);
    cursor: pointer;
    transition: border-color 0.14s ease, background 0.14s ease, box-shadow 0.14s ease;
}

.lux-feedback-template-editor__new:hover,
.lux-feedback-template-editor__new.is-inline:hover {
    border-style: solid;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-feedback-template-editor__new.is-inline {
    width: auto;
    margin-top: 0.65rem;
}

.lux-feedback-template-editor__list-body {
    flex: 1;
    min-height: 0;
    overflow: auto;
    padding: 0.45rem 0.55rem 0.65rem;
}

.lux-feedback-template-editor__list {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
    margin: 0;
    padding: 0;
    list-style: none;
}

.lux-feedback-template-editor__list-empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: 0.35rem;
    padding: 1.25rem 0.75rem;
    color: #64748b;
    font-size: 0.75rem;
}

.lux-feedback-template-editor__list-empty i {
    font-size: 1.35rem;
    color: #94a3b8;
}

.lux-feedback-template-editor__list-empty strong {
    color: #0f172a;
    font-size: 0.8125rem;
}

.lux-feedback-template-editor__item {
    border: 1px solid #e2e8f0;
    border-radius: 14px;
    background: #fff;
    transition: border-color 0.14s ease, box-shadow 0.14s ease, transform 0.14s ease;
}

.lux-feedback-template-editor__item.is-selected {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.38);
    box-shadow: 0 8px 20px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.lux-feedback-template-editor__item-main {
    display: flex;
    align-items: flex-start;
    gap: 0.3rem;
    padding: 0.42rem 0.45rem;
}

.lux-feedback-template-editor__item-select {
    flex: 1;
    min-width: 0;
    padding: 0;
    border: none;
    background: transparent;
    text-align: left;
    cursor: pointer;
}

.lux-feedback-template-editor__item-name {
    display: block;
    font-size: 0.75rem;
    font-weight: 800;
    color: #0f172a;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.lux-feedback-template-editor__item-meta {
    display: block;
    margin-top: 0.12rem;
    font-size: 0.625rem;
    font-weight: 600;
    color: #94a3b8;
}

.lux-feedback-template-editor__item-actions {
    display: inline-flex;
    align-items: center;
    gap: 0.15rem;
    flex-shrink: 0;
}

.lux-feedback-template-editor__item-action {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.7rem;
    height: 1.7rem;
    border: 1px solid #e2e8f0;
    border-radius: 10px;
    background: #fff;
    color: #64748b;
    text-decoration: none;
    cursor: pointer;
    transition: border-color 0.14s ease, color 0.14s ease, background 0.14s ease;
}

.lux-feedback-template-editor__item-action:hover {
    color: var(--lux-primary-dark, #3730a3);
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
}

.lux-feedback-template-editor__item-action.is-danger:hover {
    color: #be123c;
    border-color: rgba(244, 63, 94, 0.35);
    background: #fff1f2;
}

.lux-feedback-template-editor__form-pane {
    min-width: 0;
    min-height: 0;
    overflow: auto;
    padding: 0.85rem 0.95rem 0.85rem;
    background:
        radial-gradient(circle at 100% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.05), transparent 42%),
        linear-gradient(180deg, #fbfdff 0%, #ffffff 48%);
}

.lux-feedback-template-editor__status {
    display: flex;
    align-items: center;
    gap: 0.65rem;
    margin-bottom: 0.75rem;
    padding: 0.65rem 0.75rem;
    border-radius: 14px;
    border: 0px solid #e2e8f0;
    background:
        radial-gradient(circle at 100% 0%, rgba(20, 184, 166, 0.08), transparent 50%),
        #f8fafc;
}

.lux-feedback-template-editor__status-icon {
    width: 2rem;
    height: 2rem;
    display: grid;
    place-items: center;
    border-radius: 11px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    color: var(--lux-primary, #5b5ff4);
    flex-shrink: 0;
}

.lux-feedback-template-editor__status-copy {
    flex: 1;
    min-width: 0;
}

.lux-feedback-template-editor__status-copy strong {
    display: block;
    font-size: 0.8125rem;
    color: #0f172a;
}

.lux-feedback-template-editor__status-copy p {
    margin: 0.15rem 0 0;
    font-size: 0.6875rem;
    color: #64748b;
}

.lux-feedback-template-editor__preview-link {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    padding: 0.3rem 0.55rem;
    border-radius: 999px;
    border: 0px solid #e2e8f0;
    background: #fff;
    font-size: 0.625rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--lux-primary-dark, #3730a3);
    text-decoration: none;
}

.lux-feedback-template-editor__preview-link:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
}

/* Feedback template — editor hero (create / edit / preview) */
.lux-ft-hero {
    position: relative;
    margin-bottom: 0.75rem;
    padding: 0.95rem 1rem;
    border-radius: 18px;
    border: 1px solid rgba(226, 232, 240, 0.95);
    background:
        linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.92)),
        radial-gradient(circle at 100% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08), transparent 55%);
    box-shadow: 0 14px 34px rgba(15, 23, 42, 0.07);
    overflow: hidden;
}

.lux-ft-hero__glow {
    position: absolute;
    top: -45%;
    right: -8%;
    width: 220px;
    height: 220px;
    border-radius: 50%;
    pointer-events: none;
    background: radial-gradient(circle, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16), transparent 68%);
}

.lux-ft-hero--create .lux-ft-hero__glow {
    background: radial-gradient(circle, rgba(20, 184, 166, 0.2), transparent 68%);
}

.lux-ft-hero--preview .lux-ft-hero__glow {
    background: radial-gradient(circle, rgba(148, 163, 184, 0.18), transparent 68%);
}

.lux-ft-hero__inner {
    position: relative;
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.75rem;
    flex-wrap: wrap;
}

.lux-ft-hero__main {
    flex: 1;
    min-width: 0;
}

.lux-ft-hero__badges {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.35rem;
    margin-bottom: 0.35rem;
}

.lux-ft-hero__mode-pill {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    padding: 0.22rem 0.55rem;
    border-radius: 999px;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
}

.lux-ft-hero__mode-pill.is-create {
    color: #0f766e;
    background: #ccfbf1;
    border: 0px solid #99f6e4;
}

.lux-ft-hero__mode-pill.is-edit {
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.2);
}

.lux-ft-hero__mode-pill.is-preview {
    color: #475569;
    background: #f1f5f9;
    border: 0px solid #e2e8f0;
}

.lux-ft-hero__mode-pill.is-idle {
    color: #64748b;
    background: #f8fafc;
    border: 0px solid #e2e8f0;
}

.lux-ft-hero__ref {
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    color: #94a3b8;
}

.lux-ft-hero__title {
    margin: 0;
    font-size: 1.05rem;
    font-weight: 800;
    letter-spacing: -0.02em;
    color: #0f172a;
    line-height: 1.25;
}

.lux-ft-hero__subtitle {
    margin: 0.3rem 0 0;
    max-width: 34rem;
    font-size: 0.6875rem;
    line-height: 1.45;
    color: #64748b;
}

.lux-ft-hero__chips {
    display: flex;
    flex-wrap: wrap;
    gap: 0.3rem;
    margin: 0.5rem 0 0;
    padding: 0;
    list-style: none;
}

.lux-ft-hero__chip {
    display: inline-flex;
    align-items: center;
    gap: 0.22rem;
    padding: 0.18rem 0.45rem;
    border-radius: 999px;
    font-size: 0.625rem;
    font-weight: 700;
    color: #475569;
    background: #fff;
    border: 1px solid #e2e8f0;
}

.lux-ft-hero__chip.is-muted {
    color: #64748b;
    background: #f8fafc;
}

.lux-ft-hero__aside {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 0.35rem;
    flex-shrink: 0;
}

.lux-ft-hero__action {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.38rem 0.65rem;
    border-radius: 12px;
    font-size: 0.6875rem;
    font-weight: 800;
    cursor: pointer;
    text-decoration: none;
    border: 0px solid #e2e8f0;
    background: #fff;
    color: var(--lux-primary-dark, #3730a3);
}

.lux-ft-hero__action--preview:hover {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
}

.lux-ft-hero__action--ghost {
    color: #64748b;
    background: #f8fafc;
}

.lux-ft-hero__action--ghost:hover {
    color: #0f172a;
    border-color: #cbd5e1;
}

/* Feedback template — details panel */
.lux-ft-details {
    margin-bottom: 0.7rem;
    border: 1px solid rgba(226, 232, 240, 0.95);
    border-radius: 18px;
    background: #fff;
    box-shadow: 0 10px 28px rgba(15, 23, 42, 0.05);
    overflow: hidden;
}

.lux-ft-details--empty {
    background: rgba(248, 250, 252, 0.85);
}

.lux-ft-details__empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: 0.3rem;
    padding: 1.25rem 1rem;
    color: #64748b;
}

.lux-ft-details__empty i {
    font-size: 1.25rem;
    color: #94a3b8;
}

.lux-ft-details__empty strong {
    font-size: 0.8125rem;
    color: #334155;
}

.lux-ft-details__empty p {
    margin: 0;
    max-width: 18rem;
    font-size: 0.6875rem;
    line-height: 1.45;
}

.lux-ft-details__head {
    display: flex;
    align-items: flex-start;
    gap: 0.6rem;
    padding: 0.7rem 0.85rem;
    border-bottom: 1px solid #e2e8f0;
    background: linear-gradient(180deg, rgba(248, 250, 252, 0.95), rgba(255, 255, 255, 0.6));
}

.lux-ft-details__head-icon {
    width: 2.1rem;
    height: 2.1rem;
    display: grid;
    place-items: center;
    border-radius: 12px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary, #5b5ff4);
    flex-shrink: 0;
}

.lux-ft-details__head-copy h3 {
    margin: 0;
