    border: 0px solid rgba(226, 232, 240, 0.95);
    background: #fff;
    box-shadow: 0 6px 18px rgba(15, 23, 42, 0.04);
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.lux-fb-q--hero .lux-fb-q__card {
    padding: 1.15rem 1.1rem 1rem;
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
    background:
        radial-gradient(circle at 100% 0%, rgba(14, 165, 233, 0.06), transparent 45%),
        #fff;
    box-shadow: 0 12px 28px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-fb-q__label {
    display: block;
    margin: 0 0 0.55rem;
    font-size: 0.875rem;
    font-weight: 700;
    line-height: 1.4;
    color: #0f172a;
}

.lux-fb-q__required {
    margin-left: 0.15rem;
    color: #dc2626;
    font-weight: 800;
}

.lux-fb-q__hint {
    display: block;
    margin-top: 0.35rem;
    font-size: 0.75rem;
    color: #94a3b8;
}

/* Text inputs */
.lux-fb-form input[type="text"],
.lux-fb-form input[type="number"],
.lux-fb-form textarea,
.lux-fb-form select {
    width: 100%;
    padding: 0.6rem 0.75rem;
    border: 0px solid #e2e8f0;
    border-radius: 12px;
    background: #f8fafc;
    font-size: 0.875rem;
    color: #0f172a;
    transition: border-color 0.14s ease, box-shadow 0.14s ease, background 0.14s ease;
}

.lux-fb-form input:focus,
.lux-fb-form textarea:focus,
.lux-fb-form select:focus {
    outline: none;
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.45);
    background: #fff;
    box-shadow: 0 0 0 3px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.lux-fb-form textarea {
    min-height: 6.5rem;
    resize: vertical;
}

/* Star ratings — aligned buttons (overrides legacy feedback/style.css) */
.lux-fb-page .starRating,
.lux-fb-page .starRating.smallstar {
    display: none !important;
}

.lux-fb-stars {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.45rem;
    width: 100%;
}

.lux-fb-stars__row {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    flex-wrap: nowrap;
}

.lux-fb-stars__btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.85rem;
    height: 2.85rem;
    padding: 0;
    border: 0px solid #e2e8f0;
    border-radius: 14px;
    background: #fff;
    cursor: pointer;
    transition: transform 0.12s ease, border-color 0.14s ease, box-shadow 0.14s ease, background 0.14s ease;
}

.lux-fb-stars__btn .fa-star,
.lux-fb-stars__btn .lux-fb-stars__icon {
    display: block;
    font-size: 1.35rem;
    color: #cbd5e1;
    line-height: 1;
    width: 1em;
    height: 1em;
    text-align: center;
    pointer-events: none;
}

.lux-fb-stars__btn:hover:not(:disabled) {
    transform: translateY(-2px);
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
    box-shadow: 0 6px 14px rgba(15, 23, 42, 0.08);
}

.lux-fb-stars__btn.is-lit .fa-star,
.lux-fb-stars__btn.is-selected .fa-star {
    color: #f59e0b;
}

.lux-fb-stars__btn.colorred .fa-star { color: #ef4444 !important; }
.lux-fb-stars__btn.colororange .fa-star { color: #f97316 !important; }
.lux-fb-stars__btn.colorblue .fa-star { color: #3b82f6 !important; }
.lux-fb-stars__btn.colorlightgreen1 .fa-star { color: #22c55e !important; }
.lux-fb-stars__btn.colorgreen .fa-star { color: #16a34a !important; }

.lux-fb-stars__btn.colorred,
.lux-fb-stars__btn.colororange,
.lux-fb-stars__btn.colorblue,
.lux-fb-stars__btn.colorlightgreen1,
.lux-fb-stars__btn.colorgreen {
    border-color: rgba(148, 163, 184, 0.35);
    background: #fff;
}

.lux-fb-stars--hero .lux-fb-stars__btn {
    width: 3.25rem;
    height: 3.25rem;
}

.lux-fb-stars--hero .lux-fb-stars__btn .fa-star {
    font-size: 1.65rem;
}

.lux-fb-stars__hint {
    font-size: 0.75rem;
    font-weight: 600;
    color: #94a3b8;
    text-align: center;
}

.lux-fb-q__card--hero-rating {
    text-align: center;
}

.lux-fb-q__label--hero {
    text-align: center;
    font-size: 1.0625rem !important;
}

.lux-fb-section--hero .lux-fb-section__head--center {
    text-align: center;
}

.lux-fb-grid--hero {
    max-width: 36rem;
    margin: 0 auto;
}

/* Multi-dimension star rating — full width table */
.lux-fb-multi-rating {
    width: 100%;
}

.lux-fb-multi-rating__table {
    width: 100%;
    margin-top: 0.65rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 14px;
    background: #fff;
    overflow: visible;
}

.lux-fb-multi-rating__head,
.lux-fb-dimension-rating {
    display: grid;
    grid-template-columns: minmax(11rem, 30%) minmax(0, 1fr) 3.5rem;
    align-items: center;
    column-gap: 1rem;
    padding: 0.6rem 1rem;
}

.lux-fb-multi-rating__head {
    background: linear-gradient(180deg, #f1f5f9 0%, #e8eef4 100%);
    border-bottom: 1px solid #e2e8f0;
    border-radius: 14px 14px 0 0;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-fb-multi-rating__col--stars {
    text-align: center;
}

.lux-fb-multi-rating__col--score {
    text-align: right;
}

.lux-fb-multi-rating__body .lux-fb-dimension-rating {
    border-bottom: 1px solid rgba(226, 232, 240, 0.85);
    background: #fff;
}

.lux-fb-multi-rating__body .lux-fb-dimension-rating:last-child {
    border-bottom: none;
    border-radius: 0 0 14px 14px;
}

.lux-fb-page .lux-fb-q__card .rating,
.lux-fb-page .lux-fb-q__card .ratingInner {
    margin: 0;
    padding: 0;
    min-height: 0;
    background: transparent;
    border-radius: 0;
}

.lux-fb-dimension-rating__title {
    margin: 0;
    font-size: 0.875rem;
    font-weight: 700;
    color: #0f172a;
    line-height: 1.35;
    word-break: break-word;
}

.lux-fb-dimension-rating__stars-cell {
    min-width: 0;
    width: 100%;
    overflow: visible;
}

.lux-fb-dimension-rating__stars-cell .lux-fb-stars {
    width: 100%;
    max-width: none;
    align-items: stretch;
}

.lux-fb-stars--matrix .lux-fb-stars__row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.4rem;
    width: 100%;
    flex-wrap: nowrap;
}

.lux-fb-stars--matrix .lux-fb-stars__btn {
    flex: 1 1 0;
    min-width: 2.15rem;
    max-width: 3.25rem;
    width: auto;
    height: 2.5rem;
    padding: 0;
}

.lux-fb-stars--matrix .lux-fb-stars__btn .fa-star,
.lux-fb-stars--matrix .lux-fb-stars__btn .lux-fb-stars__icon {
    font-size: 1.15rem;
}

.lux-fb-dimension-rating__score {
    font-size: 0.8125rem;
    font-weight: 800;
    color: #64748b;
    text-align: right;
    white-space: nowrap;
}

.lux-fb-form .ratingInner {
    display: flex;
    flex-direction: column;
    gap: 0;
}

.lux-fb-thanks-line {
    margin: 0.75rem 0 0;
    text-align: center;
    font-size: 0.9375rem;
    font-weight: 700;
    color: var(--lux-primary, #5b5ff4);
}


/* Radio / checkbox options */
.lux-fb-form .radioField {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    margin: 0.35rem 0 0;
    padding: 0.45rem 0.55rem;
    border-radius: 10px;
    border: 0px solid transparent;
    cursor: pointer;
    transition: background 0.12s ease, border-color 0.12s ease;
}

.lux-fb-form .radioField:hover {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.05);
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.lux-fb-form .radioField label {
    margin: 0;
    font-size: 0.8125rem;
    font-weight: 600;
    color: #334155;
    cursor: pointer;
}

.lux-fb-form .radioField input[type="radio"],
.lux-fb-form .radioField input[type="checkbox"] {
    width: 1rem;
    height: 1rem;
    accent-color: var(--lux-primary, #5b5ff4);
}

/* Reactions */
.lux-fb-form .reactions {
    padding: 0.25rem 0;
}

.lux-fb-form .reaction_inner {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 0.65rem;
    margin: 0.65rem 0;
}

.lux-fb-form .emoji {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.25rem;
    padding: 0.5rem;
    border-radius: 14px;
    border: 2px solid transparent;
    cursor: pointer;
    transition: border-color 0.14s ease, transform 0.12s ease, background 0.14s ease;
}

.lux-fb-form .emoji:hover,
.lux-fb-form .emoji_img.colorgreen {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
    transform: translateY(-2px);
}

.lux-fb-form .emoji_img img {
    width: 3rem;
    height: 3rem;
    object-fit: contain;
}

.lux-fb-form .emoji span {
    font-size: 0.6875rem;
    font-weight: 700;
    color: #64748b;
}

.lux-fb-form .info-text {
    display: flex;
    align-items: flex-start;
    gap: 0.45rem;
    margin-top: 0.65rem;
    padding: 0.65rem 0.75rem;
    border-radius: 12px;
    background: rgba(14, 165, 233, 0.08);
    border: 0px solid rgba(14, 165, 233, 0.18);
}

.lux-fb-form .info-text h5 {
    margin: 0;
    font-size: 0.75rem;
    font-weight: 600;
    line-height: 1.45;
    color: #0369a1;
}

.lux-fb-form .info-text .fa-circle-info {
    color: #0ea5e9;
    margin-top: 0.1rem;
}

/* Alerts & states */
.lux-fb-alert {
    margin: 0;
    padding: 0.75rem 0.95rem;
    border-radius: 14px;
    font-size: 0.875rem;
    font-weight: 600;
    line-height: 1.45;
}

.lux-fb-alert--error {
    background: rgba(239, 68, 68, 0.1);
    border: 0px solid rgba(239, 68, 68, 0.25);
    color: #b91c1c;
}

.lux-fb-alert--success {
    background: rgba(22, 163, 74, 0.1);
    border: 0px solid rgba(22, 163, 74, 0.25);
    color: #15803d;
}

.lux-fb-alert--info {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.2);
    color: #3730a3;
}

.lux-fb-loading {
    padding: 3rem 1.75rem;
    text-align: center;
    color: #64748b;
    font-weight: 600;
}

/* Footer actions */
.lux-fb-foot {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    margin-top: 1.25rem;
    padding-top: 1.15rem;
    border-top: 1px solid rgba(148, 163, 184, 0.25);
}

.lux-fb-foot__note {
    flex: 1;
    min-width: 12rem;
    margin: 0;
    font-size: 0.75rem;
    line-height: 1.45;
    color: #94a3b8;
}

.lux-fb-foot__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
}

.lux-fb-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    min-height: 2.5rem;
    padding: 0 1.15rem;
    border-radius: 9911px;
    border: 0px solid #e2e8f0;
    background: #fff;
    font-size: 0.8125rem;
    font-weight: 800;
    color: #475569;
    cursor: pointer;
    transition: transform 0.12s ease, box-shadow 0.14s ease, border-color 0.14s ease;
}

.lux-fb-btn:hover:not(:disabled) {
    transform: translateY(-1px);
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.3);
    box-shadow: 0 6px 16px rgba(15, 23, 42, 0.08);
}

.lux-fb-btn--primary {
    border: none;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
    color: #fff;
    box-shadow: 0 10px 24px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
}

.lux-fb-btn--primary:hover:not(:disabled) {
    box-shadow: 0 14px 28px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
}

.lux-fb-btn img {
    width: 1.25rem;
    height: 1.25rem;
}

.lux-fb-page__legal {
    margin-top: 1.25rem;
    text-align: center;
    font-size: 0.6875rem;
    color: #94a3b8;
    line-height: 1.5;
}

@media (max-width: 900px) {
    .lux-fb-shell-layout {
        grid-template-columns: 1fr;
    }

    .lux-fb-rich {
        width: 100%;
        max-width: none;
        position: static;
        max-height: none;
        border-left: none;
        border-top: 1px solid rgba(148, 163, 184, 0.2);
    }
}

@media (max-width: 720px) {
    .lux-fb-grid {
        grid-template-columns: 1fr;
    }

    .lux-fb-q--half {
        grid-column: 1 / -1;
    }

    .lux-fb-form,
    .lux-fb-hero,
    .lux-fb-rich {
        padding-left: 1.1rem;
        padding-right: 1.1rem;
    }

    .lux-fb-page__ribbon {
        font-size: 0.625rem;
        right: -3.25rem;
    }

    .lux-fb-multi-rating__head,
    .lux-fb-dimension-rating {
        grid-template-columns: 1fr;
        row-gap: 0.45rem;
        padding: 0.65rem 0.85rem;
    }

    .lux-fb-multi-rating__head {
        display: none;
    }

    .lux-fb-dimension-rating__stars-cell .lux-fb-stars--matrix .lux-fb-stars__row {
        justify-content: flex-start;
        gap: 0.35rem;
    }

    .lux-fb-stars--matrix .lux-fb-stars__btn {
        flex: 0 0 2.35rem;
        max-width: none;
    }

    .lux-fb-dimension-rating__score {
        text-align: left;
    }

    .lux-fb-stars__btn {
        width: 2.55rem;
        height: 2.55rem;
    }

    .lux-fb-stars--hero .lux-fb-stars__btn {
        width: 2.85rem;
        height: 2.85rem;
    }
}

