/* Project details — richer Activity / Team / Calendar / Alerts panels */
.lux-project-details-page .lux-pd-tab {
    position: relative;
    border: 1px solid rgba(226, 232, 240, 0.95);
    border-radius: 20px;
    overflow: hidden;
    background:
        radial-gradient(circle at 100% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06), transparent 40%),
        #fff;
