    z-index: 1;
}

.lux-pd-tab--activity::before {
    background: linear-gradient(180deg, #6366f1, #14b8a6);
}

.lux-pd-tab--team::before {
    background: linear-gradient(180deg, #8b5cf6, #0ea5e9);
}

.lux-pd-tab--calendar::before {
    background: linear-gradient(180deg, #0ea5e9, #8b5cf6);
}

.lux-pd-tab--alerts::before {
    background: linear-gradient(180deg, #f59e0b, #ef4444);
}

.lux-project-details-page .lux-pd-tab .lux-pd-tab__head,
.lux-project-details-page .lux-pd-tab .lux-settings-tab__head {
    padding: 1.15rem 1.25rem 1rem;
    background:
        linear-gradient(135deg, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.07), transparent 55%),
        #fff;
}

.lux-project-details-page .lux-pd-tab .lux-pd-tab__icon,
.lux-project-details-page .lux-pd-tab .lux-settings-tab__icon {
    width: 2.65rem;
    height: 2.65rem;
    border-radius: 14px;
    box-shadow: inset 0 0 0 1px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

