    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.24);
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
}

.lux-onb-summary__collapsed-strip {
    margin-bottom: 0.15rem;
}

.lux-onb-summary__collapsed-line {
    margin: 0;
    font-size: 0.75rem;
    color: #64748b;
    line-height: 1.45;
}

.lux-onb-summary__body {
    overflow: hidden;
    transition: max-height 0.28s ease, opacity 0.22s ease;
}

.lux-onb-summary__body .lux-onb-hero--queue {
    margin-bottom: 0.65rem;
    border-radius: 16px;
}

.lux-onb-summary__body .lux-onb-kpi-strip {
    margin-bottom: 0.65rem;
}

.lux-onb-summary__body .lux-onb-insights {
    margin-bottom: 0;
}

.lux-onb-summary--case .lux-onb-hero--detail {
    margin-bottom: 0.65rem;
    border-radius: 16px;
}

.lux-onb-summary--case .lux-onb-insight-strip {
    margin-bottom: 0;
}

/* F03-T5 — New-hire self-service portal */
.lux-onb-self-service-page .lux-onb-hero--self-service {
    margin-bottom: 0.65rem;
    border-radius: 16px;
}

.lux-onb-self-service__toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    flex-wrap: wrap;
    margin-bottom: 0.75rem;
}

.lux-onb-self-service__result-count {
    font-size: 0.72rem;
    font-weight: 700;
    color: #64748b;
    letter-spacing: 0.02em;
}

.lux-onb-self-service__panel {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.lux-onb-task--self-service .lux-onb-task__cta {
    display: inline-flex;
    align-items: center;
    gap: 0.2rem;
    flex-shrink: 0;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: var(--lux-primary-dark, #3730a3);
}

.lux-onb-task--self-service.is-actionable {
    border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18);
}

.lux-onb-task__status-chip {
    display: inline-flex;
    align-items: center;
    padding: 0.1rem 0.45rem;
    border-radius: 9911px;
    font-size: 0.62rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.lux-onb-task__status-chip.is-primary {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary-dark, #3730a3);
}

.lux-onb-task__status-chip.is-success,
.lux-onb-task__status-chip.is-green {
    background: rgba(16, 185, 129, 0.12);
    color: #047857;
}

.lux-onb-task__status-chip.is-neutral {
    background: rgba(148, 163, 184, 0.16);
    color: #475569;
}

.lux-onb-task__required-chip {
    display: inline-flex;
    padding: 0.1rem 0.4rem;
    border-radius: 9911px;
    background: rgba(245, 158, 11, 0.12);
    color: #b45309;
    font-size: 0.6rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.lux-onb-self-service__empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: 0.45rem;
    padding: 2rem 1rem;
    border-radius: 16px;
    background: rgba(248, 250, 252, 0.9);
    border: 1px dashed rgba(226, 232, 240, 0.95);
}

.lux-onb-self-service__empty-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 999px;
    background: rgba(16, 185, 129, 0.12);
    color: #059669;
    font-size: 1.1rem;
}

.lux-onb-self-service__empty h3 {
    margin: 0;
    font-size: 0.95rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-onb-self-service__empty p {
    margin: 0;
    max-width: 28rem;
    font-size: 0.78rem;
    color: #64748b;
    line-height: 1.5;
}

.lux-onb-self-service__skeleton {
    display: flex;
    flex-direction: column;
    gap: 0.65rem;
}

.lux-onb-self-service__skeleton-card {
    height: 5.5rem;
    border-radius: 16px;
    background: linear-gradient(90deg, #f1f5f9 0%, #e2e8f0 50%, #f1f5f9 100%);
    background-size: 200% 100%;
    animation: lux-onb-shimmer 1.2s ease-in-out infinite;
}

.lux-onb-hook-banner {
    display: flex;
    align-items: flex-start;
    gap: 0.55rem;
    margin-bottom: 0.75rem;
    padding: 0.65rem 0.75rem;
    border-radius: 14px;
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: rgba(248, 250, 252, 0.95);
}

.lux-onb-hook-banner.is-green {
    border-color: rgba(16, 185, 129, 0.28);
    background: rgba(16, 185, 129, 0.08);
}

.lux-onb-hook-banner.is-amber,
.lux-onb-hook-banner.is-pending {
    border-color: rgba(245, 158, 11, 0.3);
    background: rgba(251, 191, 36, 0.1);
}

.lux-onb-hook-banner.is-rose,
.lux-onb-hook-banner.is-failed {
    border-color: rgba(239, 68, 68, 0.28);
    background: rgba(254, 226, 226, 0.55);
}

.lux-onb-hook-banner__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.75rem;
    height: 1.75rem;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.85);
    color: #64748b;
    flex-shrink: 0;
}

.lux-onb-hook-banner__copy {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
    min-width: 0;
}

.lux-onb-hook-banner__copy strong {
    font-size: 0.72rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #0f172a;
}

.lux-onb-hook-banner__copy > span {
    font-size: 0.75rem;
    color: #64748b;
    line-height: 1.4;
}

.lux-onb-hook-banner__error {
    font-size: 0.72rem !important;
    color: #b91c1c !important;
    font-weight: 700;
}

.lux-onb-self-service__retry {
    border: none;
    background: none;
    padding: 0;
    font: inherit;
    font-weight: 800;
    color: var(--lux-primary-dark, #3730a3);
    text-decoration: underline;
    cursor: pointer;
}

@keyframes lux-onb-shimmer {
    0% { background-position: 100% 0; }
    100% { background-position: -100% 0; }
}

.lux-onb-page.lux-hrms-dash {
    padding: 0.75rem 0.75rem 1.5rem;
}

.lux-onb-page__error {
    margin: 0 0 0.75rem;
    padding: 0.65rem 0.85rem;
    border-radius: 14px;
    background: rgba(239, 68, 68, 0.08);
    color: #b91c1c;
    font-size: 0.82rem;
    font-weight: 700;
}

/* Hero variants */
.lux-onb-hero--queue.lux-onb-hero--join {
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14), transparent 50%),
        radial-gradient(circle at 100% 100%, rgba(16, 185, 129, 0.12), transparent 42%),
        linear-gradient(135deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.96));
}

.lux-onb-hero--queue.lux-onb-hero--exit {
    background:
        radial-gradient(circle at 0% 0%, rgba(245, 158, 11, 0.12), transparent 48%),
        radial-gradient(circle at 100% 100%, rgba(239, 68, 68, 0.08), transparent 42%),
        linear-gradient(135deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.96));
}

.lux-onb-hero--detail {
    align-items: center;
    flex-wrap: wrap;
}

.lux-onb-hero__detail-main {
    display: flex;
    align-items: center;
    gap: 0.85rem;
    flex: 1;
    min-width: 0;
}

.lux-onb-hero__detail-aside {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.55rem;
    flex-shrink: 0;
}

.lux-onb-hero__template {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    font-size: 0.72rem;
    font-weight: 700;
    color: #64748b;
}

/* Luxury action pills */
.lux-onb-action {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.35rem;
    min-height: var(--lux-action-min-height);
    padding: 0 0.9rem;
    border: none;
    border-radius: 999px;
    font-size: var(--lux-action-font-size);
    font-weight: 800;
    text-decoration: none;
    cursor: pointer;
    transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.lux-onb-action--compact {
    min-height: var(--lux-action-compact-min-height);
    padding: 0 0.7rem;
    font-size: 0.625rem;
}

.lux-onb-action--primary {
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
    color: #fff;
    box-shadow: 0 6px 16px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
}

.lux-onb-action--primary:hover {
    color: #fff;
    text-decoration: none;
    transform: translateY(-1px);
}

.lux-onb-action--ghost {
    background: rgba(255, 255, 255, 0.92);
    color: #475569;
    box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.95);
}

.lux-onb-action--ghost:hover {
    color: var(--lux-primary-dark, #3730a3);
    text-decoration: none;
}

/* Toolbar + filters */
.lux-onb-toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.85rem 1rem;
    margin-bottom: 0.85rem;
    padding: 0.75rem 0.9rem;
    border-radius: 16px;
    background: rgba(255, 255, 255, 0.72);
    box-shadow: 0 8px 20px rgba(15, 23, 42, 0.04);
}

.lux-onb-toolbar__grid {
    display: flex;
    align-items: flex-end;
    gap: 1.25rem;
    flex: 1;
    min-width: 0;
    flex-wrap: wrap;
}

.lux-onb-toolbar__status-col {
    flex: 1;
    min-width: min(100%, 320px);
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

.lux-onb-toolbar__dept-col {
    flex-shrink: 0;
    width: min(220px, 100%);
    display: flex;
    align-items: flex-end;
}

.lux-onb-toolbar__label {
    display: block;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
    line-height: 1;
}

.lux-onb-toolbar__chips {
    flex-wrap: wrap;
}

.lux-onb-toolbar__count {
    display: inline-flex;
    align-items: baseline;
    gap: 0.25rem;
    flex-shrink: 0;
    padding: 0.35rem 0.65rem;
    border-radius: 999px;
    background: rgba(248, 250, 252, 0.95);
    box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.9);
    font-size: 0.72rem;
    font-weight: 700;
    color: #64748b;
}

.lux-onb-toolbar__count strong {
    font-size: 0.82rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-onb-dept-filter.lux-att-employee-filter {
    width: 100%;
    min-width: 0;
}

.lux-onb-dept-filter.lux-att-employee-filter.is-header .lux-att-employee-filter__trigger {
    width: 100%;
    min-width: 0;
    max-width: none;
    min-height: 2.11rem;
    padding: 0.28rem 0.6rem;
    border-radius: 12px;
    box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.95);
}

.lux-onb-dept-filter .lux-att-employee-filter__trigger i.fe-briefcase {
    color: var(--lux-primary-dark, #3730a3);
    flex-shrink: 0;
}

.lux-onb-dept-filter .lux-att-employee-filter__trigger.is-open .lux-att-employee-filter__chevron {
    transform: rotate(180deg);
    opacity: 1;
}

.lux-onb-dept-filter .lux-att-employee-filter__chevron {
    transition: transform 0.18s ease, opacity 0.18s ease;
}

/* Case card grid */
.lux-onb-case-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 0.65rem;
}

.lux-onb-case-card {
    display: flex;
    flex-direction: column;
    gap: 0.65rem;
    padding: 0.85rem 0.9rem;
    border-radius: 18px;
    background:
        linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.94));
    box-shadow: 0 10px 24px rgba(15, 23, 42, 0.06);
    text-decoration: none;
    color: inherit;
    transition: transform 0.18s ease, box-shadow 0.18s ease;
}

.lux-onb-case-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 14px 32px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    text-decoration: none;
    color: inherit;
}

.lux-onb-case-card--exit:hover {
    box-shadow: 0 14px 32px rgba(245, 158, 11, 0.14);
}

.lux-onb-case-card--skeleton {
    min-height: 190px;
    animation: lux-onb-shimmer 1.2s ease-in-out infinite;
    background: linear-gradient(90deg, rgba(226,232,240,0.35), rgba(241,245,249,0.9), rgba(226,232,240,0.35));
    background-size: 200% 100%;
}

.lux-onb-case-card__top {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.5rem;
}

.lux-onb-case-card__identity {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    min-width: 0;
}

.lux-onb-case-card__avatar {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 14px;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), #818cf8);
    color: #fff;
    font-size: 0.78rem;
    font-weight: 900;
    flex-shrink: 0;
}

.lux-onb-case-card--exit .lux-onb-case-card__avatar {
    background: linear-gradient(135deg, #f59e0b, #ef4444);
}

.lux-onb-case-card__avatar--lg {
    width: 3.25rem;
    height: 3.25rem;
    font-size: 1rem;
    border-radius: 18px;
}

.lux-onb-case-card__name {
    display: block;
    font-size: 0.92rem;
    font-weight: 900;
    color: #0f172a;
    line-height: 1.2;
}

.lux-onb-case-card__role {
    display: block;
    font-size: 0.74rem;
    font-weight: 600;
    color: #64748b;
}

.lux-onb-case-card__meta {
    display: flex;
    flex-wrap: wrap;
    gap: 0.35rem 0.65rem;
    font-size: 0.72rem;
    font-weight: 600;
    color: #64748b;
}

.lux-onb-case-card__meta span {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
}

.lux-onb-case-card__progress-track {
    height: 7px;
    border-radius: 999px;
    background: rgba(226, 232, 240, 0.9);
    overflow: hidden;
}

.lux-onb-case-card__progress-fill {
    height: 100%;
    border-radius: inherit;
    background: linear-gradient(90deg, var(--lux-primary, #5b5ff4), #34d399);
}

.lux-onb-case-card--exit .lux-onb-case-card__progress-fill {
    background: linear-gradient(90deg, #f59e0b, #f97316);
}

.lux-onb-case-card__progress-labels {
    display: flex;
    justify-content: space-between;
    margin-top: 0.3rem;
    font-size: 0.72rem;
    font-weight: 700;
    color: #64748b;
}

.lux-onb-case-card__foot {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 0.45rem;
    padding-top: 0.35rem;
    border-top: 1px solid rgba(226, 232, 240, 0.8);
    font-size: 0.72rem;
    font-weight: 700;
}

.lux-onb-case-card__owner {
    color: #64748b;
}

.lux-onb-case-card__alert {
    color: #b45309;
}

.lux-onb-case-card__open {
    margin-left: auto;
    color: var(--lux-primary-dark, #3730a3);
}

/* Progress ring (detail hero) */
.lux-onb-progress-ring {
    --lux-onb-pct: 0;
    width: 4.5rem;
    height: 4.5rem;
    border-radius: 50%;
    display: grid;
    place-items: center;
    background:
        radial-gradient(closest-side, #fff 78%, transparent 80% 100%),
        conic-gradient(var(--lux-primary, #5b5ff4) calc(var(--lux-onb-pct) * 1%), rgba(226, 232, 240, 0.9) 0);
    box-shadow: 0 8px 20px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18);
}

.lux-onb-hero--exit .lux-onb-progress-ring {
    background:
        radial-gradient(closest-side, #fff 78%, transparent 80% 100%),
        conic-gradient(#f59e0b calc(var(--lux-onb-pct) * 1%), rgba(226, 232, 240, 0.9) 0);
}

.lux-onb-progress-ring__value {
    font-size: 0.9rem;
    font-weight: 900;
    color: #312e81;
}

/* Insight strip */
.lux-onb-insight-strip {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.55rem;
    margin-bottom: 0.85rem;
}

.lux-onb-insight {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.7rem 0.75rem;
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.88);
    box-shadow: 0 8px 18px rgba(15, 23, 42, 0.05);
}

.lux-onb-insight__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 10px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary-dark, #3730a3);
}

.lux-onb-insight__label {
    display: block;
    font-size: 0.6875rem;
    font-weight: 800;
    color: #94a3b8;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.lux-onb-insight__value {
    display: block;
    margin-top: 0.1rem;
    font-size: 0.88rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-onb-detail__cta {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 0.65rem;
    margin-bottom: 0.85rem;
    padding: 0.75rem 0.9rem;
    border-radius: 16px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06);
    box-shadow: inset 0 0 0 1px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.lux-onb-detail__cta-hint {
    font-size: 0.75rem;
    font-weight: 600;
    color: #64748b;
}

.lux-onb-detail__cta--done {
    background: rgba(34, 197, 94, 0.08);
    box-shadow: inset 0 0 0 1px rgba(34, 197, 94, 0.18);
    color: #15803d;
    font-size: 0.8125rem;
    font-weight: 700;
}

.lux-onb-detail__cta--done .fe-check-circle {
    color: #16a34a;
}

/* —— Lifecycle case detail page shell —— */
.lux-onb-detail__shell {
    display: flex;
    flex-direction: column;
    gap: 0.85rem;
    margin: 0 var(--lux-page-gutter-x, 1.25rem) 0.85rem;
}

.lux-onb-detail__shell .lux-onb-hero--detail {
    margin-bottom: 0;
    border-radius: 16px;
}

.lux-onb-detail__shell .lux-onb-detail__kpi {
    margin-bottom: 0;
}

.lux-onb-detail-quick-nav {
    margin-bottom: 0;
}

.lux-onb-detail .lux-hrms-dash__panel.lux-onb-checklist-section {
    margin: 0 var(--lux-page-gutter-x, 1.25rem) var(--lux-page-block-bottom, 1.5rem);
}

.lux-onb-settlement {
    flex-direction: column;
    align-items: stretch;
    gap: 0.75rem;
}

.lux-onb-settlement--ready {
    background: rgba(34, 197, 94, 0.08);
    box-shadow: inset 0 0 0 1px rgba(34, 197, 94, 0.18);
}

.lux-onb-settlement--blocked {
    background: rgba(245, 158, 11, 0.08);
    box-shadow: inset 0 0 0 1px rgba(245, 158, 11, 0.2);
}

.lux-onb-settlement__head {
    display: flex;
    gap: 0.65rem;
    align-items: flex-start;
}

.lux-onb-settlement__head .fe-dollar-sign {
    color: #b45309;
    font-size: 1.1rem;
    margin-top: 0.1rem;
}

.lux-onb-settlement--ready .lux-onb-settlement__head .fe-dollar-sign {
    color: #16a34a;
}

.lux-onb-settlement__blockers {
    margin: 0;
    padding-left: 1.1rem;
    font-size: 0.78rem;
    font-weight: 600;
    color: #b45309;
}

.lux-onb-settlement__tasks {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

.lux-onb-settlement__task-btn {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.5rem;
    border: none;
    border-radius: 10px;
    padding: 0.45rem 0.6rem;
    background: rgba(255, 255, 255, 0.65);
    font-size: 0.8rem;
    font-weight: 700;
    color: #0f172a;
    cursor: pointer;
}

.lux-onb-settlement__task-btn:hover {
    background: rgba(255, 255, 255, 0.95);
}

.lux-onb-audit__head {
    display: flex;
    gap: 0.75rem;
    align-items: flex-start;
    margin-bottom: 0.75rem;
}

.lux-onb-audit__list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.lux-onb-audit__list li {
    display: grid;
    grid-template-columns: 6.5rem 1fr;
    gap: 0.5rem 1rem;
    font-size: 0.875rem;
}

.lux-onb-audit__date {
    color: #64748b;
    font-weight: 600;
}

.lux-onb-audit__label {
    font-weight: 700;
    color: #0f172a;
}

.lux-onb-audit__detail {
    grid-column: 2;
    color: #475569;
    font-size: 0.8125rem;
}

/* F03 — Lifecycle template catalog */
.lux-onb-template-panel .lux-hrms-dash__panel-body {
    padding-top: 0.15rem;
}

.lux-onb-template-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 0.75rem;
}

.lux-onb-template-grid--loading {
    min-height: 12rem;
}

.lux-onb-template-card {
    display: flex;
    flex-direction: column;
    gap: 0.7rem;
    padding: 0.9rem 0.95rem;
    border-radius: 18px;
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08), transparent 52%),
        linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.94));
    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.8),
        0 10px 24px rgba(15, 23, 42, 0.06);
    transition: transform 0.18s ease, box-shadow 0.18s ease;
}

.lux-onb-template-card:hover {
    transform: translateY(-2px);
    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.85),
        0 14px 32px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.lux-onb-template-card--exit {
    background:
        radial-gradient(circle at 100% 0%, rgba(245, 158, 11, 0.1), transparent 52%),
        linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(255, 251, 235, 0.92));
}

.lux-onb-template-card--exit:hover {
    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.85),
        0 14px 32px rgba(245, 158, 11, 0.14);
}

.lux-onb-template-card--skeleton {
    min-height: 210px;
    animation: lux-onb-shimmer 1.2s ease-in-out infinite;
    background: linear-gradient(90deg, rgba(226, 232, 240, 0.35), rgba(241, 245, 249, 0.9), rgba(226, 232, 240, 0.35));
    background-size: 200% 100%;
}

.lux-onb-template-card__top {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.65rem;
}

.lux-onb-template-card__identity {
    display: flex;
    align-items: center;
    gap: 0.65rem;
    min-width: 0;
}

.lux-onb-template-card__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.65rem;
    height: 2.65rem;
    border-radius: 14px;
    flex-shrink: 0;
    background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), #818cf8);
    color: #fff;
    font-size: 0.78rem;
    font-weight: 900;
    letter-spacing: 0.03em;
    box-shadow: 0 8px 18px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
}

.lux-onb-template-card--exit .lux-onb-template-card__icon {
    background: linear-gradient(135deg, #f59e0b, #ef4444);
    box-shadow: 0 8px 18px rgba(245, 158, 11, 0.28);
}

.lux-onb-template-card__head-copy {
    min-width: 0;
}

.lux-onb-template-card__name {
    margin: 0;
    font-size: 0.92rem;
    font-weight: 900;
    color: #0f172a;
    line-height: 1.25;
}

.lux-onb-template-card__code {
    display: block;
    margin-top: 0.15rem;
    font-size: 0.68rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-onb-template-card__count {
    display: inline-flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-width: 3.1rem;
    padding: 0.35rem 0.5rem;
    border-radius: 12px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
    color: var(--lux-primary-dark, #3730a3);
    flex-shrink: 0;
}

.lux-onb-template-card__count strong {
    font-size: 1rem;
    font-weight: 900;
    line-height: 1;
}

.lux-onb-template-card__count span {
    margin-top: 0.1rem;
    font-size: 0.58rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
}

.lux-onb-template-card--exit .lux-onb-template-card__count {
    background: rgba(245, 158, 11, 0.12);
    color: #b45309;
}

.lux-onb-template-card__desc {
    margin: 0;
    font-size: 0.75rem;
    font-weight: 600;
    line-height: 1.45;
    color: #64748b;
}

.lux-onb-template-card__chips {
    display: flex;
    flex-wrap: wrap;
    gap: 0.35rem;
}

.lux-onb-template-card__chips span {
    display: inline-flex;
    align-items: center;
    gap: 0.28rem;
    padding: 0.28rem 0.5rem;
    border-radius: 999px;
    background: rgba(248, 250, 252, 0.95);
    box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.95);
    font-size: 0.68rem;
    font-weight: 700;
    color: #475569;
}

.lux-onb-template-card__chips span i {
    font-size: 0.72rem;
    color: #94a3b8;
}

.lux-onb-template-card__foot {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.5rem;
    margin-top: auto;
    padding-top: 0.55rem;
    border-top: 1px solid rgba(226, 232, 240, 0.85);
}

.lux-onb-template-card__status {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    font-size: 0.68rem;
    font-weight: 700;
    color: #047857;
}

.lux-onb-template-card__status i {
    font-size: 0.75rem;
}

.lux-onb-template-card__foot .lux-onb-action {
    margin-left: auto;
}

@media (max-width: 640px) {
    .lux-onb-template-grid {
        grid-template-columns: 1fr;
    }
}

/* F03 — Lifecycle template authoring (luxury drawer) */
.lux-onb-template-author {
    width: min(34rem, 100%);
}

.lux-onb-template-author .lux-onb-drawer__head {
    padding: 0.8rem 1rem 0.7rem;
}

.lux-onb-template-author .lux-onb-drawer__category-icon {
    width: 2.35rem;
    height: 2.35rem;
    border-radius: 14px;
    font-size: 0.9rem;
}

.lux-onb-template-author .lux-onb-drawer__head-copy h2 {
    margin: 0;
    font-size: 1.05rem;
    line-height: 1.25;
}

.lux-onb-template-author .lux-onb-drawer__task-id {
    margin-top: 0.25rem;
    font-size: 0.7rem;
    line-height: 1.35;
}

.lux-onb-template-author .lux-onb-drawer__body {
    padding-top: 0.65rem;
}

.lux-onb-template-author.is-exit .lux-onb-template-author__intro {
    background:
        radial-gradient(circle at 100% 0%, rgba(217, 119, 6, 0.12), transparent 55%),
        rgba(217, 119, 6, 0.05);
}

.lux-onb-template-author.is-exit .lux-onb-template-author__intro i,
.lux-onb-template-author.is-exit .lux-onb-template-author__field.is-highlight > span,
.lux-onb-template-author.is-exit .lux-onb-template-author__field.is-highlight > span i {
    color: #b45309;
}

.lux-onb-template-author.is-exit .lux-onb-template-author__task-icon {
    background: rgba(217, 119, 6, 0.14);
    color: #b45309;
}

.lux-onb-template-author.is-exit .lux-onb-template-author__add-btn {
    background: rgba(217, 119, 6, 0.12);
    color: #b45309;
}

.lux-onb-template-author.is-exit .lux-onb-template-author__pill.is-active {
    background: rgba(217, 119, 6, 0.14);
    color: #b45309;
    box-shadow: inset 0 0 0 1px rgba(217, 119, 6, 0.22);
}

.lux-onb-template-author__body {
    display: flex;
    flex-direction: column;
    gap: 0.85rem;
}

.lux-onb-template-author__intro {
    display: flex;
    align-items: flex-start;
    gap: 0.5rem;
    padding: 0.7rem 0.8rem;
    border-radius: 14px;
    background:
        radial-gradient(circle at 100% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1), transparent 55%),
        rgba(var(--lux-primary-rgb, 91, 95, 244), 0.05);
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.65);
}

.lux-onb-template-author__intro i {
    margin-top: 0.1rem;
    color: var(--lux-primary-dark, #3730a3);
    font-size: 0.9rem;
    flex-shrink: 0;
}

.lux-onb-template-author__intro p {
    margin: 0;
    font-size: 0.6875rem;
    font-weight: 600;
    color: #475569;
    line-height: 1.45;
}

.lux-onb-template-author__highlights {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.5rem;
    margin-bottom: 0.15rem;
}

.lux-onb-template-author__highlight {
    padding: 0.6rem 0.7rem;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.92);
    box-shadow: 0 4px 14px rgba(15, 23, 42, 0.04);
}

.lux-onb-template-author__highlight span {
    display: block;
    font-size: 0.5625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-onb-template-author__highlight strong {
    display: block;
    margin-top: 0.1rem;
    font-size: 1rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-onb-template-author__highlight.is-required strong { color: #b45309; }
.lux-onb-template-author__highlight.is-self strong { color: #047857; }

.lux-onb-template-author__error {
    display: flex;
    align-items: flex-start;
    gap: 0.4rem;
    margin: 0;
    padding: 0.6rem 0.7rem;
    border-radius: 12px;
    background: rgba(254, 242, 242, 0.95);
    font-size: 0.75rem;
    font-weight: 700;
    color: #b91c1c;
    line-height: 1.4;
}

.lux-onb-template-author__card {
    position: relative;
    padding: 0.85rem;
    border-radius: 16px;
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06), transparent 50%),
        rgba(255, 255, 255, 0.9);
    border: 0px solid rgba(226, 232, 240, 0.95);
    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.75),
        0 8px 22px rgba(15, 23, 42, 0.05);
    overflow: hidden;
}

.lux-onb-template-author__card.is-tasks {
    background:
        radial-gradient(circle at 100% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08), transparent 52%),
        rgba(248, 250, 252, 0.95);
    overflow: visible;
}

.lux-onb-template-author__card-head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.65rem;
    margin-bottom: 0.7rem;
    padding-bottom: 0.6rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.9);
}

.lux-onb-template-author__card-head h3 {
    margin: 0;
    display: flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.875rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-onb-template-author__card-head p {
    margin: 0.2rem 0 0;
    font-size: 0.6875rem;
    font-weight: 600;
    color: #64748b;
    line-height: 1.4;
}

.lux-onb-template-author__grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.65rem;
}

.lux-onb-template-author__field {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    margin: 0 0 0.65rem;
}

.lux-onb-template-author__field.is-wide {
    grid-column: 1 / -1;
}

.lux-onb-template-author__field > span {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-onb-template-author__field > span i {
    font-size: 0.7rem;
    color: #94a3b8;
}

.lux-onb-template-author__field.is-highlight > span {
    color: var(--lux-primary-dark, #3730a3);
}

.lux-onb-template-author__field.is-highlight > span i {
    color: var(--lux-primary-dark, #3730a3);
}

.lux-onb-template-author__input,
.lux-onb-template-author__textarea {
    width: 100%;
    min-height: 2.2rem;
    padding: 0.4rem 0.6rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.98);
    font-size: 0.875rem;
    font-weight: 600;
    color: #0f172a;
}

.lux-onb-template-author__textarea {
    min-height: 3.75rem;
    resize: vertical;
    line-height: 1.45;
}

.lux-onb-template-author__field.is-highlight .lux-onb-template-author__input,
.lux-onb-template-author__field.is-highlight .lux-onb-template-author__textarea {
    background: linear-gradient(
        180deg,
        rgba(var(--lux-primary-rgb, 91, 95, 244), 0.04),
        rgba(255, 255, 255, 0.98)
    );
    box-shadow: inset 0 0 0 1px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.lux-onb-template-author__input:focus,
.lux-onb-template-author__textarea:focus {
    outline: none;
    box-shadow:
        inset 0 0 0 1px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35),
        0 0 0 3px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
}

.lux-onb-template-author__add-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    min-height: 2rem;
    padding: 0 0.75rem;
    border: 0;
    border-radius: 999px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary-dark, #3730a3);
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    cursor: pointer;
    flex-shrink: 0;
    transition: background 0.15s ease, box-shadow 0.15s ease;
}

.lux-onb-template-author__add-btn:hover {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.16);
    box-shadow: 0 4px 12px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18);
}

.lux-onb-template-author__task-list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0.7rem;
}

.lux-onb-template-author__task-card {
    padding: 0.8rem;
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.92);
    border: 0px solid rgba(226, 232, 240, 0.95);
    box-shadow: 0 6px 18px rgba(15, 23, 42, 0.04);
}

.lux-onb-template-author__task-actions {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    flex-shrink: 0;
}

.lux-onb-template-author__duplicate {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.85rem;
    height: 1.85rem;
    border: 0;
    border-radius: 10px;
    background: rgba(148, 163, 184, 0.12);
    color: #64748b;
    cursor: pointer;
    transition: background 0.15s ease, color 0.15s ease;
}

.lux-onb-template-author__duplicate:hover {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    color: var(--lux-primary-dark, #3730a3);
}

.lux-onb-template-author__task-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.65rem;
    margin-bottom: 0.55rem;
}

.lux-onb-template-author__task-id {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    min-width: 0;
}

.lux-onb-template-author__task-icon {
    display: grid;
    place-items: center;
    width: 2.1rem;
    height: 2.1rem;
    border-radius: 10px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary-dark, #3730a3);
    font-size: 0.9rem;
    flex-shrink: 0;
}

.lux-onb-template-author__task-id strong {
    display: block;
    font-size: 0.75rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-onb-template-author__task-id span {
    display: block;
    font-size: 0.625rem;
    font-weight: 600;
    color: #64748b;
}

.lux-onb-template-author__remove {
    display: inline-grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    border: 0;
    border-radius: 10px;
    background: rgba(254, 242, 242, 0.95);
    color: #b91c1c;
    cursor: pointer;
    box-shadow: inset 0 0 0 1px rgba(225, 29, 72, 0.1);
    transition: transform 0.12s ease;
}

.lux-onb-template-author__remove:active {
    transform: translateY(1px);
}

.lux-onb-template-author__pills {
    display: flex;
    flex-wrap: wrap;
    gap: 0.45rem;
    margin-top: 0.15rem;
}

.lux-onb-template-author__pill {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    min-height: 1.85rem;
    padding: 0 0.65rem;
    border: 0;
    border-radius: 999px;
    background: rgba(248, 250, 252, 0.95);
    color: #64748b;
    font-size: 0.6875rem;
    font-weight: 700;
    cursor: pointer;
    box-shadow: inset 0 0 0 1px rgba(148, 163, 184, 0.28);
    transition: background 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
}

.lux-onb-template-author__pill.is-active {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
    color: var(--lux-primary-dark, #3730a3);
    box-shadow: inset 0 0 0 1px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.22);
}

.lux-onb-template-author__pill:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

@media (max-width: 640px) {
    .lux-onb-template-author__highlights,
    .lux-onb-template-author__grid {
        grid-template-columns: 1fr;
    }

    .lux-onb-template-author__card-head {
        flex-direction: column;
        align-items: stretch;
    }

    .lux-onb-template-author__add-btn {
        justify-content: center;
        width: 100%;
    }
}

/* F03 — Start lifecycle case drawer (luxury) */
.lux-onb-case-start {
    width: min(34rem, 100%);
}

.lux-onb-case-start__scroll {
    display: block;
}

.lux-onb-case-start__form {
    display: flex;
    flex-direction: column;
    gap: 0.85rem;
    min-height: min-content;
}

.lux-onb-case-start .lux-onb-template-author__card,
.lux-onb-case-start__card {
    overflow: visible;
    flex-shrink: 0;
}

.lux-onb-case-start__card--schedule .lux-onb-template-author__grid:last-child .lux-onb-template-author__field {
    margin-bottom: 0;
}

.lux-onb-case-start__highlights {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.5rem;
}

.lux-onb-case-start__highlights .lux-onb-template-author__highlight strong.is-text {
    font-size: 0.75rem;
    letter-spacing: 0.02em;
    text-transform: none;
    line-height: 1.25;
}

.lux-onb-case-start__loading {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    margin: 0;
    padding: 0.65rem 0.75rem;
    border-radius: 12px;
    background: rgba(248, 250, 252, 0.95);
    font-size: 0.75rem;
    font-weight: 700;
    color: #64748b;
}

.lux-onb-case-start__empty {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.75rem;
    padding: 0.85rem;
    border-radius: 14px;
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06), transparent 50%),
        rgba(255, 255, 255, 0.92);
    box-shadow: 0 6px 18px rgba(15, 23, 42, 0.04);
}

.lux-onb-case-start__empty > i {
    display: grid;
    place-items: center;
    width: 2.25rem;
    height: 2.25rem;
    border-radius: 10px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary-dark, #3730a3);
    font-size: 1rem;
    flex-shrink: 0;
}

.lux-onb-case-start__empty strong {
    display: block;
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-onb-case-start__empty p {
    margin: 0.15rem 0 0;
    font-size: 0.6875rem;
    font-weight: 600;
    color: #64748b;
}

.lux-onb-case-start__empty .lux-onb-action {
    margin-left: auto;
}

.lux-onb-case-start__template-desc {
    margin: -0.35rem 0 0;
    padding: 0.55rem 0.65rem;
    border-radius: 10px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.05);
