        justify-content: center;
    }
}

.lux-onb-convert__body {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.lux-onb-convert__grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.65rem 1rem;
}

.lux-onb-convert__field-label {
    display: block;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.04em;
