    margin-bottom: 0.15rem;
}

.lux-onb-convert__field-value {
    font-size: 0.875rem;
    font-weight: 700;
    color: #0f172a;
}

.lux-onb-convert__role {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
    font-size: 0.75rem;
    font-weight: 700;
    color: #475569;
}

.lux-onb-convert__role select {
    border-radius: 12px;
    border: 1px solid rgba(148, 163, 184, 0.35);
    padding: 0.55rem 0.7rem;
