    font-weight: 600;
}

.lux-onb-convert__blockers ul {
    margin: 0;
    padding-left: 1rem;
}

.lux-onb-convert__error {
    color: #b91c1c;
    font-size: 0.8125rem;
    font-weight: 700;
    margin: 0;
}

.lux-onb-convert__success {
    text-align: center;
    padding: 1.25rem 0.5rem;
}

.lux-onb-convert__success .fe-check-circle {
    font-size: 2rem;
    color: #16a34a;
}

.lux-onb-convert__success h3 {
    margin: 0.5rem 0 0.35rem;
    font-size: 1.125rem;
}

.lux-onb-convert__success-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    justify-content: center;
    margin-top: 1rem;
}

.lux-onb-convert__loading {
    color: #64748b;
    font-weight: 600;
}

/* Badges */
.lux-onb-badge {
    display: inline-flex;
    align-items: center;
    padding: 0.22rem 0.55rem;
    border-radius: 999px;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.02em;
    white-space: nowrap;
}

.lux-onb-badge--primary { background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12); color: #4338ca; }
.lux-onb-badge--success { background: rgba(34, 197, 94, 0.14); color: #15803d; }
.lux-onb-badge--warning { background: rgba(245, 158, 11, 0.16); color: #b45309; }
.lux-onb-badge--danger { background: rgba(239, 68, 68, 0.12); color: #b91c1c; }
.lux-onb-badge--info { background: rgba(14, 165, 233, 0.12); color: #0369a1; }
.lux-onb-badge--neutral,
.lux-onb-badge--muted { background: rgba(148, 163, 184, 0.16); color: #475569; }

/* Checklist */
.lux-onb-checklist-section {
    margin-top: 0.35rem;
    padding: 1rem 1.05rem 1.1rem;
    border-radius: 22px;
    background:
        radial-gradient(circle at 100% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.06), transparent 38%),
        linear-gradient(160deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.94));
    box-shadow: 0 14px 36px rgba(15, 23, 42, 0.07);
    border: 1px solid rgba(226, 232, 240, 0.75);
}

.lux-onb-checklist-hero {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 1rem;
    margin-bottom: 0.85rem;
    padding-bottom: 0.85rem;
    border-bottom: 1px solid rgba(241, 245, 249, 0.98);
}

.lux-onb-checklist-hero__eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.22rem 0.55rem;
    border-radius: 999px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    font-size: 0.65rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: var(--lux-primary-dark, #4338ca);
}

.lux-onb-checklist-hero__title {
    margin: 0.45rem 0 0;
    font-size: 1.15rem;
    font-weight: 900;
    color: #0f172a;
    letter-spacing: -0.02em;
}

.lux-onb-checklist-hero__desc {
    margin: 0.3rem 0 0;
    max-width: 36rem;
    font-size: 0.78rem;
    font-weight: 600;
    color: #64748b;
    line-height: 1.45;
}

.lux-onb-checklist-hero__stats {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    flex-shrink: 0;
}

.lux-onb-checklist-hero__ring {
    --lux-onb-ring: var(--lux-primary, #5b5ff4);
    width: 4.25rem;
    height: 4.25rem;
    border-radius: 50%;
    display: grid;
    place-items: center;
    background: conic-gradient(
        var(--lux-onb-ring) calc(var(--lux-onb-pct, 0) * 1%),
        rgba(226, 232, 240, 0.92) 0
    );
    box-shadow: 0 8px 20px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.lux-onb-checklist-hero__ring span {
    width: 3.15rem;
    height: 3.15rem;
    border-radius: 50%;
    display: grid;
    place-items: center;
    background: #fff;
    font-size: 0.78rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-onb-checklist-hero__figures {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
}

.lux-onb-checklist-hero__figures article {
    display: flex;
    flex-direction: column;
    gap: 0.05rem;
}

.lux-onb-checklist-hero__figures span {
    font-size: 0.65rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-onb-checklist-hero__figures strong {
    font-size: 0.9rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-onb-checklist-hero__figures strong.is-alert {
    color: #dc2626;
}

.lux-onb-checklist {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.lux-onb-checklist__group {
    --onb-tone: var(--lux-primary, #5b5ff4);
    --onb-tone-rgb: var(--lux-primary-rgb, 91, 95, 244);
    border-radius: 18px;
    overflow: hidden;
    background: rgba(255, 255, 255, 0.98);
    box-shadow: 0 10px 28px rgba(15, 23, 42, 0.05);
    border: 1px solid rgba(241, 245, 249, 0.98);
}

.lux-onb-checklist__group--violet { --onb-tone: #7c3aed; --onb-tone-rgb: 124, 58, 237; }
.lux-onb-checklist__group--blue { --onb-tone: #2563eb; --onb-tone-rgb: 37, 99, 235; }
.lux-onb-checklist__group--primary { --onb-tone: var(--lux-primary, #5b5ff4); --onb-tone-rgb: var(--lux-primary-rgb, 91, 95, 244); }
.lux-onb-checklist__group--green { --onb-tone: #16a34a; --onb-tone-rgb: 22, 163, 74; }
.lux-onb-checklist__group--teal { --onb-tone: #0d9488; --onb-tone-rgb: 13, 148, 136; }
.lux-onb-checklist__group--amber { --onb-tone: #d97706; --onb-tone-rgb: 217, 119, 6; }
.lux-onb-checklist__group--rose { --onb-tone: #e11d48; --onb-tone-rgb: 225, 29, 72; }
.lux-onb-checklist__group--slate { --onb-tone: #475569; --onb-tone-rgb: 71, 85, 105; }
.lux-onb-checklist__group--neutral { --onb-tone: #64748b; --onb-tone-rgb: 100, 116, 139; }

.lux-onb-checklist__group-head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.65rem;
    padding: 0.85rem 1rem 0.7rem;
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--onb-tone-rgb), 0.14), transparent 55%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.96));
    border-bottom: 1px solid rgba(241, 245, 249, 0.98);
}

.lux-onb-checklist__group-brand {
    display: flex;
    align-items: center;
    gap: 0.65rem;
    min-width: 0;
}

.lux-onb-checklist__group-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.35rem;
    height: 2.35rem;
    border-radius: 14px;
    background: linear-gradient(135deg, var(--onb-tone), rgba(var(--onb-tone-rgb), 0.65));
    color: #fff;
    font-size: 0.95rem;
    box-shadow: 0 8px 18px rgba(var(--onb-tone-rgb), 0.28);
    flex-shrink: 0;
}

.lux-onb-checklist__group-title {
    margin: 0;
    font-size: 0.95rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-onb-checklist__group-sub {
    margin: 0.15rem 0 0;
    font-size: 0.72rem;
    font-weight: 600;
    color: #64748b;
}

.lux-onb-checklist__group-pill {
    padding: 0.25rem 0.6rem;
    border-radius: 999px;
    background: rgba(var(--onb-tone-rgb), 0.12);
    font-size: 0.6875rem;
    font-weight: 800;
    color: var(--onb-tone);
    flex-shrink: 0;
}

.lux-onb-checklist__group-progress {
    height: 4px;
    background: rgba(226, 232, 240, 0.85);
}

.lux-onb-checklist__group-progress-fill {
    height: 100%;
    border-radius: inherit;
    background: linear-gradient(90deg, var(--onb-tone), rgba(var(--onb-tone-rgb), 0.55));
    transition: width 0.25s ease;
}

.lux-onb-checklist-empty {
    text-align: center;
    padding: 2.5rem 1rem;
    border-radius: 16px;
    background: rgba(248, 250, 252, 0.9);
    color: #64748b;
}

.lux-onb-checklist-empty i {
    font-size: 1.75rem;
    color: #94a3b8;
}

.lux-onb-task {
    width: 100%;
    display: grid;
    grid-template-columns: auto auto 1fr auto auto;
    align-items: center;
    gap: 0.55rem 0.65rem;
    padding: 0.75rem 0.85rem;
    border: none;
    border-radius: 0;
    background: transparent;
    text-align: left;
    cursor: pointer;
    position: relative;
    transition: background 0.15s ease, transform 0.15s ease;
}

.lux-onb-task::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0.35rem;
    bottom: 0.35rem;
    width: 3px;
    border-radius: 999px;
    background: rgba(var(--onb-tone-rgb), 0.35);
    opacity: 0;
    transition: opacity 0.15s ease;
}

.lux-onb-task:hover {
    background: rgba(var(--onb-tone-rgb), 0.04);
}

.lux-onb-task:hover::before {
    opacity: 1;
}

.lux-onb-task.is-completed {
    opacity: 0.78;
}

.lux-onb-task.is-completed .lux-onb-task__title {
    text-decoration: line-through;
    text-decoration-color: rgba(100, 116, 139, 0.45);
}

.lux-onb-task.is-completed .lux-onb-task__state {
    color: #16a34a;
}

.lux-onb-task.is-blocked .lux-onb-task__state,
.lux-onb-task.is-overdue .lux-onb-task__state {
    color: #dc2626;
}

.lux-onb-task__index {
    display: inline-grid;
    place-items: center;
    width: 1.35rem;
    height: 1.35rem;
    border-radius: 8px;
    background: rgba(var(--onb-tone-rgb), 0.1);
    font-size: 0.65rem;
    font-weight: 900;
    color: var(--onb-tone);
}

.lux-onb-task__state {
    font-size: 1rem;
    color: #94a3b8;
}

.lux-onb-task__body {
    min-width: 0;
}

.lux-onb-task__title {
    display: block;
    font-size: 0.84rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.25;
}

.lux-onb-task__meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.35rem;
    margin-top: 0.35rem;
}

.lux-onb-task__owner-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.15rem 0.45rem 0.15rem 0.2rem;
    border-radius: 999px;
    background: rgba(248, 250, 252, 0.95);
    box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.9);
    font-size: 0.68rem;
    font-weight: 700;
    color: #475569;
}

.lux-onb-task__owner-avatar {
    display: inline-grid;
    place-items: center;
    width: 1.15rem;
    height: 1.15rem;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--onb-tone), rgba(var(--onb-tone-rgb), 0.6));
    color: #fff;
    font-size: 0.55rem;
    font-weight: 900;
}

.lux-onb-task__due-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.2rem;
    padding: 0.15rem 0.45rem;
    border-radius: 999px;
    background: rgba(14, 165, 233, 0.1);
    font-size: 0.68rem;
    font-weight: 700;
    color: #0369a1;
}

.lux-onb-task__due-chip.is-overdue {
    background: rgba(239, 68, 68, 0.1);
    color: #b91c1c;
}

.lux-onb-task__optional-chip {
    padding: 0.15rem 0.45rem;
    border-radius: 999px;
    background: rgba(148, 163, 184, 0.14);
    font-size: 0.65rem;
    font-weight: 800;
    color: #64748b;
}

.lux-onb-task__chevron {
    color: #cbd5e1;
    font-size: 0.9rem;
    transition: transform 0.15s ease, color 0.15s ease;
}

.lux-onb-task:hover .lux-onb-task__chevron {
    color: var(--onb-tone);
    transform: translateX(2px);
}

.lux-onb-checklist__tasks {
    list-style: none;
    margin: 0;
    padding: 0.35rem 0.5rem 0.55rem;
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
}

.lux-onb-checklist__tasks li + li {
    border-top: 1px solid rgba(241, 245, 249, 0.98);
}

/* Drawer */
@keyframes lux-onb-drawer-backdrop-in {
    from { opacity: 0; }
    to { opacity: 1; }
}

@keyframes lux-onb-drawer-slide-in {
    from {
        opacity: 0;
        transform: translateX(28px);
    }
    to {
        opacity: 1;
        transform: translateX(0);
    }
}

@keyframes lux-onb-drawer-backdrop-out {
    from { opacity: 1; }
    to { opacity: 0; }
}

@keyframes lux-onb-drawer-slide-out {
    from {
        opacity: 1;
        transform: translateX(0);
    }
    to {
        opacity: 0;
        transform: translateX(28px);
    }
}

.lux-onb-drawer-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(8, 12, 28, 0.52);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    z-index: var(--lux-z-overlay);
    display: flex;
    justify-content: flex-end;
    overflow: hidden;
    animation: lux-onb-drawer-backdrop-in 0.22s ease;
}

.lux-onb-drawer-backdrop.is-closing {
    animation: lux-onb-drawer-backdrop-out 0.28s ease forwards;
}

.lux-onb-drawer {
    --onb-drawer-accent: var(--lux-primary, #5b5ff4);
    --onb-drawer-accent-rgb: var(--lux-primary-rgb, 91, 95, 244);
    position: relative;
    width: min(460px, 100%);
    height: 100%;
    max-height: 100vh;
    max-height: 100dvh;
    min-height: 0;
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--onb-drawer-accent-rgb), 0.08), transparent 42%),
        linear-gradient(180deg, rgba(255, 255, 255, 1) 0%, rgba(248, 250, 252, 0.98) 100%);
    box-shadow:
        -1px 0 0 rgba(255, 255, 255, 0.8) inset,
        -20px 0 60px rgba(15, 23, 42, 0.18);
    display: flex;
    flex-direction: column;
    overflow: hidden;
    animation: lux-onb-drawer-slide-in 0.28s cubic-bezier(0.22, 1, 0.36, 1);
}

.lux-onb-drawer.is-closing {
    animation: lux-onb-drawer-slide-out 0.28s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.lux-onb-drawer--primary { --onb-drawer-accent: var(--lux-primary, #5b5ff4); --onb-drawer-accent-rgb: var(--lux-primary-rgb, 91, 95, 244); }
.lux-onb-drawer--success { --onb-drawer-accent: #16a34a; --onb-drawer-accent-rgb: 22, 163, 74; }
.lux-onb-drawer--warning { --onb-drawer-accent: #d97706; --onb-drawer-accent-rgb: 217, 119, 6; }
.lux-onb-drawer--danger { --onb-drawer-accent: #dc2626; --onb-drawer-accent-rgb: 220, 38, 38; }
.lux-onb-drawer--neutral,
.lux-onb-drawer--muted { --onb-drawer-accent: #64748b; --onb-drawer-accent-rgb: 100, 116, 139; }

.lux-onb-drawer.is-overdue {
    --onb-drawer-accent: #dc2626;
    --onb-drawer-accent-rgb: 220, 38, 38;
}

.lux-onb-drawer__accent {
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 4px;
    background: linear-gradient(180deg, var(--onb-drawer-accent), rgba(var(--onb-drawer-accent-rgb), 0.35));
    box-shadow: 0 0 18px rgba(var(--onb-drawer-accent-rgb), 0.35);
}

.lux-onb-drawer__head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.75rem;
    flex-shrink: 0;
    padding: 1.15rem 1.2rem 1rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.9);
    background:
        radial-gradient(circle at 100% 0%, rgba(var(--onb-drawer-accent-rgb), 0.14), transparent 55%),
        linear-gradient(135deg, rgba(var(--onb-drawer-accent-rgb), 0.05), rgba(255, 255, 255, 0.98));
}

.lux-onb-drawer__head-main {
    display: flex;
    align-items: flex-start;
    gap: 0.75rem;
    min-width: 0;
}

.lux-onb-drawer__category-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.65rem;
    height: 2.65rem;
    border-radius: 16px;
    flex-shrink: 0;
    color: #fff;
    font-size: 1rem;
    background: linear-gradient(135deg, var(--onb-drawer-accent), rgba(var(--onb-drawer-accent-rgb), 0.65));
    box-shadow: 0 10px 22px rgba(var(--onb-drawer-accent-rgb), 0.28);
}

.lux-onb-drawer__head-copy {
    min-width: 0;
}

.lux-onb-drawer__eyebrow {
    display: block;
    font-size: 0.65rem;
    font-weight: 800;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--onb-drawer-accent);
}

.lux-onb-drawer__head h2 {
    margin: 0.3rem 0 0;
    font-size: 1.12rem;
    font-weight: 900;
    color: #0f172a;
    letter-spacing: -0.02em;
    line-height: 1.25;
}

.lux-onb-drawer__badges {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.35rem;
    margin-top: 0.55rem;
}

.lux-onb-drawer__pill {
    display: inline-flex;
    align-items: center;
    gap: 0.2rem;
    padding: 0.18rem 0.5rem;
    border-radius: 999px;
    font-size: 0.65rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
}

.lux-onb-drawer__pill--required {
    background: rgba(var(--onb-drawer-accent-rgb), 0.12);
    color: var(--onb-drawer-accent);
}

.lux-onb-drawer__pill--optional {
    background: rgba(148, 163, 184, 0.16);
    color: #64748b;
}

.lux-onb-drawer__pill--overdue {
    background: rgba(239, 68, 68, 0.12);
    color: #b91c1c;
}

.lux-onb-drawer__close {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.15rem;
    height: 2.15rem;
    border: none;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.82);
    box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.9);
    color: #64748b;
    cursor: pointer;
    transition: background 0.14s ease, color 0.14s ease, box-shadow 0.14s ease;
    flex-shrink: 0;
}

.lux-onb-drawer__close:hover {
    color: var(--onb-drawer-accent);
    background: rgba(var(--onb-drawer-accent-rgb), 0.08);
    box-shadow: inset 0 0 0 1px rgba(var(--onb-drawer-accent-rgb), 0.22);
}

.lux-onb-drawer__body {
    padding: 1rem 1.2rem 1.15rem;
    flex: 1 1 auto;
    min-height: 0;
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
    -webkit-overflow-scrolling: touch;
}

.lux-onb-drawer__body::-webkit-scrollbar {
    width: 6px;
}

.lux-onb-drawer__body::-webkit-scrollbar-thumb {
    border-radius: 999px;
    background: rgba(148, 163, 184, 0.45);
}

.lux-onb-drawer__banner {
    display: flex;
    align-items: flex-start;
    gap: 0.65rem;
    margin-bottom: 0.85rem;
    padding: 0.8rem 0.85rem;
    border-radius: 16px;
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--onb-drawer-accent-rgb), 0.1), transparent 55%),
        rgba(248, 250, 252, 0.95);
    box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.9);
}

.lux-onb-drawer__banner.is-alert {
    background:
        radial-gradient(circle at 0% 0%, rgba(239, 68, 68, 0.1), transparent 55%),
        rgba(254, 242, 242, 0.95);
    box-shadow: inset 0 0 0 1px rgba(254, 202, 202, 0.85);
}

.lux-onb-drawer__banner.is-success {
    background:
        radial-gradient(circle at 0% 0%, rgba(34, 197, 94, 0.1), transparent 55%),
        rgba(240, 253, 244, 0.95);
    box-shadow: inset 0 0 0 1px rgba(187, 247, 208, 0.85);
}

.lux-onb-drawer__banner-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 12px;
    flex-shrink: 0;
    color: var(--onb-drawer-accent);
    background: rgba(var(--onb-drawer-accent-rgb), 0.12);
    font-size: 0.95rem;
}

.lux-onb-drawer__banner.is-alert .lux-onb-drawer__banner-icon {
    color: #dc2626;
    background: rgba(239, 68, 68, 0.12);
}

.lux-onb-drawer__banner.is-success .lux-onb-drawer__banner-icon {
    color: #16a34a;
    background: rgba(34, 197, 94, 0.12);
}

.lux-onb-drawer__banner strong {
    display: block;
    font-size: 0.82rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-onb-drawer__banner p {
    margin: 0.2rem 0 0;
    font-size: 0.74rem;
    font-weight: 600;
    color: #64748b;
    line-height: 1.45;
}

.lux-onb-drawer__facts {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.55rem;
}

.lux-onb-drawer__fact {
    display: flex;
    align-items: flex-start;
    gap: 0.55rem;
    padding: 0.75rem 0.7rem;
    border-radius: 16px;
    background: rgba(255, 255, 255, 0.98);
    box-shadow:
        0 8px 20px rgba(15, 23, 42, 0.04),
        inset 0 0 0 1px rgba(226, 232, 240, 0.9);
    transition: box-shadow 0.15s ease, transform 0.15s ease;
}

.lux-onb-drawer__fact:hover {
    transform: translateY(-1px);
    box-shadow:
        0 12px 26px rgba(var(--onb-drawer-accent-rgb), 0.08),
        inset 0 0 0 1px rgba(var(--onb-drawer-accent-rgb), 0.14);
}

.lux-onb-drawer__fact-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.85rem;
    height: 1.85rem;
    border-radius: 11px;
    flex-shrink: 0;
    color: var(--onb-drawer-accent);
    background: rgba(var(--onb-drawer-accent-rgb), 0.1);
    font-size: 0.82rem;
}

.lux-onb-drawer__fact-label {
    display: block;
    font-size: 0.65rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #94a3b8;
}

.lux-onb-drawer__fact-value {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    margin-top: 0.2rem;
    font-size: 0.82rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.25;
}

.lux-onb-drawer__fact-value.is-alert {
    color: #b91c1c;
}

.lux-onb-drawer__owner-avatar {
    display: inline-grid;
    place-items: center;
    width: 1.35rem;
    height: 1.35rem;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--onb-drawer-accent), rgba(var(--onb-drawer-accent-rgb), 0.6));
    color: #fff;
    font-size: 0.58rem;
    font-weight: 900;
    flex-shrink: 0;
}

.lux-onb-drawer__notes-card {
    margin-top: 0.85rem;
    padding: 0.85rem 0.9rem;
    border-radius: 16px;
    background:
        radial-gradient(circle at 100% 0%, rgba(var(--onb-drawer-accent-rgb), 0.08), transparent 50%),
        rgba(248, 250, 252, 0.95);
    box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.9);
}

.lux-onb-drawer__notes-card header {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: var(--onb-drawer-accent);
}

.lux-onb-drawer__notes-card p {
    margin: 0.45rem 0 0;
    font-size: 0.8rem;
    font-weight: 600;
    color: #475569;
    line-height: 1.55;
}

.lux-onb-drawer__hint {
    display: flex;
    align-items: flex-start;
    gap: 0.55rem;
    margin-top: 0.85rem;
    padding: 0.8rem 0.85rem;
    border-radius: 14px;
    background: rgba(var(--onb-drawer-accent-rgb), 0.05);
    box-shadow: inset 0 0 0 1px rgba(var(--onb-drawer-accent-rgb), 0.1);
}

.lux-onb-drawer__hint i {
    color: var(--onb-drawer-accent);
    font-size: 0.95rem;
    margin-top: 0.1rem;
    flex-shrink: 0;
}

.lux-onb-drawer__hint p {
    margin: 0;
    font-size: 0.74rem;
    font-weight: 600;
    color: #64748b;
    line-height: 1.5;
}

.lux-onb-drawer__foot {
    flex-shrink: 0;
    padding: 0.95rem 1.2rem 1.1rem;
    border-top: 1px solid rgba(226, 232, 240, 0.9);
    background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.6), rgba(248, 250, 252, 0.98));
    box-shadow: 0 -8px 24px rgba(15, 23, 42, 0.04);
}

.lux-onb-drawer__foot-actions {
    display: flex;
    gap: 0.5rem;
    flex-wrap: wrap;
}

.lux-onb-drawer__foot-hint {
    margin: 0.55rem 0 0;
    font-size: 0.68rem;
    font-weight: 600;
    color: #94a3b8;
    line-height: 1.4;
}

.lux-onb-drawer__case {
    padding: 0.85rem 1.2rem 0.75rem;
    border-bottom: 1px solid rgba(241, 245, 249, 0.98);
    background:
        radial-gradient(circle at 0% 100%, rgba(var(--onb-drawer-accent-rgb), 0.08), transparent 50%),
        rgba(248, 250, 252, 0.65);
}

.lux-onb-drawer__case-main {
    display: flex;
    align-items: center;
    gap: 0.65rem;
}

.lux-onb-drawer__case-avatar {
    display: inline-grid;
    place-items: center;
    width: 2.4rem;
    height: 2.4rem;
    border-radius: 14px;
    background: linear-gradient(135deg, var(--onb-drawer-accent), rgba(var(--onb-drawer-accent-rgb), 0.6));
    color: #fff;
    font-size: 0.78rem;
    font-weight: 900;
    flex-shrink: 0;
}

.lux-onb-drawer__case-eyebrow {
    display: block;
    font-size: 0.62rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-onb-drawer__case-name {
    display: block;
    margin-top: 0.1rem;
    font-size: 0.9rem;
    font-weight: 900;
    color: #0f172a;
}

.lux-onb-drawer__case-role {
    display: block;
    margin-top: 0.1rem;
    font-size: 0.72rem;
    font-weight: 600;
    color: #64748b;
}

.lux-onb-drawer__case-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 0.45rem 0.85rem;
    margin-top: 0.55rem;
    font-size: 0.7rem;
    font-weight: 700;
    color: #64748b;
}

.lux-onb-drawer__case-meta span {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
}

.lux-onb-drawer__task-id {
    display: block;
    margin-top: 0.45rem;
    font-size: 0.65rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    color: #94a3b8;
    font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}

.lux-onb-drawer__pill--due-soon {
    background: rgba(245, 158, 11, 0.14);
    color: #b45309;
}

.lux-onb-drawer__section {
    margin-top: 0.85rem;
}

.lux-onb-drawer__section-head {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    margin-bottom: 0.45rem;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: var(--onb-drawer-accent);
}

.lux-onb-drawer__description {
    margin: 0;
    font-size: 0.8rem;
    font-weight: 600;
    color: #475569;
    line-height: 1.55;
}

.lux-onb-drawer__fact-sub {
    display: block;
    margin-top: 0.12rem;
    font-size: 0.68rem;
    font-weight: 600;
    color: #94a3b8;
}

.lux-onb-drawer__steps {
    margin: 0;
    padding: 0;
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
    counter-reset: onb-step;
}

.lux-onb-drawer__steps li {
    display: flex;
    align-items: flex-start;
    gap: 0.55rem;
    padding: 0.55rem 0.65rem;
    border-radius: 12px;
    background: rgba(248, 250, 252, 0.95);
    box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.9);
    font-size: 0.76rem;
    font-weight: 600;
    color: #475569;
    line-height: 1.4;
}

.lux-onb-drawer__steps li::before {
    counter-increment: onb-step;
    content: counter(onb-step);
    display: inline-grid;
    place-items: center;
    width: 1.25rem;
    height: 1.25rem;
    border-radius: 8px;
    flex-shrink: 0;
    background: rgba(var(--onb-drawer-accent-rgb), 0.12);
    color: var(--onb-drawer-accent);
    font-size: 0.65rem;
    font-weight: 900;
}

.lux-onb-drawer__deps {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
}

.lux-onb-drawer__dep {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.55rem 0.65rem;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.98);
    box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.9);
}

.lux-onb-drawer__dep > i {
    font-size: 0.95rem;
    flex-shrink: 0;
}

.lux-onb-drawer__dep.is-satisfied > i {
    color: #16a34a;
}

.lux-onb-drawer__dep.is-pending > i {
    color: #94a3b8;
}

.lux-onb-drawer__dep strong {
    display: block;
    font-size: 0.78rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-onb-drawer__dep span span {
    display: block;
    margin-top: 0.08rem;
    font-size: 0.68rem;
    font-weight: 600;
    color: #64748b;
}

.lux-onb-drawer__attachments {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
}

.lux-onb-drawer__attachments li {
    display: grid;
    grid-template-columns: auto 1fr auto;
    align-items: center;
    gap: 0.55rem;
    padding: 0.55rem 0.65rem;
    border-radius: 12px;
    background: rgba(248, 250, 252, 0.95);
    box-shadow: inset 0 0 0 1px rgba(226, 232, 240, 0.9);
}

.lux-onb-drawer__file-icon {
    display: inline-grid;
    place-items: center;
    width: 1.85rem;
    height: 1.85rem;
    border-radius: 10px;
    background: rgba(var(--onb-drawer-accent-rgb), 0.1);
    color: var(--onb-drawer-accent);
    font-size: 0.82rem;
}

.lux-onb-drawer__file-main strong {
    display: block;
    font-size: 0.76rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-onb-drawer__file-main span {
    display: block;
    margin-top: 0.06rem;
    font-size: 0.66rem;
    font-weight: 600;
    color: #94a3b8;
}

.lux-onb-drawer__file-action {
    border: none;
    border-radius: 999px;
    padding: 0.2rem 0.55rem;
    background: rgba(var(--onb-drawer-accent-rgb), 0.1);
    color: var(--onb-drawer-accent);
    font-size: 0.65rem;
    font-weight: 800;
    cursor: not-allowed;
    opacity: 0.75;
}

.lux-onb-drawer__timeline {
    list-style: none;
    margin: 0;
    padding: 0 0 0 0.35rem;
    display: flex;
    flex-direction: column;
    gap: 0;
    position: relative;
}

.lux-onb-drawer__timeline::before {
    content: "";
    position: absolute;
    left: 0.5rem;
    top: 0.35rem;
    bottom: 0.35rem;
    width: 2px;
    border-radius: 999px;
    background: linear-gradient(180deg, rgba(var(--onb-drawer-accent-rgb), 0.35), rgba(226, 232, 240, 0.9));
}

.lux-onb-drawer__timeline li {
    display: flex;
    align-items: flex-start;
    gap: 0.65rem;
    padding: 0.45rem 0 0.45rem 0.15rem;
    position: relative;
}

.lux-onb-drawer__timeline-dot {
    width: 0.65rem;
    height: 0.65rem;
    border-radius: 50%;
    margin-top: 0.2rem;
    flex-shrink: 0;
    background: var(--onb-drawer-accent);
    box-shadow: 0 0 0 3px rgba(var(--onb-drawer-accent-rgb), 0.18);
    z-index: 1;
}

.lux-onb-drawer__timeline strong {
    display: block;
    font-size: 0.76rem;
    font-weight: 800;
    color: #0f172a;
}

.lux-onb-drawer__timeline span {
    display: block;
    margin-top: 0.08rem;
    font-size: 0.68rem;
    font-weight: 600;
    color: #64748b;
}

/* Lifecycle insights charts */
.lux-onb-insights {
    margin-bottom: 0.75rem;
}

.lux-onb-insights__grid {
    margin-bottom: 0.55rem;
}

.lux-onb-insights__bars {
    margin-top: 0.15rem;
}

.lux-onb-insights__highlights {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0.5rem;
}

.lux-onb-insights__highlight {
    display: flex;
    align-items: flex-start;
    gap: 0.55rem;
    padding: 0.7rem 0.75rem;
    border-radius: 16px;
    background: rgba(255, 255, 255, 0.98);
    box-shadow: 0 8px 22px rgba(15, 23, 42, 0.05);
    border: 1px solid rgba(241, 245, 249, 0.98);
}

.lux-onb-insights__highlight-icon {
    display: inline-grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    border-radius: 12px;
    flex-shrink: 0;
    font-size: 0.9rem;
}

.lux-onb-insights__highlight.is-primary .lux-onb-insights__highlight-icon {
    color: var(--lux-primary-dark, #3730a3);
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.lux-onb-insights__highlight.is-green .lux-onb-insights__highlight-icon {
    color: #15803d;
    background: rgba(34, 197, 94, 0.14);
}

.lux-onb-insights__highlight.is-violet .lux-onb-insights__highlight-icon {
    color: #6d28d9;
    background: rgba(124, 58, 237, 0.12);
}

.lux-onb-insights__highlight.is-rose .lux-onb-insights__highlight-icon {
    color: #b91c1c;
    background: rgba(239, 68, 68, 0.12);
}

.lux-onb-insights__highlight.is-neutral .lux-onb-insights__highlight-icon {
    color: #64748b;
    background: rgba(148, 163, 184, 0.14);
}

.lux-onb-insights__highlight-label {
    display: block;
    font-size: 0.65rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #94a3b8;
}

.lux-onb-insights__highlight strong {
    display: block;
    margin-top: 0.12rem;
    font-size: 1.05rem;
    font-weight: 900;
    color: #0f172a;
    line-height: 1.1;
}

.lux-onb-insights__highlight small {
    display: block;
    margin-top: 0.15rem;
    font-size: 0.68rem;
    font-weight: 600;
    color: #64748b;
}

.lux-onb-back-nav.pd-back-nav {
    margin: 0.65rem 0 0.5rem;
}

.lux-onb-queue-panel .lux-hrms-dash__panel-body {
    padding-top: 0.15rem;
}

@keyframes lux-onb-shimmer {
    0% { background-position: 200% 0; }
    100% { background-position: -200% 0; }
}

@media (max-width: 991px) {
    .lux-onb-insight-strip {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .lux-onb-toolbar {
        align-items: stretch;
    }

    .lux-onb-toolbar__grid {
        width: 100%;
    }

    .lux-onb-toolbar__dept-col {
        width: 100%;
    }

    .lux-onb-toolbar__count {
        width: 100%;
        justify-content: center;
    }

    .lux-onb-checklist-hero {
        flex-direction: column;
    }

    .lux-onb-checklist-hero__stats {
        width: 100%;
        justify-content: flex-start;
    }

    .lux-onb-insights__highlights {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .lux-onb-hero__detail-main {
        flex-direction: column;
        align-items: flex-start;
    }
}

/* F05 — Attendance regularization & intelligence (luxury) */

/* Shared surface — policy + intelligence panels */
.lux-att-policy,
.lux-att-intel {
    position: relative;
    margin: 0 0.75rem 0.85rem;
    padding: 0.95rem 1rem 1.05rem;
    border: 0px solid rgba(var(--lux-primary-rgb, 91, 95, 244), 0.14);
    border-radius: 18px;
    background:
        radial-gradient(circle at 0% 0%, rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08), transparent 48%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.96));
    box-shadow:
        0 0 0 1px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.05),
        0 12px 32px rgba(15, 23, 42, 0.06);
    overflow: hidden;
}

.lux-att-policy__glow,
.lux-att-intel__glow {
    position: absolute;
    inset: 0 0 auto 0;
    height: 3px;
    background: linear-gradient(
        90deg,
        var(--lux-primary, #5b5ff4),
        rgba(var(--lux-primary-rgb, 91, 95, 244), 0.25)
    );
    pointer-events: none;
}

.lux-att-policy__hero,
.lux-att-intel__hero {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.75rem;
    margin-bottom: 0.85rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid rgba(226, 232, 240, 0.9);
}

.lux-att-policy__title,
.lux-att-intel__title {
    margin: 0.15rem 0 0;
    font-size: 1.15rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.2;
}

.lux-att-policy__subtitle,
.lux-att-intel__subtitle {
    margin: 0.25rem 0 0;
    font-size: 0.75rem;
    font-weight: 600;
    color: #64748b;
    line-height: 1.45;
    max-width: 36rem;
}

.lux-att-policy__hero-badge,
.lux-att-intel__source {
    flex-shrink: 0;
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.35rem 0.65rem;
    border-radius: 999px;
    font-size: 0.6875rem;
    font-weight: 800;
    letter-spacing: 0.02em;
}

.lux-att-policy__hero-badge {
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary-dark, #3730a3);
}

.lux-att-policy__hero-badge i {
    font-size: 0.75rem;
}

.lux-att-intel__source.is-api {
    background: rgba(16, 185, 129, 0.12);
    color: #047857;
}

.lux-att-intel__source.is-client {
    background: rgba(245, 158, 11, 0.12);
    color: #b45309;
}

.lux-att-policy__metrics,
.lux-att-intel__metrics {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(9.5rem, 1fr));
    gap: 0.55rem;
    margin-bottom: 0.85rem;
}

.lux-att-policy__metric,
.lux-att-intel__metric {
    display: flex;
    align-items: flex-start;
    gap: 0.55rem;
    padding: 0.65rem 0.75rem;
    border: 0px solid rgba(226, 232, 240, 0.95);
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.92);
    box-shadow: 0 4px 14px rgba(15, 23, 42, 0.04);
}

.lux-att-policy__metric > i,
.lux-att-intel__metric-icon {
    display: grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    border-radius: 10px;
    background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
    color: var(--lux-primary-dark, #3730a3);
    font-size: 0.875rem;
