}

.lux-leave-register__row:hover {
    background: rgba(248, 250, 252, 0.9);
}

.lux-leave-register__type {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
}

.lux-leave-register__type em {
    font-style: normal;
    font-size: 0.6875rem;
    color: #94a3b8;
}

.lux-leave-register__comment {
    margin: 0.25rem 0 0;
    font-size: 0.6875rem;
