}

.lux-leave-register__skeleton {
    min-height: 14rem;
    border-radius: 14px;
    background: linear-gradient(90deg, rgba(226, 232, 240, 0.45), rgba(248, 250, 252, 0.95), rgba(226, 232, 240, 0.45));
    background-size: 200% 100%;
    animation: lux-att-f05-shimmer 1.4s ease-in-out infinite;
}

.lux-leave-status-badge {
    display: inline-flex;
    align-items: center;
    padding: 0.2rem 0.55rem;
    border-radius: 999px;
    font-size: 0.6875rem;
    font-weight: 700;
}

.lux-leave-drawer-backdrop {
    z-index: var(--lux-z-overlay);
}

.lux-leave-drawer {
    width: min(28rem, 100vw);
}

.lux-leave-drawer__eyebrow {
    display: block;
    font-size: 0.6875rem;
    font-weight: 700;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #94a3b8;
    margin-bottom: 0.2rem;
}

.lux-leave-drawer__body {
    display: flex;
    flex-direction: column;
    min-height: 0;
    padding: 0;
}

.lux-leave-drawer__scroll {
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
    padding: 1rem 1.25rem;
    display: flex;
    flex-direction: column;
    gap: 0.85rem;
}

.lux-leave-drawer__field {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
}

.lux-leave-drawer__label {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.6875rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: #94a3b8;
}

.lux-leave-drawer__input,
.lux-leave-drawer__textarea {
    width: 100%;
    padding: 0.55rem 0.65rem;
    border-radius: 10px;
    border: 1px solid rgba(148, 163, 184, 0.35);
    font-size: 0.8125rem;
    background: rgba(255, 255, 255, 0.95);
}

.lux-leave-drawer__textarea {
    resize: vertical;
    min-height: 4.5rem;
}

.lux-leave-drawer__grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.75rem;
}

.lux-leave-drawer__half-row {
    display: flex;
    flex-direction: column;
    gap: 0.45rem;
}

.lux-leave-drawer__check {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    font-size: 0.8125rem;
    color: #475569;
}

.lux-leave-drawer__computed {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.65rem 0.75rem;
    border-radius: 12px;
    background: rgba(251, 191, 36, 0.1);
    border: 1px solid rgba(251, 191, 36, 0.22);
    font-size: 0.8125rem;
    color: #78350f;
}

.lux-leave-drawer__computed strong {
    margin-left: auto;
    font-size: 1rem;
}

.lux-leave-drawer__computed em {
    font-style: normal;
    font-size: 0.6875rem;
    color: #92400e;
}

.lux-leave-drawer__btn {
    padding: 0.5rem 0.9rem;
    border-radius: 10px;
    font-size: 0.8125rem;
    font-weight: 700;
    border: 1px solid transparent;
    cursor: pointer;
}

.lux-leave-drawer__btn.is-ghost {
    background: rgba(255, 255, 255, 0.9);
    border-color: rgba(148, 163, 184, 0.35);
    color: #475569;
}

.lux-leave-drawer__btn.is-primary {
    background: linear-gradient(135deg, #f59e0b, #d97706);
    color: #fff;
}

.lux-leave-drawer__btn:disabled {
    opacity: 0.55;
    cursor: not-allowed;
}

.lux-leave-empty {
    margin-top: 0.5rem;
}

@media (max-width: 768px) {
    .lux-leave-drawer__grid {
        grid-template-columns: 1fr;
    }

    .lux-leave-tabs {
        padding-inline: 0.75rem;
    }

    .lux-leave-calendar__heatmap {
        grid-template-columns: repeat(7, minmax(0, 1fr));
    }
}

/* ── Leave sub-panels luxury v3 ─────────────────────────────────────────── */

.lux-leave-subpanel {
    border-radius: 18px;
    border: 1px solid rgba(148, 163, 184, 0.22);
    background:
        radial-gradient(circle at 0% 0%, rgba(251, 191, 36, 0.08), transparent 42%),
        linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(248, 250, 252, 0.92));
    box-shadow: 0 10px 28px rgba(15, 23, 42, 0.05);
    padding: 1rem 1.1rem 1.15rem;
}

.lux-leave-subpanel__head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 1rem;
    margin-bottom: 0.85rem;
    flex-wrap: wrap;
}

.lux-leave-subpanel__eyebrow {
    display: block;
    font-size: 0.6875rem;
    font-weight: 700;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #b45309;
    margin-bottom: 0.2rem;
}

.lux-leave-subpanel__title {
    margin: 0;
    font-size: 1rem;
