    text-align: center;
    font-size: 0.875rem;
    font-weight: 700;
    color: #0f172a;
}

.lux-leave-calendar__summary {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.65rem;
    margin-bottom: 0.85rem;
}

.lux-leave-calendar__stat {
    padding: 0.65rem 0.75rem;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.72);
    border: 1px solid rgba(148, 163, 184, 0.2);
}

.lux-leave-calendar__stat span {
    display: block;
    font-size: 0.6875rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: #94a3b8;
}

.lux-leave-calendar__stat strong {
    font-size: 1.25rem;
    color: #0f172a;
}

.lux-leave-calendar__heatmap-wrap {
    margin-bottom: 0.85rem;
}

.lux-leave-calendar__heatmap-label {
    font-size: 0.6875rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #94a3b8;
    margin-bottom: 0.45rem;
}

.lux-leave-calendar__heatmap {
    display: grid;
    grid-template-columns: repeat(7, minmax(0, 1fr));
    gap: 0.35rem;
}

.lux-leave-calendar__heatmap--skeleton {
    min-height: 4.5rem;
    border-radius: 12px;
    background: linear-gradient(90deg, rgba(226, 232, 240, 0.45), rgba(248, 250, 252, 0.95), rgba(226, 232, 240, 0.45));
    background-size: 200% 100%;
    animation: lux-att-f05-shimmer 1.4s ease-in-out infinite;
}

.lux-leave-calendar__day {
    position: relative;
    min-height: 2.4rem;
    border-radius: 10px;
    border: 1px solid rgba(148, 163, 184, 0.18);
    background: rgba(255, 255, 255, 0.75);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 0.1rem;
}

.lux-leave-calendar__day.is-weekend {
    opacity: 0.72;
}

.lux-leave-calendar__day.is-today {
    border-color: rgba(217, 119, 6, 0.45);
    box-shadow: inset 0 0 0 1px rgba(217, 119, 6, 0.25);
}

.lux-leave-calendar__day.is-low {
    background: rgba(254, 243, 199, 0.65);
}

.lux-leave-calendar__day.is-medium {
    background: rgba(251, 191, 36, 0.35);
}

.lux-leave-calendar__day.is-high {
    background: rgba(245, 158, 11, 0.45);
}

.lux-leave-calendar__day-num {
    font-size: 0.6875rem;
    font-weight: 700;
    color: #475569;
}

.lux-leave-calendar__day-count {
    font-size: 0.625rem;
    font-weight: 800;
    color: #92400e;
}

.lux-leave-calendar__legend {
    display: flex;
    gap: 0.65rem;
    margin-top: 0.45rem;
    font-size: 0.6875rem;
    color: #64748b;
}

.lux-leave-calendar__legend span {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
}

.lux-leave-calendar__legend span::before {
    content: "";
    width: 0.65rem;
    height: 0.65rem;
    border-radius: 3px;
}

.lux-leave-calendar__legend .is-low::before { background: rgba(254, 243, 199, 0.95); border: 1px solid #fcd34d; }
.lux-leave-calendar__legend .is-medium::before { background: rgba(251, 191, 36, 0.55); }
.lux-leave-calendar__legend .is-high::before { background: rgba(245, 158, 11, 0.65); }

.lux-leave-calendar__employee {
    display: inline-flex;
    align-items: center;
    gap: 0.55rem;
}

.lux-leave-calendar__avatar {
    width: 1.85rem;
    height: 1.85rem;
    border-radius: 8px;
    display: inline-grid;
    place-items: center;
    font-size: 0.625rem;
    font-weight: 800;
    color: #fff;
    background: linear-gradient(135deg, #f59e0b, #d97706);
}

.lux-leave-calc__totals {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.65rem;
    margin-bottom: 0.85rem;
}

.lux-leave-calc__total {
    padding: 0.75rem;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.75);
    border: 1px solid rgba(148, 163, 184, 0.2);
}

.lux-leave-calc__total span {
    display: block;
    font-size: 0.6875rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: #94a3b8;
}

.lux-leave-calc__total strong {
    font-size: 1.35rem;
    color: #0f172a;
}

.lux-leave-calc__total.is-balance strong {
    color: #047857;
}

.lux-leave-calc__balance-val {
    color: #047857;
}

.lux-leave-coverage.is-loading,
.lux-leave-analytics.is-loading,
.lux-leave-payroll.is-loading {
    min-height: 8rem;
    border-radius: 14px;
    background: linear-gradient(90deg, rgba(226, 232, 240, 0.45), rgba(248, 250, 252, 0.95), rgba(226, 232, 240, 0.45));
    background-size: 200% 100%;
    animation: lux-att-f05-shimmer 1.4s ease-in-out infinite;
}

.lux-leave-coverage__head {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.75rem 1.1rem;
    margin-bottom: 0.7rem;
}

.lux-leave-coverage__intro {
    min-width: min(100%, 16rem);
    flex: 1 1 14rem;
}

.lux-leave-coverage__summary {
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
}

.lux-leave-coverage__stat {
    display: flex;
    flex-direction: column;
    gap: 0.1rem;
    min-width: 4.75rem;
    padding: 0.4rem 0.6rem;
    border-radius: 10px;
    border: 1px solid rgba(148, 163, 184, 0.2);
    background: rgba(248, 250, 252, 0.95);
}

.lux-leave-coverage__stat span {
    font-size: 0.625rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #64748b;
}

.lux-leave-coverage__stat strong {
    font-size: 1rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.15;
}

.lux-leave-coverage__stat.is-expected {
    border-color: rgba(251, 146, 60, 0.35);
    background: rgba(255, 237, 213, 0.92);
}

.lux-leave-coverage__stat.is-actual {
    border-color: rgba(5, 150, 105, 0.25);
    background: rgba(236, 253, 245, 0.92);
}

.lux-leave-coverage__stat.is-gap.is-behind {
    border-color: rgba(225, 29, 72, 0.25);
    background: rgba(255, 241, 242, 0.95);
}

.lux-leave-coverage__stat.is-gap.is-ahead {
    border-color: rgba(5, 150, 105, 0.25);
    background: rgba(236, 253, 245, 0.92);
}

.lux-leave-coverage__toggle {
    display: inline-flex;
    margin: 0 0 0.7rem;
