.lux-leave-coverage__cell.is-bad {
    background: rgba(254, 226, 226, 0.85);
    border-color: rgba(244, 63, 94, 0.35);
}
.lux-leave-coverage__cell.is-bad .lux-leave-coverage__pct {
    color: #be123c;
}
.lux-leave-coverage__cell.is-low { background: rgba(209, 250, 229, 0.65); }
.lux-leave-coverage__cell.is-medium { background: rgba(254, 243, 199, 0.75); }
.lux-leave-coverage__cell.is-high { background: rgba(254, 226, 226, 0.8); }
.lux-leave-coverage__cell.is-pending,
.lux-leave-coverage__cell.is-empty {
    background: rgba(248, 250, 252, 0.9);
    color: #94a3b8;
