.lux-leave-coverage__day {
    display: block;
    font-size: 0.625rem;
    font-weight: 700;
    color: #64748b;
}

.lux-leave-coverage__pct {
    display: block;
    font-size: 0.8125rem;
    font-weight: 800;
    color: #0f172a;
