  border: 1px solid rgba(148, 163, 184, 0.32);
  background: rgba(255, 255, 255, 0.92);
  color: #64748b;
  text-decoration: none;
  transition: color 0.15s ease, border-color 0.15s ease, transform 0.15s ease;
}

.lux-payroll-register__open:hover {
  color: var(--lux-primary-dark, #3730a3);
  border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
  transform: translateX(1px);
  text-decoration: none;
}

.lux-payroll-register__open.is-disabled {
  opacity: 0.25;
  pointer-events: none;
}

.lux-payroll-register__issue-code {
  display: block;
  font-size: 0.8125rem;
  font-weight: 800;
  color: #0f172a;
}

.lux-payroll-register__money {
  display: inline-block;
  font-variant-numeric: tabular-nums;
  font-weight: 800;
  font-size: 0.8125rem;
  color: #0f172a;
  white-space: nowrap;
}

.lux-payroll-register__money.is-muted {
  color: #64748b;
  font-weight: 700;
}

.lux-payroll-code {
  display: inline-block;
  padding: 0.1rem 0.4rem;
  border-radius: 6px;
  background: rgba(15, 23, 42, 0.05);
  font-size: 0.75rem;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}

.lux-payroll-readiness-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 2.75rem;
  padding: 0.15rem 0.45rem;
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 800;
}

.lux-payroll-readiness-pill.is-low { background: rgba(244, 63, 94, 0.12); color: #be123c; }
.lux-payroll-readiness-pill.is-mid { background: rgba(245, 158, 11, 0.15); color: #b45309; }
.lux-payroll-readiness-pill.is-high { background: rgba(16, 185, 129, 0.15); color: #047857; }
.lux-payroll-readiness-pill.is-slate { background: rgba(100, 116, 139, 0.12); color: #475569; }

.lux-payroll-readiness__bars,
.lux-payroll-readiness__row {
  list-style: none;
  padding: 0;
  margin: 0;
}

.lux-payroll-readiness__bars {
  display: grid;
  gap: 0.85rem;
}

.lux-payroll-readiness__row {
  padding: 0.65rem 0.75rem;
  border-radius: 12px;
  background: rgba(248, 250, 252, 0.9);
  border: 1px solid rgba(226, 232, 240, 0.8);
}

.lux-payroll-readiness__label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.45rem;
}

.lux-payroll-readiness__label-main {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.45rem;
  min-width: 0;
}

.lux-payroll-readiness__link {
  font-size: 0.8125rem;
  font-weight: 800;
  color: #0f172a;
  text-decoration: none;
}

.lux-payroll-readiness__link:hover {
  color: var(--lux-primary-dark, #3730a3);
}

.lux-payroll-readiness__track {
  height: 0.55rem;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.08);
  overflow: hidden;
}

.lux-payroll-readiness__track span {
  display: block;
  height: 100%;
  border-radius: inherit;
  transition: width 0.35s ease;
}

.lux-payroll-readiness__track .is-low { background: linear-gradient(90deg, #fb7185, #f43f5e); }
.lux-payroll-readiness__track .is-mid { background: linear-gradient(90deg, #fbbf24, #f59e0b); }
.lux-payroll-readiness__track .is-high { background: linear-gradient(90deg, #34d399, #10b981); }

.lux-payroll-readiness__meta,
.lux-payroll-readiness__empty {
  display: block;
  margin-top: 0.35rem;
  font-size: 0.75rem;
  font-weight: 600;
  color: #64748b;
}

.lux-payroll-exception-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  gap: 0.55rem;
}

.lux-payroll-exception-card {
  padding: 0.75rem 0.85rem;
  border-radius: 12px;
  border: 1px solid rgba(226, 232, 240, 0.95);
  background: rgba(255, 255, 255, 0.9);
}

.lux-payroll-exception-card.is-blocker {
  border-color: rgba(244, 63, 94, 0.25);
  background: rgba(255, 241, 242, 0.7);
}

.lux-payroll-exception-card.is-warning {
  border-color: rgba(245, 158, 11, 0.25);
  background: rgba(255, 251, 235, 0.75);
}

.lux-payroll-exception-card__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin-bottom: 0.35rem;
}

.lux-payroll-exception-card__code {
  font-size: 0.6875rem;
  font-weight: 700;
  color: #94a3b8;
}

.lux-payroll-exception-card__message {
  margin: 0;
  font-size: 0.8125rem;
  font-weight: 600;
  line-height: 1.45;
  color: #0f172a;
}

.lux-payroll-exception-card__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin-top: 0.45rem;
  font-size: 0.75rem;
  color: #64748b;
}

.lux-payroll-lifecycle {
  margin-bottom: 0.85rem;
  padding: 0.75rem 1rem;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.98);
  border: 1px solid rgba(226, 232, 240, 0.95);
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.04);
}

.lux-payroll-lifecycle__steps {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem 0;
  list-style: none;
  padding: 0;
  margin: 0;
}

.lux-payroll-lifecycle__step {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  flex: 1 1 auto;
  min-width: 0;
  position: relative;
  padding-right: 1.25rem;
}

.lux-payroll-lifecycle__step:not(:last-child)::after {
  content: "";
  position: absolute;
  right: 0.35rem;
  top: 50%;
  width: 0.65rem;
  height: 1px;
  background: #cbd5e1;
}

.lux-payroll-lifecycle__marker {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.5rem;
  height: 1.5rem;
  border-radius: 999px;
  font-size: 0.6875rem;
  font-weight: 800;
  background: rgba(148, 163, 184, 0.18);
  color: #64748b;
  flex-shrink: 0;
}

.lux-payroll-lifecycle__step.is-complete .lux-payroll-lifecycle__marker {
  background: rgba(16, 185, 129, 0.15);
  color: #047857;
}

.lux-payroll-lifecycle__step.is-current .lux-payroll-lifecycle__marker {
  background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
  color: #fff;
  box-shadow: 0 4px 12px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
}

.lux-payroll-lifecycle__label {
  font-size: 0.75rem;
  font-weight: 700;
  color: #64748b;
  white-space: nowrap;
}

.lux-payroll-lifecycle__step.is-current .lux-payroll-lifecycle__label {
  color: #0f172a;
}

.lux-payroll-run-detail__meta-strip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 1rem;
  margin-bottom: 0.85rem;
  font-size: 0.75rem;
  font-weight: 700;
  color: #64748b;
}

.lux-payroll-run-detail__grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(280px, 340px);
  gap: 0.85rem;
  align-items: start;
}

.lux-payroll-run-detail__main .lux-hrms-dash__panel-head {
  align-items: center;
}

.lux-payroll-run-detail__aside {
  position: sticky;
  top: 1rem;
}

.lux-payroll-cost-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 0.65rem;
}

.lux-payroll-cost-card {
  padding: 0.85rem 0.95rem;
  border-radius: 14px;
  border: 1px solid rgba(226, 232, 240, 0.95);
  background: rgba(248, 250, 252, 0.9);
}

.lux-payroll-cost-card__title {
  margin: 0 0 0.55rem;
  font-size: 0.875rem;
  font-weight: 800;
  color: #0f172a;
}

.lux-payroll-cost-card__stats {
  display: grid;
  gap: 0.35rem;
  margin: 0;
}

.lux-payroll-cost-card__stats div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
}

.lux-payroll-cost-card__stats dt {
  margin: 0;
  font-size: 0.6875rem;
  font-weight: 700;
  color: #94a3b8;
}

.lux-payroll-cost-card__stats dd {
  margin: 0;
  font-size: 0.8125rem;
  font-weight: 800;
  color: #0f172a;
  font-variant-numeric: tabular-nums;
}

.lux-payroll-ai-panel {
  background:
    radial-gradient(circle at 0% 0%, rgba(99, 102, 241, 0.1), transparent 55%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.96));
  border: 1px solid rgba(99, 102, 241, 0.18);
  border-radius: 14px;
  padding: 0.95rem 1rem;
}

.lux-payroll-ai-panel__headline {
  margin: 0 0 0.85rem;
  font-size: 0.9375rem;
  font-weight: 800;
  line-height: 1.45;
  color: #0f172a;
}

.lux-payroll-ai-panel__section {
  margin-bottom: 0.85rem;
}

.lux-payroll-ai-panel__section-title {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  margin: 0 0 0.45rem;
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #64748b;
}

.lux-payroll-ai-panel__list {
  padding-left: 1.1rem;
  margin: 0;
  font-size: 0.8125rem;
  font-weight: 600;
  line-height: 1.5;
  color: #334155;
}

.lux-payroll-ai-panel__foot {
  padding-top: 0.65rem;
  border-top: 1px solid rgba(99, 102, 241, 0.12);
}

.lux-payroll-ai-panel__eyebrow {
  display: block;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #94a3b8;
  margin-bottom: 0.2rem;
}

.lux-payroll-ai-panel__note {
  font-size: 0.75rem;
  font-weight: 600;
  color: #64748b;
  margin: 0;
}

.lux-payroll-ai-panel__summary {
  margin: 0 0 0.75rem;
  font-size: 0.8125rem;
  line-height: 1.55;
  color: #475569;
}

.lux-payroll-ai-panel__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
  margin-bottom: 0.75rem;
}

.lux-payroll-ai-panel__confidence {
  display: inline-flex;
  align-items: center;
  padding: 0.2rem 0.55rem;
  border-radius: 999px;
  background: rgba(99, 102, 241, 0.12);
  color: #4338ca;
  font-size: 0.6875rem;
  font-weight: 800;
}

.lux-payroll-ai-panel__badge {
  display: inline-flex;
  align-items: center;
  padding: 0.2rem 0.55rem;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.06);
  color: #64748b;
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.lux-payroll-ai-panel__action {
  margin: 0 0 0.85rem;
  padding: 0.65rem 0.75rem;
  border-radius: 10px;
  background: rgba(16, 185, 129, 0.08);
  border: 1px solid rgba(16, 185, 129, 0.18);
  color: #065f46;
  font-size: 0.8125rem;
  font-weight: 700;
  line-height: 1.45;
}

.lux-payroll-ai-panel__list--rich li {
  display: grid;
  gap: 0.15rem;
}

.lux-payroll-ai-panel__list--rich li strong {
  font-size: 0.8125rem;
  color: #0f172a;
}

.lux-payroll-ai-panel__list--rich li small {
  font-size: 0.75rem;
  color: #64748b;
  line-height: 1.45;
}

.lux-payroll-ai-panel__chip {
  display: inline-flex;
  width: fit-content;
  padding: 0.1rem 0.45rem;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.16);
  color: #475569;
  font-size: 0.6875rem;
  font-weight: 700;
}

.lux-payroll-ai-panel__evidence {
  margin: 0;
  padding-left: 1rem;
  color: #64748b;
  font-size: 0.75rem;
  line-height: 1.5;
}

.lux-payroll-ai-panel--loading {
  opacity: 0.85;
}

@media (max-width: 1200px) {
  .lux-hrms-dash__kpi-strip {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 992px) {
  .lux-payroll-dashboard__grid,
  .lux-payroll-run-detail__grid {
    grid-template-columns: 1fr;
  }

  .lux-payroll-run-detail__aside {
    position: static;
  }

  .lux-payroll-hero__actions {
    width: 100%;
    align-items: stretch;
  }

  .lux-payroll-hero__buttons {
    justify-content: flex-start;
  }

  .lux-payroll-summary-card__stats {
    grid-template-columns: 1fr;
  }
}

/* F09 — Paychecks / payslip (luxury) */
.lux-paycheck-page,
.lux-my-paychecks-page {
  padding-bottom: var(--lux-page-block-bottom);
}

.lux-paycheck-hero {
  align-items: center;
  flex-wrap: wrap;
}

.lux-paycheck__error {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  flex-wrap: wrap;
  margin-bottom: 0.85rem;
}

.lux-paycheck-kpi-strip .lux-payroll-kpi.is-green { border-color: rgba(5, 150, 105, 0.2); }
.lux-paycheck-kpi-strip .lux-payroll-kpi.is-amber { border-color: rgba(217, 119, 6, 0.2); }
.lux-paycheck-kpi-strip .lux-my-work-kpi.is-primary { border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.18); }

.lux-paycheck-insights {
  display: grid;
  gap: 0.45rem;
  margin-bottom: 0.85rem;
}

.lux-paycheck-insight {
  text-decoration: none;
  color: inherit;
}

.lux-paycheck-insight__copy {
  display: flex;
  flex-direction: column;
  gap: 0.12rem;
  min-width: 0;
}

.lux-paycheck-insight__copy strong {
  font-size: 0.8125rem;
  color: #0f172a;
}

.lux-paycheck-insight__copy small {
  font-size: 0.75rem;
  color: #64748b;
}

.lux-paycheck-insight__chevron {
  margin-left: auto;
  color: #94a3b8;
}

.lux-paycheck-panel__toolbar {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 0 0.95rem 0.75rem;
  border-bottom: 1px solid rgba(148, 163, 184, 0.16);
}

.lux-paycheck-register-wrap {
  overflow-x: auto;
  border-radius: 14px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.92), rgba(248, 250, 252, 0.88));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.8);
}

.lux-paycheck-register {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.8125rem;
}

.lux-paycheck-register thead th {
  padding: 0.75rem 1rem;
  text-align: left;
  font-size: 0.6875rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #94a3b8;
  white-space: nowrap;
  border-bottom: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(248, 250, 252, 0.92);
  position: sticky;
  top: 0;
  z-index: 1;
}

.lux-paycheck-register tbody td {
  padding: 0.85rem 1rem;
  border-bottom: 1px solid rgba(148, 163, 184, 0.14);
  vertical-align: middle;
}

.lux-paycheck-register__row.is-attention {
  background: linear-gradient(90deg, rgba(254, 243, 199, 0.42), transparent 58%);
}

.lux-paycheck-register__row:hover {
  background: rgba(248, 250, 252, 0.95);
}

.lux-paycheck-register__primary {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  min-width: 0;
  text-decoration: none;
  color: inherit;
}

.lux-paycheck-register__avatar {
  width: 2.35rem;
  height: 2.35rem;
  border-radius: 11px;
  display: inline-grid;
  place-items: center;
  font-size: 0.8125rem;
  font-weight: 800;
  color: #fff;
  background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
  flex-shrink: 0;
}

.lux-paycheck-register__avatar.is-green {
  background: linear-gradient(135deg, #10b981, #047857);
}

.lux-paycheck-register__primary-copy {
  display: flex;
  flex-direction: column;
  gap: 0.12rem;
  min-width: 0;
}

.lux-paycheck-register__primary-title {
  color: #0f172a;
  font-size: 0.875rem;
  font-weight: 800;
}

.lux-paycheck-register__primary-meta {
  color: #64748b;
  font-size: 0.75rem;
  font-weight: 600;
}

.lux-paycheck-register__period,
.lux-paycheck-register__date {
  font-size: 0.75rem;
  font-weight: 700;
  color: #334155;
  white-space: nowrap;
}

.lux-paycheck-register__net {
  font-variant-numeric: tabular-nums;
  color: #0f172a;
}

.lux-paycheck-register__actions {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  justify-content: flex-end;
}

.lux-paycheck-register__btn {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.35rem 0.6rem;
  border-radius: 10px;
  border: 1px solid transparent;
  font-size: 0.75rem;
  font-weight: 700;
  cursor: pointer;
}

.lux-paycheck-register__btn.is-primary {
  background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
  color: #fff;
}

.lux-paycheck-register__btn.is-ghost {
  background: rgba(255, 255, 255, 0.92);
  color: #475569;
  border-color: rgba(148, 163, 184, 0.35);
