.lux-payslip-detail__amount-card {
  padding: 0.85rem 1rem;
  border-radius: 14px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(255, 255, 255, 0.92);
}

.lux-payslip-detail__amount-card span {
  display: block;
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #94a3b8;
  margin-bottom: 0.25rem;
}

.lux-payslip-detail__amount-card strong {
  font-size: 1.125rem;
  color: #0f172a;
  font-variant-numeric: tabular-nums;
}

.lux-payslip-detail__amount-card.is-net {
  border-color: rgba(16, 185, 129, 0.25);
  background: rgba(209, 250, 229, 0.35);
}

.lux-payslip-detail__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.55rem;
}

.lux-payslip-detail__meta-item {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.75rem;
  font-weight: 600;
  color: #64748b;
