}

.lux-payslip-detail__ytd-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.65rem;
}

.lux-payslip-detail__ytd-card {
  padding: 0.75rem 0.85rem;
  border-radius: 12px;
  background: rgba(248, 250, 252, 0.95);
  border: 1px solid rgba(148, 163, 184, 0.18);
}

.lux-payslip-detail__ytd-card span {
  display: block;
  font-size: 0.6875rem;
  font-weight: 700;
  color: #94a3b8;
