    flex-wrap: wrap;
  }

  .lux-rbac-panel__grid {
    grid-template-columns: 1fr;
  }

  .lux-rbac-detail {
    position: static;
    max-height: none;
  }
}

@media (max-width: 992px) {
  .lux-rbac-panel__filters {
    grid-template-columns: 1fr;
  }

  .lux-rbac-detail__summary {
    grid-template-columns: 1fr;
  }

  .lux-rbac-detail__summary-bar {
    order: 3;
  }

  .lux-rbac-detail__matrix--dense {
    grid-template-columns: 1fr;
  }

  .lux-rbac-snapshot {
    grid-template-columns: 1fr;
  }

  .lux-rbac-quick-nav__grid {
    grid-template-columns: 1fr;
  }

  .lux-rbac-panel__selected {
    display: none;
  }
}

