/* F21-T8 — Workspace responsive polish */
@media (max-width: 1200px) {
  .lux-workspace-home-hero .lux-hrms-dash__hero-main,
  .lux-my-work-hero .lux-hrms-dash__hero-main,
  .lux-notifications-page .lux-hrms-dash__hero-main,
  .lux-appr-hero .lux-hrms-dash__hero-main {
    min-width: 0;
  }
}

@media (max-width: 992px) {
  .lux-workspace-home-hero,
  .lux-my-work-hero,
  .lux-appr-hero {
    flex-direction: column;
    align-items: stretch;
  }

  .lux-my-work-hero__actions,
  .lux-workspace-home-hero__actions {
    width: 100%;
    align-items: flex-start;
  }

  .lux-my-work-panel__filters,
  .lux-notifications-panel__filters {
    grid-template-columns: 1fr;
  }

  .lux-workspace-briefing__priority-link {
    grid-template-columns: auto 1fr;
  }

  .lux-workspace-briefing__chevron {
    display: none;
  }

  .lux-appr-toolbar__grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  .lux-hrms-dash__kpi-strip,
  .lux-workspace-home-kpi-strip,
  .lux-my-work-kpi-strip,
  .lux-notifications-kpi-strip {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .lux-workspace-saved-view-bar__form {
    flex-direction: column;
    align-items: stretch;
  }

  .lux-workspace-saved-view-bar__form .lux-appr-toolbar__search-input {
    width: 100%;
  }
}

