  flex-direction: column;
  gap: 0.15rem;
  padding: 0.65rem 0.75rem;
  border-radius: 0.8rem;
  border: 1px solid rgba(226, 232, 240, 0.95);
  background: rgba(255, 255, 255, 0.88);
}

.lux-staffing-drawer__preview-stat.is-wide {
  grid-column: 1 / -1;
}

.lux-staffing-drawer__preview-stat span {
  font-size: 0.625rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #94a3b8;
}

.lux-staffing-drawer__preview-stat strong {
  font-size: 0.875rem;
  color: #0f172a;
}

.lux-staffing-drawer__preview-stat strong.is-rose { color: #be123c; }
.lux-staffing-drawer__preview-stat strong.is-primary { color: var(--lux-primary-dark, #3730a3); }
.lux-staffing-drawer__preview-stat strong.is-slate { color: #475569; }

.lux-staffing-drawer__section {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.lux-staffing-drawer__section-label {
  font-size: 0.625rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #64748b;
}

.lux-staffing-drawer__grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.55rem;
}

.lux-staffing-drawer__field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.lux-staffing-drawer__field.is-wide {
  grid-column: 1 / -1;
}

.lux-staffing-drawer__field > span {
  font-size: 0.6875rem;
  font-weight: 700;
  color: #475569;
}

.lux-staffing-drawer__input,
.lux-staffing-drawer__textarea {
  width: 100%;
  border: 1px solid rgba(148, 163, 184, 0.28);
  border-radius: 0.7rem;
  padding: 0.6rem 0.75rem;
  font-size: 0.8125rem;
  background: #fff;
  color: #0f172a;
}

.lux-staffing-drawer__textarea {
  resize: vertical;
  min-height: 4.5rem;
}

.lux-staffing-drawer__field.is-highlight .lux-staffing-drawer__input,
.lux-staffing-drawer__field.is-highlight .lux-staffing-drawer__textarea {
  border-color: rgba(37, 99, 235, 0.22);
  background: rgba(255, 255, 255, 0.96);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.8);
}

.lux-staffing-drawer__input:focus,
.lux-staffing-drawer__textarea:focus {
  outline: none;
  border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.45);
  box-shadow: 0 0 0 3px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
}

.lux-staffing-drawer__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.lux-staffing-drawer__chip {
  border: 1px solid rgba(226, 232, 240, 0.98);
  border-radius: 999px;
  padding: 0.3rem 0.65rem;
  background: rgba(248, 250, 252, 0.9);
  font-size: 0.6875rem;
  font-weight: 700;
  color: #475569;
  cursor: pointer;
}

.lux-staffing-drawer__chip.is-active {
  border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
  background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1);
  color: var(--lux-primary-dark, #3730a3);
}

.lux-staffing-drawer__stepper {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.35rem 0.5rem;
  border-radius: 0.75rem;
  border: 1px solid rgba(148, 163, 184, 0.24);
  background: #fff;
}

.lux-staffing-drawer__stepper strong {
  min-width: 1.5rem;
  text-align: center;
  font-size: 0.9375rem;
  color: #0f172a;
}

.lux-staffing-drawer__stepper-btn {
  width: 1.75rem;
  height: 1.75rem;
  border: none;
  border-radius: 0.55rem;
  background: rgba(148, 163, 184, 0.14);
  color: #475569;
  cursor: pointer;
}

.lux-staffing-drawer__stepper-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.lux-staffing-drawer__priority-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.45rem;
}

.lux-staffing-drawer__priority-card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.2rem;
  padding: 0.6rem 0.65rem;
  border-radius: 0.75rem;
  border: 1px solid rgba(226, 232, 240, 0.98);
  background: rgba(255, 255, 255, 0.9);
  text-align: left;
  cursor: pointer;
}

.lux-staffing-drawer__priority-card i {
  font-size: 0.875rem;
}

.lux-staffing-drawer__priority-card strong {
  font-size: 0.75rem;
  color: #0f172a;
}

.lux-staffing-drawer__priority-card small {
  font-size: 0.625rem;
  color: #94a3b8;
  line-height: 1.3;
}

.lux-staffing-drawer__priority-card.is-rose i { color: #e11d48; }
.lux-staffing-drawer__priority-card.is-primary i { color: var(--lux-primary-dark, #3730a3); }
.lux-staffing-drawer__priority-card.is-slate i { color: #64748b; }

.lux-staffing-drawer__priority-card.is-active {
  border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
  box-shadow: 0 8px 20px rgba(15, 23, 42, 0.05);
}

.lux-staffing-drawer__priority-card.is-active.is-rose {
  border-color: rgba(244, 63, 94, 0.28);
  background: rgba(255, 241, 242, 0.7);
}

.lux-staffing-drawer__tip-card {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 0.65rem;
  align-items: center;
  padding: 0.75rem 0.85rem;
  border-radius: 0.85rem;
  border: 1px solid rgba(124, 58, 237, 0.16);
  background: linear-gradient(135deg, rgba(245, 243, 255, 0.85), rgba(255, 255, 255, 0.95));
}

.lux-staffing-drawer__tip-card i {
  color: #6d28d9;
  font-size: 1rem;
}

.lux-staffing-drawer__tip-card strong {
  display: block;
  font-size: 0.75rem;
  color: #0f172a;
}

.lux-staffing-drawer__tip-card p {
  margin: 0.15rem 0 0;
  font-size: 0.6875rem;
  color: #64748b;
}

.lux-staffing-drawer__tip-link {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  font-size: 0.6875rem;
  font-weight: 700;
  color: #6d28d9;
  text-decoration: none;
  white-space: nowrap;
}

.lux-staffing-drawer__workflow {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.lux-staffing-drawer__steps {
  display: flex;
  gap: 0.35rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.lux-staffing-drawer__step {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
  padding: 0.45rem 0.25rem;
  border-radius: 0.65rem;
  background: rgba(248, 250, 252, 0.9);
  border: 1px solid rgba(226, 232, 240, 0.95);
}

.lux-staffing-drawer__step.is-active {
  border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
  background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.08);
}

.lux-staffing-drawer__step.is-complete {
  border-color: rgba(16, 185, 129, 0.22);
  background: rgba(236, 253, 245, 0.8);
}

.lux-staffing-drawer__step.is-rejected {
  border-color: rgba(244, 63, 94, 0.22);
  background: rgba(255, 241, 242, 0.8);
}

.lux-staffing-drawer__step-marker {
  width: 1.35rem;
  height: 1.35rem;
  border-radius: 999px;
  display: inline-grid;
  place-items: center;
  font-size: 0.625rem;
  font-weight: 800;
  background: rgba(148, 163, 184, 0.18);
  color: #475569;
}

.lux-staffing-drawer__step.is-active .lux-staffing-drawer__step-marker,
.lux-staffing-drawer__step.is-complete .lux-staffing-drawer__step-marker {
  background: var(--lux-primary, #5b5ff4);
  color: #fff;
}

.lux-staffing-drawer__step.is-complete .lux-staffing-drawer__step-marker {
  background: #059669;
}

.lux-staffing-drawer__step-label {
  font-size: 0.625rem;
  font-weight: 700;
  color: #64748b;
  text-align: center;
}

.lux-staffing-drawer__workflow-note {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0;
  font-size: 0.6875rem;
  color: #be123c;
}

.lux-staffing-drawer__workflow-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}

.lux-staffing-drawer__error {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0;
  padding: 0.55rem 0.65rem;
  border-radius: 0.65rem;
  background: rgba(244, 63, 94, 0.08);
  color: #be123c;
  font-size: 0.75rem;
}

.lux-staffing-drawer__foot {
  display: flex;
  justify-content: flex-end;
  gap: 0.5rem;
  padding-top: 0.35rem;
  margin-top: auto;
  border-top: 1px solid rgba(226, 232, 240, 0.95);
}

.lux-staffing-drawer__btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  min-height: 2.125rem;
  padding: 0 0.9rem;
  border-radius: 999px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  background: rgba(255, 255, 255, 0.95);
  font-size: 0.75rem;
  font-weight: 800;
  color: #475569;
  cursor: pointer;
}

.lux-staffing-drawer__btn.is-primary {
  border-color: transparent;
  background: linear-gradient(135deg, var(--lux-primary, #5b5ff4), var(--lux-primary-dark, #3730a3));
  color: #fff;
  box-shadow: 0 8px 20px rgba(var(--lux-primary-rgb, 91, 95, 244), 0.28);
}

.lux-staffing-drawer__btn.is-success {
  border-color: rgba(16, 185, 129, 0.22);
  background: rgba(236, 253, 245, 0.95);
  color: #047857;
}

.lux-staffing-drawer__btn.is-danger {
  border-color: rgba(244, 63, 94, 0.22);
  background: rgba(255, 241, 242, 0.95);
  color: #be123c;
}

.lux-staffing-drawer__btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

@media (max-width: 640px) {
  .lux-staffing-drawer__grid,
  .lux-staffing-drawer__priority-grid,
  .lux-staffing-drawer__preview {
    grid-template-columns: 1fr;
  }

  .lux-staffing-drawer__tip-card {
    grid-template-columns: auto 1fr;
  }

  .lux-staffing-drawer__tip-link {
    grid-column: 1 / -1;
  }
}

@media (max-width: 991px) {
  .lux-staffing-register-wrap {
    overflow-x: auto;
  }
}

/* F13-T5 — Bench & roll-off page */
.lux-bench-page {
  --bench-accent: var(--lux-primary, #5b5ff4);
  position: relative;
  padding-bottom: var(--lux-page-block-bottom);
}

.lux-bench-lux__ambient {
  position: absolute;
  inset: 0 0 auto 0;
  height: 22rem;
  pointer-events: none;
  overflow: hidden;
  z-index: 0;
}

.lux-bench-lux__orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(2px);
}

.lux-bench-lux__orb--a {
  width: 18rem;
  height: 18rem;
  top: -6rem;
  right: -3rem;
  background: radial-gradient(circle, rgba(20, 184, 166, 0.22), transparent 68%);
}

.lux-bench-lux__orb--b {
  width: 14rem;
  height: 14rem;
  top: 2rem;
  left: -3rem;
  background: radial-gradient(circle, rgba(56, 189, 248, 0.14), transparent 70%);
}

.lux-bench-page > .lux-module-hero,
.lux-bench-page > .lux-bench-page__body {
  position: relative;
  z-index: 1;
}

.lux-bench-page__body {
  display: grid;
  gap: 1rem;
}

.lux-bench-hero.lux-module-hero {
  position: relative;
  overflow: hidden;
  margin-bottom: 0.35rem;
}

.lux-bench-hero.lux-module-hero::after {
  content: "";
  position: absolute;
  width: 16rem;
  height: 16rem;
  right: -3rem;
  top: -5rem;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(45, 212, 191, 0.28), transparent 68%);
  pointer-events: none;
}

.lux-bench-hero .lux-module-hero__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 0.45rem;
}

.lux-bench-panel {
  border: 1px solid rgba(148, 163, 184, 0.18);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.9));
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.04);
}

.lux-bench-panel--register,
.lux-bench-panel--timeline {
  margin-top: 0;
}

.lux-bench-panel--timeline {
  border-color: rgba(20, 184, 166, 0.22);
  background:
    linear-gradient(165deg, rgba(20, 184, 166, 0.07), transparent 42%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.92));
}

.lux-bench-panel--register {
  border-color: rgba(56, 189, 248, 0.18);
  background:
    linear-gradient(165deg, rgba(56, 189, 248, 0.06), transparent 38%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.9));
}

.lux-bench-panel__toolbar {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  padding: 0.15rem 1rem 0.9rem;
  border-bottom: 1px solid rgba(226, 232, 240, 0.85);
  background: linear-gradient(180deg, rgba(248, 250, 252, 0.75), transparent);
}

.lux-bench-timeline {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(15rem, 1fr));
  gap: 0.65rem;
  padding: 0.85rem 1rem 1rem;
}

.lux-bench-timeline__item {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 0.65rem;
  padding: 0.75rem 0.85rem;
  border: 1px solid rgba(226, 232, 240, 0.95);
  border-radius: 0.85rem;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.95));
  text-align: left;
  cursor: pointer;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
}

.lux-bench-timeline__item:hover {
  border-color: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.35);
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.06);
  transform: translateY(-1px);
}

.lux-bench-timeline__avatar {
  width: 2rem;
  height: 2rem;
  border-radius: 999px;
  display: inline-grid;
  place-items: center;
  font-size: 0.7rem;
  font-weight: 700;
  background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.12);
  color: var(--lux-primary-dark, #3730a3);
}

.lux-bench-timeline__copy {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
  min-width: 0;
}

.lux-bench-timeline__copy strong {
  font-size: 0.8125rem;
  color: #0f172a;
}

.lux-bench-timeline__copy span {
  font-size: 0.6875rem;
  color: #64748b;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.lux-bench-timeline__meta {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.2rem;
}

.lux-bench-timeline__chip {
  font-size: 0.625rem;
  font-weight: 600;
  padding: 0.15rem 0.45rem;
  border-radius: 999px;
}

.lux-bench-timeline__chip.is-amber { background: rgba(245, 158, 11, 0.14); color: #b45309; }
.lux-bench-timeline__chip.is-primary { background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1); color: var(--lux-primary-dark, #3730a3); }
.lux-bench-timeline__chip.is-sky { background: rgba(14, 165, 233, 0.12); color: #0369a1; }

.lux-bench-timeline__meta time {
  font-size: 0.6875rem;
  color: #64748b;
}

.lux-bench-register-wrap {
  overflow-x: auto;
}

.lux-bench-register {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.8125rem;
}

.lux-bench-register thead th {
  position: sticky;
  top: 0;
  z-index: 1;
  padding: 0.65rem 0.75rem;
  text-align: left;
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #64748b;
  background: rgba(248, 250, 252, 0.98);
  border-bottom: 1px solid rgba(226, 232, 240, 0.95);
}

.lux-bench-register tbody td {
  padding: 0.75rem;
  border-bottom: 1px solid rgba(241, 245, 249, 0.95);
  vertical-align: middle;
}

.lux-bench-register__row.is-soon {
  background: rgba(245, 158, 11, 0.04);
}

.lux-bench-register__row.is-long {
  background: rgba(244, 63, 94, 0.03);
}

.lux-bench-register__row:hover {
  background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.03);
}

.lux-bench-register__person {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  border: none;
  background: transparent;
  padding: 0;
  text-align: left;
  cursor: pointer;
}

.lux-bench-register__avatar {
  width: 2rem;
  height: 2rem;
  border-radius: 999px;
  display: inline-grid;
  place-items: center;
  flex-shrink: 0;
  font-size: 0.6875rem;
  font-weight: 700;
  background: linear-gradient(135deg, rgba(37, 99, 235, 0.12), rgba(99, 102, 241, 0.16));
  color: var(--lux-primary-dark, #3730a3);
}

.lux-bench-register__person-copy strong {
  display: block;
  color: #0f172a;
}

.lux-bench-register__meta,
.lux-bench-register__date,
.lux-bench-register__skills {
  display: block;
  font-size: 0.6875rem;
  color: #64748b;
}

.lux-bench-register__project {
  font-weight: 500;
  color: #334155;
}

.lux-bench-register__avail {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 2.5rem;
  padding: 0.2rem 0.45rem;
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 600;
}

.lux-bench-register__avail.is-primary { background: rgba(var(--lux-primary-rgb, 91, 95, 244), 0.1); color: var(--lux-primary-dark, #3730a3); }
.lux-bench-register__avail.is-amber { background: rgba(245, 158, 11, 0.14); color: #b45309; }
.lux-bench-register__avail.is-sky { background: rgba(14, 165, 233, 0.12); color: #0369a1; }
.lux-bench-register__avail.is-green { background: rgba(16, 185, 129, 0.12); color: #047857; }

.lux-bench-register__days.is-alert {
  color: #be123c;
  font-weight: 700;
}

/* F13-T5 — Bench luxury drawer */
.lux-bench-drawer__backdrop {
  position: fixed;
  inset: 0;
  z-index: var(--lux-z-overlay);
  border: none;
  background: rgba(15, 23, 42, 0.42);
  backdrop-filter: blur(4px);
  cursor: pointer;
}

.lux-bench-drawer {
  position: fixed;
  top: 0;
  right: 0;
  z-index: var(--lux-z-overlay-panel);
  width: min(32rem, 100vw);
  height: 100vh;
  height: 100dvh;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background:
    radial-gradient(circle at 100% 0%, rgba(37, 99, 235, 0.12), transparent 42%),
    radial-gradient(circle at 0% 100%, rgba(99, 102, 241, 0.08), transparent 38%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.98));
  box-shadow: -24px 0 64px rgba(15, 23, 42, 0.18);
  overflow: hidden;
}

.lux-bench-drawer.is-amber { --bench-accent: #d97706; }
.lux-bench-drawer.is-blue,
.lux-bench-drawer.is-primary { --bench-accent: #2563eb; }
.lux-bench-drawer.is-green { --bench-accent: #059669; }
.lux-bench-drawer.is-sky { --bench-accent: #0284c7; }

.lux-bench-drawer__glow {
  position: absolute;
  inset: 0 0 auto 0;
  height: 3px;
  background: linear-gradient(90deg, var(--bench-accent, var(--lux-primary, #5b5ff4)), rgba(99, 102, 241, 0.15));
  pointer-events: none;
}

.lux-bench-drawer__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 1rem 1.1rem 0.9rem;
  border-bottom: 1px solid rgba(226, 232, 240, 0.95);
  background: rgba(248, 250, 252, 0.92);
}

.lux-bench-drawer__head-main {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  min-width: 0;
}

.lux-bench-drawer__avatar {
  width: 2.75rem;
  height: 2.75rem;
  border-radius: 999px;
  display: inline-grid;
  place-items: center;
  flex-shrink: 0;
  font-size: 0.8125rem;
  font-weight: 700;
  background: linear-gradient(135deg, rgba(37, 99, 235, 0.14), rgba(99, 102, 241, 0.18));
  color: var(--lux-primary-dark, #3730a3);
}

.lux-bench-drawer__eyebrow {
  display: block;
  font-size: 0.625rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #64748b;
}

.lux-bench-drawer__head-copy h2 {
  margin: 0.15rem 0 0;
  font-size: 1.125rem;
  color: #0f172a;
}

.lux-bench-drawer__subtitle {
  margin: 0.15rem 0 0.35rem;
  font-size: 0.75rem;
