/* F13-T6 — Capacity simulation / what-if */
.lux-simulation-page {
  position: relative;
  padding-bottom: var(--lux-page-block-bottom);
}

.lux-simulation-lux__ambient {
  position: absolute;
  inset: 0 0 auto 0;
  height: 22rem;
  pointer-events: none;
  overflow: hidden;
  z-index: 0;
}

.lux-simulation-lux__orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(2px);
}

.lux-simulation-lux__orb--a {
  width: 18rem;
  height: 18rem;
  top: -6rem;
  right: -3rem;
  background: radial-gradient(circle, rgba(56, 189, 248, 0.22), transparent 68%);
}

.lux-simulation-lux__orb--b {
  width: 14rem;
  height: 14rem;
  top: 2rem;
  left: -3rem;
  background: radial-gradient(circle, rgba(99, 102, 241, 0.14), transparent 70%);
}

.lux-simulation-page > .lux-module-hero,
.lux-simulation-page > .lux-simulation-page__body {
  position: relative;
  z-index: 1;
}

.lux-simulation-page__body {
  display: grid;
  gap: 1rem;
}

.lux-simulation-hero.lux-module-hero {
  position: relative;
  overflow: hidden;
  margin-bottom: 0.35rem;
}

.lux-simulation-hero.lux-module-hero::after {
  content: "";
  position: absolute;
  width: 16rem;
  height: 16rem;
  right: -3rem;
  top: -5rem;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(125, 211, 252, 0.3), transparent 68%);
  pointer-events: none;
}

.lux-simulation-hero .lux-module-hero__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 0.45rem;
}

.lux-simulation-panel-wrap,
.lux-simulation-results-wrap {
  border: 1px solid rgba(148, 163, 184, 0.18);
  background:
    linear-gradient(165deg, rgba(56, 189, 248, 0.06), transparent 42%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.9));
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.04);
}

.lux-simulation-results-wrap {
  background:
    linear-gradient(165deg, rgba(99, 102, 241, 0.06), transparent 42%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.9));
}


.lux-simulation-hero {
