@media (max-width: 768px) {
  .lux-staffing-ai-queue__item {
    grid-template-columns: 1fr;
  }
}

/* F15 — Project governance (milestones, timeline, risks) */
.lux-gov-lux {
  position: relative;
  padding-bottom: 1rem;
  isolation: isolate;
}

.lux-gov-lux__ambient {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}

.lux-gov-lux__orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(60px);
  opacity: 0.55;
}

.lux-gov-lux__orb--a {
  width: 420px;
  height: 420px;
  top: -120px;
  left: -80px;
  background: radial-gradient(circle, rgba(99, 102, 241, 0.28), transparent 68%);
}

.lux-gov-lux__orb--b {
  width: 360px;
  height: 360px;
  top: 40px;
  right: -60px;
  background: radial-gradient(circle, rgba(16, 185, 129, 0.18), transparent 70%);
}

.lux-gov-lux.is-blue .lux-gov-lux__orb--a { background: radial-gradient(circle, rgba(59, 130, 246, 0.32), transparent 68%); }
.lux-gov-lux.is-indigo .lux-gov-lux__orb--a { background: radial-gradient(circle, rgba(79, 70, 229, 0.3), transparent 68%); }
.lux-gov-lux.is-amber .lux-gov-lux__orb--a { background: radial-gradient(circle, rgba(245, 158, 11, 0.28), transparent 68%); }
.lux-gov-lux.is-rose .lux-gov-lux__orb--a { background: radial-gradient(circle, rgba(244, 63, 94, 0.26), transparent 68%); }
.lux-gov-lux.is-violet .lux-gov-lux__orb--a { background: radial-gradient(circle, rgba(139, 92, 246, 0.3), transparent 68%); }

.lux-gov-lux-hero,
.lux-gov-lux__kpi-strip,
.lux-gov-lux__insights,
.lux-gov-lux__quick-nav,
.lux-gov-lux__content {
  position: relative;
  z-index: 1;
}

.lux-gov-lux-hero {
  flex-direction: column;
  align-items: stretch;
  gap: 0.5rem;
  margin-bottom: 0.35rem;
}

.lux-gov-lux-hero__top {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  width: 100%;
}

.lux-gov-lux-hero.is-blue .lux-hrms-dash__hero-title span { color: #1d4ed8; }
.lux-gov-lux-hero.is-indigo .lux-hrms-dash__hero-title span { color: #4338ca; }
.lux-gov-lux-hero.is-amber .lux-hrms-dash__hero-title span { color: #d97706; }
.lux-gov-lux-hero.is-rose .lux-hrms-dash__hero-title span { color: #e11d48; }
.lux-gov-lux-hero.is-violet .lux-hrms-dash__hero-title span { color: #6d28d9; }

/* Project module zone chrome (register pages — compact variant) */
.lux-project-zone {
  display: grid;
  gap: 0.65rem;
}

.lux-project-zone--compact {
  padding: 0.25rem var(--lux-page-gutter-x, 0.75rem) 0;
  gap: 0.35rem;
}

.lux-project-zone__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
}

.lux-project-zone__copy {
  display: grid;
  gap: 0.15rem;
  min-width: 0;
}

.lux-project-zone__title {
  margin: 0;
  font-size: 1.05rem;
}

.lux-project-zone__lede {
  margin: 0;
  max-width: 52rem;
  font-size: 0.78rem;
  font-weight: 600;
  color: #64748b;
  line-height: 1.45;
}

.lux-project-zone__nav {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.4rem;
}

.lux-project-zone__nav-link {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  min-height: 2.25rem;
  padding: 0.35rem 0.7rem;
  border-radius: 999px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  background: rgba(255, 255, 255, 0.82);
  text-decoration: none;
  color: #334155;
  font-size: 0.74rem;
  font-weight: 700;
  transition: border-color 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
