.lux-project-zone__nav-link:hover {
  border-color: rgba(99, 102, 241, 0.35);
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.05);
}

.lux-project-zone__nav-link.is-active {
  border-color: rgba(99, 102, 241, 0.45);
  background: linear-gradient(135deg, rgba(99, 102, 241, 0.12), rgba(255, 255, 255, 0.95));
  color: #312e81;
  box-shadow: 0 10px 22px rgba(99, 102, 241, 0.1);
}

.lux-project-zone__nav-link i {
  font-size: 0.82rem;
  color: #6366f1;
}

.lux-project-zone__nav-link.is-active i {
  color: #4f46e5;
