.lux-gov-lux__module-nav {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0.55rem;
}

.lux-gov-lux__module-link {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.65rem 0.75rem;
  border-radius: 14px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(255, 255, 255, 0.72);
  text-decoration: none;
  color: inherit;
  transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
}

.lux-gov-lux__module-link:hover {
  transform: translateY(-1px);
  border-color: rgba(99, 102, 241, 0.28);
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.06);
}

.lux-gov-lux__module-link.is-active {
  border-color: rgba(99, 102, 241, 0.45);
  background: linear-gradient(135deg, rgba(99, 102, 241, 0.12), rgba(255, 255, 255, 0.95));
  box-shadow: 0 12px 28px rgba(99, 102, 241, 0.12);
}

.lux-gov-lux__module-icon {
  width: 2rem;
  height: 2rem;
  border-radius: 10px;
  display: grid;
  place-content: center;
  font-size: 0.95rem;
  color: #4f46e5;
  background: rgba(99, 102, 241, 0.1);
}

.lux-gov-lux__module-link.is-active .lux-gov-lux__module-icon {
  color: #fff;
  background: linear-gradient(135deg, #6366f1, #4f46e5);
}

.lux-gov-lux__module-copy {
  display: grid;
  gap: 0.05rem;
  min-width: 0;
}

.lux-gov-lux__module-copy strong {
  font-size: 0.8rem;
  font-weight: 800;
  color: #0f172a;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.lux-gov-lux__module-copy small {
  font-size: 0.65rem;
  font-weight: 600;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

/* F15 — Rich governance KPI strip */
.lux-gov-kpi-strip,
.lux-gov-lux__kpi-strip {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(158px, 1fr));
  gap: var(--lux-kpi-strip-grid-gap);
  margin: var(--lux-kpi-strip-margin);
}

.lux-gov-kpi {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  min-height: var(--lux-kpi-min-height);
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.78);
  border-radius: 18px;
  background:
    radial-gradient(circle at 100% 0%, color-mix(in srgb, var(--gov-kpi-accent, #6366f1) 14%, transparent), transparent 56%),
    linear-gradient(165deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.9));
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.96) inset,
    0 18px 40px rgba(15, 23, 42, 0.08);
  backdrop-filter: blur(10px);
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}

.lux-gov-kpi:hover {
  transform: translateY(-2px);
  border-color: color-mix(in srgb, var(--gov-kpi-accent, #6366f1) 28%, rgba(255, 255, 255, 0.78));
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.98) inset,
    0 24px 48px rgba(15, 23, 42, 0.11);
}

.lux-gov-kpi__accent {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--gov-kpi-accent, #6366f1), color-mix(in srgb, var(--gov-kpi-accent, #6366f1) 35%, transparent));
  z-index: 1;
}

.lux-gov-kpi__glow {
  position: absolute;
  width: 5.5rem;
  height: 5.5rem;
  top: -2.2rem;
  right: -1.6rem;
  border-radius: 50%;
  background: radial-gradient(circle, color-mix(in srgb, var(--gov-kpi-accent, #6366f1) 22%, transparent), transparent 68%);
  pointer-events: none;
  z-index: 0;
}

.lux-gov-kpi__inner {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
  height: 100%;
  padding: 0.95rem 1rem 1rem;
}

.lux-gov-kpi__head {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  min-height: 2rem;
}

.lux-gov-kpi__icon {
  flex-shrink: 0;
  width: 2.15rem;
  height: 2.15rem;
  border-radius: 12px;
