}

.lux-delivery-gantt__sidebar {
  border-right: 1px solid rgba(148, 163, 184, 0.22);
  overflow: auto;
}

.lux-delivery-gantt__lane {
  display: grid;
  gap: 0.1rem;
  width: 100%;
  padding: 0.45rem 0.75rem;
  border: 0;
  border-bottom: 1px solid rgba(226, 232, 240, 0.9);
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.lux-delivery-gantt__lane strong {
  font-size: 0.82rem;
  color: #0f172a;
}

.lux-delivery-gantt__lane span {
  font-size: 0.72rem;
  color: #94a3b8;
}

.lux-delivery-gantt__lane.is-selected,
.lux-delivery-gantt__lane:hover {
  background: rgba(59, 130, 246, 0.06);
}

.lux-delivery-gantt__lane.is-critical {
  box-shadow: inset 3px 0 0 rgba(244, 63, 94, 0.65);
}

.lux-delivery-gantt__tracks-scroll {
  overflow: auto;
}

.lux-delivery-gantt__tracks {
  position: relative;
  min-height: 100%;
}

.lux-delivery-gantt__today {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 2px;
  background: rgba(244, 63, 94, 0.75);
  z-index: 2;
  pointer-events: none;
}

.lux-delivery-gantt__links {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 1;
}

.lux-delivery-gantt__link-path {
  fill: none;
  stroke: rgba(100, 116, 139, 0.55);
  stroke-width: 1.5;
}

.lux-delivery-gantt__track-row {
  position: relative;
  border-bottom: 1px solid rgba(241, 245, 249, 0.95);
}

.lux-delivery-gantt__bar {
  position: absolute;
  top: 10px;
  height: 32px;
  border: 1px solid rgba(148, 163, 184, 0.35);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.95);
  overflow: hidden;
  cursor: grab;
  z-index: 3;
  padding: 0;
}

.lux-delivery-gantt__bar.is-dragging {
  cursor: grabbing;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.18);
