}

.lux-delivery-gantt__bar.is-green { border-color: rgba(16, 185, 129, 0.45); background: rgba(16, 185, 129, 0.12); }
.lux-delivery-gantt__bar.is-blue { border-color: rgba(59, 130, 246, 0.45); background: rgba(59, 130, 246, 0.12); }
.lux-delivery-gantt__bar.is-amber { border-color: rgba(245, 158, 11, 0.45); background: rgba(245, 158, 11, 0.14); }
.lux-delivery-gantt__bar.is-rose { border-color: rgba(244, 63, 94, 0.45); background: rgba(244, 63, 94, 0.12); }
.lux-delivery-gantt__bar.is-slate { border-color: rgba(148, 163, 184, 0.45); background: rgba(148, 163, 184, 0.12); }

.lux-delivery-gantt__bar.is-critical {
  outline: 2px solid rgba(244, 63, 94, 0.35);
}

.lux-delivery-gantt__bar-progress {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  background: rgba(59, 130, 246, 0.22);
  pointer-events: none;
}

.lux-delivery-gantt__bar-label {
  position: relative;
  z-index: 1;
  display: block;
  padding: 0 0.55rem;
  font-size: 0.72rem;
