  line-height: 30px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: #0f172a;
}

.lux-delivery-gantt__legend-warn {
  color: #e11d48;
  font-weight: 600;
}

.lux-delivery-gantt__link-path.is-critical {
  stroke: rgba(244, 63, 94, 0.85);
  stroke-width: 2.25;
}

.lux-gov-reschedule-warning {
  margin: 0 0 0.75rem;
}

/* F15-T3 — Dependency validation & critical path */
.lux-gov-deps-panel {
  display: grid;
  gap: 1rem;
  margin-bottom: 1rem;
}

.lux-gov-deps-panel__summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.75rem;
}

.lux-gov-deps-panel__summary > div {
  padding: 0.85rem 1rem;
  border-radius: 12px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  background: rgba(248, 250, 252, 0.9);
}

.lux-gov-deps-panel__eyebrow {
