.lux-gov-deps-panel__issue strong {
  display: block;
  font-size: 0.82rem;
  color: #0f172a;
}

.lux-gov-deps-panel__issue span {
  display: block;
  margin-top: 0.15rem;
  font-size: 0.78rem;
  color: #64748b;
}

.lux-gov-deps-panel__form {
  padding: 0.9rem 1rem;
  border-radius: 12px;
  border: 1px dashed rgba(148, 163, 184, 0.4);
  background: rgba(255, 255, 255, 0.85);
}

.lux-gov-deps-panel__form-title {
  margin: 0 0 0.65rem;
  font-size: 0.82rem;
  font-weight: 600;
  color: #334155;
}

.lux-gov-deps-panel__fields {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.65rem;
  align-items: end;
}

.lux-gov-deps-panel__fields label {
