  gap: 0.3rem;
  font-size: 0.72rem;
  color: #64748b;
}

.lux-gov-deps-panel__fields select,
.lux-gov-deps-panel__fields input {
  width: 100%;
  border: 1px solid rgba(148, 163, 184, 0.45);
  border-radius: 8px;
  padding: 0.45rem 0.55rem;
  font-size: 0.82rem;
  background: #fff;
}

.lux-gov-deps-panel__submit {
  border: 0;
  border-radius: 10px;
  padding: 0.55rem 0.85rem;
  background: linear-gradient(135deg, #2563eb, #4f46e5);
