  border: 1px dashed rgba(148, 163, 184, 0.35);
  color: #64748b;
  font-size: 0.85rem;
}

.lux-gov-deps-issue {
  font-size: 0.76rem;
  color: #64748b;
}

.lux-gov-deps-issue.is-ok { color: #059669; }
.lux-gov-deps-issue.is-warning { color: #d97706; }
.lux-gov-deps-issue.is-error { color: #e11d48; }

/* F15-T4 — Risk register */
