  padding: 0.45rem 0.55rem;
  font-size: 0.82rem;
  background: #fff;
}

.lux-gov-risk-form__submit {
  border: 0;
  border-radius: 10px;
  padding: 0.55rem 0.85rem;
  background: linear-gradient(135deg, #e11d48, #be123c);
  color: #fff;
  font-size: 0.82rem;
  font-weight: 600;
