/* ── Lux inline alert (module body, replaces Bootstrap alert-danger) ─────── */
.lux-inline-alert {
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: flex-start;
  gap: 0.65rem;
  margin: 0 0 0.45rem;
  padding: 0.65rem 0.75rem;
  border-radius: 14px;
  border: 1px solid rgba(244, 63, 94, 0.22);
