    linear-gradient(135deg, rgba(255, 255, 255, 0.96), rgba(255, 241, 242, 0.88)),
    radial-gradient(120% 100% at 0% 0%, rgba(244, 63, 94, 0.08), transparent 55%);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.85) inset,
    0 10px 24px rgba(190, 18, 60, 0.06);
}

.lux-inline-alert__glow {
  position: absolute;
  inset: auto -8% -60% auto;
  width: 140px;
  height: 140px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(244, 63, 94, 0.14), transparent 68%);
  pointer-events: none;
}

.lux-inline-alert__icon {
  position: relative;
  z-index: 1;
  flex: 0 0 auto;
  width: 1.85rem;
  height: 1.85rem;
  border-radius: 10px;
  display: grid;
  place-content: center;
  font-size: 0.9rem;
  color: #be123c;
  background: rgba(244, 63, 94, 0.12);
  border: 1px solid rgba(244, 63, 94, 0.14);
}

.lux-inline-alert__copy {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 0.1rem;
  min-width: 0;
  flex: 1 1 auto;
}

.lux-inline-alert__eyebrow {
  font-size: 0.6rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #e11d48;
}

.lux-inline-alert__message {
  margin: 0;
  font-size: 0.75rem;
  font-weight: 600;
  line-height: 1.4;
  color: #9f1239;
}

.lux-inline-alert__dismiss {
  position: relative;
  z-index: 1;
  flex: 0 0 auto;
  width: 1.55rem;
  height: 1.55rem;
  margin-top: 0.05rem;
  border: 0;
  border-radius: 999px;
  background: rgba(244, 63, 94, 0.1);
  color: #be123c;
  display: grid;
  place-content: center;
  cursor: pointer;
  transition: background 0.12s ease, transform 0.12s ease;
}

.lux-inline-alert__dismiss:hover {
  background: rgba(244, 63, 94, 0.18);
  transform: scale(1.04);
}

.lux-inline-alert--warning {
  border-color: rgba(245, 158, 11, 0.28);
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.96), rgba(255, 251, 235, 0.9)),
    radial-gradient(120% 100% at 0% 0%, rgba(245, 158, 11, 0.1), transparent 55%);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.85) inset, 0 10px 24px rgba(180, 83, 9, 0.05);
}
.lux-inline-alert--warning .lux-inline-alert__icon { color: #b45309; background: rgba(245, 158, 11, 0.12); border-color: rgba(245, 158, 11, 0.16); }
.lux-inline-alert--warning .lux-inline-alert__eyebrow { color: #d97706; }
.lux-inline-alert--warning .lux-inline-alert__message { color: #92400e; }
