    border-radius: 14px;
    padding: 0.9rem 1rem;
    background: linear-gradient(145deg, rgba(255, 255, 255, 0.95), rgba(248, 250, 252, 0.8));
    box-shadow: 0 8px 20px rgba(15, 23, 42, 0.04);
}
.lux-finance-metric-card.is-green { border-color: rgba(16, 185, 129, 0.25); background: rgba(236, 253, 245, 0.45); }
.lux-finance-metric-card.is-indigo { border-color: rgba(99, 102, 241, 0.25); background: rgba(238, 242, 255, 0.45); }
.lux-finance-metric-card.is-amber { border-color: rgba(245, 158, 11, 0.28); background: rgba(255, 251, 235, 0.55); }
.lux-finance-metric-card.is-violet { border-color: rgba(139, 92, 246, 0.25); background: rgba(245, 243, 255, 0.5); }
.lux-finance-metric-card.is-rose { border-color: rgba(244, 63, 94, 0.25); background: rgba(255, 241, 242, 0.55); }

.lux-finance-metric-card__label {
    display: block;
    font-size: 0.65rem;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: #64748b;
    margin-bottom: 0.35rem;
}

.lux-finance-metric-card__value {
    display: block;
    font-size: 1.25rem;
    font-weight: 800;
    color: #0f172a;
    letter-spacing: -0.02em;
}

.lux-finance-metric-card small {
    display: block;
    margin-top: 0.25rem;
    font-size: 0.75rem;
    color: #64748b;
}

.lux-finance-pipeline {
    list-style: none;
    margin: 0;
    padding: 0;
    display: grid;
    gap: 0.75rem;
    counter-reset: revrec-step;
}

.lux-finance-pipeline li {
    counter-increment: revrec-step;
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.75rem 0.9rem;
    align-items: start;
    padding: 0.85rem 1rem;
    border-radius: 14px;
    border: 1px solid rgba(226, 232, 240, 0.95);
    background: linear-gradient(135deg, rgba(255, 255, 255, 0.92), rgba(248, 250, 252, 0.75));
}

.lux-finance-pipeline li::before {
    content: counter(revrec-step);
    width: 1.75rem;
    height: 1.75rem;
    border-radius: 999px;
    display: grid;
    place-items: center;
    font-size: 0.75rem;
    font-weight: 800;
    background: rgba(99, 102, 241, 0.12);
    color: #4338ca;
    grid-row: 1 / span 2;
}

.lux-finance-pipeline strong {
    font-size: 0.875rem;
    color: #0f172a;
}

.lux-finance-pipeline span {
    grid-column: 2;
    font-size: 0.8125rem;
    color: #64748b;
    line-height: 1.45;
}

@media (max-width: 1100px) {
    .lux-finance-form-grid,
    .lux-finance-form-grid.is-3 {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
    .lux-finance-metric-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 720px) {
    .lux-finance-form-grid,
    .lux-finance-form-grid.is-3,
    .lux-finance-form-grid.is-2,
    .lux-finance-metric-grid {
        grid-template-columns: 1fr;
    }
    .lux-finance-field.is-span-2 { grid-column: auto; }
}

/* —— Invoice document JSON App Config editor —— */
.lux-appconfig-editor-section--invoice-json .lux-appconfig-invoice-json__textarea,
.lux-ac-config-block--invoice-json .lux-appconfig-invoice-json__textarea {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  font-size: 0.78rem;
  line-height: 1.45;
  min-height: 18rem;
  border-radius: 12px;
  border: 1px solid rgba(203, 213, 225, 0.95);
  background: rgba(248, 250, 252, 0.95);
  color: #0f172a;
  white-space: pre;
}
.lux-appconfig-invoice-json__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
  align-items: center;
}

/* ========== Notification templates admin (luxury) ========== */
.lux-ntpl-page {
  padding-bottom: var(--lux-page-block-bottom);
}

.lux-ntpl-page .lux-module-hero {
  position: relative;
  overflow: hidden;
}

.lux-ntpl-page .lux-module-hero::after {
  content: "";
  position: absolute;
  right: -4%;
  top: -30%;
  width: 280px;
  height: 280px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(56, 189, 248, 0.22), transparent 68%);
  pointer-events: none;
}

.lux-ntpl-editor-banner {
  margin-bottom: 1rem;
}

.lux-ntpl-panel.lux-hrms-dash__panel {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background:
    linear-gradient(165deg, rgba(56, 189, 248, 0.06), transparent 38%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.94));
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.9) inset,
    0 18px 42px rgba(15, 23, 42, 0.06);
}

.lux-ntpl-panel::before {
  content: "";
  position: absolute;
  inset: 0 auto auto 0;
  width: 100%;
  height: 3px;
  background: linear-gradient(90deg, #38bdf8, var(--lux-primary, #5b5ff4), #14b8a6);
  opacity: 0.9;
  pointer-events: none;
}

.lux-ntpl-panel__toolbar {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  padding: 0 1.1rem 0.95rem;
  border-bottom: 1px solid rgba(241, 245, 249, 0.98);
  background: linear-gradient(180deg, rgba(248, 250, 252, 0.65), transparent);
}

.lux-ntpl-toolbar__row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.75rem;
}

.lux-ntpl-toolbar__search {
  position: relative;
  flex: 1 1 16rem;
  min-width: 12rem;
}

.lux-ntpl-toolbar__search > i {
  position: absolute;
  left: 0.9rem;
  top: 50%;
  transform: translateY(-50%);
  color: #94a3b8;
  pointer-events: none;
}

.lux-ntpl-toolbar__search-input {
  width: 100%;
  min-height: 2.65rem;
  padding: 0.55rem 0.95rem 0.55rem 2.45rem;
  border-radius: 14px;
  border: 1px solid rgba(15, 23, 42, 0.1);
  background: rgba(255, 255, 255, 0.95);
  font-size: 0.875rem;
  font-weight: 600;
  color: #0f172a;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
}

.lux-ntpl-toolbar__search-input:focus {
  outline: none;
  border-color: rgba(56, 189, 248, 0.55);
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.16);
}

.lux-ntpl-toolbar__count {
  color: #64748b;
  font-size: 0.8125rem;
  font-weight: 600;
}

.lux-ntpl-toolbar__count strong {
  color: #0f172a;
  font-weight: 800;
}

.lux-ntpl-panel__filters {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.85rem 1.25rem;
}

.lux-ntpl-toolbar__group {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.lux-ntpl-toolbar__label {
  font-size: 0.6875rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #94a3b8;
}

@media (max-width: 720px) {
  .lux-ntpl-panel__filters {
    grid-template-columns: 1fr;
  }
}

.lux-ntpl-register-wrap {
  margin: 0.15rem;
  width: 100%;
  max-width: 100%;
  overflow-x: hidden;
}

.lux-ntpl-page .lux-ntpl-panel,
.lux-ntpl-page .lux-ntpl-panel .lux-hrms-dash__panel-body,
.lux-ntpl-page .lux-admin-lux__content {
  min-width: 0;
  max-width: 100%;
}

.lux-ntpl-register {
  width: 100%;
  table-layout: fixed;
}

.lux-ntpl-register th:nth-child(1),
.lux-ntpl-register td:nth-child(1) { width: 26%; }
.lux-ntpl-register th:nth-child(2),
.lux-ntpl-register td:nth-child(2) { width: 12%; }
.lux-ntpl-register th:nth-child(3),
.lux-ntpl-register td:nth-child(3) { width: 24%; }
.lux-ntpl-register th:nth-child(4),
.lux-ntpl-register td:nth-child(4) { width: 12%; }
.lux-ntpl-register th:nth-child(5),
.lux-ntpl-register td:nth-child(5) { width: 10%; }
.lux-ntpl-register th:nth-child(6),
.lux-ntpl-register td:nth-child(6) { width: 16%; }

.lux-ntpl-register__subject,
.lux-ntpl-register .lux-appr-policy-register__primary-meta,
.lux-ntpl-register .lux-appr-policy-register__primary-title {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.lux-ntpl-register__actions {
  flex-wrap: wrap;
}

.lux-ntpl-register__primary-btn {
  display: block;
  width: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.lux-ntpl-register__primary-btn:hover .lux-appr-policy-register__primary-title {
  color: var(--lux-primary-dark, #3730a3);
}

.lux-ntpl-register__row.is-override {
  background: linear-gradient(90deg, rgba(91, 95, 244, 0.05), transparent 55%);
}

.lux-ntpl-register__row.is-disabled {
  background: linear-gradient(90deg, rgba(254, 243, 199, 0.45), transparent 58%);
}

.lux-ntpl-register__subject {
  display: inline-block;
  max-width: 18rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 700;
  color: #334155;
}

.lux-ntpl-register__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.lux-ntpl-register__action.is-secondary {
  color: #0f766e;
}

.lux-ntpl-register__action.is-secondary:hover {
  background: rgba(20, 184, 166, 0.08);
  border-color: rgba(20, 184, 166, 0.3);
}

/* Drawer popup */
.lux-ntpl-drawer.lux-onb-drawer {
  position: relative;
  width: min(48rem, 100vw);
  max-width: 100%;
  overflow: hidden;
  box-shadow:
    -28px 0 70px rgba(15, 23, 42, 0.32),
    0 0 0 1px rgba(255, 255, 255, 0.1) inset;
  background:
    linear-gradient(180deg, rgba(248, 250, 252, 0.98), rgba(255, 255, 255, 0.98));
}

.lux-ntpl-drawer .lux-onb-drawer__accent {
  background: linear-gradient(180deg, #38bdf8, var(--lux-primary, #5b5ff4), #14b8a6);
}

.lux-ntpl-drawer .lux-leave-drawer__scroll {
  display: flex;
  flex-direction: column;
  gap: 1.15rem;
}

.lux-ntpl-drawer__hero {
  display: flex;
  gap: 0.95rem;
  align-items: flex-start;
  padding: 1rem 1.05rem;
  border-radius: 16px;
  border: 1px solid rgba(56, 189, 248, 0.22);
  background:
    linear-gradient(135deg, rgba(56, 189, 248, 0.14), rgba(91, 95, 244, 0.08) 48%, rgba(20, 184, 166, 0.08)),
    #fff;
  box-shadow: 0 10px 28px rgba(14, 165, 233, 0.08);
}

.lux-ntpl-drawer__hero-icon {
  flex-shrink: 0;
  width: 2.75rem;
  height: 2.75rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 14px;
  background: linear-gradient(145deg, #38bdf8, #0284c7);
  color: #fff;
  font-size: 1.2rem;
  box-shadow: 0 10px 22px rgba(2, 132, 199, 0.28);
}

.lux-ntpl-drawer__hero strong {
  display: block;
  color: #0c4a6e;
  font-size: 0.92rem;
  font-weight: 800;
  line-height: 1.3;
}

.lux-ntpl-drawer__hero p {
  margin: 0.3rem 0 0;
  color: #64748b;
  font-size: 0.8125rem;
  font-weight: 600;
  line-height: 1.45;
}

.lux-ntpl-drawer__code {
  display: inline-block;
  margin-top: 0.45rem;
  padding: 0.28rem 0.55rem;
  border-radius: 10px;
  background: rgba(15, 23, 42, 0.06);
  color: #334155;
  font-size: 0.75rem;
  font-weight: 700;
  word-break: break-all;
}

.lux-ntpl-drawer__html {
  min-height: 13rem;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  font-size: 0.78rem;
  line-height: 1.5;
  background: linear-gradient(180deg, #0f172a, #111827) !important;
  color: #e2e8f0 !important;
  border-color: rgba(15, 23, 42, 0.55) !important;
}

.lux-ntpl-drawer__send {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0.65rem;
  align-items: end;
}

@media (max-width: 560px) {
  .lux-ntpl-drawer__send {
    grid-template-columns: 1fr;
  }
}

.lux-ntpl-drawer__status {
  margin: 0.45rem 0 0;
  padding: 0.55rem 0.75rem;
  border-radius: 12px;
  background: rgba(16, 185, 129, 0.1);
  border: 1px solid rgba(16, 185, 129, 0.22);
  font-size: 0.8125rem;
  font-weight: 700;
  color: #047857;
}

.lux-ntpl-drawer__confirm {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 1rem 1.05rem;
  border-radius: 16px;
  border: 1px solid rgba(239, 68, 68, 0.24);
  background: linear-gradient(180deg, #fef2f2, #fff);
  box-shadow: 0 12px 28px rgba(220, 38, 38, 0.08);
}

.lux-ntpl-drawer__confirm strong {
  color: #991b1b;
  font-size: 0.9rem;
  font-weight: 800;
}

.lux-ntpl-drawer__confirm p {
  margin: 0;
  color: #7f1d1d;
  font-size: 0.8125rem;
  font-weight: 600;
  line-height: 1.45;
}

.lux-ntpl-drawer__confirm-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.lux-ntpl-drawer .lux-leave-drawer__btn.is-danger {
  background: linear-gradient(135deg, #ef4444, #dc2626);
  color: #fff;
  border: none;
  box-shadow: 0 8px 20px rgba(220, 38, 38, 0.28);
}

.lux-ntpl-preview-overlay {
  position: absolute;
  inset: 0;
  z-index: 8;
  display: flex;
  flex-direction: column;
  background: rgba(8, 15, 30, 0.55);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  animation: lux-ntpl-fade-in 0.18s ease;
}

@keyframes lux-ntpl-fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

.lux-ntpl-preview-panel {
  display: flex;
  flex-direction: column;
  height: 100%;
  margin: 0.85rem;
  border-radius: 20px;
  overflow: hidden;
  background: #fff;
  box-shadow: 0 28px 70px rgba(15, 23, 42, 0.35);
}

.lux-ntpl-preview-panel__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.95rem 1.1rem;
  border-bottom: 1px solid rgba(15, 23, 42, 0.08);
  background:
    linear-gradient(135deg, rgba(56, 189, 248, 0.1), rgba(91, 95, 244, 0.06)),
    linear-gradient(180deg, #f8fafc, #fff);
}

.lux-ntpl-preview-panel__head h3 {
  margin: 0;
  font-size: 1rem;
  font-weight: 800;
  color: #0f172a;
}

.lux-ntpl-preview-panel__head p {
  margin: 0.2rem 0 0;
  font-size: 0.75rem;
  font-weight: 600;
  color: #64748b;
}

.lux-ntpl-preview-panel__body {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  padding: 1.1rem;
  background:
    radial-gradient(ellipse 70% 40% at 50% 0%, rgba(56, 189, 248, 0.08), transparent 60%),
    #f1f5f9;
}

.lux-ntpl-preview-panel__frame {
  min-height: 100%;
  padding: 1.15rem 1.25rem;
  border-radius: 16px;
  background: #fff;
  border: 1px solid rgba(15, 23, 42, 0.08);
  box-shadow: 0 12px 32px rgba(15, 23, 42, 0.08);
}

.lux-ntpl-drawer-backdrop.lux-onb-drawer-backdrop {
  background: rgba(8, 15, 30, 0.58);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}
